/****** Object:  UserDefinedFunction [dbo].[CalculateExpenseShare]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[CalculateExpenseShare]
(
    @DistributionType NVARCHAR(10), -- 'VALUE', 'WEIGHT', 'QUANTITY'
    @ItemValue Numeric(18,3),      -- قيمة الصنف
    @ItemWeight Numeric(18,3),     -- وزن الصنف
    @ItemQuantity Numeric(18,3),   -- كمية الصنف
    @TotalValues Numeric(18,3),    -- إجمالي القيم
    @TotalWeights Numeric(18,3),   -- إجمالي الأوزان
    @TotalQuantities Numeric(18,3),-- إجمالي الكميات
    @TotalExpenses Numeric(18,3)   -- إجمالي المصاريف (نقل + شحن + جمرك)
)
RETURNS Numeric(18,3)
AS
BEGIN
    DECLARE @Share Numeric(18,3)

    IF @DistributionType = 'VALUE'
        SET @Share = CASE 
                        WHEN @TotalValues = 0 THEN 0 
                        ELSE (@ItemValue / @TotalValues) * @TotalExpenses 
                     END

    ELSE IF @DistributionType = 'WEIGHT'
        SET @Share = CASE 
                        WHEN @TotalWeights = 0 THEN 0 
                        ELSE (@ItemWeight / @TotalWeights) * @TotalExpenses 
                     END

    ELSE IF @DistributionType = 'QUANTITY'
        SET @Share = CASE 
                        WHEN @TotalQuantities = 0 THEN 0 
                        ELSE (@ItemQuantity / @TotalQuantities) * @TotalExpenses 
                     END

    ELSE
        SET @Share = 0 -- نوع غير معروف

    RETURN ROUND(@Share, 4)
	--RETURN @Share
END

GO
/****** Object:  UserDefinedFunction [dbo].[get_PURE_PERFET]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[get_PURE_PERFET]
(
    -- Add the parameters for the function here
@D_F DATE,
@D_T DATE
)
RETURNS NVARCHAR(100)
AS
BEGIN
DECLARE @TOTAL_BERFET FLOAT,@PURE_BERFET FLOAT
--------------------------------------------------------------------------------------------مجمل الربح
SELECT @TOTAL_BERFET =  ISNULL(SUM(Total),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 1 and isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --مبيعات
SELECT @TOTAL_BERFET -=  ISNULL(SUM(Discount),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --تحفيض
SELECT @TOTAL_BERFET -=  ISNULL(SUM(PURE),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 10 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --راجع


SELECT @TOTAL_BERFET -=  ISNULL(SUM(Total),0)  FROM Agents_Balance_MV_V where isDepended = 1 And BsType_ID = 8 and isvoid  = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T  --تالف
SELECT @TOTAL_BERFET -=  ISNULL ( ( SUM(ISNULL(Cost,0) * ISNULL(QTY,0)) ) ,0 )  FROM SB_Contents where isDepended = 1 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --تكلفة مبيعات
SELECT @TOTAL_BERFET -=  ISNULL ( ( SUM(ISNULL(Cost,0) * ISNULL(QYT,0)) ) ,0 )  FROM FRM_Contents_Details where isDepended = 1 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --تكلفة مبيعات
-----------------------------------------------------------------------------------------/مجمل الربح



--------------------------------------------------------------------------------------------صافي الربح
SET @PURE_BERFET = @TOTAL_BERFET
SELECT @PURE_BERFET -=  ISNULL(SUM(Total),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 2 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --مصروفات

SELECT @PURE_BERFET -=  ISNULL(SUM(pure),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND  isVoid = 0 AND BsType_ID = 5 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --مرتبات الموظفين
-----------------------------------------------------------------------------------------/صافي الربح


RETURN  @PURE_BERFET


end








GO
/****** Object:  UserDefinedFunction [dbo].[get_TimeDuration]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[get_TimeDuration]
(
    -- Add the parameters for the function here
@Start_Time datetime

)
RETURNS NVARCHAR(100)
AS
BEGIN

DECLARE @TimeInSeconds INT , @STR_NAME NVARCHAR(100)

SET @TimeInSeconds = DATEDIFF(SECOND, @Start_Time, GETDATE()) 
SELECT @STR_NAME = 
RIGHT('0' + CAST(@TimeInSeconds / 3600 AS VARCHAR),2) + ':' +
RIGHT('0' + CAST((@TimeInSeconds / 60) % 60 AS VARCHAR),2) + ':' +
RIGHT('0' + CAST(@TimeInSeconds % 60 AS VARCHAR),2) + ' / و ' + ' يوم ' +
LEFT('0' + CAST(@TimeInSeconds  / 3600 / 24 AS VARCHAR),2) 


RETURN  @STR_NAME


end








GO
