/****** Object:  View [dbo].[TR_MV_Report_V]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[TR_MV_Report_V]
AS
SELECT        dbo.Treasury_Balance_MV_V.T_ID, dbo.Treasury_Balance_MV_V.User_ID, dbo.Treasury_Balance_MV_V.Tr_ID, dbo.TreasuryCard.Tr_Name, dbo.Treasury_Balance_MV_V.date, dbo.TreasuryBalance_Type.Type_Name, 
                         ISNULL(dbo.Treasury_Balance_MV_V.Bank_Name, N'---') AS Bank_Name, ISNULL(dbo.Treasury_Balance_MV_V.CheckNum, N'---') AS CheckNum, ISNULL(dbo.Treasury_Balance_MV_V.Debit, 0) AS Debit, 
                         ISNULL(dbo.Treasury_Balance_MV_V.Credit, 0) AS Credit, dbo.Treasury_Balance_MV_V.Balance, dbo.TreasuryBalance_Type.id AS Type_ID, dbo.Users.UserName, dbo.Treasury_Balance_MV_V.isVoid, 
                         dbo.Treasury_Balance_MV_V.notice_move, dbo.Agents.Ag_name
FROM            dbo.Agents INNER JOIN
                         dbo.Agents_Balance_MV_RCT ON dbo.Agents.AG_ID = dbo.Agents_Balance_MV_RCT.AG_ID RIGHT OUTER JOIN
                         dbo.Treasury_Balance_MV_V INNER JOIN
                         dbo.TreasuryBalance_Type ON dbo.Treasury_Balance_MV_V.Tr_Type_ID = dbo.TreasuryBalance_Type.id INNER JOIN
                         dbo.TreasuryCard ON dbo.Treasury_Balance_MV_V.Tr_ID = dbo.TreasuryCard.Tr_ID INNER JOIN
                         dbo.Users ON dbo.Treasury_Balance_MV_V.User_ID = dbo.Users.User_ID ON dbo.Agents_Balance_MV_RCT.T_ID = dbo.Treasury_Balance_MV_V.AGBalance_T_ID
GO
/****** Object:  View [dbo].[Tr_Billing_TMP_1_V]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[Tr_Billing_TMP_1_V]
AS
SELECT        Tr_ID, SUM(ISNULL(Debit, 0)) AS S_D, SUM(ISNULL(Credit, 0)) AS S_C
FROM            dbo.Treasury_Balance_MV_V
GROUP BY Tr_ID, isVoid
HAVING        (isVoid = 0)
GO
/****** Object:  View [dbo].[TR_MENU_V]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[TR_MENU_V]
AS
SELECT        dbo.TreasuryCard.Tr_ID, dbo.TreasuryCard.Tr_Name, dbo.TreasuryCard.Tr_AccountNumber, ISNULL(dbo.Tr_Billing_TMP_1_V.S_D, 0) AS T_DEBIT, ISNULL(dbo.Tr_Billing_TMP_1_V.S_C, 0) AS T_CREDIT, 
                         dbo.Tr_Billing_TMP_1_V.S_C - dbo.Tr_Billing_TMP_1_V.S_D AS T_BALANCE, ISNULL(dbo.TreasuryCard.Tree_Code, N'') AS Tree_Code
FROM            dbo.TreasuryCard LEFT OUTER JOIN
                         dbo.Tr_Billing_TMP_1_V ON dbo.TreasuryCard.Tr_ID = dbo.Tr_Billing_TMP_1_V.Tr_ID
GO
/****** Object:  View [dbo].[A_AG_B_RCT_NEW_D_C_V]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[A_AG_B_RCT_NEW_D_C_V]
AS
SELECT        dbo.Agents_Balance_MV_RCT.T_ID, dbo.Agents_Balance_MV_RCT.AG_ID, ISNULL(dbo.Agents_Balance_MV_RCT.Pure, 0) AS Pure, dbo.Agents_Balance_MV_RCT.BsType_ID, dbo.AgentBalance_Type.Balance, 
                         CASE WHEN AgentBalance_Type.Balance = 'D' THEN Pure ELSE NULL END AS DEBIT, CASE WHEN AgentBalance_Type.Balance = 'C' THEN Pure ELSE NULL END AS CREDIT
FROM            dbo.Agents_Balance_MV_RCT INNER JOIN
                         dbo.AgentBalance_Type ON dbo.Agents_Balance_MV_RCT.BsType_ID = dbo.AgentBalance_Type.id
WHERE        (dbo.Agents_Balance_MV_RCT.isDepended = 1) AND (dbo.Agents_Balance_MV_RCT.isVoid = 0)

UNION ALL

SELECT        dbo.Agents_Balance_MV_RCT.T_ID, dbo.Agents_Balance_MV_RCT.AG_ID, ISNULL(dbo.Agents_Balance_MV_RCT.Discount, 0) AS Pure, dbo.AgentBalance_Type.id AS BsType_ID , dbo.AgentBalance_Type.Balance, 
                         CASE WHEN AgentBalance_Type.Balance = 'D' THEN Discount ELSE NULL END AS DEBIT, CASE WHEN AgentBalance_Type.Balance = 'C' THEN Discount ELSE NULL END AS CREDIT
FROM            dbo.Agents_Balance_MV_RCT INNER JOIN
                         dbo.AgentBalance_Type ON dbo.Agents_Balance_MV_RCT.BsType_ID = dbo.AgentBalance_Type.Parent_ID
WHERE        (dbo.Agents_Balance_MV_RCT.isDepended = 1) AND (dbo.Agents_Balance_MV_RCT.isVoid = 0) AND ( (dbo.Agents_Balance_MV_RCT.Discount > 0) OR  (dbo.Agents_Balance_MV_RCT.Discount IS NOT NULL ) )

GO
/****** Object:  View [dbo].[Frm_Contents_Sum_V]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
