FROM            dbo.FRM_Contents_Details
GROUP BY Bill_T_ID
GO
/****** Object:  View [dbo].[A_AG_SUM_TMP_V]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [dbo].[A_AG_SUM_TMP_V]
AS

SELECT Bill_T_ID AS T_ID,SUM(T_Price) AS TOTAL FROM SB_Contents GROUP BY Bill_T_ID
UNION ALL 
SELECT Pch_T_ID AS T_ID,SUM(Total) AS TOTAL FROM Pch_Details GROUP BY Pch_T_ID
UNION ALL 
SELECT IMEX_T_ID AS T_ID,SUM(Total) AS TOTAL FROM EXP_Details GROUP BY IMEX_T_ID
UNION ALL 
SELECT T_ID,CASE WHEN TOTAL IS NULL THEN PURE ELSE TOTAL END AS TOTAL FROM Agents_Balance_MV WHERE BsType_ID = 5
UNION ALL 
SELECT T_ID,CASE WHEN TOTAL IS NULL THEN Credit ELSE TOTAL END AS TOTAL FROM Agents_Balance_MV WHERE BsType_ID = 6
UNION ALL 
SELECT IMEX_T_ID AS T_ID,SUM(Total) AS TOTAL FROM IMEX_Details GROUP BY IMEX_T_ID
UNION ALL 
SELECT Bill_T_ID AS T_ID,SUM(T_Price) AS TOTAL FROM Rtn_Contents GROUP BY Bill_T_ID
--UNION ALL 
--SELECT B_T_ID AS T_ID,SUM(Total) AS TOTAL FROM Store_Trans_Details GROUP BY B_T_ID
UNION ALL 
SELECT Bill_T_ID AS T_ID,SUM(TOTAL) AS TOTAL FROM Frm_Contents_Sum_V GROUP BY Bill_T_ID
--UNION ALL 
--SELECT Bill_T_ID AS T_ID,SUM(Cost*QYT) AS TOTAL FROM FRM_Contents_Details GROUP BY Bill_T_ID
UNION ALL 
SELECT Bill_T_ID AS T_ID,SUM(T_Price) AS TOTAL FROM ViewBill_Contents GROUP BY Bill_T_ID
UNION ALL 
SELECT InSale_T_ID AS T_ID,SUM(Total) AS TOTAL FROM InSale_Details GROUP BY InSale_T_ID
UNION ALL 
SELECT T_ID,CASE WHEN TOTAL IS NULL THEN PURE ELSE TOTAL END AS TOTAL FROM Agents_Balance_MV WHERE BsType_ID = 34
UNION ALL 
SELECT OutSale_T_ID AS T_ID,SUM(Total) AS TOTAL FROM Outsale_Details GROUP BY OutSale_T_ID
UNION ALL 
SELECT T_ID,CASE WHEN TOTAL IS NULL THEN Debit ELSE TOTAL END AS TOTAL FROM Agents_Balance_MV WHERE BsType_ID = 37
--UNION ALL 
--SELECT T_ID,TOTAL FROM Agents_Balance_MV WHERE BsType_ID = 38
--UNION ALL 
--SELECT T_ID,TOTAL FROM Agents_Balance_MV WHERE BsType_ID = 39


GO
/****** Object:  View [dbo].[A_AG_B_NEW_D_C_V]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[A_AG_B_NEW_D_C_V]
AS
SELECT        dbo.Agents_Balance_MV.T_ID, dbo.Agents_Balance_MV.AG_ID, dbo.Agents_Balance_MV.BsType_ID, dbo.AgentBalance_Type.Balance AS Balance_Type, ISNULL(dbo.A_AG_SUM_TMP_V.TOTAL, 0) AS TOTAL, 
                         ISNULL(dbo.Agents_Balance_MV.Discount, 0) AS Discount, ISNULL(dbo.A_AG_SUM_TMP_V.TOTAL, 0) - ISNULL(dbo.Agents_Balance_MV.Discount, 0) AS Pure, 
                         CASE WHEN AgentBalance_Type.Balance = 'D' THEN (ISNULL(dbo.A_AG_SUM_TMP_V.TOTAL, 0) - ISNULL(dbo.Agents_Balance_MV.Discount, 0)) ELSE NULL END AS DEBIT, 
                         CASE WHEN AgentBalance_Type.Balance = 'C' THEN (ISNULL(dbo.A_AG_SUM_TMP_V.TOTAL, 0) - ISNULL(dbo.Agents_Balance_MV.Discount, 0)) ELSE NULL END AS CREDIT
FROM            dbo.Agents_Balance_MV INNER JOIN
                         dbo.AgentBalance_Type ON dbo.Agents_Balance_MV.BsType_ID = dbo.AgentBalance_Type.id LEFT OUTER JOIN
                         dbo.A_AG_SUM_TMP_V ON dbo.Agents_Balance_MV.T_ID = dbo.A_AG_SUM_TMP_V.T_ID

GO
