CREATE VIEW [dbo].[AGENTS_Billing_TMP1_V] AS
SELECT   dbo.Agents_Balance_MV.AG_ID,ISNULL(sum(dbo.A_AG_B_NEW_D_C_V.Debit),0) AS S_D,ISNULL(sum(dbo.A_AG_B_NEW_D_C_V.Credit),0) AS S_C
FROM    dbo.Agents_Balance_MV INNER JOIN
                         dbo.A_AG_B_NEW_D_C_V ON dbo.Agents_Balance_MV.T_ID = dbo.A_AG_B_NEW_D_C_V.T_ID
WHERE Agents_Balance_MV.isDepended = 1 AND Agents_Balance_MV.isVoid = 0 --And Agents_Balance_MV.AG_ID > 1
GROUP BY dbo.Agents_Balance_MV.AG_ID

UNION

SELECT  dbo.Agents_Balance_MV_RCT.AG_ID,ISNULL(SUM(dbo.A_AG_B_RCT_NEW_D_C_V.Debit),0) AS S_D ,ISNULL(SUM(dbo.A_AG_B_RCT_NEW_D_C_V.Credit),0) AS S_C
FROM    dbo.Agents_Balance_MV_RCT  INNER JOIN
dbo.A_AG_B_RCT_NEW_D_C_V ON dbo.Agents_Balance_MV_RCT.T_ID = dbo.A_AG_B_RCT_NEW_D_C_V.T_ID

WHERE Agents_Balance_MV_RCT.isDepended = 1 AND Agents_Balance_MV_RCT.isVoid = 0  --And Agents_Balance_MV_RCT.AG_ID > 1
GROUP BY  dbo.Agents_Balance_MV_RCT.AG_ID


UNION

SELECT  dbo.AG_MV_TRANSACTION.AG_ID_FROM AS AG_ID,0 AS S_D ,ISNULL(SUM(dbo.AG_MV_TRANSACTION.VALUE),0) AS S_C
FROM    dbo.AG_MV_TRANSACTION 

WHERE  AG_MV_TRANSACTION.is_Void = 0
GROUP BY  dbo.AG_MV_TRANSACTION.AG_ID_FROM



UNION

SELECT  dbo.AG_MV_TRANSACTION.AG_ID_TO AS AG_ID,ISNULL(SUM(dbo.AG_MV_TRANSACTION.VALUE),0) AS S_D ,0 AS S_C
FROM    dbo.AG_MV_TRANSACTION 

WHERE  AG_MV_TRANSACTION.is_Void = 0
GROUP BY  dbo.AG_MV_TRANSACTION.AG_ID_TO



GO
