                         dbo.AGENTS_Billing_TMP_2_V.S_D - dbo.AGENTS_Billing_TMP_2_V.S_C AS T_BALANCE, dbo.Currency.Cr_Equal, dbo.Agents.DATE_START, dbo.Agents.Tree_Code
