CREATE VIEW [dbo].[IM_Perfet_V]
AS
SELECT        dbo.IM_Menu.item_name, dbo.Units.U_Name, dbo.SB_Contents.QTY, dbo.SB_Contents.Cost, dbo.SB_Contents.Cost * dbo.SB_Contents.QTY AS T_Cost, dbo.SB_Contents.Price, dbo.SB_Contents.T_Price, 
                         dbo.SB_Contents.Price - dbo.SB_Contents.Cost AS Perfet_ByOne, dbo.SB_Contents.T_Price - dbo.SB_Contents.Cost * dbo.SB_Contents.QTY AS Total_Perfet, ISNULL(dbo.SB_Contents.Saler_Percent, 0) AS Saler_Percent, 
                         ISNULL(((dbo.SB_Contents.Price - dbo.SB_Contents.Cost) * dbo.SB_Contents.QTY) * (dbo.SB_Contents.Saler_Percent / 100), 0) AS Saler_Money, dbo.SB_Contents.Date, dbo.SB_Contents.ST_ID, dbo.General_menu.GM_ID, 
                         ISNULL(dbo.SB_Contents.is_By_Min_SP, 0) AS is_By_Min_SP, ISNULL(dbo.SB_Contents.is_By_Min_SP_2, 0) AS is_By_Min_SP_2, ISNULL(dbo.SB_Contents.Markter_Val * dbo.SB_Contents.QTY, 0) AS Markter_Val, 
                         dbo.General_menu.Cat_ID, dbo.SB_Contents.IM_ID
FROM            dbo.SB_Contents INNER JOIN
                         dbo.IM_Menu ON dbo.SB_Contents.IM_ID = dbo.IM_Menu.IM_ID INNER JOIN
                         dbo.Units ON dbo.SB_Contents.U_ID = dbo.Units.U_ID INNER JOIN
                         dbo.General_menu ON dbo.IM_Menu.GM_ID = dbo.General_menu.GM_ID
WHERE        (dbo.SB_Contents.isDepended = 1)

GO
