CREATE VIEW [dbo].[ST_Balance_TMP1_Negitave_V] AS
--'A1' AS T_ID,
SELECT  A1.DATE,A1.IM_ID,A1.ST_ID,A1.D_Vaild,ISNULL(sum(A1.ST_QTY)*-1,0) AS QTY
FROM    SB_Contents A1 WHERE A1.isDepended = 1 
GROUP BY A1.IM_ID , A1.ST_ID , A1.D_Vaild,A1.DATE --,T_ID

UNION ALL

--'A2' AS T_ID,
SELECT   A2.DATE,A2.IM_ID,A2.ST_ID,A2.D_Vaild,ISNULL(sum(A2.ST_QTY)*-1,0) AS QTY
FROM    Rtn_Contents A2 WHERE A2.isDepended = 1  and A2.Rtn_Type_ID = 7  
GROUP BY A2.IM_ID , A2.ST_ID , A2.D_Vaild,A2.DATE --,T_ID


UNION ALL

--'A3' AS T_ID,
SELECT   A3.DATE,A3.IM_ID,A3.ST_f_ID,A3.D_Vaild,ISNULL(sum(A3.ST_QTY)*-1,0) AS QTY
FROM    Store_Trans_Details A3 WHERE A3.isDepended = 1  
GROUP BY A3.IM_ID , A3.ST_f_ID , A3.D_Vaild,A3.DATE --,T_ID


UNION ALL

--'A4' AS T_ID,
SELECT   A4.DATE,A4.IM_ID,A4.ST_ID,A4.D_Vaild,ISNULL(sum(A4.ST_QTY)*-1,0) AS QTY
FROM   IMEX_Details A4 WHERE A4.isDepended = 1  
GROUP BY A4.IM_ID , A4.ST_ID , A4.D_Vaild,A4.DATE --,T_ID

UNION ALL

--'A5' AS T_ID,
SELECT  A5.DATE,A5.IM_ID, A5.ST_ID, A5.D_Vaild,ISNULL(sum( A5.ST_QTY)*-1,0) AS QTY
FROM    InSale_Details  A5 WHERE  A5.isDepended = 1  
GROUP BY  A5.IM_ID ,  A5.ST_ID ,  A5.D_Vaild , A5.DATE --,T_ID

UNION ALL

--'A6' AS T_ID,
SELECT    A6.DATE,A6.IM_ID, A6.ST_ID, A6.D_Vaild,ISNULL(sum( A6.ST_QTY)*-1,0) AS QTY
FROM    FRM_Contents_Details  A6 WHERE  A6.isDepended = 1 --and is_not_Qty <> 1  
GROUP BY  A6.IM_ID ,  A6.ST_ID ,  A6.D_Vaild , A6.DATE --,T_ID

UNION ALL

--'A7' AS T_ID,
SELECT    A7.DATE,A7.Struct_ID AS IM_ID, A7.ST_ID,'' AS D_Vaild,ISNULL(sum(A7.ST_QTY)*-1,0) AS QTY
FROM    SB_Contents_Structers A7 WHERE A7.isDepended = 1  --AND Struct_ID = 29
GROUP BY A7.Struct_ID , A7.ST_ID , A7.DATE--,T_ID

UNION ALL

--'A8' AS T_ID,
SELECT   A8.DATE,A8.IM_ID,A8.ST_ID,A8.Valid_D,ISNULL(sum(A8.ST_QTY),0) AS QTY
FROM    ST_QTY_Deferences A8 WHERE   A8.ST_QTY < 0  
GROUP BY    A8.IM_ID ,   A8.ST_ID,A8.Valid_D , A8.DATE--,T_ID

GO
/****** Object:  View [dbo].[ST_Balance_TMP1_Plus_V]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [dbo].[ST_Balance_TMP1_Plus_V] AS

--'B1' as T_ID,
SELECT   A.DATE,A.IM_ID,A.ST_ID,A.D_Vaild,ISNULL(sum(A.ST_QTY),0) AS QTY
FROM    Pch_Details A WHERE A.isDepended = 1
GROUP BY A.IM_ID , A.ST_ID , A.D_Vaild,A.DATE  --,T_ID

UNION ALL

--'B2' AS T_ID,
SELECT   B.DATE,B.IM_ID,B.ST_ID,B.D_Vaild,ISNULL(sum(B.ST_QTY),0) AS QTY
FROM    Rtn_Contents B WHERE B.isDepended = 1  and B.Rtn_Type_ID = 1
GROUP BY B.IM_ID , B.ST_ID , B.D_Vaild,B.DATE --, T_ID

UNION ALL

--'B3' AS T_ID,
SELECT   C.DATE,C.IM_ID, C.ST_To_ID, C.D_Vaild,ISNULL(sum( C.ST_QTY),0) AS QTY
FROM    Store_Trans_Details  C WHERE  C.isDepended = 1
GROUP BY  C.IM_ID ,  C.ST_To_ID ,  C.D_Vaild,C.DATE--,T_ID

UNION ALL

--'B4' AS T_ID,
SELECT   D.DATE,D.IM_ID,D.ST_ID,D.D_Vaild,ISNULL(sum(D.ST_QTY),0) AS QTY
FROM   FRM_Details D WHERE D.isDepended = 1
GROUP BY D.IM_ID , D.ST_ID , D.D_Vaild,D.DATE--,T_ID

UNION ALL

--'B5' AS T_ID,
SELECT   E.DATE,E.IM_ID,E.ST_ID,E.D_Vaild,ISNULL(sum(E.ST_QTY),0) AS QTY
FROM    Outsale_Details E WHERE E.isDepended = 1
GROUP BY E.IM_ID , E.ST_ID , E.D_Vaild,T_ID,E.DATE

UNION ALL

--'B6' AS T_ID,
SELECT   F.DATE,F.IM_ID,F.ST_ID,F.Valid_D,ISNULL(sum(F.ST_QTY),0) AS QTY
FROM    ST_QTY_Deferences F WHERE F.ST_QTY > 0
GROUP BY F.IM_ID , F.ST_ID ,F.Valid_D,F.DATE--,T_ID

GO
