CREATE VIEW [dbo].[ST_Balance_TMP2_QTY_V] AS

select DATE,IM_ID, ST_ID,D_Vaild, ISNULL(sum(QTY),0) AS QTY

from ((select CONVERT(DATE,DATE) AS DATE,IM_ID, ST_ID,D_Vaild, convert(numeric(18,3),sum(QTY)) as qty
       from ST_Balance_TMP1_Plus_V group by IM_ID, ST_ID,D_Vaild,CONVERT(DATE,DATE)
      ) union all
      (select CONVERT(DATE,DATE) AS DATE,IM_ID, ST_ID,D_Vaild, convert(numeric(18,3),sum(QTY)) as qty
       from ST_Balance_TMP1_Negitave_V  group by IM_ID, ST_ID,D_Vaild,CONVERT(DATE,DATE)
      )
     ) t12
	      
group by IM_ID, ST_ID,D_Vaild,DATE;





