CREATE VIEW [dbo].[IM_STORE_View]
AS
SELECT        dbo.IM_Menu.IM_ID, dbo.IM_Menu.item_name, dbo.Units_V.U_Name, IM_Units_1.is_Default, (dbo.IM_Menu.Cost * dbo.Units_V.U_Cargo) * (dbo.ST_Balance_V.QTY / dbo.Units_V.U_Cargo) AS T_Cost, dbo.Stores.St_Name, 
                         dbo.General_menu.GM_Name, dbo.IM_Menu.Cost * dbo.Units_V.U_Cargo AS Cost, FORMAT(CAST(dbo.IM_Menu.Last_Pch_Cargo * dbo.Units_V.U_Cargo AS REAL), '') AS Last_Pch_Price, dbo.IM_Menu.GM_ID, dbo.Stores.ST_ID, 
                         dbo.IM_Menu.IM_Num, IM_Units_1.Barcode, dbo.ST_Balance_V.D_Vaild AS D_Valid, dbo.ST_Balance_V.QTY / dbo.Units_V.U_Cargo AS QTY, dbo.Pch_Details.T_ID, FORMAT(CAST(IM_Units_1.Price AS REAL), '') AS Price, 
                         IM_Units_1.U_ID, dbo.IM_CAT.ID AS IM_CAT_ID, dbo.ST_Balance_V.QTY / dbo.Units_V.U_Cargo * IM_Units_1.Price AS Sum_Sales, FORMAT(CAST(IM_Units_1.Min_SP AS REAL), '') AS Min_SP, 
                         FORMAT(CAST(IM_Units_1.Min_SP_2 AS REAL), '') AS Min_SP_2, dbo.ST_Balance_V.QTY AS ST_QTY, dbo.Units_V.U_Cargo
FROM            dbo.IM_Menu LEFT OUTER JOIN
                         dbo.IM_Units AS IM_Units_1 INNER JOIN
                         dbo.Units_V ON IM_Units_1.U_ID = dbo.Units_V.U_ID ON dbo.IM_Menu.IM_ID = IM_Units_1.IM_ID LEFT OUTER JOIN
                         dbo.Stores INNER JOIN
                         dbo.ST_Balance_V ON dbo.Stores.ST_ID = dbo.ST_Balance_V.ST_ID ON dbo.IM_Menu.IM_ID = dbo.ST_Balance_V.IM_ID LEFT OUTER JOIN
                         dbo.General_menu ON dbo.IM_Menu.GM_ID = dbo.General_menu.GM_ID LEFT OUTER JOIN
                         dbo.IM_CAT ON dbo.General_menu.Cat_ID = dbo.IM_CAT.ID LEFT OUTER JOIN
                         dbo.Pch_Details ON dbo.IM_Menu.IM_ID = dbo.Pch_Details.IM_ID AND dbo.IM_Menu.Last_PchT_ID = dbo.Pch_Details.T_ID
WHERE        (dbo.IM_Menu.isStore = 1) AND (IM_Units_1.is_Default = 1) OR
                         (dbo.IM_Menu.isStore = 2)
GO
