SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO















CREATE VIEW [dbo].[ALL_BALANCES_TMP_1_V]
AS

  SELECT 
       [Tree_Code]  AS Tree_Code  
       ,[Tr_Name]  AS B_NAME
      ,ISNULL([T_DEBIT],0) AS [T_DEBIT]
      ,ISNULL([T_CREDIT],0) AS [T_CREDIT]
      ,ISNULL([T_BALANCE],0) AS [T_BALANCE]

	  ,CASE WHEN (  ISNULL([T_CREDIT],0) - ISNULL([T_DEBIT],0)   ) > 0 THEN  (  ISNULL([T_CREDIT],0) - ISNULL([T_DEBIT],0)   ) ELSE    '0'       END AS T_CREDIT_1
	  ,CASE WHEN (  ISNULL([T_CREDIT],0) - ISNULL([T_DEBIT],0)   ) < 0 THEN  (  ISNULL([T_CREDIT],0) - ISNULL([T_DEBIT],0)   ) ELSE      '0'      END  AS T_DEBIT_1

	  --,CASE WHEN ISNULL([T_BALANCE],0) < 0 THEN '0' ELSE        ISNULL([T_BALANCE],0)          END AS T_CREDIT_1
	  --,CASE WHEN ISNULL([T_BALANCE],0) > 0 THEN '0' ELSE        ISNULL([T_BALANCE],0)          END AS T_DEBIT_1
  FROM [dbo].[TR_MENU_V]
  UNION ALL
  SELECT   
        [Tree_Code] AS Tree_Code 
       ,[Ag_name] AS B_NAME
      ,ISNULL([T_DEBIT],0) AS [T_DEBIT]
      ,ISNULL([T_CREDIT],0) AS [T_CREDIT]
      ,ISNULL([T_BALANCE],0) AS [T_BALANCE]

	  ,CASE WHEN (  ISNULL([T_CREDIT],0) - ISNULL([T_DEBIT],0)   ) > 0 THEN  (  ISNULL([T_CREDIT],0) - ISNULL([T_DEBIT],0)   ) ELSE    '0'       END AS T_CREDIT_1
	  ,CASE WHEN (  ISNULL([T_CREDIT],0) - ISNULL([T_DEBIT],0)   ) < 0 THEN  (  ISNULL([T_CREDIT],0) - ISNULL([T_DEBIT],0)   ) ELSE      '0'      END  AS T_DEBIT_1
	  --,CASE WHEN ISNULL([T_BALANCE],0) > 0 THEN '0' ELSE       ISNULL([T_BALANCE],0)             END AS T_CREDIT_1
	  --,CASE WHEN ISNULL([T_BALANCE],0) < 0 THEN '0' ELSE       ISNULL([T_BALANCE],0)             END AS T_DEBIT_1
  FROM [dbo].[AGENTS_MENU_V]

  -----------------------------------------------------------------------------------------
  UNION ALL


  SELECT (SELECT ISNULL(TREE_CODE,'') FROM Agent_Balance_Tree WHERE T_ID = 1 )  AS Tree_Code 
  ,'حساب إجمالي المبيعات' AS B_NAME
  ,ISNULL(SUM(TOTAL),0) AS [T_DEBIT]
  ,0 AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  , 0 AS T_CREDIT_1
  ,ISNULL(SUM(TOTAL),0) AS T_DEBIT_1

  FROM Agents_Balance_MV_V WHERE BsType_ID = 1 AND isDepended = 1 AND isVoid = 0

  -----------------------------------------------------------------------------------------

    UNION ALL

  SELECT (SELECT ISNULL(TREE_CODE,'') FROM Agent_Balance_Tree WHERE T_ID = 3 )  AS Tree_Code 
  ,'حساب إجمالي المشتريات' AS B_NAME
  ,0 AS [T_DEBIT]
  ,ISNULL(SUM(TOTAL),0) AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  , ISNULL(SUM(TOTAL),0) AS T_CREDIT_1
  ,0 AS T_DEBIT_1

  FROM Agents_Balance_MV_V WHERE BsType_ID = 7 AND isDepended = 1 AND isVoid = 0

    -----------------------------------------------------------------------------------------

    UNION ALL

  SELECT (SELECT ISNULL(TREE_CODE,'') FROM Agent_Balance_Tree WHERE T_ID = 2 )  AS Tree_Code 
  ,'حساب المصروفات' AS B_NAME
  ,0 AS [T_DEBIT]
  ,ISNULL(SUM(TOTAL),0) AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  , ISNULL(SUM(TOTAL),0) AS T_CREDIT_1
  ,0 AS T_DEBIT_1

  FROM Agents_Balance_MV_V WHERE BsType_ID = 2 AND isDepended = 1 AND isVoid = 0


      -----------------------------------------------------------------------------------------

    UNION ALL

  SELECT (SELECT ISNULL(TREE_CODE,'') FROM Agent_Balance_Tree WHERE T_ID = 4 )  AS Tree_Code 
  ,'حساب تخفيض المبيعات' AS B_NAME
  ,0 AS [T_DEBIT]
  ,ISNULL(SUM(Discount),0) AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  , ISNULL(SUM(Discount),0) AS T_CREDIT_1
  ,0 AS T_DEBIT_1

  FROM Agents_Balance_MV_V WHERE BsType_ID = 1 AND isDepended = 1 AND isVoid = 0


        -----------------------------------------------------------------------------------------

    UNION ALL

  SELECT (SELECT ISNULL(TREE_CODE,'') FROM Agent_Balance_Tree WHERE T_ID = 5 )  AS Tree_Code 
  ,(SELECT ISNULL(B_NAME,'') FROM Agent_Balance_Tree WHERE T_ID = 5 ) AS B_NAME
  ,ISNULL(SUM(Discount),0) AS [T_DEBIT]
  ,0 AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  , 0 AS T_CREDIT_1
  ,ISNULL(SUM(Discount),0) AS T_DEBIT_1

  FROM Agents_Balance_MV_V WHERE BsType_ID = 7 AND isDepended = 1 AND isVoid = 0


    -----------------------------------------------------------------------------------------
  UNION ALL

  SELECT (SELECT ISNULL(TREE_CODE,'') FROM Agent_Balance_Tree WHERE T_ID = 6 )  AS Tree_Code 
  ,'حساب راجع المبيعات' AS B_NAME
  ,0 AS [T_DEBIT]
  ,ISNULL(SUM(TOTAL),0) AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  , ISNULL(SUM(TOTAL),0) AS T_CREDIT_1
  ,0 AS T_DEBIT_1

  FROM Agents_Balance_MV_V WHERE BsType_ID = 10 AND isDepended = 1 AND isVoid = 0


          -----------------------------------------------------------------------------------------


		      UNION ALL

  SELECT 0,'حساب تكلفة راجع المبيعات' AS B_NAME
  ,SUM(COST * QTY) AS [T_DEBIT]
  ,0 AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  ,0 AS T_CREDIT_1
  ,SUM(COST * QTY) AS T_DEBIT_1

  FROM Rtn_Contents WHERE  isDepended = 1 


    UNION ALL

  SELECT (SELECT ISNULL(TREE_CODE,'') FROM Agent_Balance_Tree WHERE T_ID = 7 )  AS Tree_Code 
  ,'حساب راجع المشتريات' AS B_NAME
  ,ISNULL(SUM(TOTAL),0) AS [T_DEBIT]
  ,0 AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  , 0 AS T_CREDIT_1
  ,ISNULL(SUM(TOTAL),0) AS T_DEBIT_1

  FROM Agents_Balance_MV_V WHERE BsType_ID = 11 AND isDepended = 1 AND isVoid = 0


  
      UNION ALL

   SELECT (SELECT ISNULL(TREE_CODE,'') FROM Agent_Balance_Tree WHERE T_ID = 8 )  AS Tree_Code 
  , 'حساب المرتبات' AS B_NAME
  ,0 AS [T_DEBIT]
  ,ISNULL(SUM(TOTAL),0) AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  , ISNULL(SUM(TOTAL),0) AS T_CREDIT_1
  ,0 AS T_DEBIT_1

  FROM Agents_Balance_MV_V WHERE BsType_ID = 5 AND isDepended = 1 AND isVoid = 0



        UNION ALL

   SELECT (SELECT ISNULL(TREE_CODE,'') FROM Agent_Balance_Tree WHERE T_ID = 9 )  AS Tree_Code 
  , 'حساب المخزون' AS B_NAME

  ,0 AS [T_DEBIT]
  ,ISNULL(SUM(T_Cost),0) AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  , ISNULL(SUM(T_Cost),0) AS T_CREDIT_1
  ,0 AS T_DEBIT_1


  FROM IM_STORE_View 



          UNION ALL

   SELECT (SELECT ISNULL(TREE_CODE,'') FROM Agent_Balance_Tree WHERE T_ID = 10 )  AS Tree_Code 
  , 'حساب تكلفة المبيعات' AS B_NAME
  ,ISNULL(SUM(T_Cost),0) AS [T_DEBIT]
  ,0 AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  , 0 AS T_CREDIT_1
  ,ISNULL(SUM(T_Cost),0) AS T_DEBIT_1

  FROM IM_Perfet_V 


            UNION ALL

   SELECT (SELECT ISNULL(TREE_CODE,'') FROM Agent_Balance_Tree WHERE T_ID = 11 )  AS Tree_Code 
  , 'حساب المخزون أول المدة' AS B_NAME
  ,ISNULL(SUM(TOTAL),0) AS [T_DEBIT]
  ,0 AS [T_CREDIT]
  ,0 AS [T_BALANCE]

  , 0 AS T_CREDIT_1
  ,ISNULL(SUM(TOTAL),0) AS T_DEBIT_1

  FROM  Pch_Details WHERE isDepended = 1 AND Pch_T_ID IN (SELECT T_ID FROM Agents_Balance_MV WHERE BsType_ID = 9 AND isDepended = 1 AND isVoid = 0)



GO
