                         ISNULL(dbo.Agents_Balance_MV_RCT.ReferNum, N'---') AS ReferNum, ISNULL(dbo.Agents_Balance_MV_RCT.Receipt_Title, N'---') AS Receipt_Title, ISNULL(dbo.A_AG_B_RCT_NEW_D_C_V.DEBIT, 0) AS Debit, 
                         ISNULL(dbo.A_AG_B_RCT_NEW_D_C_V.CREDIT, 0) AS Credit, ISNULL(dbo.Agents_Balance_MV_RCT.Balance, 0) AS Balance, dbo.Users.UserName, dbo.Users.User_ID, dbo.Agents_Balance_MV_RCT.isVoid, 
                         ISNULL(dbo.Agents_Balance_MV_RCT.Debit_2, 0) AS Debit_2, ISNULL(dbo.Agents_Balance_MV_RCT.Credit_2, 0) AS Credit_2, ISNULL(dbo.Agents_Balance_MV_RCT.Balance_2, 0) AS Balance_2, 
                         dbo.Agents_Balance_MV_RCT.Receipt_Num
