CREATE VIEW [dbo].[IM_MaxAlert_V]
AS
SELECT        dbo.IM_Menu.IM_ID, dbo.IM_QTY_ALERT.ST_ID, dbo.Stores.St_Name, dbo.IM_Menu.item_name, dbo.Units.U_Name, dbo.ST_Balance_V.QTY / dbo.Units.U_Cargo AS QTY, 
                         dbo.IM_QTY_ALERT.MAX_QTY AS IM_QTY_ALERT_ST
FROM            dbo.Stores INNER JOIN
                         dbo.IM_QTY_ALERT ON dbo.Stores.ST_ID = dbo.IM_QTY_ALERT.ST_ID INNER JOIN
                         dbo.ST_Balance_V INNER JOIN
                         dbo.IM_Menu ON dbo.ST_Balance_V.IM_ID = dbo.IM_Menu.IM_ID INNER JOIN
                         dbo.IM_Units ON dbo.IM_Menu.IM_ID = dbo.IM_Units.IM_ID INNER JOIN
                         dbo.Units ON dbo.IM_Units.U_ID = dbo.Units.U_ID ON dbo.IM_QTY_ALERT.ST_ID = dbo.ST_Balance_V.ST_ID AND dbo.IM_QTY_ALERT.IM_ID = dbo.IM_Menu.IM_ID
WHERE        (dbo.IM_Units.is_Default = 1) AND (dbo.IM_Menu.isStore = 1) OR
                         (dbo.IM_Menu.isStore = 2)
GROUP BY dbo.ST_Balance_V.QTY / dbo.Units.U_Cargo, dbo.Units.U_Name, dbo.IM_Menu.item_name, dbo.IM_Menu.IM_ID, dbo.Stores.St_Name, dbo.IM_QTY_ALERT.ST_ID, dbo.IM_QTY_ALERT.MAX_QTY



















