FROM            dbo.Agents_Balance_MV INNER JOIN
                         dbo.SB_Contents ON dbo.Agents_Balance_MV.T_ID = dbo.SB_Contents.Bill_T_ID
GROUP BY dbo.Agents_Balance_MV.Table_ID, dbo.Agents_Balance_MV.isDepended, dbo.Agents_Balance_MV.isVoid, dbo.Agents_Balance_MV.isPied
HAVING        (dbo.Agents_Balance_MV.isDepended = 1) AND (dbo.Agents_Balance_MV.isVoid = 0) AND (dbo.Agents_Balance_MV.Table_ID IS NOT NULL) AND (dbo.Agents_Balance_MV.isPied = 0)
GO
