                         dbo.Agents_Balance_MV.S_Bill_Pr_ID, dbo.Agents_Balance_MV.BsType_ID, dbo.Agents_Balance_MV.Date, dbo.Agents_Balance_MV.isPied, dbo.Agents_Balance_MV.Total, dbo.Agents_Balance_MV.Discount, 
                         dbo.Agents_Balance_MV.Pure
FROM            dbo.Agents_Balance_MV LEFT OUTER JOIN
