/****** Object:  View [dbo].[V_ProjectSummary]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[V_ProjectSummary]
AS
SELECT        P.ProjectId, P.ProjectCode, P.ProjectName, SUM(CASE WHEN A.BsType_ID = 7 THEN A.Pure ELSE 0 END) AS PurchaseCost, SUM(CASE WHEN A.BsType_ID = 2 THEN A.Pure ELSE 0 END) AS ExpenseCost, 
                         SUM(CASE WHEN A.BsType_ID = 1 THEN A.Pure ELSE 0 END) AS SalesValue, SUM(CASE WHEN A.BsType_ID = 7 THEN A.Pied ELSE 0 END) AS PurchasePaid, SUM(CASE WHEN A.BsType_ID = 2 THEN A.Pied ELSE 0 END) 
                         AS ExpensePaid, SUM(CASE WHEN A.BsType_ID = 1 THEN A.Pied ELSE 0 END) AS SalesReceived, SUM(CASE WHEN A.BsType_ID = 7 THEN (A.Pure - A.Pied) ELSE 0 END) AS PurchaseRest, 
                         SUM(CASE WHEN A.BsType_ID = 2 THEN (A.Pure - A.Pied) ELSE 0 END) AS ExpenseRest, SUM(CASE WHEN A.BsType_ID = 1 THEN (A.Pure - A.Pied) ELSE 0 END) AS SalesRest, 
                         SUM(CASE WHEN A.BsType_ID = 1 THEN A.Pure ELSE 0 END) - (SUM(CASE WHEN A.BsType_ID = 7 THEN A.Pure ELSE 0 END) + SUM(CASE WHEN A.BsType_ID = 2 THEN A.Pure ELSE 0 END)) AS Profit, P.CreatedDate
FROM            dbo.Projects AS P LEFT OUTER JOIN
                         dbo.ProjectDocuments AS PD ON PD.ProjectId = P.ProjectId LEFT OUTER JOIN
                         dbo.Agents_Balance_MV AS A ON A.T_ID = PD.T_ID
GROUP BY P.ProjectId, P.ProjectCode, P.ProjectName, P.CreatedDate
GO
/****** Object:  View [dbo].[V_ProjectPartnersSummary]    Script Date: 09/05/2026 16:40:09 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  VIEW [dbo].[V_ProjectPartnersSummary]
AS
SELECT
    PP.ProjectPartnerId,
    PP.ProjectId,
    PRJ.ProjectCode,
    PRJ.ProjectName,
    P.PartnerId,
    P.PartnerName,
    P.DefaultSharePercent,
    PP.SharePercent,
    ISNULL(VS.Profit, 0) AS ProjectProfit,
    (ISNULL(VS.Profit, 0) * PP.SharePercent / 100.0) AS PartnerProfit,
    PP.Notes
FROM dbo.ProjectPartners PP
INNER JOIN dbo.Projects PRJ
    ON PRJ.ProjectId = PP.ProjectId
INNER JOIN dbo.Partners P
    ON P.PartnerId = PP.PartnerId
LEFT JOIN dbo.V_ProjectSummary VS
    ON VS.ProjectId = PP.ProjectId;
GO
