CREATE VIEW [dbo].[ST_Balance_TMP_Plus_Negitave_2_V]
AS
SELECT        dbo.ST_Balance_TMP_Plus_Negitave_V.Bill_T_ID, dbo.ST_Balance_TMP_Plus_Negitave_V.ST_ID, CONVERT(DATE, dbo.ST_Balance_TMP_Plus_Negitave_V.DATE) AS DATE, 
                         SUM(dbo.ST_Balance_TMP_Plus_Negitave_V.T_COST) AS T_COST, dbo.Stores.Tree_Code AS ACC_CODE
