GROUP BY CONVERT(DATE, dbo.ST_Balance_TMP_Plus_Negitave_V.DATE), dbo.IM_Menu.isStore, dbo.ST_Balance_TMP_Plus_Negitave_V.Bill_T_ID, dbo.ST_Balance_TMP_Plus_Negitave_V.ST_ID, dbo.Stores.Tree_Code
HAVING        (dbo.IM_Menu.isStore = 1) OR
                         (dbo.IM_Menu.isStore = 2)
