CREATE VIEW [dbo].[Pr_CASH_OUT_TMP_V]
AS
SELECT        Pr_ID, SUM(Pure) AS CASH_OUT
FROM            dbo.Agents_Balance_MV_RCT
GROUP BY Pr_ID, BsType_ID, isDepended, isVoid
HAVING        (BsType_ID = 4) AND (isDepended = 1) AND (isVoid = 0)
GO
