CREATE VIEW [dbo].[Periods_ALL_V]
AS
SELECT        dbo.Users.User_ID, dbo.Users.UserName, dbo.Periods.Pr_ID, dbo.Periods.Pr_Start, dbo.Periods.Pr_End, dbo.Periods.NotesOn_Start, dbo.Periods.NotesOn_End, dbo.Periods.AG_Counter, dbo.Pr_CASH_IN_TMP_V.CASH_IN, 
                         dbo.Pr_CASH_OUT_TMP_V.CASH_OUT, dbo.Periods.Debit, dbo.Tables_Flate.Flate_Name
						 , CONCAT(DATEDIFF(Minute, dbo.Periods.Pr_Start, dbo.Periods.Pr_End) / 60, ':', DATEDIFF(Minute, dbo.Periods.Pr_Start, dbo.Periods.Pr_End) % 60) AS WORK_TIME
FROM            dbo.Periods INNER JOIN
                         dbo.Users ON dbo.Periods.User_ID = dbo.Users.User_ID LEFT OUTER JOIN
                         dbo.Tables_Flate ON dbo.Periods.TB_Flate_ID = dbo.Tables_Flate.Flate_ID LEFT OUTER JOIN
                         dbo.Pr_CASH_IN_TMP_V ON dbo.Periods.Pr_ID = dbo.Pr_CASH_IN_TMP_V.Pr_ID LEFT OUTER JOIN
                         dbo.Pr_CASH_OUT_TMP_V ON dbo.Periods.Pr_ID = dbo.Pr_CASH_OUT_TMP_V.Pr_ID
