CREATE VIEW [dbo].[ACC_BALANCE_V]
AS
SELECT        dbo.ACC_BALANCE.T_ID, dbo.ACC_BALANCE_MASTER.T_ID AS B_T_ID, dbo.ACC_BALANCE.DATE_IN, dbo.ACC_BALANCE.ACC_CODE, dbo.ACC_BALANCE.DEBIT, dbo.ACC_BALANCE.CREDIT, dbo.ACC_BALANCE.USER_ID, 
                         dbo.ACC_BALANCE.IS_VOID, dbo.ACC_BALANCE.Currency, dbo.ACC_BALANCE.Notes, dbo.ACCOUNTS_TREE.ACC_NAME, dbo.ACC_BALANCE_MASTER.DATE, dbo.ACC_BALANCE_MASTER.NOTES AS MASTER_NOTES, 
                         dbo.ACCOUNTS_TREE.ACC_LEVEL, ISNULL(dbo.ACC_BALANCE.DEBIT, 0) - ISNULL(dbo.ACC_BALANCE.CREDIT, 0) AS BALANCE, dbo.ACC_BALANCE.Bill_Num, dbo.ACC_BALANCE.COST_ID, dbo.COST_CENTER.COST_NAME, 
                         dbo.ACCOUNTS_TREE.ACC_PARENT, dbo.Currency.Cr_Name, dbo.ACC_BALANCE_MASTER.Currency_Equal, CASE WHEN dbo.ACC_BALANCE.is_Depended = 0 THEN 'القيـــد غير معتمد' ELSE 'القيـــد مـعتمد' END AS ACC_Depend_Status, 
                         dbo.ACC_BALANCE.is_Depended, dbo.ACC_BALANCE_MASTER.Currency_ID, USERS_1.UserName, ISNULL(dbo.USERS.UserName, N'(غير معتمد)') AS USER_DEPENDED, ISNULL(dbo.ACC_BALANCE_MASTER.Receipt_Num, '') 
                         AS Receipt_Num, dbo.ACC_BALANCE_MASTER.Bank_Name, dbo.ACC_BALANCE_MASTER.Check_Number, dbo.ACC_BALANCE_MASTER.Receipt_Type, dbo.ACC_BALANCE_MASTER.JournalNumber, 
                         dbo.ACC_BALANCE_MASTER.BankTransactionNumber
FROM            dbo.ACC_BALANCE INNER JOIN
                         dbo.ACCOUNTS_TREE ON dbo.ACC_BALANCE.ACC_CODE = dbo.ACCOUNTS_TREE.ACC_CODE LEFT OUTER JOIN
                         dbo.Currency ON dbo.ACC_BALANCE.Currency = dbo.Currency.Cr_ID LEFT OUTER JOIN
                         dbo.ACC_BALANCE_MASTER ON dbo.ACC_BALANCE.B_T_ID = dbo.ACC_BALANCE_MASTER.T_ID LEFT OUTER JOIN
                         dbo.USERS ON dbo.ACC_BALANCE_MASTER.DEPEND_USER_ID = dbo.USERS.User_ID LEFT OUTER JOIN
                         dbo.USERS AS USERS_1 ON dbo.ACC_BALANCE_MASTER.USER_ID = USERS_1.User_ID LEFT OUTER JOIN
                         dbo.COST_CENTER ON dbo.ACC_BALANCE.COST_ID = dbo.COST_CENTER.COST_ID
GO
