CREATE VIEW [dbo].[SALES_SYSTEM_BALANCES_V]
AS
SELECT        dbo.SALES_SYSTEM_BALANCES.Tran_ID, dbo.SALES_SYSTEM_BALANCES.DATE, dbo.SALES_SYSTEM_BALANCES.Bill_Num, dbo.SALES_SYSTEM_BALANCES.CREDIT AS ACC_CODE, 
                        dbo.ACCOUNTS_TREE.ACC_NAME,  dbo.SALES_SYSTEM_BALANCES.AMOUNT AS CREDIT, NULL AS DEBIT, dbo.ACCOUNTS_TREE.ACC_LEVEL, dbo.ACCOUNTS_TREE.ACC_PARENT
FROM            dbo.SALES_SYSTEM_BALANCES INNER JOIN
                         dbo.ACCOUNTS_TREE ON dbo.SALES_SYSTEM_BALANCES.CREDIT = dbo.ACCOUNTS_TREE.ACC_CODE
                         WHERE dbo.SALES_SYSTEM_BALANCES.CREDIT > 0

		
						 						 UNION ALL

SELECT        dbo.SALES_SYSTEM_BALANCES.Tran_ID, dbo.SALES_SYSTEM_BALANCES.DATE, dbo.SALES_SYSTEM_BALANCES.Bill_Num, dbo.SALES_SYSTEM_BALANCES.DEBIT AS ACC_CODE, 
                          dbo.ACCOUNTS_TREE.ACC_NAME,NULL AS CREDIT, dbo.SALES_SYSTEM_BALANCES.AMOUNT AS DEBIT, dbo.ACCOUNTS_TREE.ACC_LEVEL, dbo.ACCOUNTS_TREE.ACC_PARENT
FROM            dbo.SALES_SYSTEM_BALANCES INNER JOIN
                         dbo.ACCOUNTS_TREE ON dbo.SALES_SYSTEM_BALANCES.DEBIT = dbo.ACCOUNTS_TREE.ACC_CODE
                         WHERE dbo.SALES_SYSTEM_BALANCES.DEBIT > 0



						                    UNION ALL

											SELECT        dbo.AssetJournalEntries.ID, dbo.AssetJournalEntries.EntryDate AS DATE, dbo.AssetJournalEntries.NOTES AS Bill_Num, dbo.AssetJournalEntries.CreditAccount AS ACC_CODE, 
                        dbo.ACCOUNTS_TREE.ACC_NAME,  dbo.AssetJournalEntries.Amount AS CREDIT, NULL AS DEBIT, dbo.ACCOUNTS_TREE.ACC_LEVEL, dbo.ACCOUNTS_TREE.ACC_PARENT
FROM            dbo.AssetJournalEntries INNER JOIN
                         dbo.ACCOUNTS_TREE ON dbo.AssetJournalEntries.CreditAccount = dbo.ACCOUNTS_TREE.ACC_CODE
                         WHERE dbo.AssetJournalEntries.Amount > 0

		
						 						 UNION ALL

SELECT        dbo.AssetJournalEntries.ID, dbo.AssetJournalEntries.EntryDate AS DATE, dbo.AssetJournalEntries.NOTES AS Bill_Num, dbo.AssetJournalEntries.DebitAccount AS ACC_CODE, 
                          dbo.ACCOUNTS_TREE.ACC_NAME,NULL AS CREDIT, dbo.AssetJournalEntries.Amount AS DEBIT, dbo.ACCOUNTS_TREE.ACC_LEVEL, dbo.ACCOUNTS_TREE.ACC_PARENT
FROM            dbo.AssetJournalEntries INNER JOIN
                         dbo.ACCOUNTS_TREE ON dbo.AssetJournalEntries.DebitAccount = dbo.ACCOUNTS_TREE.ACC_CODE
                         WHERE dbo.AssetJournalEntries.Amount > 0


GO
