/****** Object:  View [dbo].[ACC_Billing_TMP_2_V]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[ACC_Billing_TMP_2_V] AS

WITH  cte AS (
        SELECT 
		t.*, 
		t.ACC_CODE AS root
          FROM ACCOUNTS_TREE AS t
         UNION ALL
        SELECT
		t.*, 
		t0.root
          FROM cte AS t0
          JOIN ACCOUNTS_TREE AS t
            ON t.ACC_PARENT = t0.ACC_CODE
     )
SELECT root
     , MIN(t2.ACC_PARENT) AS ACC_PAERNT
     , SUM(t1.DEBIT)      AS DEBIT
	 , SUM(t1.CREDIT)      AS CREDIT
	 , ( SUM(t1.DEBIT) - SUM(t1.CREDIT) ) AS BALANCE
  FROM cte AS t1 
  JOIN ACCOUNTS_TREE AS t2
    ON t1.root = t2.ACC_CODE
 GROUP BY root


GO
/****** Object:  View [dbo].[ACCOUNTS_TREE_V]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[ACCOUNTS_TREE_V]
AS
SELECT        dbo.ACCOUNTS_TREE.T_ID, dbo.ACCOUNTS_TREE.ACC_CODE, dbo.ACCOUNTS_TREE.ACC_LEVEL, dbo.ACCOUNTS_TREE.ACC_PARENT, dbo.ACCOUNTS_TREE.ACC_NAME, dbo.ACCOUNTS_TREE.ACC_TYPE, 
                         dbo.ACCOUNTS_TREE.ACC_CAT, dbo.ACCOUNTS_TREE.ACC_CLOSING, ISNULL(dbo.ACC_Billing_TMP_2_V.DEBIT, 0) AS DEBIT, ISNULL(dbo.ACC_Billing_TMP_2_V.CREDIT, 0) AS CREDIT, 
                         CASE WHEN ISNULL(dbo.ACC_Billing_TMP_2_V.CREDIT, 0) > ISNULL(dbo.ACC_Billing_TMP_2_V.DEBIT, 0) THEN ISNULL(dbo.ACC_Billing_TMP_2_V.CREDIT, 0) - ISNULL(dbo.ACC_Billing_TMP_2_V.DEBIT, 0) 
                         ELSE (ISNULL(dbo.ACC_Billing_TMP_2_V.DEBIT, 0) - ISNULL(dbo.ACC_Billing_TMP_2_V.CREDIT, 0)) * - 1 END AS BALANCE, ISNULL(dbo.ACCOUNTS_TREE.ACC_HINT, N'') AS ACC_HINT, 
                         dbo.ACCOUNTS_TREE.ACC_NATURAL, dbo.ACCOUNTS_TREE.is_Balance_View, ISNULL(dbo.ACCOUNTS_TREE.cash_flow_ID, 0) AS cash_flow_ID, ISNULL(dbo.ACCOUNTS_TREE.SIDE, 'بلا') AS SIDE, 
                         ISNULL(dbo.ACCOUNTS_TREE.is_Lock_Trans, 0) AS is_Lock_Trans, CASE WHEN ISNULL(dbo.ACC_Billing_TMP_2_V.CREDIT, 0) > ISNULL(dbo.ACC_Billing_TMP_2_V.DEBIT, 0) 
                         THEN 'الحساب مدين' WHEN ISNULL(dbo.ACC_Billing_TMP_2_V.CREDIT, 0) < ISNULL(dbo.ACC_Billing_TMP_2_V.DEBIT, 0) THEN 'الحساب دائن' ELSE '' END AS Acc_Current_Status, ISNULL(dbo.ACCOUNTS_TREE.ACC_DIGIT, 
                         LEN(CAST(dbo.ACCOUNTS_TREE.ACC_PARENT AS VARCHAR))) AS ACC_DIGIT,

						 CASE WHEN ISNULL(dbo.ACCOUNTS_TREE.START_CREDIT, 0) > ISNULL(dbo.ACCOUNTS_TREE.START_DEBIT, 0) 
						 THEN ISNULL(dbo.ACCOUNTS_TREE.START_CREDIT, 0) - ISNULL(dbo.ACCOUNTS_TREE.START_DEBIT, 0) 
                         ELSE (ISNULL(dbo.ACCOUNTS_TREE.START_DEBIT, 0) - ISNULL(dbo.ACCOUNTS_TREE.START_CREDIT, 0)) * - 1 END AS START_BALANCE,

						CASE WHEN ISNULL(dbo.ACCOUNTS_TREE.END_CREDIT, 0) > ISNULL(dbo.ACCOUNTS_TREE.END_DEBIT, 0) 
						 THEN ISNULL(dbo.ACCOUNTS_TREE.END_CREDIT, 0) - ISNULL(dbo.ACCOUNTS_TREE.END_DEBIT, 0) 
                         ELSE (ISNULL(dbo.ACCOUNTS_TREE.END_DEBIT, 0) - ISNULL(dbo.ACCOUNTS_TREE.END_CREDIT, 0)) * - 1 END AS END_BALANCE


FROM            dbo.ACCOUNTS_TREE LEFT OUTER JOIN
                         dbo.ACC_Billing_TMP_2_V ON dbo.ACCOUNTS_TREE.ACC_CODE = dbo.ACC_Billing_TMP_2_V.root


GO
/****** Object:  View [dbo].[BALANCES_REVIEW_V]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*SELECT [رقم الحساب],[إسم الحساب],[مدين - المجاميع],[دائــن - المجاميع],([مديـن - الأرصــدة]) AS [مديـن - الأرصــدة],[دائـن - الأرصــدة]
 ,[ACC_LEVEL] 
FROM ACCOUNTS_TREE_CREDIT_V
UNION ALL
	SELECT [رقم الحساب],[إسم الحساب],[مدين - المجاميع],[دائــن - المجاميع],[مديـن - الأرصــدة],[دائـن - الأرصــدة]
 ,[ACC_LEVEL] 
FROM ACCOUNTS_TREE_DEBIT_V*/
CREATE VIEW [dbo].[BALANCES_REVIEW_V]
AS
SELECT        T_ID, ACC_CODE AS [رقم الحساب], ACC_NAME AS [إسم الحساب], ISNULL(CREDIT, 0) AS [مدين - المجاميع], ISNULL(DEBIT, 0) AS [دائــن - المجاميع], CASE WHEN (ISNULL([CREDIT], 0) - ISNULL([DEBIT], 0)) > 0 THEN (ISNULL([CREDIT], 0) 
                         - ISNULL([DEBIT], 0)) ELSE '0' END AS [مديـن - الأرصــدة], CASE WHEN (ISNULL([CREDIT], 0) - ISNULL([DEBIT], 0)) < 0 THEN ((ISNULL([CREDIT], 0) - ISNULL([DEBIT], 0)) * - 1) ELSE '0' END AS [دائـن - الأرصــدة], ACC_LEVEL, 
                         ACC_PARENT
FROM            dbo.ACCOUNTS_TREE_V
WHERE        (is_Balance_View = 1)
GO
/****** Object:  View [dbo].[Vw_BudgetReserveBalance]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  VIEW [dbo].[Vw_BudgetReserveBalance]
AS
SELECT
    r.BudgetEntryId        AS ReserveEntryId,
    r.BudgetItemId,
    r.FiscalYear,
    r.EntryDate            AS ReserveDate,
    r.Amount               AS ReservedAmount,

    ISNULL(SUM(rel.Amount), 0) AS ReleasedAmount,

    r.Amount - ISNULL(SUM(rel.Amount), 0) AS RemainingAmount,

    r.Notes
FROM Budget_Entries r
LEFT JOIN Budget_Entries rel
    ON rel.ReserveEntryId = r.BudgetEntryId
   AND rel.EntryType = 3
WHERE r.EntryType = 2
GROUP BY
    r.BudgetEntryId,
    r.BudgetItemId,
    r.FiscalYear,
    r.EntryDate,
    r.Amount,
    r.Notes;
GO
/****** Object:  View [dbo].[Vw_BudgetPartiallyReleasedReserves]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[Vw_BudgetPartiallyReleasedReserves]
AS
SELECT
    rb.ReserveEntryId,
    rb.BudgetItemId,
    rb.FiscalYear,
    rb.ReserveDate,
    rb.ReservedAmount,
    rb.ReleasedAmount,
    rb.RemainingAmount,
    rb.Notes,

    -- بيانات البند
    i.ItemCode,
    i.ItemName,
    c.ChapterCode,
    d.DoorCode

FROM dbo.Vw_BudgetReserveBalance rb
JOIN Budget_Items i
    ON rb.BudgetItemId = i.BudgetItemId
JOIN Budget_Chapters c
    ON i.ChapterId = c.ChapterId
JOIN Budget_Doors d
    ON c.DoorId = d.DoorId

WHERE
    rb.ReleasedAmount > 0
    AND rb.RemainingAmount > 0;
GO
