CREATE VIEW [dbo].[ACC_BALANCE_MASTER_V]
AS
SELECT        dbo.ACC_BALANCE_MASTER.T_ID, dbo.ACC_BALANCE_MASTER.DATE, dbo.ACC_BALANCE_MASTER.DATE_IN, dbo.ACC_BALANCE_MASTER.NOTES, dbo.ACC_BALANCE_SUM_V.DEBIT, dbo.ACC_BALANCE_SUM_V.CREDIT, 
                         dbo.ACC_BALANCE_MASTER.is_Depended, CASE WHEN dbo.ACC_BALANCE_MASTER.is_Depended = 0 THEN 'القيـــد غير معتمد' ELSE 'القيـــد مـعتمد' END AS ACC_Depend_Status, 
                         CASE WHEN DEBIT <> CREDIT THEN 'القيـــد غير موزون' ELSE 'القيـــد مـــوزون' END AS ACC_B_Status, CASE WHEN DEBIT <> CREDIT THEN '0' ELSE '1' END AS ACC_B_Status_Flag, dbo.ACC_BALANCE_MASTER.JournalNumber
