/****** Object:  View [dbo].[VW_Budget_Allocations_Adjusted]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[VW_Budget_Allocations_Adjusted]
AS
SELECT
    a.BudgetItemId,
    a.FiscalYear,
    a.AllocatedAmount
    + ISNULL(SUM(
        CASE
            WHEN d.ToBudgetItemId = a.BudgetItemId THEN d.Amount
            WHEN d.FromBudgetItemId = a.BudgetItemId THEN -d.Amount
        END
      ),0) AS AdjustedAllocatedAmount
FROM Budget_Allocations a
LEFT JOIN Budget_Transfer_Details d
    ON a.FiscalYear = (
        SELECT t.FiscalYear
        FROM Budget_Transfers t
        WHERE t.TransferId = d.TransferId
          AND t.IsApproved = 1
    )
GROUP BY
    a.BudgetItemId,
    a.FiscalYear,
    a.AllocatedAmount;















