/****** Object:  View [dbo].[VW_Budget_Control]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE VIEW [dbo].[VW_Budget_Control]
AS
SELECT
    a.BudgetItemId,
    a.FiscalYear,
    a.AdjustedAllocatedAmount AS AllocatedAmount,

    ISNULL(SUM(CASE WHEN e.EntryType = 1 THEN e.Amount END), 0) AS TotalSpent,
    ISNULL(SUM(CASE WHEN e.EntryType = 2 THEN e.Amount END), 0) AS TotalReserved,

    a.AdjustedAllocatedAmount
        - ISNULL(SUM(CASE WHEN e.EntryType = 1 THEN e.Amount END), 0)
        - ISNULL(SUM(CASE WHEN e.EntryType = 2 THEN e.Amount END), 0)
        AS AvailableAmount
FROM VW_Budget_Allocations_Adjusted a
LEFT JOIN Budget_Entries e
    ON a.BudgetItemId = e.BudgetItemId
    AND a.FiscalYear = e.FiscalYear
GROUP BY
    a.BudgetItemId,
    a.FiscalYear,
    a.AdjustedAllocatedAmount;



















