SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[ExchangeTransactions_V]
AS
SELECT        dbo.ExchangeTransactions.ExchangeId, dbo.ExchangeTransactions.OperationType, dbo.ExchangeTransactions.VaultId, dbo.ExchangeTransactions.ForeignCurrencyId, dbo.ExchangeTransactions.ForeignAmount, 
                         dbo.ExchangeTransactions.RateSnapshot, dbo.ExchangeTransactions.CommissionPercentSnapshot, dbo.ExchangeTransactions.TotalLYD, dbo.ExchangeTransactions.CommissionLYD, dbo.ExchangeTransactions.NetLYD, 
                         dbo.Currency.Cr_Name, dbo.ExchangeTransactions.StatusId, dbo.ExchangeTransactions.JournalId, dbo.ExchangeTransactions.ReferenceNo, dbo.ExchangeTransactions.Note, dbo.ExchangeTransactions.CreatedAt, 
                         dbo.ExchangeTransactions.CreatedBy, dbo.ExchangeTransactions.ApprovedAt, dbo.ExchangeTransactions.ApprovedBy, dbo.ExchangeTransactions.RejectedAt, dbo.ExchangeTransactions.RejectedBy, 
                         dbo.ExchangeTransactions.RejectReason, dbo.ExchangeStatus.StatusName, dbo.Rct_Mang_V.ACC_NAME, dbo.ExchangeTransactions.CustomerName, dbo.ExchangeTransactions.CustomerIdentityNumber
FROM            dbo.ExchangeTransactions INNER JOIN
                         dbo.ExchangeStatus ON dbo.ExchangeTransactions.StatusId = dbo.ExchangeStatus.StatusId INNER JOIN
                         dbo.Rct_Mang_V ON dbo.ExchangeTransactions.VaultId = dbo.Rct_Mang_V.ACC_CODE LEFT OUTER JOIN
                         dbo.Currency ON dbo.ExchangeTransactions.ForeignCurrencyId = dbo.Currency.Cr_ID
GO
/****** Object:  View [dbo].[VW_Budget_Status]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[VW_Budget_Status]
AS
SELECT
    d.DoorId,
    d.DoorCode,
    d.DoorName,

    c.ChapterId,
    c.ChapterCode,
    c.ChapterName,

    i.BudgetItemId,
    i.ItemCode,
    i.ItemName,

    a.FiscalYear,
    a.AllocatedAmount,

    ISNULL(SUM(CASE WHEN e.EntryType = 1 THEN e.Amount END), 0) AS TotalSpent,
    ISNULL(SUM(CASE WHEN e.EntryType = 2 THEN e.Amount END), 0) AS TotalReserved,

    a.AllocatedAmount
        - ISNULL(SUM(CASE WHEN e.EntryType = 1 THEN e.Amount END), 0)
        - ISNULL(SUM(CASE WHEN e.EntryType = 2 THEN e.Amount END), 0)
        AS AvailableAmount

FROM Budget_Allocations a
JOIN Budget_Items i      ON a.BudgetItemId = i.BudgetItemId
JOIN Budget_Chapters c   ON i.ChapterId = c.ChapterId
JOIN Budget_Doors d      ON c.DoorId = d.DoorId
LEFT JOIN Budget_Entries e
    ON a.BudgetItemId = e.BudgetItemId
    AND a.FiscalYear = e.FiscalYear

GROUP BY
    d.DoorId, d.DoorCode, d.DoorName,
    c.ChapterId, c.ChapterCode, c.ChapterName,
    i.BudgetItemId, i.ItemCode, i.ItemName,
    a.FiscalYear, a.AllocatedAmount;
GO
