/****** Object:  View [dbo].[ACC_BALANCE_TABLE_V]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[ACC_BALANCE_TABLE_V]
AS

WITH RecursiveHierarchy AS (
    SELECT T_ID, ACC_CODE, ACC_NAME, ACC_PARENT, ACC_LEVEL , is_Balance_View,ACC_CLOSING,SIDE,is_Lock_Trans,DEBIT,CREDIT
    FROM ACCOUNTS_TREE
    WHERE ACC_PARENT = 0  -- اختيار الحسابات الرئيسية (الأب)
    
    UNION ALL
    
    SELECT d.T_ID, d.ACC_CODE, d.ACC_NAME, d.ACC_PARENT, d.ACC_LEVEL, d.is_Balance_View,d.ACC_CLOSING,d.SIDE,d.is_Lock_Trans,d.DEBIT,d.CREDIT
    FROM ACCOUNTS_TREE d
    INNER JOIN RecursiveHierarchy r
    ON d.ACC_PARENT = r.ACC_CODE  -- ربط الأبناء بالأب من خلال ACC_PARENT
)
SELECT * 
FROM RecursiveHierarchy
--ORDER BY ACC_CODE;  -- الترتيب حسب رقم الكود

GO
/****** Object:  View [dbo].[BALANCES_REVIEW_NO_LEVELS_V]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[BALANCES_REVIEW_NO_LEVELS_V]
AS
SELECT        T_ID, ACC_CODE AS [رقم الحساب], ACC_NAME AS [إسم الحساب], ISNULL(CREDIT, 0) AS [مدين - المجاميع], ISNULL(DEBIT, 0) AS [دائــن - المجاميع], CASE WHEN (ISNULL([CREDIT], 0) - ISNULL([DEBIT], 0)) > 0 THEN (ISNULL([CREDIT], 0) 
                         - ISNULL([DEBIT], 0)) ELSE '0' END AS [مديـن - الأرصــدة], CASE WHEN (ISNULL([CREDIT], 0) - ISNULL([DEBIT], 0)) < 0 THEN ((ISNULL([CREDIT], 0) - ISNULL([DEBIT], 0)) * - 1) ELSE '0' END AS [دائـن - الأرصــدة], ACC_LEVEL, 
                         ACC_PARENT
FROM            dbo.ACC_BALANCE_TABLE_V
GO
