                         dbo.Users ON dbo.Agents_Balance_MV.User_ID = dbo.Users.User_ID LEFT OUTER JOIN
                         dbo.Agents AS Agents_1 ON dbo.Agents_Balance_MV.AG_ID = Agents_1.AG_ID LEFT OUTER JOIN
                         dbo.A_AG_B_NEW_D_C_V ON dbo.Agents_Balance_MV.T_ID = dbo.A_AG_B_NEW_D_C_V.T_ID LEFT OUTER JOIN
                         dbo.Void_Names ON dbo.Agents_Balance_MV.isVoid = dbo.Void_Names.T_ID ON dbo.Agents.AG_ID = dbo.Agents_Balance_MV.Cr_ID LEFT OUTER JOIN
                         dbo.AG_Balance_With_Pied_TMP_2_V ON dbo.Agents_Balance_MV.T_ID = dbo.AG_Balance_With_Pied_TMP_2_V.T_ID ON 
                         dbo.AG_Balance_With_Pied_TMP_V.Receipt_Tran_ID = dbo.Agents_Balance_MV.T_ID LEFT OUTER JOIN
                         dbo.Travels_Costmers ON dbo.Agents_Balance_MV.Cr_ID = dbo.Travels_Costmers.Cr_ID LEFT OUTER JOIN
                         dbo.AG_Projects ON dbo.Agents_Balance_MV.Proj_ID = dbo.AG_Projects.Proj_ID LEFT OUTER JOIN
                         dbo.Sales_Bills_Types ON dbo.Agents_Balance_MV.S_Bills_Type = dbo.Sales_Bills_Types.B_Type_ID LEFT OUTER JOIN
                         dbo.Tables ON dbo.Agents_Balance_MV.Table_ID = dbo.Tables.TB_ID LEFT OUTER JOIN
                         dbo.PiedTypes ON dbo.AG_Balance_With_Pied_TMP_2_V.is_Pied = dbo.PiedTypes.Pied_ID
WHERE        (dbo.Agents_Balance_MV.BsType_ID = 1)
