CREATE VIEW [dbo].[AGENT_BALANCES_Discount_V]
AS
SELECT        dbo.Agents_Balance_MV_V.T_ID, dbo.Agents_Balance_MV_V.Receipt_Num, dbo.Agents_Balance_MV_V.AG_ID, dbo.Agents_Balance_MV_V.SB_ID, dbo.Agents_Balance_MV_V.S_Bill_Pr_ID, dbo.Agents_Balance_MV_V.Pch_ID, 
                         dbo.Agents_Balance_MV_V.Date, dbo.Agents_Balance_MV_V.ReferNum, dbo.Agents_Balance_MV_V.BsType_ID, CASE WHEN BsType_ID = 7 THEN Discount ELSE NULL END AS DEBIT, 
                         CASE WHEN BsType_ID = 1 THEN Discount ELSE NULL END AS CREDIT, CASE WHEN BsType_ID = 1 THEN '4' ELSE '5' END AS ACC_T_ID
FROM            dbo.Agents_Balance_MV_V INNER JOIN
                         dbo.AgentBalance_Type ON dbo.Agents_Balance_MV_V.BsType_ID = dbo.AgentBalance_Type.id
WHERE        (dbo.Agents_Balance_MV_V.Discount > '0') AND (dbo.Agents_Balance_MV_V.isDepended = 1) AND (dbo.Agents_Balance_MV_V.isVoid = 0)
GO
