CREATE VIEW [dbo].[FRM_Contents_Manuel_V]
AS
SELECT        dbo.FRM_Contents_Details.T_ID, dbo.Agents_Balance_MV.T_ID AS Frm_ID, dbo.FRM_Contents_Details.IM_ID, dbo.FRM_Contents_Details.U_ID, dbo.Stores.St_Name, dbo.IM_Menu.item_name, dbo.FRM_Contents_Details.QYT, 
                         dbo.Units.U_Name + N'*' + CONVERT(varchar(12), dbo.FRM_Contents_Details.U_Cargo) AS U_NAME, dbo.FRM_Contents_Details.Cost, dbo.FRM_Contents_Details.Cost * dbo.FRM_Contents_Details.QYT AS Total, 
                         dbo.SB_Info_V.Ag_name, dbo.Agents.Ag_name AS Emp_Name, dbo.FRM_Contents_Details.isDepended, dbo.SB_Info_V.SB_ID, dbo.Agents_Balance_MV.Cr_ID, dbo.Agents_Balance_MV.Date, dbo.FRM_Contents_Details.ST_ID, 
                         dbo.IM_Menu.isStore, dbo.FRM_Contents_Details.is_Not_Qty, CASE WHEN is_Not_Qty = 1 THEN 'بدون خصم كمية' ELSE '' END AS QTY_STATUS
FROM            dbo.FRM_Contents_Details INNER JOIN
                         dbo.Units ON dbo.FRM_Contents_Details.U_ID = dbo.Units.U_ID INNER JOIN
                         dbo.IM_Menu ON dbo.FRM_Contents_Details.IM_ID = dbo.IM_Menu.IM_ID INNER JOIN
                         dbo.Stores ON dbo.FRM_Contents_Details.ST_ID = dbo.Stores.ST_ID INNER JOIN
                         dbo.Agents_Balance_MV ON dbo.FRM_Contents_Details.Bill_T_ID = dbo.Agents_Balance_MV.T_ID LEFT OUTER JOIN
                         dbo.Agents ON dbo.Agents_Balance_MV.Cr_ID = dbo.Agents.AG_ID LEFT OUTER JOIN
                         dbo.SB_Info_V ON dbo.Agents_Balance_MV.Travel_ID = dbo.SB_Info_V.T_ID
WHERE        (dbo.Agents_Balance_MV.BsType_ID = 18)
GO
