CREATE VIEW [dbo].[FRM_CONTENTS_SUM_ONLY_STUCK_V]
AS
SELECT        dbo.FRM_Contents_Manuel_V.Total, dbo.Agents_Balance_MV_V.Date
FROM            dbo.IM_Menu INNER JOIN
                         dbo.FRM_Contents_Manuel_V ON dbo.IM_Menu.IM_ID = dbo.FRM_Contents_Manuel_V.IM_ID INNER JOIN
                         dbo.Agents_Balance_MV_V ON dbo.FRM_Contents_Manuel_V.Frm_ID = dbo.Agents_Balance_MV_V.T_ID
WHERE        (dbo.IM_Menu.isStore = 1) AND (dbo.Agents_Balance_MV_V.isDepended = 1) AND (dbo.Agents_Balance_MV_V.isVoid = 0) OR
                         (dbo.IM_Menu.isStore = 2)

GO
