CREATE VIEW [dbo].[FRM_Details_V]
AS
SELECT        dbo.Stores.St_Name, dbo.IM_Menu.item_name, dbo.Units.U_Name + N'*' + CONVERT(varchar(12), dbo.FRM_Details.U_Cargo) AS U_NAME, dbo.Units.U_ID, dbo.FRM_Details.T_ID, dbo.FRM_Details.FRM_T_ID, 
                         dbo.FRM_Details.QYT, dbo.FRM_Details.IM_ID, dbo.FRM_Details.ST_ID, dbo.FRM_Details.Price, dbo.FRM_Details.D_Vaild, dbo.FRM_Details.Total, dbo.FRM_Details.NewSale, dbo.FRM_Details.ST_QTY, 
                         dbo.FRM_Details.U_Cargo, dbo.SB_Info_V.Ag_name, dbo.Agents_Balance_MV.AG_ID, dbo.Agents.Ag_name AS Emp_Name, dbo.SB_Info_V.SB_ID, dbo.FRM_Details.isDepended, dbo.Agents_Balance_MV.Cr_ID, 
                         dbo.Agents_Balance_MV.Date
FROM            dbo.Agents_Balance_MV LEFT OUTER JOIN
                         dbo.SB_Info_V ON dbo.Agents_Balance_MV.Travel_ID = dbo.SB_Info_V.T_ID LEFT OUTER JOIN
                         dbo.Agents ON dbo.Agents_Balance_MV.Cr_ID = dbo.Agents.AG_ID RIGHT OUTER JOIN
                         dbo.IM_Menu INNER JOIN
                         dbo.FRM_Details ON dbo.IM_Menu.IM_ID = dbo.FRM_Details.IM_ID INNER JOIN
                         dbo.Units ON dbo.FRM_Details.U_ID = dbo.Units.U_ID INNER JOIN
                         dbo.Stores ON dbo.FRM_Details.ST_ID = dbo.Stores.ST_ID ON dbo.Agents_Balance_MV.T_ID = dbo.FRM_Details.FRM_T_ID
GO
