CREATE VIEW [dbo].[SB_Rsv_V]
AS
SELECT        dbo.SB_Rsv.T_ID, dbo.SB_Rsv.SB_T_ID, dbo.SB_Rsv.DATE_F, DATEDIFF(DAY, dbo.SB_Rsv.DATE_F, GETDATE()) AS DAYS, DATEDIFF(Month, dbo.SB_Rsv.DATE_F, GETDATE()) AS MONTHS, DATEDIFF(Year, 
                         dbo.SB_Rsv.DATE_F, GETDATE()) AS YEARS, dbo.SB_Info_V.SB_ID, dbo.SB_Info_V.Ag_name, dbo.IM_Menu.item_name
