                         dbo.SB_Info_V ON dbo.SB_Contents.Bill_T_ID = dbo.SB_Info_V.T_ID INNER JOIN
                         dbo.IM_Menu ON dbo.SB_Contents.IM_ID = dbo.IM_Menu.IM_ID
GO
