CREATE VIEW [dbo].[SB_Contents_V]
AS
SELECT        dbo.SB_Contents.T_ID, dbo.SB_Contents.Bill_T_ID, FORMAT(CAST(dbo.SB_Contents.Price AS REAL), '') AS Price, FORMAT(CAST(dbo.SB_Contents.QTY AS REAL), '') AS QTY, dbo.SB_Contents.T_Price, 
                         dbo.SB_Contents.isDepended, dbo.IM_Menu.item_name + N' ' + dbo.Units.U_Name + N'  ' + ISNULL(dbo.SB_Contents.Compons, N'') AS IM_Name, dbo.General_menu.Printer_ID AS Ptr_ID, ISNULL(dbo.IM_Menu.isChangePrice, 
                         0) AS isChangePrice, dbo.Units.U_Name + N'*' + CONVERT(varchar(12), dbo.SB_Contents.U_Cargo) AS Unit_Name, dbo.IM_Menu.IM_ID, dbo.IM_Menu.item_name, dbo.SB_Contents.U_ID, dbo.SB_Contents.Date, 
                         dbo.SB_Contents.ST_ID, dbo.Stores.St_Name, dbo.SB_Contents.D_Vaild, dbo.SB_Contents.Cost, ISNULL(dbo.SB_Contents.Notes, N'') AS Notes, dbo.IM_Menu.IM_Num, 
                         dbo.SB_Contents.Cost * dbo.SB_Contents.QTY AS SUM_Cost, dbo.IM_Menu.item_name + N' ' + dbo.Units.U_Name + N'  ' AS IM_NAME_ONLY, dbo.Printers.Printer_Path, dbo.SB_Contents.Barcode, 
                         dbo.SB_Contents.Serial_Code, dbo.IM_Menu.isStore, dbo.SB_Contents.ST_QTY, dbo.SB_Contents.is_Check, dbo.SB_Contents.U_Cargo, 
                         dbo.IM_Menu.item_nameSales + N' ' + dbo.Units.U_Name + N'  ' + ISNULL(dbo.SB_Contents.Compons, N'') AS IM_NAME_2, dbo.Agents_Balance_MV.AG_ID, dbo.Agents_Balance_MV.SB_ID, dbo.Agents_Balance_MV.User_ID, 
                         dbo.IM_Menu.Notes AS IM_NOTE, ISNULL(dbo.SB_Contents.IM_Discount, 0) AS IM_Discount, dbo.IM_Menu.IM_Full_Photo AS Img_Path, 0 AS Current_Qty, dbo.Stores.TREE_CODE
FROM            dbo.Units INNER JOIN
                         dbo.SB_Contents ON dbo.Units.U_ID = dbo.SB_Contents.U_ID INNER JOIN
                         dbo.Stores ON dbo.SB_Contents.ST_ID = dbo.Stores.ST_ID LEFT OUTER JOIN
                         dbo.IM_Menu ON dbo.SB_Contents.IM_ID = dbo.IM_Menu.IM_ID LEFT OUTER JOIN
                         dbo.Agents_Balance_MV ON dbo.SB_Contents.Bill_T_ID = dbo.Agents_Balance_MV.T_ID LEFT OUTER JOIN
                         dbo.Printers INNER JOIN
                         dbo.General_menu ON dbo.Printers.Printer_ID = dbo.General_menu.Printer_ID ON dbo.IM_Menu.GM_ID = dbo.General_menu.GM_ID
GO
