                         dbo.Pch_Details.Barcode, dbo.Pch_Details.U_ID, dbo.Pch_Details.U_Cargo, dbo.Agents_Balance_MV.AG_ID, dbo.Agents_Balance_MV.Pch_ID, dbo.Agents_Balance_MV.Jrd_ID, dbo.Agents_Balance_MV.User_ID, 
                         dbo.Pch_Details.AVG_Cost, dbo.Pch_Details.AVG_COSTChange, dbo.Stores.TREE_CODE, dbo.Pch_Details.EXP_VALUE, dbo.Pch_Details.Price - ISNULL(dbo.Pch_Details.EXP_VALUE, 0) AS Main_Price, 
