                         dbo.IM_full_movement_tmp_V.N AS Q_IN, dbo.IM_full_movement_tmp_V.Price AS السعر, dbo.AgentBalance_Type.Type_Name AS [نوع المعاملة], dbo.IM_full_movement_tmp_V.Bill_ID AS [رقم المعاملة], dbo.Agents.Ag_name AS الحساب, 
