CREATE VIEW [dbo].[A_AG_TMP_V]
AS
SELECT        dbo.Agents_Balance_MV.T_ID, CASE WHEN TOTAL IS NULL AND PURE IS NOT NULL THEN PURE WHEN TOTAL IS NULL AND PURE IS NULL AND Debit IS NOT NULL AND Credit IS NULL THEN Debit WHEN TOTAL IS NULL AND 
                         PURE IS NULL AND Debit IS NULL AND Credit IS NOT NULL THEN Credit ELSE ISNULL(dbo.Agents_Balance_MV.Total, 0) - ISNULL(dbo.Agents_Balance_MV.Discount, 0) END AS Pure
FROM            dbo.Agents_Balance_MV INNER JOIN
                         dbo.AgentBalance_Type ON dbo.Agents_Balance_MV.BsType_ID = dbo.AgentBalance_Type.id
