                         dbo.Pch_Details.ST_QTY / dbo.Units.U_Cargo AS QTY, dbo.Pch_Details.Price, dbo.Pch_Details.Total AS T_Price, dbo.Pch_Details.IM_ID, dbo.Pch_Details.T_ID, dbo.Pch_Details.ST_ID, dbo.General_menu.GM_Name, 
