SELECT        dbo.Agents_Balance_MV.AG_ID, dbo.Agents_Balance_MV.Date, dbo.IM_Menu.item_name, dbo.Units.U_Name, dbo.Agents.Ag_name, dbo.Rtn_Contents.T_ID, dbo.Rtn_Contents.IM_ID, dbo.Rtn_Contents.Price, 
                         dbo.Rtn_Contents.ST_QTY / dbo.Units.U_Cargo AS QTY, dbo.Rtn_Contents.T_Price, dbo.Agents_Balance_MV.BsType_ID, dbo.Agents_Balance_MV.SRtn_ID, dbo.Agents_Balance_MV.PRtn_ID, 
                         dbo.General_menu.GM_Name, ISNULL(dbo.Rtn_Contents.Proj_ID, 1) AS Proj_ID, dbo.Rtn_Contents.U_ID, dbo.Rtn_Contents.D_Vaild, dbo.General_menu.GM_ID
FROM            dbo.Agents_Balance_MV INNER JOIN
                         dbo.Agents ON dbo.Agents_Balance_MV.AG_ID = dbo.Agents.AG_ID INNER JOIN
                         dbo.Rtn_Contents ON dbo.Agents_Balance_MV.T_ID = dbo.Rtn_Contents.Bill_T_ID INNER JOIN
                         dbo.IM_Menu ON dbo.Rtn_Contents.IM_ID = dbo.IM_Menu.IM_ID INNER JOIN
                         dbo.General_menu ON dbo.IM_Menu.GM_ID = dbo.General_menu.GM_ID INNER JOIN
                         dbo.IM_Units ON dbo.IM_Menu.IM_ID = dbo.IM_Units.IM_ID INNER JOIN
                         dbo.Units ON dbo.IM_Units.U_ID = dbo.Units.U_ID
WHERE        (dbo.Agents_Balance_MV.isDepended = 1) AND (dbo.Rtn_Contents.isDepended = 1) AND (dbo.IM_Units.is_Default = 1)











GO
