CREATE VIEW [dbo].[Agent_SB_IM_MV_V]
AS
SELECT        dbo.Agents_Balance_MV.AG_ID, dbo.SB_Contents.Date, dbo.Agents_Balance_MV.SB_ID, dbo.Agents.Ag_name, dbo.Stores.St_Name, dbo.IM_Menu.item_name, dbo.Units.U_Name + N'*' + CONVERT(varchar(12), 
                         dbo.SB_Contents.U_Cargo) AS U_NAME, dbo.SB_Contents.D_Vaild, dbo.SB_Contents.ST_QTY / dbo.Units.U_Cargo AS QTY, dbo.SB_Contents.Price, dbo.SB_Contents.T_Price, dbo.SB_Contents.T_ID, dbo.SB_Contents.IM_ID, 
                         dbo.Agents_Balance_MV.T_ID AS B_T_ID, ISNULL(dbo.Agents_Balance_MV.Discount, 0) AS Discount, dbo.SB_Contents.ST_ID, dbo.SB_Contents.Cost, dbo.General_menu.GM_Name, dbo.SB_Contents.Saler_Percent, 
                         ISNULL(dbo.Agents_Balance_MV.Proj_ID, 1) AS Proj_ID, dbo.IM_Menu.IM_Num, dbo.SB_Contents.U_ID, dbo.General_menu.GM_ID, dbo.Agents_Balance_MV.Barcode, dbo.SB_Contents.Markter_Val, 
                         dbo.SB_Contents.Serial_Code, dbo.SB_Contents.is_By_Min_SP, dbo.SB_Contents.is_By_Min_SP_2, dbo.Agents_Balance_MV.Pr_ID, dbo.SB_Contents.Barcode AS IM_Barcode, dbo.Agents_Balance_MV.isPied
FROM            dbo.Agents_Balance_MV INNER JOIN
                         dbo.SB_Contents ON dbo.Agents_Balance_MV.T_ID = dbo.SB_Contents.Bill_T_ID INNER JOIN
                         dbo.IM_Menu ON dbo.SB_Contents.IM_ID = dbo.IM_Menu.IM_ID INNER JOIN
                         dbo.Agents ON dbo.Agents_Balance_MV.AG_ID = dbo.Agents.AG_ID INNER JOIN
                         dbo.Stores ON dbo.SB_Contents.ST_ID = dbo.Stores.ST_ID INNER JOIN
                         dbo.General_menu ON dbo.IM_Menu.GM_ID = dbo.General_menu.GM_ID INNER JOIN
                         dbo.Units ON dbo.SB_Contents.U_ID = dbo.Units.U_ID
WHERE        (dbo.SB_Contents.isDepended = 1) AND (dbo.Agents_Balance_MV.isDepended = 1) AND (dbo.Agents_Balance_MV.isVoid = 0)
GO
