CREATE VIEW [dbo].[ChequeStatuses_V]
AS
SELECT        dbo.ACC_BALANCE_MASTER.T_ID, dbo.ACCOUNTS_TREE.ACC_NAME, dbo.ACC_BALANCE_MASTER.Receipt_Num, dbo.ACC_BALANCE.CREDIT AS VALUE, dbo.ACC_BALANCE_MASTER.Check_Number, 
                         'صك إيداع' AS Cheque_Type, dbo.ACC_BALANCE_MASTER.IssueDate, dbo.ACC_BALANCE_MASTER.DueDate, dbo.ACC_BALANCE_MASTER.ChequeStatus, dbo.ACC_BALANCE_MASTER.ReconciliationDate, 
                         dbo.ACC_BALANCE_MASTER.BankTransactionNumber, dbo.ACC_BALANCE_MASTER.Cheque_Notes, dbo.ACC_BALANCE_MASTER.StatusId, dbo.ChequeStatuses.NameAr, dbo.ChequeStatuses.IsFinal
						 ,ChequeStatuses .BackColorHex,ChequeStatuses.ForeColorHex,dbo.ACC_BALANCE_MASTER.DATE
FROM            dbo.ACC_BALANCE_MASTER INNER JOIN
                         dbo.ACC_BALANCE ON dbo.ACC_BALANCE_MASTER.T_ID = dbo.ACC_BALANCE.B_T_ID INNER JOIN
                         dbo.ACCOUNTS_TREE ON dbo.ACC_BALANCE.ACC_CODE = dbo.ACCOUNTS_TREE.ACC_CODE INNER JOIN
                         dbo.ChequeStatuses ON dbo.ACC_BALANCE_MASTER.StatusId = dbo.ChequeStatuses.StatusId
WHERE        (dbo.ACC_BALANCE.DEBIT IS NULL) AND (dbo.ACC_BALANCE_MASTER.Check_Number IS NOT NULL) AND (dbo.ACC_BALANCE_MASTER.is_Depended = 1) AND (dbo.ACC_BALANCE_MASTER.Receipt_Type = 3)



UNION ALL


SELECT        dbo.ACC_BALANCE_MASTER.T_ID, dbo.ACCOUNTS_TREE.ACC_NAME, dbo.ACC_BALANCE_MASTER.Receipt_Num, dbo.ACC_BALANCE.DEBIT AS VALUE, dbo.ACC_BALANCE_MASTER.Check_Number, 
                         'صك سحب' AS Cheque_Type, dbo.ACC_BALANCE_MASTER.IssueDate, dbo.ACC_BALANCE_MASTER.DueDate, dbo.ACC_BALANCE_MASTER.ChequeStatus, dbo.ACC_BALANCE_MASTER.ReconciliationDate, 
                         dbo.ACC_BALANCE_MASTER.BankTransactionNumber, dbo.ACC_BALANCE_MASTER.Cheque_Notes, dbo.ACC_BALANCE_MASTER.StatusId, dbo.ChequeStatuses.NameAr, dbo.ChequeStatuses.IsFinal
						 ,ChequeStatuses .BackColorHex,ChequeStatuses.ForeColorHex,dbo.ACC_BALANCE_MASTER.DATE
FROM            dbo.ACC_BALANCE_MASTER INNER JOIN
                         dbo.ACC_BALANCE ON dbo.ACC_BALANCE_MASTER.T_ID = dbo.ACC_BALANCE.B_T_ID INNER JOIN
                         dbo.ACCOUNTS_TREE ON dbo.ACC_BALANCE.ACC_CODE = dbo.ACCOUNTS_TREE.ACC_CODE INNER JOIN
                         dbo.ChequeStatuses ON dbo.ACC_BALANCE_MASTER.StatusId = dbo.ChequeStatuses.StatusId
WHERE        (dbo.ACC_BALANCE.CREDIT IS NULL) AND (dbo.ACC_BALANCE_MASTER.Check_Number IS NOT NULL) AND (dbo.ACC_BALANCE_MASTER.is_Depended = 1) AND (dbo.ACC_BALANCE_MASTER.Receipt_Type = 4)

GO
