/****** Object:  View [dbo].[Currency_Schedule_V]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[Currency_Schedule_V]
AS
--SELECT DISTINCT A.T_ID, A.Cr_ID, A.D_F, ISNULL
--                             ((SELECT        TOP (1) DATEADD(day, - 1, D_F) AS Expr1
--                                 FROM            dbo.Currency_Schedule AS B
--                                 WHERE        (B.Cr_ID = A.Cr_ID) AND (D_F > A.D_F)
--                                 ORDER BY D_F), '9999-12-31') AS D_T, dbo.Currency.Cr_Name, A.Price,A.BuyPrice
--FROM            dbo.Currency RIGHT OUTER JOIN
--                         dbo.Currency_Schedule ON dbo.Currency.Cr_ID = dbo.Currency_Schedule.Cr_ID LEFT OUTER JOIN
--                         dbo.Currency_Schedule AS A ON A.Cr_ID = A.Cr_ID

SELECT  
    A.T_ID,
    A.Cr_ID,
    A.D_F,
    ISNULL(
        (
            SELECT TOP (1) DATEADD(DAY, -1, B.D_F)
            FROM dbo.Currency_Schedule AS B
            WHERE B.Cr_ID = A.Cr_ID
              AND B.D_F > A.D_F
            ORDER BY B.D_F
        ),
        '9999-12-31'
    ) AS D_T,
    C.Cr_Name,
    A.Price,
    A.BuyPrice
FROM dbo.Currency_Schedule A
INNER JOIN dbo.Currency C 
    ON C.Cr_ID = A.Cr_ID


GO
