CREATE VIEW [dbo].[Emp_Salaries_V]
AS
SELECT        Agents_1.Ag_name AS Agent_name, dbo.Agents_Balance_MV.Year, dbo.Agents_Balance_MV.Month, ISNULL(Agents_1.AG_Salary, 0) AS AG_Salary, SUM(ISNULL(dbo.Agents_Balance_MV.Debit, 0)) AS SumDebit, 
