CREATE VIEW [dbo].[EXP_Details_Report_V]
AS
SELECT        dbo.Expenses_Card.Ex_Name, SUM(dbo.EXP_Details.QYT) AS QYT, SUM(dbo.EXP_Details.Total) AS Total, dbo.Agents_Balance_MV.Date, dbo.Expenses_Card.Ex_ID, dbo.Agents.Ag_name, dbo.Agents_Balance_MV.About, 
                         dbo.Agents_Balance_MV.EXP_ID
FROM            dbo.EXP_Details INNER JOIN
                         dbo.Expenses_Card ON dbo.EXP_Details.EX_ID = dbo.Expenses_Card.Ex_ID INNER JOIN
                         dbo.Agents_Balance_MV ON dbo.EXP_Details.IMEX_T_ID = dbo.Agents_Balance_MV.T_ID INNER JOIN
                         dbo.Agents ON dbo.Agents_Balance_MV.AG_ID = dbo.Agents.AG_ID
GROUP BY dbo.Expenses_Card.Ex_Name, dbo.EXP_Details.isDepended, dbo.Agents_Balance_MV.Date, dbo.Agents_Balance_MV.isVoid, dbo.Expenses_Card.Ex_ID, dbo.Agents.Ag_name, dbo.Agents_Balance_MV.About, 
                         dbo.Agents_Balance_MV.EXP_ID
HAVING        (dbo.EXP_Details.isDepended = 1) AND (dbo.Agents_Balance_MV.isVoid = 0)




GO
