CREATE VIEW [dbo].[FRM_Contents_Report_V]
AS
SELECT        dbo.Stores.St_Name, dbo.IM_Menu.item_name, dbo.Units.U_Name, dbo.Stores.ST_ID, dbo.FRM_Contents_Details.DATE, dbo.FRM_Contents_Details.ST_QTY / dbo.Units.U_Cargo AS QYT
FROM            dbo.IM_Menu INNER JOIN
                         dbo.IM_Units ON dbo.IM_Menu.IM_ID = dbo.IM_Units.IM_ID INNER JOIN
                         dbo.Units ON dbo.IM_Units.U_ID = dbo.Units.U_ID INNER JOIN
                         dbo.FRM_Contents_Details ON dbo.IM_Menu.IM_ID = dbo.FRM_Contents_Details.IM_ID INNER JOIN
                         dbo.Stores ON dbo.FRM_Contents_Details.ST_ID = dbo.Stores.ST_ID
WHERE        (dbo.IM_Units.is_Default = 1) AND (dbo.FRM_Contents_Details.isDepended = 1)
GROUP BY dbo.Stores.St_Name, dbo.IM_Menu.item_name, dbo.Units.U_Name, dbo.Stores.ST_ID, dbo.FRM_Contents_Details.DATE, dbo.FRM_Contents_Details.ST_QTY / dbo.Units.U_Cargo






