CREATE VIEW [dbo].[FRM_Contents_V]
AS
SELECT        dbo.Agents_Balance_MV.T_ID, dbo.FRM_Contents_Details.IM_ID, dbo.FRM_Contents_Details.U_ID, dbo.Stores.St_Name, dbo.IM_Menu.item_name, SUM(dbo.FRM_Contents_Details.QYT) AS QYT, 
                         dbo.Units.U_Name + N'*' + CONVERT(varchar(12), dbo.FRM_Contents_Details.U_Cargo) AS U_NAME, SUM(dbo.FRM_Contents_Details.Cost) AS Cost, dbo.FRM_Contents_Details.Barcode, dbo.FRM_Contents_Details.U_Cargo, 
                         dbo.FRM_Contents_Details.Bill_T_ID, dbo.FRM_Contents_Details.isDepended, Stores_1.TREE_CODE
FROM            dbo.FRM_Contents_Details INNER JOIN
                         dbo.Units ON dbo.FRM_Contents_Details.U_ID = dbo.Units.U_ID INNER JOIN
                         dbo.IM_Menu ON dbo.FRM_Contents_Details.IM_ID = dbo.IM_Menu.IM_ID INNER JOIN
                         dbo.FRM_Details ON dbo.FRM_Contents_Details.FRM_IM_T_ID = dbo.FRM_Details.T_ID INNER JOIN
                         dbo.Agents_Balance_MV ON dbo.FRM_Details.FRM_T_ID = dbo.Agents_Balance_MV.T_ID INNER JOIN
                         dbo.Stores ON dbo.FRM_Contents_Details.ST_ID = dbo.Stores.ST_ID INNER JOIN
                         dbo.Stores AS Stores_1 ON dbo.FRM_Contents_Details.ST_ID = Stores_1.ST_ID
WHERE        (dbo.Agents_Balance_MV.BsType_ID = 13)
GROUP BY dbo.Agents_Balance_MV.T_ID, dbo.FRM_Contents_Details.IM_ID, dbo.FRM_Contents_Details.U_ID, dbo.Stores.St_Name, dbo.IM_Menu.item_name, dbo.Units.U_Name + N'*' + CONVERT(varchar(12), 
                         dbo.FRM_Contents_Details.U_Cargo), dbo.FRM_Contents_Details.Barcode, dbo.FRM_Contents_Details.U_Cargo, dbo.FRM_Contents_Details.Bill_T_ID, dbo.FRM_Contents_Details.isDepended, Stores_1.TREE_CODE
GO
