CREATE VIEW [dbo].[FRM_Info_V]
AS
SELECT DISTINCT 
                         dbo.Agents.Ag_name, dbo.Agents_Balance_MV.T_ID, ISNULL(dbo.Agents_Balance_MV.isPied, 0) AS isPied, dbo.Agents_Balance_MV.isDepended, dbo.Agents_Balance_MV.isVoid, dbo.Agents_Balance_MV.AG_ID, 
                         dbo.Users.UserName AS U_Name, ISNULL(dbo.Agents_Balance_MV.About, N'') AS About, dbo.Agents_Balance_MV.Date, ISNULL(dbo.Agents_Balance_MV.Total, 0) AS Total, ISNULL(dbo.Agents_Balance_MV.Pure, 0) AS Pure, 
                         ISNULL(dbo.Agents_Balance_MV.Discount, 0) AS Discount, CONVERT(nvarchar(100), dbo.Agents_Balance_MV.S_Bill_Pr_ID) + CONVERT(nvarchar(100), ISNULL(dbo.Agents_Balance_MV.Table_ID, 0)) 
                         + CONVERT(nvarchar(100), ISNULL(dbo.Agents_Balance_MV.SB_ID, 0)) AS Search, dbo.Agents_Balance_MV.Barcode, dbo.Agents.Type_ID, ISNULL(dbo.Agents_Balance_MV.Pied, 0) AS Pied, dbo.Agents_Balance_MV.User_ID, 
                         dbo.Agents_Balance_MV.Frm_ID, ISNULL(dbo.Agents_Balance_MV.Receipt_Title, N'') AS Receipt_Title, dbo.Agents_Balance_MV.Frm_ID_M, ISNULL(dbo.Agents_Balance_MV.Cr_ID, 0) AS Cr_ID, 
                         ISNULL(dbo.Agents_Balance_MV.Travel_ID, 0) AS Travel_ID, Agents_1.Ag_name AS EMP_NAME
FROM            dbo.Agents_Balance_MV INNER JOIN
                         dbo.Agents ON dbo.Agents_Balance_MV.AG_ID = dbo.Agents.AG_ID INNER JOIN
                         dbo.Users ON dbo.Agents_Balance_MV.User_ID = dbo.Users.User_ID LEFT OUTER JOIN
                         dbo.Agents AS Agents_1 ON dbo.Agents_Balance_MV.Cr_ID = Agents_1.AG_ID
WHERE        (dbo.Agents_Balance_MV.BsType_ID = 13) OR
                         (dbo.Agents_Balance_MV.BsType_ID = 18)
GO
