CREATE VIEW [dbo].[IM_RtnPerfet_V]
AS
SELECT        dbo.IM_Menu.item_name, dbo.Units.U_Name, dbo.Rtn_Contents.QTY, dbo.Rtn_Contents.Cost, dbo.Rtn_Contents.Cost * dbo.Rtn_Contents.QTY AS T_Cost, dbo.Rtn_Contents.Price, dbo.Rtn_Contents.T_Price, 
                         dbo.Rtn_Contents.Price - dbo.Rtn_Contents.Cost AS Perfet_ByOne, (dbo.Rtn_Contents.Price - dbo.Rtn_Contents.Cost) * dbo.Rtn_Contents.QTY AS Total_Perfet, dbo.Rtn_Contents.Date, 
                         ((dbo.Rtn_Contents.Price - dbo.Rtn_Contents.Cost) * dbo.Rtn_Contents.QTY) * (dbo.Rtn_Contents.Saler_Percent / 100) AS RTN_Saler_Money, dbo.Rtn_Contents.ST_ID, dbo.General_menu.GM_ID, 
                         ISNULL(dbo.Rtn_Contents.is_By_Min_SP, 0) AS is_By_Min_SP, ISNULL(dbo.Rtn_Contents.is_By_Min_SP_2, 0) AS is_By_Min_SP_2, dbo.Rtn_Contents.Markter_Val * dbo.Rtn_Contents.QTY AS Markter_Val, 
                         dbo.Agents_Balance_MV.BsType_ID
FROM            dbo.Rtn_Contents INNER JOIN
                         dbo.IM_Menu ON dbo.Rtn_Contents.IM_ID = dbo.IM_Menu.IM_ID INNER JOIN
                         dbo.Units ON dbo.Rtn_Contents.U_ID = dbo.Units.U_ID INNER JOIN
                         dbo.General_menu ON dbo.IM_Menu.GM_ID = dbo.General_menu.GM_ID INNER JOIN
                         dbo.Agents_Balance_MV ON dbo.Rtn_Contents.Bill_T_ID = dbo.Agents_Balance_MV.T_ID
WHERE        (dbo.Rtn_Contents.isDepended = 1)

