CREATE VIEW [dbo].[Pch_Details_Report_V]
AS
SELECT        dbo.Agents_Balance_MV.Date, SUM(dbo.Pch_Details.ST_QTY / dbo.Units.U_Cargo) AS QYT, dbo.Users.UserName, dbo.IM_Menu.item_name, dbo.Pch_Details.Total AS Price, dbo.Stores.St_Name, dbo.Pch_Details.D_Vaild, 
                         dbo.Pch_Details.ST_ID, dbo.Units.U_Name + N'*' + CONVERT(varchar(12), dbo.Pch_Details.U_Cargo) AS U_NAME
FROM            dbo.Units INNER JOIN
                         dbo.IM_Units ON dbo.Units.U_ID = dbo.IM_Units.U_ID INNER JOIN
                         dbo.Agents_Balance_MV INNER JOIN
                         dbo.Users ON dbo.Agents_Balance_MV.User_ID = dbo.Users.User_ID INNER JOIN
                         dbo.Pch_Details ON dbo.Agents_Balance_MV.T_ID = dbo.Pch_Details.Pch_T_ID INNER JOIN
                         dbo.IM_Menu ON dbo.Pch_Details.IM_ID = dbo.IM_Menu.IM_ID INNER JOIN
                         dbo.Stores ON dbo.Pch_Details.ST_ID = dbo.Stores.ST_ID ON dbo.IM_Units.IM_ID = dbo.Pch_Details.IM_ID
WHERE        (dbo.Agents_Balance_MV.isVoid = 0) AND (dbo.Agents_Balance_MV.BsType_ID = 7) AND (dbo.Pch_Details.isDepended = 1) AND (dbo.IM_Units.is_Default = 1)
GROUP BY dbo.Agents_Balance_MV.Date, dbo.Users.UserName, dbo.IM_Menu.item_name, dbo.Pch_Details.Total, dbo.Stores.St_Name, dbo.Pch_Details.D_Vaild, dbo.Pch_Details.ST_ID, dbo.Units.U_Name + N'*' + CONVERT(varchar(12), 
                         dbo.Pch_Details.U_Cargo)



GO
