CREATE VIEW [dbo].[Periods_TotalCount_V]
AS
SELECT        TOP (100) PERCENT dbo.Periods.Pr_ID, dbo.Users.UserName, dbo.Periods.Pr_Start, dbo.Periods.Pr_End, ISNULL(dbo.Periods.NotesOn_Start, N'/') AS NotesOn_Start, ISNULL(dbo.Periods.NotesOn_End, N'/') AS NotesOn_End, 
                         SUM(ISNULL(dbo.Agents_Balance_MV.Pure, 0)) AS Pure
FROM            dbo.Periods INNER JOIN
                         dbo.Users ON dbo.Periods.User_ID = dbo.Users.User_ID LEFT OUTER JOIN
                         dbo.Agents_Balance_MV ON dbo.Periods.Pr_ID = dbo.Agents_Balance_MV.Pr_ID
WHERE        (dbo.Periods.Pr_isOpen = 0) AND (dbo.Agents_Balance_MV.BsType_ID = 1) OR
                         (dbo.Agents_Balance_MV.BsType_ID = 3)
GROUP BY dbo.Periods.Pr_ID, dbo.Users.UserName, dbo.Periods.Pr_Start, dbo.Periods.Pr_End, ISNULL(dbo.Periods.NotesOn_Start, N'/'), ISNULL(dbo.Periods.NotesOn_End, N'/')


























