                         dbo.Agents_Balance_MV.AG_ID, dbo.Users.UserName AS U_Name, ISNULL(dbo.Agents_Balance_MV.About, N'') AS About, dbo.Agents_Balance_MV.Date, ISNULL(dbo.Agents_Balance_MV.Total, 0) AS Total, 
