                         ISNULL(dbo.Agents_Balance_MV.Table_ID, 0)) + CONVERT(nvarchar(100), ISNULL(dbo.Agents_Balance_MV.SB_ID, 0)) AS Search, dbo.Agents_Balance_MV.Barcode, dbo.Agents.Type_ID, 
