                         dbo.Agents_Balance_MV.isDepended, dbo.Agents_Balance_MV.isVoid, dbo.Agents_Balance_MV.AG_ID, dbo.PiedTypes.PIED_Name, dbo.Agents_Balance_MV.S_Bills_Type, dbo.Users.UserName AS U_Name, 
                         ISNULL(dbo.Agents_Balance_MV.About, N'') AS About, dbo.Agents_Balance_MV.Pr_ID, dbo.Agents_Balance_MV.S_Bill_Pr_ID, dbo.Agents_Balance_MV.Date, ISNULL(dbo.Agents_Balance_MV.Total, 0) AS Total, 
                         ISNULL(dbo.Agents_Balance_MV.Pure, 0) AS Pure, ISNULL(dbo.Agents_Balance_MV.Discount, 0) AS Discount, CONVERT(nvarchar(100), dbo.Agents_Balance_MV.S_Bill_Pr_ID) + CONVERT(nvarchar(100), 
                         ISNULL(dbo.Agents_Balance_MV.Table_ID, 0)) + CONVERT(nvarchar(100), ISNULL(dbo.Agents_Balance_MV.SB_ID, 0)) AS Search, dbo.Agents_Balance_MV.SB_ID, ISNULL(dbo.Tables.T_Name, N'') AS T_Name, 
                         dbo.Agents_Balance_MV.Barcode, dbo.Agents.Type_ID, ISNULL(dbo.Agents_Balance_MV.Pied, 0) AS Pied, dbo.Users.User_ID, ISNULL(dbo.Agents_Balance_MV.TB_isOrderd, 0) AS TB_isOrderd, 
                         ISNULL(dbo.Agents_Balance_MV.Bill_Berfet, 0) AS Bill_Berfet, ISNULL(dbo.Agents_Balance_MV.Bill_Rtn_Berfet, 0) AS Bill_Rtn_Berfet, ISNULL(dbo.Agents_Balance_MV.Proj_ID, 1) AS Proj_ID, 
                         ISNULL(dbo.AG_Projects.Proj_NAME, N'N/A') AS Proj_NAME, ISNULL(dbo.Agents_Balance_MV.isPause, 0) AS isPause, ISNULL(dbo.Agents_Balance_MV.Markter_ID, 1) AS Markter_ID, ISNULL(dbo.Agents_Balance_MV.Travel_ID, 
                         1) AS Travel_ID, dbo.Travels_Costmers.Cr_Name, ISNULL(dbo.Agents_Balance_MV.Cr_Adress, N'') AS Cr_Adress, ISNULL(dbo.Agents_Balance_MV.Cr_Phone, N'') AS Cr_Phone, dbo.Void_Names.Void_NAME, 
                         dbo.Agents_Balance_MV.Cr_ID
