CREATE VIEW [dbo].[Tables_NotPied_V]
AS
SELECT        dbo.Agents_Balance_MV.Table_ID, dbo.Units.U_Name, dbo.IM_Menu.item_name + N'  ' + dbo.Units.U_Name + N'  ' + ISNULL(dbo.SB_Contents.Compons, N'') AS IM_Name, dbo.SB_Contents.Price, SUM(dbo.SB_Contents.QTY) 
                         AS QTY, SUM(dbo.SB_Contents.T_Price) AS T_Price, dbo.SB_Contents.IM_ID
FROM            dbo.Units INNER JOIN
                         dbo.Agents_Balance_MV INNER JOIN
                         dbo.SB_Contents ON dbo.Agents_Balance_MV.T_ID = dbo.SB_Contents.Bill_T_ID ON dbo.Units.U_ID = dbo.SB_Contents.U_ID INNER JOIN
                         dbo.IM_Menu ON dbo.SB_Contents.IM_ID = dbo.IM_Menu.IM_ID
WHERE        (dbo.Agents_Balance_MV.isPied = 0) AND (dbo.Agents_Balance_MV.isVoid = 0) AND (dbo.Agents_Balance_MV.TB_isOrderd = 1)
GROUP BY dbo.Agents_Balance_MV.Table_ID, dbo.Units.U_Name, dbo.IM_Menu.item_name + N'  ' + dbo.Units.U_Name + N'  ' + ISNULL(dbo.SB_Contents.Compons, N''), dbo.SB_Contents.Price, dbo.SB_Contents.IM_ID
