/****** Object:  View [dbo].[V_AccountingPostingMonitor]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [dbo].[V_AccountingPostingMonitor]
AS

SELECT
    CAST('MV' AS NVARCHAR(20)) AS SourceTable,
    m.T_ID,
    m.[Date],
    m.BsType_ID,
    t.Type_Name,
    a.AG_NAME,
    CAST(NULL AS nvarchar(2500)) AS Tr_name,
    m.Total,
    m.Discount,
    m.Pure,
    m.isDepended,
    m.isVoid,
    m.JournalId,
    m.PostedAt,
    m.PostedBy,
    CASE 
        WHEN m.JournalId IS NULL THEN N'غير مرحل'
        ELSE N'مرحل'
    END AS PostingStatus,
    m.Receipt_Title,
    m.About
FROM dbo.Agents_Balance_MV m
LEFT JOIN dbo.AgentBalance_Type t
    ON t.id = m.BsType_ID
LEFT JOIN dbo.Agents a
    ON M.AG_ID = a.AG_ID

UNION ALL

SELECT
    CAST('RCT' AS NVARCHAR(20)) AS SourceTable,
    r.T_ID,
    r.[Date],
    r.BsType_ID,
    t.Type_Name,
    a.AG_NAME,
    tr.Tr_NAME,
    r.Total,
    r.Discount,
    r.Pure,
    r.isDepended,
    r.isVoid,
    r.JournalId,
    r.PostedAt,
    r.PostedBy,
    CASE 
        WHEN r.JournalId IS NULL THEN N'غير مرحل'
        ELSE N'مرحل'
    END AS PostingStatus,
    r.Receipt_Title,
    r.About
FROM dbo.Agents_Balance_MV_RCT r
LEFT JOIN dbo.AgentBalance_Type t
    ON t.id = r.BsType_ID
LEFT JOIN dbo.TreasuryCard tr
    ON r.TR_ID = tr.TR_ID
	LEFT JOIN dbo.Agents a
    ON r.AG_ID = a.AG_ID;

GO
