/****** Object:  View [dbo].[VW_Budget_AvailableBalance]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[VW_Budget_AvailableBalance]
AS
SELECT
    a.BudgetItemId,
    a.FiscalYear,
    a.AllocatedAmount
        - ISNULL(SUM(CASE WHEN e.EntryType = 1 THEN e.Amount END), 0)
        - ISNULL(SUM(CASE WHEN e.EntryType = 2 THEN e.Amount END), 0)
        AS AvailableAmount
FROM Budget_Allocations a
LEFT JOIN Budget_Entries e
    ON a.BudgetItemId = e.BudgetItemId
    AND a.FiscalYear = e.FiscalYear
GROUP BY
    a.BudgetItemId,
    a.FiscalYear,
    a.AllocatedAmount;
GO
/****** Object:  View [dbo].[Vw_BudgetItemSummary]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[Vw_BudgetItemSummary]
AS
SELECT
    a.BudgetItemId,
    a.FiscalYear,

    /* الاعتماد */
    Allocated = ISNULL(a.AllocatedAmount, 0),

    /* المصروف */
    Spent = ISNULL(SUM(
        CASE WHEN e.EntryType = 1 THEN e.Amount ELSE 0 END
    ), 0),

    /* المحجوز (حجز - فك حجز) */
    Reserved = ISNULL(SUM(
        CASE
            WHEN e.EntryType = 2 THEN e.Amount      -- حجز
            WHEN e.EntryType = 3 THEN -e.Amount     -- فك حجز
            ELSE 0
        END
    ), 0),

    /* المتاح */
    Available =
        ISNULL(a.AllocatedAmount, 0)
      - ISNULL(SUM(CASE WHEN e.EntryType = 1 THEN e.Amount ELSE 0 END), 0)
      - ISNULL(SUM(
            CASE
                WHEN e.EntryType = 2 THEN e.Amount
                WHEN e.EntryType = 3 THEN -e.Amount
                ELSE 0
            END
        ), 0)

FROM Budget_Allocations a
LEFT JOIN Budget_Entries e
    ON e.BudgetItemId = a.BudgetItemId
   AND e.FiscalYear   = a.FiscalYear

GROUP BY
    a.BudgetItemId,
    a.FiscalYear,
    a.AllocatedAmount;
GO
/****** Object:  View [dbo].[Vw_BudgetReserveTimeline]    Script Date: 09/05/2026 16:40:10 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[Vw_BudgetReserveTimeline]
AS
SELECT
    e.BudgetEntryId,
    e.ReserveEntryId,
    e.BudgetItemId,
    e.FiscalYear,
    e.EntryDate,

    CASE e.EntryType
        WHEN 2 THEN N'حجز'
        WHEN 3 THEN N'فك حجز'
        ELSE N'-'
    END AS EntryTypeName,

    CASE
        WHEN e.EntryType = 2 THEN e.Amount
        WHEN e.EntryType = 3 THEN -e.Amount
        ELSE 0
    END AS SignedAmount,

    e.Amount,
    e.Notes,

    /* اسم / ملاحظات الحجز الأصلي */
    r.Notes AS ReserveNotes,

    /* الرصيد المحجوز التراكمي */
    SUM(
        CASE
            WHEN e.EntryType = 2 THEN e.Amount
            WHEN e.EntryType = 3 THEN -e.Amount
            ELSE 0
        END
    ) OVER (
        PARTITION BY e.BudgetItemId, e.FiscalYear
        ORDER BY e.EntryDate, e.BudgetEntryId
        ROWS UNBOUNDED PRECEDING
    ) AS ReservedBalanceAfter

FROM Budget_Entries e
LEFT JOIN Budget_Entries r
    ON e.ReserveEntryId = r.BudgetEntryId
WHERE e.EntryType IN (2,3);
GO
