CREATE PROCEDURE  [dbo].[AA_GET_MAX_agents]
AS
BEGIN
DECLARE @START_ID int,@END_ID int
SELECT @START_ID=START_ID,@END_ID=END_ID FROM SERVERS-- WHERE Serv_Name = @@SERVERNAME
RETURN (select isnull(max(      AG_ID   ),@START_ID) from    Agents    WHERE   AG_ID    BETWEEN @START_ID AND @END_ID  ) + 1
end




































GO
