/****** Object:  StoredProcedure [dbo].[ACC_BALANCE_DEPEND]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ACC_BALANCE_DEPEND](@T_ID int ,@Depended Bit = 1,@USER_ID INT,@OP_Status int Output,@ERROR_MSG NVARCHAR(500) Output,
@NextNumber VARCHAR(40)  Output) AS

BEGIN
DECLARE @DATE DATE
SELECT @DATE = CONVERT(DATE,DATE) FROM DBO.ACC_BALANCE_MASTER WHERE T_ID = @T_ID 

IF (SELECT is_Close_Month FROM F_YEAR_V WHERE CONVERT(DATE,@DATE) between M_FROM and M_TO ) = 1
BEGIN
--raiserror('السنة المالية لهذا التاريخ تم إقفالها',16,1,'خطأ في السنة المالية')
SET @OP_Status =0
SET @ERROR_MSG = 'السنة المالية لهذا التاريخ تم إقفالها'
GOTO EXIT_PROC
END

IF  (SELECT is_Close_Month FROM F_YEAR_V WHERE CONVERT(DATE,@DATE) between M_FROM and M_TO ) <> 0 --(SELECT is_Close_Month FROM F_YEAR_V WHERE @DATE between M_FROM and M_TO ) IS NULL OR
BEGIN
--raiserror(' لم يتم فتح سنة مالية لهذا التاريخ ',16,1,'خطأ في السنة المالية')
SET @OP_Status =0
SET @ERROR_MSG = ' لم يتم فتح سنة مالية لهذا التاريخ '
GOTO EXIT_PROC
END

 DECLARE  @YY INT 

SET @YY = DATEPART(YEAR, @DATE)
EXEC GetNextJournalNumber @T_ID,@YY,'قيد يومية',@DATE,@NextNumber = @NextNumber OUTPUT


  if @Depended = 0 BEGIN SET @USER_ID = NULL END
	UPDATE ACC_BALANCE_MASTER SET is_Depended = @Depended ,DEPEND_USER_ID = @USER_ID WHERE  T_ID = @T_ID 
	UPDATE ACC_BALANCE SET is_Depended = @Depended WHERE  B_T_ID = @T_ID 

	UPDATE ACC_BALANCE_MASTER SET JournalNumber = @NextNumber WHERE  T_ID = @T_ID  AND JournalNumber IS NULL


	EXIT_PROC:

END


GO
/****** Object:  StoredProcedure [dbo].[ACC_BALANCE_Insert_reverse]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ACC_BALANCE_Insert_reverse](@B_T_ID       int,@OP_Status int Output,@ERROR_MSG NVARCHAR(500) Output,@USER_ID INT,@B_T_ID_NEW int Output)ASBEGIN TRY
BEGIN TRANSACTION 
--BEGIN

declare @DATE DATE,@ACC_CODE VARCHAR(40) , @NextNumber VARCHAR(40), @T_ID_2 INT ,@NextNumber_OLD VARCHAR(40)


SELECT @DATE = CONVERT(DATE,DATE) , @NextNumber_OLD = ISNULL(JournalNumber,'') FROM DBO.ACC_BALANCE_MASTER WHERE T_ID = @B_T_ID 

IF (SELECT is_Close_Month FROM F_YEAR_V WHERE CONVERT(DATE,@DATE) between M_FROM and M_TO ) = 1
BEGIN
--raiserror('السنة المالية لهذا التاريخ تم إقفالها',16,1,'خطأ في السنة المالية')
SET @OP_Status =0
SET @ERROR_MSG = 'السنة المالية لهذا التاريخ تم إقفالها'
SELECT @B_T_ID
GOTO EXIT_PROC
END

IF  (SELECT is_Close_Month FROM F_YEAR_V WHERE CONVERT(DATE,@DATE) between M_FROM and M_TO ) <> 0 --(SELECT is_Close_Month FROM F_YEAR_V WHERE @DATE between M_FROM and M_TO ) IS NULL OR
BEGIN
--raiserror(' لم يتم فتح سنة مالية لهذا التاريخ ',16,1,'خطأ في السنة المالية')
SET @OP_Status =0
SET @ERROR_MSG = ' لم يتم فتح سنة مالية لهذا التاريخ '
SELECT @B_T_ID
GOTO EXIT_PROC
END


IF  EXISTS (SELECT 1 FROM ACC_BALANCE_MASTER WHERE T_ID = @B_T_ID ) 
BEGIN

IF (SELECT is_Lock_Trans FROM ACCOUNTS_TREE WHERE ACC_CODE = @ACC_CODE ) = 1
BEGIN
--raiserror(' لم يتم فتح سنة مالية لهذا التاريخ ',16,1,'خطأ في السنة المالية')
SET @OP_Status =0
SET @ERROR_MSG = ' لا يمكنك اضافة قيد للحساب '
SELECT @B_T_ID
GOTO EXIT_PROC
END

EXEC  @B_T_ID_NEW = AA_GET_MAX_ID 'ACC_BALANCE_MASTER'

DECLARE @YY INT
SET @YY = DATEPART(YEAR, @DATE)

EXEC GetNextJournalNumber @B_T_ID_NEW,@YY,'قيد يومية',@DATE,@NextNumber = @NextNumber OUTPUT

 INSERT INTO [dbo].[ACC_BALANCE_MASTER]
           ([T_ID],
		    [DATE],
           [NOTES],
		   [Currency_ID],
		   [Currency_Equal],
		   [USER_ID],
		   [JournalNumber],
		   [DEPEND_USER_ID],
		   [is_Depended])
     SELECT
           @B_T_ID_NEW
		    ,GETDATE()
           ,'قيد عكسي للقيد  (' + CONVERT(NVARCHAR(40),@B_T_ID) + ') ,  ' +  @NextNumber_OLD
		   ,Currency_ID
		   ,Currency_Equal
		   ,@USER_ID
		   ,@NextNumber
		   ,@USER_ID
		   ,1
		   FROM ACC_BALANCE_MASTER WHERE T_ID  = @B_T_ID


END

DECLARE @i int

SELECT @i = MIN(T_ID) FROM ACC_BALANCE WHERE B_T_ID = @B_T_ID

WHILE @i IS NOT NULL
BEGIN

EXEC  @T_ID_2 = AA_GET_MAX_ID 'ACC_BALANCE'

	INSERT INTO DBO.ACC_BALANCE	   ([T_ID],	    [B_T_ID],       --[DATE],       [ACC_CODE],       [DEBIT],       [CREDIT],       [USER_ID],       [Currency],       [Notes],	   [COST_ID],	   [Bill_Num],	   [is_Depended])	SELECT 	   @T_ID_2,	   @B_T_ID_NEW,       ACC_CODE,	   CREDIT,       DEBIT,       @USER_ID,       Currency,       'قيد عكسي للقيد  (' + CONVERT(NVARCHAR(40),@B_T_ID) + ') ,  ' +  @NextNumber_OLD,
	   COST_ID,
	   Bill_Num,	   [is_Depended]
	   FROM ACC_BALANCE WHERE T_ID = @i -- B_T_ID = @B_T_ID

             SELECT @i = MIN(T_ID) FROM ACC_BALANCE WHERE B_T_ID = @B_T_ID AND T_ID > @i
	   END


	   SELECT @B_T_ID_NEW

	   UPDATE ACC_BALANCE_MASTER SET is_reverse = 1 WHERE T_ID = @B_T_ID_NEW
	   UPDATE ACC_BALANCE_MASTER SET reverse_T_ID = @B_T_ID_NEW WHERE T_ID = @B_T_ID




EXIT_PROC:
 


--END

  COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = ' [ACC_BALANCE_Insert_reverse] - ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH


GO
/****** Object:  StoredProcedure [dbo].[ACC_BALANCE_MOVE_YEAR_TO_ARCHIVE]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ACC_BALANCE_MOVE_YEAR_TO_ARCHIVE](@YEAR        int,@TYPE INT = 1 --1: SEND 2:RECEIVE)ASBEGIN TRY
BEGIN TRANSACTION 

IF @TYPE = 1
BEGIN

UPDATE ACC_BALANCE_MASTER SET YEAR = @YEAR
UPDATE ACC_BALANCE SET YEAR = @YEAR


INSERT INTO ACC_BALANCE_MASTER_ARCHIVE ([T_ID]
      ,[DATE]
      ,[DATE_IN]
      ,[NOTES]
      ,[Currency_ID]
      ,[Currency_Equal]
      ,[is_Depended]
      ,[USER_ID]
      ,[DEPEND_USER_ID]
      ,[Receipt_Type]
      ,[Receipt_Num]
      ,[Bank_Name]
      ,[Check_Number]
      ,[IssueDate]
      ,[DueDate]
      ,[ChequeStatus]
      ,[ReconciliationDate]
      ,[BankTransactionNumber]
      ,[Cheque_Notes]
      ,[StatusId]
      ,[JournalNumber]
      ,[YEAR])
          SELECT [T_ID]
      ,[DATE]
      ,[DATE_IN]
      ,[NOTES]
      ,[Currency_ID]
      ,[Currency_Equal]
      ,[is_Depended]
      ,[USER_ID]
      ,[DEPEND_USER_ID]
      ,[Receipt_Type]
      ,[Receipt_Num]
      ,[Bank_Name]
      ,[Check_Number]
      ,[IssueDate]
      ,[DueDate]
      ,[ChequeStatus]
      ,[ReconciliationDate]
      ,[BankTransactionNumber]
      ,[Cheque_Notes]
      ,[StatusId]
      ,[JournalNumber]
      ,[YEAR] FROM ACC_BALANCE_MASTER

INSERT INTO ACC_BALANCE_ARCHIVE SELECT * FROM ACC_BALANCE

DELETE FROM ACC_BALANCE_MASTER
DELETE FROM ACC_BALANCE

END
ELSE IF @TYPE = 2
BEGIN

IF (SELECT COUNT(T_ID) FROM ACC_BALANCE_MASTER) > 0
BEGIN
RAISERROR (N'يوجد بيانات حاليا في القيود المحاسبية الغير مؤرشفة، لم يتم الحذف أو النقل', 16, 1) WITH NOWAIT;
--GOTO END_PROC
END


INSERT INTO ACC_BALANCE_MASTER ([T_ID]
      ,[DATE]
      ,[DATE_IN]
      ,[NOTES]
      ,[Currency_ID]
      ,[Currency_Equal]
      ,[is_Depended]
      ,[USER_ID]
      ,[DEPEND_USER_ID]
      ,[Receipt_Type]
      ,[Receipt_Num]
      ,[Bank_Name]
      ,[Check_Number]
      ,[IssueDate]
      ,[DueDate]
      ,[ChequeStatus]
      ,[ReconciliationDate]
      ,[BankTransactionNumber]
      ,[Cheque_Notes]
      ,[StatusId]
      ,[JournalNumber]
      ,[YEAR]) SELECT [T_ID]
      ,[DATE]
      ,[DATE_IN]
      ,[NOTES]
      ,[Currency_ID]
      ,[Currency_Equal]
      ,[is_Depended]
      ,[USER_ID]
      ,[DEPEND_USER_ID]
      ,[Receipt_Type]
      ,[Receipt_Num]
      ,[Bank_Name]
      ,[Check_Number]
      ,[IssueDate]
      ,[DueDate]
      ,[ChequeStatus]
      ,[ReconciliationDate]
      ,[BankTransactionNumber]
      ,[Cheque_Notes]
      ,[StatusId]
      ,[JournalNumber]
      ,[YEAR] FROM  ACC_BALANCE_MASTER_ARCHIVE WHERE YEAR = @YEAR

INSERT INTO ACC_BALANCE  SELECT * FROM ACC_BALANCE_ARCHIVE  WHERE YEAR = @YEAR

DELETE FROM ACC_BALANCE_MASTER_ARCHIVE WHERE YEAR = @YEAR
DELETE FROM ACC_BALANCE_ARCHIVE  WHERE YEAR = @YEAR



END



--END_PROC:

 COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = ' [ACC_BALANCE_MOVE_YEAR_TO_ARCHIVE] - ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH



GO
/****** Object:  StoredProcedure [dbo].[ACC_BALANCE_proc]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ACC_BALANCE_proc]
(@T_ID         int =NULL,
@B_T_ID       int,
@DATE         datetime = NULL,
@ACC_CODE     nvarchar(50) = NULL,
@DEBIT        numeric(18,3) = NULL,
@CREDIT       numeric(18,3) = NULL,
@USER_ID      int = NULL,
@IS_VOID      int = NULL,
@Currency     int = NULL,
@Notes_MASTER        nvarchar(Max) = NULL,
@Notes       nvarchar(Max) = NULL,
@Process	 NVARCHAR(50),
@Bill_Num	nvarchar(50) = '',
@COST_ID	int	= 1,
@Cr_ID      int = 1,
@Currency_Equal numeric(18,3) = 1,
@OP_Status int Output,
@ERROR_MSG NVARCHAR(500) Output,
@NextNumber VARCHAR(40)  Output
)
AS
--BEGIN TRY
--BEGIN TRANSACTION 
BEGIN
 
 DECLARE   @ACC_NAME NVARCHAR(2500) ='' --,@YY INT 


 SELECT @ACC_NAME = ACC_NAME FROM ACCOUNTS_TREE WHERE ACC_CODE = @ACC_CODE 


IF @Process = 'DELETE'
BEGIN
SELECT @DATE = CONVERT(DATE,DATE) FROM DBO.ACC_BALANCE_MASTER WHERE T_ID = @B_T_ID 
END

IF (SELECT is_Close_Month FROM F_YEAR_V WHERE CONVERT(DATE,@DATE) between M_FROM and M_TO ) = 1
BEGIN
--raiserror('السنة المالية لهذا التاريخ تم إقفالها',16,1,'خطأ في السنة المالية')
SET @OP_Status =0
SET @ERROR_MSG = 'السنة المالية لهذا التاريخ تم إقفالها'
SELECT @B_T_ID
GOTO EXIT_PROC
END

IF  (SELECT is_Close_Month FROM F_YEAR_V WHERE CONVERT(DATE,@DATE) between M_FROM and M_TO ) <> 0 --(SELECT is_Close_Month FROM F_YEAR_V WHERE @DATE between M_FROM and M_TO ) IS NULL OR
BEGIN
--raiserror(' لم يتم فتح سنة مالية لهذا التاريخ ',16,1,'خطأ في السنة المالية')
SET @OP_Status =0
SET @ERROR_MSG = ' لم يتم فتح سنة مالية لهذا التاريخ '
SELECT @B_T_ID
GOTO EXIT_PROC
END



IF @Process = 'DELETE'
BEGIN
	DELETE FROM DBO.ACC_BALANCE WHERE T_ID = @T_ID 

	SELECT @B_T_ID
END

IF @Process = 'UPDATE_MASTER'
BEGIN


--SET @YY = DATEPART(YEAR, @DATE)
--EXEC GetNextJournalNumber @B_T_ID,@YY,'قيد يومية',@DATE,@NextNumber = @NextNumber OUTPUT

IF (SELECT JournalNumber FROM ACC_BALANCE_MASTER WHERE T_ID = @B_T_ID) IS NULL
BEGIN
	UPDATE ACC_BALANCE_MASTER SET DATE = @DATE,NOTES = @Notes_MASTER 
	--, [JournalNumber] = @NextNumber  
	WHERE  T_ID = @B_T_ID 
END
ELSE
BEGIN
--raiserror('السنة المالية لهذا التاريخ تم إقفالها',16,1,'خطأ في السنة المالية')
SET @OP_Status =0
SET @ERROR_MSG = 'لا يمكن تعديل  تاريخ فاتورة تم إصدار رقم إشاري لها'
SELECT @B_T_ID
GOTO EXIT_PROC
END

	SELECT @B_T_ID
	GOTO EXIT_PROC
	--RETURN 1
END

IF EXISTS (SELECT 1 FROM ACC_BALANCE WHERE T_ID = @T_ID )
BEGIN
	UPDATE DBO.ACC_BALANCE
	SET [B_T_ID]       = @B_T_ID,
      -- [DATE]         = @DATE,
      -- [DATE_IN]      = @DATE_IN,
       [ACC_CODE]     = @ACC_CODE,
       [DEBIT]        = @DEBIT,
       [CREDIT]       = @CREDIT,
       [USER_ID]      = @USER_ID,
       [IS_VOID]      = @IS_VOID,
       --[Currency]     = @Currency,
       [Notes]        = @Notes,
	   [Bill_Num]     = @Bill_Num,
	   [COST_ID]      = @COST_ID

	WHERE T_ID = @T_ID 

	SELECT @B_T_ID
	--RETURN 1
END
ELSE
BEGIN


IF (SELECT is_Lock_Trans FROM ACCOUNTS_TREE WHERE ACC_CODE = @ACC_CODE ) = 1
BEGIN
--raiserror(' لم يتم فتح سنة مالية لهذا التاريخ ',16,1,'خطأ في السنة المالية')
SET @OP_Status =0
SET @ERROR_MSG =  ' لا يمكنك اضافة قيد - الحساب مقفل ' + @ACC_NAME
