IF (SELECT COUNT(T_ID) FROM ACC_BALANCE_MASTER WHERE T_ID = @B_T_ID) = 0 BEGIN UPDATE ACC_BALANCE_MASTER SET USER_ID = @USER_ID WHERE T_ID = @B_T_ID END

DECLARE @T_ID_2 INT 
