/****** Object:  StoredProcedure [dbo].[ACC_BALANCE_proc_BULK]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[ACC_BALANCE_proc_BULK]
(
    @B_T_ID              INT = NULL,
    @DATE                DATETIME = NULL,
    @USER_ID             INT = NULL,
    @IS_VOID             INT = 0,
    @Notes_MASTER        NVARCHAR(MAX) = NULL,
    @Cr_ID               INT = 1,
    @Currency_Equal      NUMERIC(18,3) = 1,

    @Rows                dbo.ACC_BALANCE_BULK_TYPE READONLY,

    @OP_Status           INT OUTPUT,
    @ERROR_MSG           NVARCHAR(500) OUTPUT,
    @NextNumber          VARCHAR(40) OUTPUT,
    @New_B_T_ID          INT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        SET @OP_Status = 1;
        SET @ERROR_MSG = N'تمت العملية بنجاح';
        SET @New_B_T_ID = ISNULL(@B_T_ID, 0);

        ------------------------------------------------------------
        -- 1) التحقق من وجود تفاصيل
        ------------------------------------------------------------
        IF NOT EXISTS (SELECT 1 FROM @Rows)
        BEGIN
            SET @OP_Status = 0;
            SET @ERROR_MSG = N'لا توجد تفاصيل لإضافتها';
            ROLLBACK TRANSACTION;
            RETURN;
        END

        ------------------------------------------------------------
        -- 2) التحقق من التاريخ
        ------------------------------------------------------------
        IF @DATE IS NULL
        BEGIN
            SET @OP_Status = 0;
            SET @ERROR_MSG = N'يجب تحديد تاريخ القيد';
            ROLLBACK TRANSACTION;
            RETURN;
        END

        ------------------------------------------------------------
        -- 7) التحقق أن كل سطر به قيمة مدينة أو دائنة
        ------------------------------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM @Rows
            WHERE ISNULL(DEBIT, 0) = 0
              AND ISNULL(CREDIT, 0) = 0
        )
        BEGIN
            SET @OP_Status = 0;
            SET @ERROR_MSG = N'يوجد سطر بدون قيمة مدينة أو دائنة';
            ROLLBACK TRANSACTION;
            RETURN;
        END

        ------------------------------------------------------------
        -- 8) منع أن يكون السطر مدين ودائن في نفس الوقت
        ------------------------------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM @Rows
            WHERE ISNULL(DEBIT, 0) > 0
              AND ISNULL(CREDIT, 0) > 0
        )
        BEGIN
            SET @OP_Status = 0;
            SET @ERROR_MSG = N'لا يمكن أن يكون السطر مدين ودائن في نفس الوقت';
            ROLLBACK TRANSACTION;
            RETURN;
        END

        ------------------------------------------------------------
        -- 9) التحقق من توازن القيد
        ------------------------------------------------------------
        DECLARE @TotalDebit  NUMERIC(18,3);
        DECLARE @TotalCredit NUMERIC(18,3);

        SELECT 
            @TotalDebit  = SUM(ISNULL(DEBIT, 0)),
            @TotalCredit = SUM(ISNULL(CREDIT, 0))
        FROM @Rows;

        IF ISNULL(@TotalDebit, 0) <> ISNULL(@TotalCredit, 0)
        BEGIN
            SET @OP_Status = 0;
            SET @ERROR_MSG = N'القيد غير متوازن، إجمالي المدين لا يساوي إجمالي الدائن';
            ROLLBACK TRANSACTION;
            RETURN;
        END

        ------------------------------------------------------------
        -- 10) إنشاء ACC_BALANCE_MASTER إذا لم يكن موجودًا
        ------------------------------------------------------------
        IF ISNULL(@B_T_ID, 0) = 0 
           OR NOT EXISTS (SELECT 1 FROM ACC_BALANCE_MASTER WHERE T_ID = @B_T_ID)
        BEGIN
            EXEC @B_T_ID = AA_GET_MAX_ID 'ACC_BALANCE_MASTER';

            INSERT INTO [dbo].[ACC_BALANCE_MASTER]
            (
                [T_ID],
                [DATE],
                [NOTES],
                [Currency_ID],
                [Currency_Equal],
                [USER_ID],
                [JournalNumber]
            )
            VALUES
            (
                @B_T_ID,
                @DATE,
                @Notes_MASTER,
                @Cr_ID,
                @Currency_Equal,
                @USER_ID,
                @NextNumber
            );
        END
        ELSE
        BEGIN
            --------------------------------------------------------
            -- إذا كان القيد الرئيسي موجودًا، نحدّث بياناته بشرط عدم وجود رقم إشاري
            --------------------------------------------------------
            IF (SELECT JournalNumber FROM ACC_BALANCE_MASTER WHERE T_ID = @B_T_ID) IS NULL
            BEGIN
                UPDATE ACC_BALANCE_MASTER
                SET 
                    [DATE] = @DATE,
                    [NOTES] = @Notes_MASTER,
                    [Currency_ID] = @Cr_ID,
                    [Currency_Equal] = @Currency_Equal,
                    [USER_ID] = @USER_ID
                WHERE T_ID = @B_T_ID;
            END
            ELSE
            BEGIN
                SET @OP_Status = 0;
                SET @ERROR_MSG = N'لا يمكن تعديل قيد تم إصدار رقم إشاري له';
                ROLLBACK TRANSACTION;
                RETURN;
            END
        END

        SET @New_B_T_ID = @B_T_ID;

        ------------------------------------------------------------
        -- 11) توليد أرقام T_ID للتفاصيل دفعة واحدة
        ------------------------------------------------------------
        DECLARE @Start_T_ID INT;

        SELECT @Start_T_ID = ISNULL(MAX(T_ID), 0) + 1
        FROM ACC_BALANCE WITH (TABLOCKX, HOLDLOCK);

        ;WITH OrderedRows AS
        (
            SELECT
                ROW_NUMBER() OVER 
                (
                    ORDER BY 
                        ISNULL(RowNo, 2147483647),
                        ACC_CODE
                ) AS RN,
                ACC_CODE,
                DEBIT,
                CREDIT,
                Currency,
                Notes,
                Bill_Num,
                COST_ID
            FROM @Rows
        )
        INSERT INTO DBO.ACC_BALANCE
        (
            [T_ID],
            [B_T_ID],
            [ACC_CODE],
            [DEBIT],
            [CREDIT],
            [USER_ID],
            [IS_VOID],
            [Currency],
            [Notes],
            [COST_ID],
            [Bill_Num]
        )
        SELECT
            @Start_T_ID + RN - 1,
            @B_T_ID,
            ACC_CODE,
            ISNULL(DEBIT, 0),
            ISNULL(CREDIT, 0),
            @USER_ID,
            @IS_VOID,
            Currency,
            Notes,
            ISNULL(COST_ID, 1),
            ISNULL(Bill_Num, N'')
        FROM OrderedRows;

EXEC ACC_BALANCE_DEPEND@T_ID  = @B_T_ID ,@Depended  = 1,@USER_ID = @USER_ID,@OP_Status = '',@ERROR_MSG ='',
@NextNumber =''

        COMMIT TRANSACTION;

        SET @OP_Status = 1;
        SET @ERROR_MSG = N'تمت إضافة القيد وتفاصيله بنجاح';
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @OP_Status = 0;
        SET @ERROR_MSG = N'[ACC_BALANCE_proc_BULK] - ' + ERROR_MESSAGE();
        SET @New_B_T_ID = ISNULL(@B_T_ID, 0);
    END CATCH
END
GO
