--exec [dbo].[ACC_BALANCE_proc]--(NULL,--@B_T_ID,--@DATE,--@ACC_CODE_FROM,--@DEBIT,--@CREDIT,--@USER_ID,--0,--1,--@Notes_MASTER,--@Notes_MASTER,--'',--'',--@COST_ID,--1,--1,--@OP_Status,--@ERROR_MSG--)

--exec  [dbo].[ACC_BALANCE_proc]--(0,--@B_T_ID,--@DATE,--@ACC_CODE_TO,--@DEBIT,--@CREDIT,--@USER_ID,--0,--1,--@Notes_MASTER,--@Notes_MASTER,--'',--'',--@COST_ID,--1,--1,--1,--@ERROR_MSG,--@Receipt_Type,
