--exec  [dbo].[ACC_BALANCE_proc]--(@T_ID         int =NULL,--@B_T_ID       int,--@DATE         datetime = NULL,--@ACC_CODE     nvarchar(50) = NULL,--@DEBIT        numeric(18,3) = NULL,--@CREDIT       numeric(18,3) = NULL,--@USER_ID      int = NULL,--@IS_VOID      int = NULL,--@Currency     int = NULL,--@Notes_MASTER        nvarchar(Max) = NULL,--@Notes       nvarchar(Max) = NULL,--@Process	 NVARCHAR(50),--@Bill_Num	nvarchar(50) = '',--@COST_ID	int	= 1,--@Cr_ID      int = 1,--@Currency_Equal numeric(18,3) = 1,--@OP_Status int Output,--@ERROR_MSG NVARCHAR(500) Output,--@Receipt_Type	int	,
