/****** Object:  StoredProcedure [dbo].[ACC_GenerateClosingEntry]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ACC_GenerateClosingEntry]
    @ParentAccCode      VARCHAR(50),
    @TargetAccCode      VARCHAR(50),
    @ClosingDate        DATETIME,
    @UserId             INT,
    @ClosingType        NVARCHAR(20),      -- REVENUE / EXPENSE
    @NotesMaster        NVARCHAR(MAX),
    @CurrencyId         INT = 1,
    @CurrencyEqual      NUMERIC(18,3) = 1,
    @CostId             INT = 1,
	@YEAR               INT,
    @B_T_ID             INT OUTPUT,
    @OP_Status          INT OUTPUT,
    @ERROR_MSG          NVARCHAR(500) OUTPUT,
    @NextNumber         VARCHAR(40) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

	DECLARE @DATE_F DATE,@DATE_T DATE

	SELECT TOP 1 @DATE_F = M_FROM FROM MONTHS_CALENDR WHERE YEAR = @YEAR 
	SELECT TOP 1 @DATE_T = M_TO FROM MONTHS_CALENDR WHERE YEAR = @YEAR ORDER BY M_ID DESC
	EXEC PREPARE_ACC_BALANCE 0,@DATE_F,@DATE_T,0

    BEGIN TRY
        BEGIN TRAN;

        SET @OP_Status = 1;
        SET @ERROR_MSG = N'';

        DECLARE @TotalAmount NUMERIC(18,3) = 0;
        DECLARE @AccCode VARCHAR(50);
        DECLARE @AccName NVARCHAR(2500);
        DECLARE @Balance NUMERIC(18,3);
        DECLARE @LineNote NVARCHAR(MAX);

        DECLARE @LineDebit NUMERIC(18,3);
        DECLARE @LineCredit NUMERIC(18,3);

        IF @ClosingType NOT IN ('REVENUE', 'EXPENSE')
        BEGIN
            SET @OP_Status = 0;
            SET @ERROR_MSG = N'نوع الإقفال غير صحيح';
            ROLLBACK TRAN;
            RETURN;
        END

        IF @B_T_ID IS NULL
            SET @B_T_ID = 0;

        ;WITH AccountTree AS
        (
            SELECT 
                T_ID, ACC_CODE, ACC_NAME, ACC_PARENT, ACC_LEVEL
            FROM ACCOUNTS_TREE
            WHERE ACC_CODE = @ParentAccCode

            UNION ALL

            SELECT 
                a.T_ID, a.ACC_CODE, a.ACC_NAME, a.ACC_PARENT, a.ACC_LEVEL
            FROM ACCOUNTS_TREE a
            INNER JOIN AccountTree at 
                ON a.ACC_PARENT = at.ACC_CODE
        )
        SELECT
            V.ACC_CODE,
            V.ACC_NAME,
            CAST(ABS(ISNULL(V.BALANCE, 0)) AS NUMERIC(18,3)) AS BALANCE
        INTO #ClosingAccounts
        FROM AccountTree T
        INNER JOIN ACCOUNTS_TREE_V V
            ON V.ACC_CODE = T.ACC_CODE
        WHERE 
            T.ACC_CODE <> @ParentAccCode
            AND ISNULL(V.BALANCE, 0) <> 0
            AND ISNULL(V.is_Lock_Trans, 0) = 0
            AND NOT EXISTS
            (
                SELECT 1
                FROM ACCOUNTS_TREE C
                WHERE C.ACC_PARENT = T.ACC_CODE
            );

        IF NOT EXISTS (SELECT 1 FROM #ClosingAccounts)
        BEGIN
            SET @OP_Status = 0;
            SET @ERROR_MSG = N'لا توجد حسابات نهائية بأرصدة غير صفرية للإقفال';
            ROLLBACK TRAN;
            RETURN;
        END

        DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT ACC_CODE, ACC_NAME, BALANCE
        FROM #ClosingAccounts
        ORDER BY ACC_CODE;

        OPEN cur;
        FETCH NEXT FROM cur INTO @AccCode, @AccName, @Balance;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            SET @LineNote = N'قيد إقفال للحساب: ' + ISNULL(@AccName, N'');

            SET @LineDebit = 0;
            SET @LineCredit = 0;

            IF @ClosingType = 'REVENUE'
            BEGIN
                SET @LineDebit = NULL;
                SET @LineCredit = @Balance ;
            END
            ELSE
            BEGIN
                SET @LineDebit = @Balance ;
                SET @LineCredit = NULL;
            END

            EXEC dbo.ACC_BALANCE_proc
                @T_ID = NULL,
                @B_T_ID = @B_T_ID,
                @DATE = @ClosingDate,
                @ACC_CODE = @AccCode,
                @DEBIT =  @LineDebit,
                @CREDIT = @LineCredit ,
                @USER_ID = @UserId,
                @IS_VOID = 0,
                @Currency = @CurrencyId,
                @Notes_MASTER = @NotesMaster,
                @Notes = @LineNote,
                @Process = 'ADD',
                @Bill_Num = '',
                @COST_ID = @CostId,
                @Cr_ID = @CurrencyId,
                @Currency_Equal = @CurrencyEqual,
                @OP_Status = @OP_Status OUTPUT,
                @ERROR_MSG = @ERROR_MSG OUTPUT,
                @NextNumber = @NextNumber OUTPUT;

            IF ISNULL(@OP_Status, 0) = 0
            BEGIN
                CLOSE cur;
                DEALLOCATE cur;
                ROLLBACK TRAN;
                RETURN;
            END

            SET @TotalAmount = @TotalAmount + @Balance;

            FETCH NEXT FROM cur INTO @AccCode, @AccName, @Balance;
        END

        CLOSE cur;
        DEALLOCATE cur;

        SET @LineNote = N'الحساب المرحل إليه';

        SET @LineDebit = 0;
        SET @LineCredit = 0;

        IF @ClosingType = 'EXPENSE'
        BEGIN
            SET @LineDebit  =NULL;
            SET @LineCredit = @TotalAmount;
        END
        ELSE
        BEGIN
            SET @LineDebit  = @TotalAmount;
            SET @LineCredit = NULL;
        END

        EXEC dbo.ACC_BALANCE_proc
            @T_ID = NULL,
            @B_T_ID = @B_T_ID,
            @DATE = @ClosingDate,
            @ACC_CODE = @TargetAccCode,
            @DEBIT = @LineDebit,
            @CREDIT = @LineCredit,
            @USER_ID = @UserId,
            @IS_VOID = 0,
            @Currency = @CurrencyId,
            @Notes_MASTER = @NotesMaster,
            @Notes = @LineNote,
            @Process = 'ADD',
            @Bill_Num = '',
            @COST_ID = @CostId,
            @Cr_ID = @CurrencyId,
            @Currency_Equal = @CurrencyEqual,
            @OP_Status = @OP_Status OUTPUT,
            @ERROR_MSG = @ERROR_MSG OUTPUT,
            @NextNumber = @NextNumber OUTPUT;

        IF ISNULL(@OP_Status, 0) = 0
        BEGIN
            ROLLBACK TRAN;
            RETURN;
        END

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF CURSOR_STATUS('local', 'cur') >= -1
        BEGIN
            CLOSE cur;
            DEALLOCATE cur;
        END

        IF @@TRANCOUNT > 0
            ROLLBACK TRAN;

        SET @OP_Status = 0;
        SET @ERROR_MSG = ERROR_MESSAGE();
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[ACC_MV]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[ACC_MV] 
@ACC_CODE varchar(40),
@DATE_F DATE ,
@DATE_T DATE ,
@DEBIT FLOAT OUTPUT,
@CREDIT FLOAT OUTPUT,
@COST_ID INT = NULL,
@is_settlement bit = 0 
AS
--BEGIN 

BEGIN TRY
BEGIN TRANSACTION 

DECLARE @FIRST_DATE DATE

SELECT TOP 1 @FIRST_DATE =  M_FROM FROM MONTHS_CALENDR WHERE YEAR = (SELECT YEAR_ID FROM YEARS WHERE is_Close = 0) 


IF OBJECT_ID('tempdb..##ACC_MV_Tmp') IS NOT NULL
 drop TABLE [##ACC_MV_Tmp]

CREATE TABLE [dbo].[##ACC_MV_Tmp](
	[T_ID] [int] IDENTITY(1,1) NOT NULL,
	[IDX] [int]  NULL,
	[is_Auto] [bit]  NOT NULL,
	[رقم الحساب] [nvarchar](50) NULL,
	[مركز التكلفـــة] [nvarchar](50) NULL,
	[التاريــخ] datetime NULL,
	[رقم القيــد] NVARCHAR(4000) NULL,
	[الإشاري] NVARCHAR(4000) NULL,
	[البيــان] [nvarchar](max) NULL,
	[دائن] [float] NULL,
	[مدين] [float] NULL,
	[الرصيد] [float] NULL,
	[CREDIT] [float] NULL,
	[DEBIT] [float] NULL,
	[رقم الحركة البنكية] nvarchar(50) NULL,
	[مطابق] BIT NULL

 CONSTRAINT [PK_ACC_MV_Tmp] PRIMARY KEY CLUSTERED 
(
	[T_ID] ASC
)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
) ON [PRIMARY] TEXTIMAGE_ON [PRIMARY]


DECLARE @DEBIT_PEFORE AS float=0, @CREDIT_PEFORE AS float=0 

IF @FIRST_DATE < @DATE_F
BEGIN

SELECT @DEBIT_PEFORE = ISNULL(SUM(DEBIT),0),@CREDIT_PEFORE = ISNULL(SUM(CREDIT),0) FROM SALES_SYSTEM_BALANCES_V WHERE ACC_CODE = @ACC_CODE  And  ( convert(date,date) BETWEEN @FIRST_DATE AND @DATE_F ) --convert(date,date) < @DATE_F

SELECT @DEBIT_PEFORE = @DEBIT_PEFORE + ISNULL(SUM(DEBIT),0),@CREDIT_PEFORE = @CREDIT_PEFORE + ISNULL(SUM(CREDIT),0) FROM ACC_BALANCE_V 
WHERE ACC_CODE = @ACC_CODE  And ( convert(date,date) BETWEEN @FIRST_DATE AND @DATE_F ) AND is_Depended = 1 AND  (@COST_ID IS NULL OR COST_ID = @COST_ID) 


--------------------------------------------------------------------------------------------------------------------- FROM SALES

INSERT INTO [dbo].[##ACC_MV_Tmp]
           ([is_Auto]
		   ,[رقم الحساب]
           ,[التاريــخ]
		   ,[مركز التكلفـــة]
           ,[رقم القيــد]
		   ,[الإشاري]
           ,[البيــان]
           ,[دائن]
           ,[مدين]
           ,[الرصيد]
		   ,[CREDIT]
		   ,[DEBIT])
	
SELECT 1,@ACC_CODE,NULL,'',0,'',CONVERT(NVArchar(MAX),'الرصيد قبل المدة'),@DEBIT_PEFORE,@CREDIT_PEFORE,0,@CREDIT_PEFORE,@DEBIT_PEFORE --الرصيد قبل المدة

END

INSERT INTO [dbo].[##ACC_MV_Tmp]
           ([is_Auto]
		   ,[رقم الحساب]
           ,[التاريــخ]
		   ,[مركز التكلفـــة]
           ,[رقم القيــد]
		   ,[الإشاري]
           ,[البيــان]
           ,[دائن]
           ,[مدين]
           ,[الرصيد]
		   ,[CREDIT]
		   ,[DEBIT])
SELECT 1,ACC_CODE,DATE,'',Tran_ID,'',CONVERT(NVArchar(MAX),Bill_NUM),DEBIT,CREDIT,(ISNULL(CREDIT,0)-ISNULL(DEBIT,0)),CREDIT,DEBIT FROM SALES_SYSTEM_BALANCES_V WHERE ACC_CODE = @ACC_CODE AND CONVERT(DATE,DATE) BETWEEN @DATE_F AND @DATE_T


-------------------------------------------------------------------------------------------------------------------- FROM SALES



INSERT INTO [dbo].[##ACC_MV_Tmp]
           (
		   [is_Auto]
		   ,[رقم الحساب]
           ,[التاريــخ]
		   ,[مركز التكلفـــة]
           ,[رقم القيــد]
		   ,[الإشاري]
           ,[البيــان]
           ,[دائن]
           ,[مدين]
           ,[الرصيد]
		   ,[CREDIT]
		   ,[DEBIT]
		   ,[رقم الحركة البنكية]
		   ,[مطابق]
		   )

SELECT 
0,a.[رقم الحساب],a.[التاريــخ],a.[مركز التكلفـــة],a.[رقم القيــد],a.[الإشاري],a.[البيــان],a.[دائن],a.[مدين],

SUM(a.[الرصيد])
OVER (ORDER BY a.[رقم القيــد] ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS 'الرصيد',
a.CREDIT,a.DEBIT
,a.[رقم الحركة البنكية],a.[مطابق]
from
(

SELECT ACC_CODE AS 'رقم الحساب',DATE AS 'التاريــخ',COST_NAME as 'مركز التكلفـــة',B_T_ID AS 'رقم القيــد',JournalNumber as 'الإشاري',NOTES AS 'البيــان',DEBIT AS 'دائن',CREDIT AS 'مدين',BALANCE AS 'الرصيد'
,CREDIT,DEBIT,BankTransactionNumber AS 'رقم الحركة البنكية',0 AS 'مطابق'  FROM ACC_BALANCE_V   WHERE
 convert(date,date) between  @DATE_F AND @DATE_T  AND ACC_CODE = @ACC_CODE  AND is_Depended = 1 AND  (@COST_ID IS NULL OR COST_ID = @COST_ID) 


) as a
  ORDER BY a.[التاريــخ] ASC


DELETE FROM [dbo].[##ACC_MV_Tmp] WHERE ( convert(date,[التاريــخ]) NOT BETWEEN @DATE_F AND @DATE_T )  AND [التاريــخ] IS NOT NULL   --<> '1900-01-01'

SELECT @DEBIT = ISNULL(SUM(DEBIT),0) , @CREDIT = ISNULL(SUM(CREDIT),0)  FROM ##ACC_MV_Tmp

exec [ReCount_Acc_balance] @ACC_CODE,@DATE_F,@DATE_T



UPDATE t
SET t.[IDX] = x.NewNumber
FROM dbo.[##ACC_MV_Tmp] t
JOIN (
    SELECT [T_ID],
           ROW_NUMBER() OVER (ORDER BY [T_ID] ASC) AS NewNumber
    FROM dbo.[##ACC_MV_Tmp]
) x ON t.[T_ID] = x.[T_ID];



IF @is_settlement = 0
BEGIN
  SELECT 
       [is_Auto]  AS [قيد ألي]
      ,[IDX] AS 'ت'
      ,[التاريــخ]
      ,[رقم القيــد]
	  ,[الإشاري]
      ,[البيــان]
	  ,[مدين]
      ,[دائن]
      ,[الرصيد]
      ,[CREDIT]
      ,[DEBIT]
  FROM [dbo].[##ACC_MV_Tmp]
  ORDER BY [التاريــخ] ASC
END
ELSE
BEGIN
  SELECT 
       [is_Auto]  AS [قيد ألي]
      ,[IDX] AS 'ت'
      ,[التاريــخ]
	  ,[رقم القيــد]
      ,[رقم الحركة البنكية]
	  ,[الإشاري]
      ,[البيــان]
	  ,CASE WHEN [مدين] IS NULL THEN [دائن] ELSE [مدين] END AS [القيمة]
	  ,[مدين]
      ,[دائن]
        ,[الرصيد]
	  ,[مطابق]
      ,[CREDIT]
      ,[DEBIT]
  FROM [dbo].[##ACC_MV_Tmp]

END


--END
 COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = ' [ReCount_Acc_balance] - ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH
























