/****** Object:  StoredProcedure [dbo].[Account_Tree_SELECT_BY_ACC_CODE]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Account_Tree_SELECT_BY_ACC_CODE] 
@AccountCode varchar(50)
AS
BEGIN 
WITH AccountTree AS (
    -- القاعدة الأساسية: تحديد الحساب المدخل
    SELECT T_ID, ACC_CODE, ACC_NAME, ACC_PARENT, ACC_LEVEL
    FROM ACCOUNTS_TREE
    WHERE ACC_CODE = @AccountCode

    UNION ALL

    -- الاستدعاء الذاتي لاسترجاع جميع الأبناء المرتبطين فقط
    SELECT a.T_ID, a.ACC_CODE, a.ACC_NAME, a.ACC_PARENT, a.ACC_LEVEL
    FROM ACCOUNTS_TREE a
    INNER JOIN AccountTree at ON a.ACC_PARENT = at.ACC_CODE
)

-- استرجاع الشجرة الكاملة
SELECT * 
FROM AccountTree
ORDER BY ACC_LEVEL, ACC_CODE;

END


























GO
/****** Object:  StoredProcedure [dbo].[ACCOUNTS_TREE_pros]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ACCOUNTS_TREE_pros](@T_ID            bigint,@ACC_CODE        nvarchar(50) = NULL,@ACC_LEVEL       int = NULL,@ACC_PARENT      nvarchar(50) = NULL,@ACC_NAME        nvarchar(500) = NULL,@ACC_TYPE        int = NULL,@ACC_CAT         nvarchar(500) = NULL,@ACC_CLOSING     int = NULL,@ACC_NATURAL    CHAR(1) = 'C',@is_Balance_View int = NULL,@cash_flow_ID INT = 0,@Process	 VARCHAR(20),@SIDE NVARCHAR(100),@is_Lock_Trans	int,@ACC_DIGIT INT = NULL) AS

BEGIN
IF @Process = 'DELETE'
BEGIN

IF (SELECT count(T_ID) FROM ACC_BALANCE_V WHERE ACC_CODE = @ACC_CODE OR ACC_PARENT = @ACC_CODE) = 0
  BEGIN

	DELETE FROM dbo.ACCOUNTS_TREE	 WHERE T_ID = @T_ID 
	RETURN 1
	END
	ELSE
BEGIN
raiserror('لايمكن حذف حساب عليه حركة',16,1,'خطأ')
END


END

IF EXISTS (SELECT 1 FROM ACCOUNTS_TREE WHERE T_ID = @T_ID )
BEGIN
  
  IF @ACC_DIGIT IS NULL BEGIN SET @ACC_DIGIT = @ACC_PARENT END

	UPDATE dbo.ACCOUNTS_TREE	SET [ACC_CODE]        = @ACC_CODE,       --[ACC_LEVEL]       = @ACC_LEVEL,       --[ACC_PARENT]      = @ACC_PARENT,       [ACC_NAME]        = @ACC_NAME,       [ACC_TYPE]        = @ACC_TYPE,       [ACC_CAT]         = @ACC_CAT,       [ACC_CLOSING]     = @ACC_CLOSING,	   [ACC_NATURAL]     = @ACC_NATURAL,	   [is_Balance_View] = @is_Balance_View,	   [cash_flow_ID]    = @cash_flow_ID,	   [SIDE]            = @SIDE,	   [is_Lock_Trans]   = @is_Lock_Trans,	   [ACC_DIGIT] = @ACC_DIGIT 	WHERE T_ID = @T_ID 
	RETURN 1
END
ELSE
BEGIN

--SET @ACC_PARENT = @ACC_CODE

SELECT @T_ID = (SELECT MAX(T_ID)+1 FROM  ACCOUNTS_TREE)

	INSERT INTO dbo.ACCOUNTS_TREE	  ([T_ID],	  [ACC_CODE],       [ACC_LEVEL],       [ACC_PARENT],       [ACC_NAME],       [ACC_TYPE],       [ACC_CAT],       [ACC_CLOSING],	   [ACC_NATURAL],	   [is_Balance_View],	   [cash_flow_ID]	   ,[SIDE]	   ,[is_Lock_Trans]	   ,[ACC_DIGIT])	SELECT @T_ID,	   @ACC_CODE,       @ACC_LEVEL,       @ACC_PARENT,       @ACC_NAME,       @ACC_TYPE,       @ACC_CAT,       @ACC_CLOSING,
	   @ACC_NATURAL,
	   @is_Balance_View,
	   @cash_flow_ID,
	   @SIDE,
	   @is_Lock_Trans,
	   @ACC_DIGIT

	   SELECT @T_ID
	--RETURN 1
END
 
END


GO
/****** Object:  StoredProcedure [dbo].[ACCOUNTS_TREE_SELECT_TABLE]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ACCOUNTS_TREE_SELECT_TABLE] AS

BEGIN

WITH RecursiveHierarchy AS (
    SELECT T_ID, ACC_CODE, ACC_NAME, ACC_PARENT, ACC_LEVEL , is_Balance_View,ACC_CLOSING,SIDE,is_Lock_Trans
    FROM ACCOUNTS_TREE
    WHERE ACC_PARENT = 0  -- اختيار الحسابات الرئيسية (الأب)
    
    UNION ALL
    
    SELECT d.T_ID, d.ACC_CODE, d.ACC_NAME, d.ACC_PARENT, d.ACC_LEVEL, d.is_Balance_View,d.ACC_CLOSING,d.SIDE,d.is_Lock_Trans
    FROM ACCOUNTS_TREE d
    INNER JOIN RecursiveHierarchy r
    ON d.ACC_PARENT = r.ACC_CODE  -- ربط الأبناء بالأب من خلال ACC_PARENT
)
SELECT * 
FROM RecursiveHierarchy
ORDER BY ACC_CODE;  -- الترتيب حسب رقم الكود
 
END


