CREATE PROCEDURE  [dbo].[Activation_Details_insert]
@CP_NAME	nvarchar(500) = NULL,
@Cpu_ID	nvarchar(200) = NULL,
@ProductCode	nvarchar(200) = NULL,
@SerialNum	nvarchar(200) = NULL,
@ActiveCode	nvarchar(200) = NULL
AS
BEGIN

