/****** Object:  StoredProcedure [dbo].[ADD_IM_Not_Exisesit]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ADD_IM_Not_Exisesit]
@IM_ID int,
@item_name nvarchar(500) ,
@Barcode Nvarchar(MAX) = NULL,
@isValid INT,
@User_ID INT,
@GM_ID INT,
@U_ID INT,
@IM_Num nvarchar(200),
@Def_U_ID int,
@Barcode_By_One Nvarchar(50) = NULL,
@is_Store int =1
AS
BEGIN TRY
DECLARE @is_Default Bit , @U_IM_ID int , @U_Cargo Numeric(18,2) , @Valid_ST NVARCHAR(50)
BEGIN TRANSACTION 


SELECT @U_Cargo = U_Cargo FROM Units WHERE U_ID = @U_ID

update IM_Menu set  item_name=@item_name
,isActive=1,item_nameSales=@item_name,GM_ID =@GM_ID,isStore=@is_Store,isValid=@isValid,
isChangePrice = 0,Cost=0,IM_Num=@IM_Num,Row_Enabled = 1
 WHERE IM_ID=@IM_ID


IF @U_Cargo = 1
BEGIN
IF @Barcode IS NULL BEGIN EXEC @BARCODE = [AG_BalanceMV_GetSerial_Barcode] END
EXEC @U_IM_ID = [AA_GET_MAX_IM_UNITS]
INSERT INTO IM_Units (U_IM_ID,IM_ID,Barcode,U_ID,Price,is_Default,Row_Enabled,USER_ID)
VALUES(@U_IM_ID,@IM_ID,@Barcode,@U_ID,0,1,1,@User_ID)

END
 
IF @U_Cargo > 1
BEGIN
IF @Barcode_By_One IS NULL BEGIN EXEC @Barcode_By_One = [AG_BalanceMV_GetSerial_Barcode] END
EXEC @U_IM_ID = [AA_GET_MAX_IM_UNITS]
INSERT INTO IM_Units (U_IM_ID,IM_ID,U_ID,Barcode,Price,is_Default,Row_Enabled,USER_ID)
VALUES(@U_IM_ID,@IM_ID,@Def_U_ID,@Barcode_By_One,(0/@U_Cargo),0,1,@User_ID)

IF @Barcode IS NULL BEGIN EXEC @BARCODE = [AG_BalanceMV_GetSerial_Barcode] END
EXEC @U_IM_ID = [AA_GET_MAX_IM_UNITS]
INSERT INTO IM_Units (U_IM_ID,IM_ID,U_ID,Barcode,Price,is_Default,Row_Enabled,USER_ID)
VALUES(@U_IM_ID,@IM_ID,@U_ID,@Barcode,0,1,1,@User_ID)

END

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[ADD_IM_Not_Exisesit] Proc',16,1,'خطأ')
ROLLBACK
END CATCH





































