CREATE PROCEDURE [dbo].[AddFixedAsset]
   @id int,
    @AssetDescription NVARCHAR(255),
    @AssetGroupId INT = 1,
    @PurchaseDate DATE,
    @PurchaseAmount DECIMAL(18, 2),
    @SerialNumber NVARCHAR(100),
    @LocationId INT = 1,
    @DepreciationExpenseAccount NVARCHAR(50),
    --@AssetType NVARCHAR(255),
    @AccumulatedDepreciationAccount NVARCHAR(50),
    @UsefulLifeYears INT,
    @DepreciationMethod NVARCHAR(50),
    @SalvageValue DECIMAL(18, 2),
    @DepreciationStartDate DATE,
    @DepreciationFrequency NVARCHAR(10),  -- 'سنوي' أو 'شهري'
    @DepreciationDayOfMonth INT = NULL,    -- إذا كان شهري فقط
	@DepreciationMonthOfYear INT = NULL, -- إذا كان سنوي
	@DepreciationDayOfYear INT = NULL,  -- إذا كان سنوي
	@DepreciationRate	decimal(5, 2)= NULL
AS
--BEGIN
BEGIN TRY
BEGIN TRANSACTION 


    SET NOCOUNT ON;

	if @id > 0
	BEGIN
	DELETE FROM AssetJournalEntries WHERE AssetId = @id
	DELETE FROM FixedAssets WHERE ID = @id
	END

	EXEC @id = AA_GET_MAX_ID 'FixedAssets'

    INSERT INTO FixedAssets (
	   Id,
        AssetDescription,
        AssetGroupId,
        PurchaseDate,
        PurchaseAmount,
        SerialNumber,
        LocationId,
        DepreciationExpenseAccount,
       -- AssetType,
        AccumulatedDepreciationAccount,
        UsefulLifeYears,
        DepreciationMethod,
        SalvageValue,
        DepreciationStartDate,
        DepreciationFrequency,
        DepreciationDayOfMonth,
		DepreciationMonthOfYear,
		DepreciationDayOfYear,
		DepreciationRate
    )
    VALUES (
	    @id,
        @AssetDescription,
        @AssetGroupId,
        @PurchaseDate,
        @PurchaseAmount,
        @SerialNumber,
        @LocationId,
        @DepreciationExpenseAccount,
       -- @AssetType,
        @AccumulatedDepreciationAccount,
        @UsefulLifeYears,
        @DepreciationMethod,
        @SalvageValue,
        @DepreciationStartDate,
        @DepreciationFrequency,
        @DepreciationDayOfMonth,
		@DepreciationMonthOfYear,
		@DepreciationDayOfYear,
		@DepreciationRate
    );



	-- 2. جلب ID الخاص بالأصل الجديد
    DECLARE @AssetId INT = @id,@EntryDate DATE ;

  -- 3. تنفيذ فقط إن كانت الطريقة "القسط الثابت"
    IF @DepreciationMethod = N'القسط الثابت'
    BEGIN
        DECLARE @TotalValue DECIMAL(18,2) = @PurchaseAmount - @SalvageValue;

        IF @DepreciationFrequency = N'سنوي'
        BEGIN
            --DECLARE @AnnualAmount DECIMAL(18,2) = @TotalValue / @UsefulLifeYears;
            DECLARE @i INT = 0;

            --WHILE @i < @UsefulLifeYears
            --BEGIN
            --    INSERT INTO AssetJournalEntries (
            --        AssetId,
            --        EntryDate,
            --        DebitAccount,
            --        CreditAccount,
            --        Amount,
            --        Notes
            --    )
            --    VALUES (
            --        @AssetId,
            --        DATEADD(YEAR, @i, @DepreciationStartDate),
            --        @DepreciationExpenseAccount,
            --        @AccumulatedDepreciationAccount,
            --        @AnnualAmount,
            --        CONCAT(N'إهلاك سنوي - السنة ', @i + 1,' -  ', @AssetDescription , ' / ',@SerialNumber)
            --    );

            --    SET @i = @i + 1;
            --END
			---------------------------------------------------------------------------------------------------------------------------------
			DECLARE @AnnualAmount DECIMAL(18,2) = (@TotalValue / @UsefulLifeYears);
DECLARE @CurrentStart DATE = @PurchaseDate;
DECLARE @CurrentEnd DATE;
DECLARE @FinalEnd DATE = DATEADD(YEAR, @UsefulLifeYears, @PurchaseDate);

WHILE @CurrentStart < @FinalEnd
BEGIN
    -- تحديد نهاية الفترة: نهاية السنة أو نهاية العمر الافتراضي
    SET @CurrentEnd = CASE 
                        WHEN DATEFROMPARTS(YEAR(@CurrentStart), 12, 31) < @FinalEnd THEN DATEFROMPARTS(YEAR(@CurrentStart), 12, 31)
                        ELSE @FinalEnd
                      END;

    DECLARE @Months INT = DATEDIFF(MONTH, @CurrentStart, DATEADD(DAY, 1, @CurrentEnd));
    DECLARE @Amount DECIMAL(18,2) = (@AnnualAmount / 12) * @Months;

    -- إضافة القيد
   
   	EXEC @id = AA_GET_MAX_ID 'AssetJournalEntries'
   
   INSERT INTO AssetJournalEntries (
        Id,
        AssetId,
        EntryDate,
        DebitAccount,
        CreditAccount,
        Amount,
        Notes
    )
    VALUES (
	    @id,
        @AssetId,
        @CurrentEnd,
        @DepreciationExpenseAccount,
        @AccumulatedDepreciationAccount,
        @Amount,
        CONCAT(N'إهلاك - ', @AssetDescription , ' / ',@SerialNumber, @Months, N' شهر من ', CONVERT(NVARCHAR, @CurrentStart, 23), N' حتى ',CONVERT(NVARCHAR, @CurrentEnd, 23))
    );

    -- تحديث التاريخ للفترة التالية
    SET @CurrentStart = DATEADD(DAY, 1, @CurrentEnd);
END


        END
        ELSE IF @DepreciationFrequency = N'شهري'
BEGIN


 --BEGIN
 --           DECLARE @TotalMonths INT = @UsefulLifeYears * 12;
 --           DECLARE @MonthlyAmount DECIMAL(18,2) = @TotalValue / @TotalMonths;

 --           WHILE @CurrentStart < @FinalEnd
 --           BEGIN
 --               -- تحديد يوم القسط الشهري
 --               DECLARE @Day INT = ISNULL(@DepreciationDayOfMonth, DAY(@CurrentStart));
 --               DECLARE @MonthEnd DATE = DATEFROMPARTS(YEAR(@CurrentStart), MONTH(@CurrentStart), @Day);
 --               IF @MonthEnd < @CurrentStart SET @MonthEnd = EOMONTH(@CurrentStart);

 --               SET @CurrentEnd = IIF(@MonthEnd < @FinalEnd, @MonthEnd, @FinalEnd);

 --               DECLARE @Days INT = DATEDIFF(DAY, @CurrentStart, @CurrentEnd) + 1;
 --               DECLARE @MonthDays INT = DAY(EOMONTH(@CurrentStart));
 --               DECLARE @PartialAmount DECIMAL(18,2) = (@MonthlyAmount / @MonthDays) * @Days;

 --               INSERT INTO AssetJournalEntries (AssetId, EntryDate, DebitAccount, CreditAccount, Amount, Notes)
 --               VALUES (@AssetId, @CurrentEnd, @DepreciationExpenseAccount, @AccumulatedDepreciationAccount, @PartialAmount,
 --                       CONCAT(N'إهلاك شهري - ', @Days, N' يوم'));

 --               SET @CurrentStart = DATEADD(DAY,1,@CurrentEnd);
 --           END
 --       END



----------------------------------------------------------------------------------------------------------------------------------------------------------------------
    DECLARE @TotalMonths INT = @UsefulLifeYears * 12;
    DECLARE @MonthlyAmount DECIMAL(18,2) = @TotalValue / @TotalMonths;
    SET @i = 0;
    DECLARE @Year INT = YEAR(@DepreciationStartDate);
    DECLARE @Month INT = MONTH(@DepreciationStartDate);

    WHILE @i < @TotalMonths
    BEGIN
        DECLARE @Day INT = ISNULL(@DepreciationDayOfMonth, DAY(@DepreciationStartDate));
        set @EntryDate  = TRY_CAST(CONCAT(@Year, '-', RIGHT('0' + CAST(@Month AS VARCHAR(2)), 2), '-', RIGHT('0' + CAST(@Day AS VARCHAR(2)), 2)) AS DATE);

        IF @EntryDate IS NULL
        BEGIN
            SET @EntryDate = EOMONTH(CONCAT(@Year, '-', @Month, '-01'));
        END

		   	EXEC @id = AA_GET_MAX_ID 'AssetJournalEntries'

        INSERT INTO AssetJournalEntries (
		    id,
            AssetId,
            EntryDate,
            DebitAccount,
            CreditAccount,
            Amount,
            Notes
        )
        VALUES (
		    @id,
            @AssetId,
            @EntryDate,
            @DepreciationExpenseAccount,
            @AccumulatedDepreciationAccount,
            @MonthlyAmount,
            CONCAT(N'إهلاك شهري - شهر رقم ', @i + 1,' -  ', @AssetDescription , ' / ',@SerialNumber)
        );

        -- الانتقال للشهر التالي
        SET @Month = @Month + 1;
        IF @Month > 12
        BEGIN
            SET @Month = 1;
            SET @Year = @Year + 1;
        END

        SET @i = @i + 1;
    END
END

    END

	ELSE IF @DepreciationMethod = N'القسط المتناقص'
BEGIN
    DECLARE @BookValue DECIMAL(18,2) = @PurchaseAmount;
    DECLARE @Rate DECIMAL(5,2) = @DepreciationRate / 100;  -- تحويل النسبة إلى كسر عشري

    SET @CurrentStart  = @PurchaseDate;
    SET  @FinalEnd  = DATEADD(YEAR, @UsefulLifeYears, @PurchaseDate);
   -- DECLARE @CurrentEnd DATE;
    DECLARE @PartialAmount DECIMAL(18,2);

    WHILE @CurrentStart < @FinalEnd AND @BookValue > @SalvageValue
    BEGIN
        -- حساب نهاية الفترة حسب نوع الإهلاك
        IF @DepreciationFrequency = N'سنوي'
            SET @CurrentEnd = IIF(DATEFROMPARTS(YEAR(@CurrentStart), 12, 31) < @FinalEnd, DATEFROMPARTS(YEAR(@CurrentStart), 12, 31), @FinalEnd);
        ELSE
            SET @CurrentEnd = IIF(EOMONTH(@CurrentStart) < @FinalEnd, EOMONTH(@CurrentStart), @FinalEnd);

        -- حساب القسط
        SET @PartialAmount = ROUND(@BookValue * @Rate, 2);
        IF @BookValue - @PartialAmount < @SalvageValue
            SET @PartialAmount = @BookValue - @SalvageValue;  -- لا نخفض تحت التخريد

				EXEC @id = AA_GET_MAX_ID 'AssetJournalEntries'

        -- إدراج القسط
        INSERT INTO AssetJournalEntries (id,AssetId, EntryDate, DebitAccount, CreditAccount, Amount, Notes)
        VALUES (@id,@AssetId, @CurrentEnd, @DepreciationExpenseAccount, @AccumulatedDepreciationAccount, @PartialAmount,
                CONCAT(N'إهلاك متناقص - ', FORMAT(@PartialAmount, 'N2')));

        -- تحديث القيمة المتبقية
        SET @BookValue = @BookValue - @PartialAmount;

        -- تحديث التاريخ
        SET @CurrentStart = DATEADD(DAY,1,@CurrentEnd);
    END
END


	 COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = ' [AddFixedAsset] - ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH


--END;


GO
