CREATE PROCEDURE [dbo].[AG_Balance_Check_Receipt_Dependsy] 
@Receipt_Num int	
AS
declare @isDepend int , @isError int , @Paid_ID int

BEGIN TRAN 

	Select @isDepend = isDepended from Agents_Balance_MV WHERE Receipt_Num = @Receipt_Num
	
	IF @isDepend = 0
	BEGIN 

	SELECT @Paid_ID = Paid_ID FROM Percents_Distributions WHERE Receipt_Num = @Receipt_Num

	DELETE FROM Agents_Balance_MV WHERE Receipt_Num = @Receipt_Num

	select @isError = @@ERROR 
	IF @isError <> 0 
	goto PROBLEM

	DELETE FROM Percents_Distributions_Details WHERE Paid_ID = @Paid_ID 

	select @isError = @@ERROR 
	IF @isError <> 0 
	goto PROBLEM

	DELETE FROM Percents_Distributions WHERE Paid_ID = @Paid_ID

	select @isError = @@ERROR 
	IF @isError <> 0  
	goto PROBLEM
	
	END

		COMMIT TRAN

		PROBLEM:
	if @isError <> 0 
	begin
	raiserror ('DB ERROR _ AG_Balance_Check_Receipt_Dependsy',16,1,'خطأ')
	ROLLBACK TRAN
	END





















































GO
