--UPDATE Agents_Balance_MV SET Debit = ( ( SELECT ISNULL(SUM(T_Price),0) FROM SB_Contents WHERE Bill_T_ID = @T_ID) - ISNULL(Discount,0) )  WHERE T_ID = @T_ID
SELECT @TOTAL = ISNULL(SUM(T_Price),0) FROM SB_Contents WHERE Bill_T_ID = @T_ID
EXEC [AG_Balance_Update_Total] @T_ID,@TOTAL,@Discount

