SELECT @TOTAL = ISNULL(SUM(TOTAL),0) FROM Pch_Details WHERE Pch_T_ID = @T_ID
EXEC [AG_Balance_Update_Total] @T_ID,@TOTAL,@Discount

--END
END

COMMIT
END TRY

