/****** Object:  StoredProcedure [dbo].[AG_Balance_Update_Barcode_Order]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[AG_Balance_Update_Barcode_Order] 
@T_ID	INT,
@Pr_ID INT,
@TOTAL FLOAT,
@DISCOUNT FLOAT
AS
SET DEADLOCK_PRIORITY NORMAL

BEGIN TRY
BEGIN TRANSACTION

UPDATE Periods SET AG_Counter += 1 WHERE Pr_ID = @Pr_ID 

--TB_isOrderd=1 , S_Bills_Type = 3 ,

Update Agents_Balance_MV SET  Order_isDeleverd = 0 ,TB_isOrderd=1 
 --,Discount = @DISCOUNT ,TOTAL = @TOTAL,Pure = (@TOTAL - @DISCOUNT) , Debit = (@TOTAL - @DISCOUNT)  
WHERE T_ID = @T_ID

EXEC [AG_Balance_Update_Total]@T_ID,@TOTAL,@DISCOUNT

--EXEC AG_Balance_Update_isDepended @T_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
		print 'DB ERROR ! ([AG_Balance_Update_TB_Ordered])'
ROLLBACK
END CATCH

