/****** Object:  StoredProcedure [dbo].[AG_Balance_Update_isDepended]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[AG_Balance_Update_isDepended] 
@T_ID	int,
@Tr_ID int = NULL,
@Pr_ID int = NULL,
@Pay_ID int = 1	
AS


declare @BS_Type INT,@i int,@IM_ID int,@j int,@NewSale numeric(18, 2) = NULL,@NewSaleByOne NUMERIC(18,3),@Cost numeric(18, 2),
@PreQty numeric(18,2),@U_Cargo NUMERIC(18,2),@AG_ID int,@Pure NUMERIC(18,3),@User_ID int,@D_Valid NVARCHAR(50),@ST_T_ID int,@ST_ID int
,@ST_QTY NUMERIC(18,2),@ST_F int,@ST_T int,@Pch_ID int,@Pch_ID_2 Nvarchar(25),@Price NUMERIC(18,2),@PrevCost NUMERIC(18,2),@Invoice_Type int
,@AG_DATE DATETIME , @Min_SP NUMERIC(18,2),@Min_SP_ByOne NUMERIC(18,2),@Receipt_Title  Nvarchar(2000)

BEGIN TRY
BEGIN TRANSACTION

SELECT @BS_Type = BsType_ID , @Invoice_Type=Invoice_Type , @AG_DATE=Date , @AG_ID = AG_ID  FROM Agents_Balance_MV WHERE T_ID = @T_ID
Update Agents_Balance_MV SET isDepended=1 WHERE T_ID = @T_ID


exec [Recalculate_Agent_Bill_Total] @T_ID


IF @BS_Type = 1 
BEGIN
UPDATE SB_Contents SET isDepended = 1 where Bill_T_ID = @T_ID 
EXEC [SB_Contents_Structers_insert] @T_ID
GOTO ESC
END


IF @BS_Type = 7 -- Pch OR Invoice
BEGIN


SELECT  @Pure = PURE , @User_ID = User_ID , @Pch_ID = Pch_ID , @Pch_ID_2 = Pch_ID FROM Agents_Balance_MV_V WHERE T_ID = @T_ID

IF  (SELECT is_Auto_Pied FROM Agents WHERE AG_ID = @AG_ID) = 1
BEGIN

UPDATE Agents_Balance_MV SET Receipt_Title = @Pch_ID WHERE T_ID = @T_ID

SET @Receipt_Title = 'فاتورة مشتريات : ' + @Pch_ID_2
EXEC [Agents_BalanceMV_insert_RCT]
0,
@AG_DATE,
0,--@Receipt_Num
@AG_ID,
@Pr_ID,
@T_ID,--@Receipt_Tran_ID
'',--@ReferNum
@Receipt_Title,
@Pure,--@Pure
NULL,--@About
4,--@BsType_ID
@User_ID ,
@Tr_ID,
'',--BANK_NAME
'',--CHECK_NUMBER
@Pay_ID
--***************************************
END

END


ELSE
IF @BS_Type = 8 --IM_EX
BEGIN
UPDATE IMEX_Details SET isDepended = 1 where IMEX_T_ID = @T_ID 
END

------------------------------------------------------------------------------
ELSE
IF @BS_Type = 10 --SB_RTN
BEGIN
SELECT @Pure = PURE , @User_ID = User_ID , @Pch_ID_2 = SRtn_ID FROM Agents_Balance_MV_V WHERE T_ID = @T_ID
UPDATE Agents_Balance_MV SET Receipt_Title = @Pch_ID_2 ,DATE = GETDATE() WHERE T_ID = @T_ID
UPDATE Rtn_Contents  SET isDepended = 1 where Bill_T_ID = @T_ID 
EXEC Rtn_Contents_UPDATE_DEPENDED @T_ID 

IF (SELECT is_Auto_Pied FROM Agents WHERE AG_ID = @AG_ID) = 1 BEGIN  

SET @Receipt_Title = ' إرجاع مبيعات '+@Pch_ID_2
EXEC [Agents_BalanceMV_insert_RCT]
0,
@AG_DATE,
0,--@Receipt_Num
@AG_ID,
@Pr_ID,
@T_ID,--@Receipt_Tran_ID
'',--@ReferNum
@Receipt_Title,
@Pure,--@Pure
NULL,--@About
4,--@BsType_ID
@User_ID ,
@Tr_ID,
'',--BANK_NAME
'',--CHECK_NUMBER
@Pay_ID

END
END
------------------------------------------------------------------------------
ELSE
IF @BS_Type = 11 --PCH_RTN
BEGIN
  SELECT @Pure = PURE , @User_ID = User_ID , @Pch_ID_2 = PRtn_ID FROM Agents_Balance_MV_V WHERE T_ID = @T_ID
UPDATE Agents_Balance_MV SET Receipt_Title = @Pch_ID_2 ,DATE = GETDATE() WHERE T_ID = @T_ID
UPDATE Rtn_Contents  SET isDepended = 1 where Bill_T_ID = @T_ID 

IF (SELECT is_Auto_Pied FROM Agents WHERE AG_ID = @AG_ID) = 1 BEGIN  

SET @Receipt_Title = ' إرجاع مشتريات '+@Pch_ID_2
EXEC [Agents_BalanceMV_insert_RCT]
0,
@AG_DATE,
0,--@Receipt_Num
@AG_ID,
@Pr_ID,
@T_ID,--@Receipt_Tran_ID
'',--@ReferNum
@Receipt_Title,
@Pure,--@Pure
NULL,--@About
3,--@BsType_ID
@User_ID ,
@Tr_ID,
'',--BANK_NAME
'',--CHECK_NUMBER
@Pay_ID


END
END
---------------------------------------------------------------------------------
ELSE
IF @BS_Type = 12 --Store_Trans
BEGIN
--UPDATE Agents_Balance_MV SET ST_is_Trans = 0 WHERE T_ID = @T_ID
UPDATE Store_Trans_Details SET isDepended = 1 where B_T_ID = @T_ID 
END

IF @BS_Type = 2 -- EXP_Details
BEGIN

UPDATE EXP_Details SET isDepended = 1 where IMEX_T_ID = @T_ID 
IF (SELECT is_Auto_Pied FROM Agents WHERE AG_ID = @AG_ID) = 1 
BEGIN  
SELECT  @Pure = PURE , @User_ID = User_ID , @Pch_ID = EXP_ID , @Pch_ID_2 = EXP_ID FROM Agents_Balance_MV_V WHERE T_ID = @T_ID

SET @Receipt_Title = 'فاتورة مصروفات رقم : '+@Pch_ID_2
EXEC [Agents_BalanceMV_insert_RCT]
0,
@AG_DATE,
0,--@Receipt_Num
@AG_ID,
@Pr_ID,
@T_ID,--@Receipt_Tran_ID
'',--@ReferNum
@Receipt_Title,
@Pure,--@Pure
NULL,--@About
4,--@BsType_ID
@User_ID ,
@Tr_ID,
'',--BANK_NAME
'',--CHECK_NUMBER
@Pay_ID

END

END

IF @BS_Type = 13 OR @BS_Type = 18 -- FRM_ITEM
BEGIN

UPDATE FRM_Details SET isDepended = 1 where FRM_T_ID = @T_ID 

IF @BS_Type = 18 BEGIN UPDATE FRM_Contents_Details SET isDepended = 1 where Bill_T_ID = @T_ID END

SELECT @i = min(T_ID) From FRM_Details WHERE FRM_T_ID = @T_ID
WHILE @i IS NOT NULL
BEGIN

SELECT @IM_ID=IM_ID,@D_Valid=D_Vaild,@ST_ID = ST_ID,@ST_QTY = ST_QTY,@NewSale = NewSale,@NewSaleByOne=NewSaleByOne,@Cost = Price,@U_Cargo=U_Cargo
,@Min_SP = Min_SP , @Min_SP_ByOne =Min_SP_ByOne
FROM FRM_Details WHERE T_ID = @i

SELECT @PreQty = (ISNULL(SUM(ST_QTY),0) - @ST_QTY) FROM ST_Balance WHERE IM_ID = @IM_ID

IF @PreQty > 0 
BEGIN
 SELECT @PrevCost = Cost From IM_Menu WHERE IM_ID = @IM_ID
 UPDATE IM_Menu SET Cost = ( (@PrevCost * @PreQty) + ( (@Cost/@U_Cargo) *  @ST_QTY ) ) / ( @PreQty + @ST_QTY  ) WHERE IM_ID = @IM_ID
END
ELSE
BEGIN UPDATE IM_Menu SET Cost = (@Cost/@U_Cargo) WHERE IM_ID = @IM_ID 
END


IF @NewSale is Not NULL BEGIN
DECLARE @Tmp_Cargo2 Numeric(18,2)
SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID
WHILE @j is Not NULL
BEGIN
SELECT @Tmp_Cargo2 = U_Cargo FROM IM_Menu_Units_V  WHERE U_IM_ID = @j
UPDATE IM_Units SET Price = (@NewSale/@U_Cargo) * @Tmp_Cargo2 WHERE U_IM_ID = @j

SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID AND U_IM_ID > @j
END
END
----------------------------------------------------------
IF @NewSaleByOne is Not NULL BEGIN 
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V  WHERE IM_ID = @IM_ID And U_Cargo = 1
WHILE @j is Not NULL
BEGIN
 UPDATE IM_Units SET Price = @NewSaleByOne WHERE U_IM_ID = @j
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_Cargo = 1 AND U_IM_ID > @j
END
END

---------------------------------------------------------------------------------
IF @Min_SP is Not NULL BEGIN
SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID
WHILE @j is Not NULL
BEGIN
SELECT @Tmp_Cargo2 = U_Cargo FROM IM_Menu_Units_V  WHERE U_IM_ID = @j
UPDATE IM_Units SET Min_SP = (@Min_SP/@U_Cargo) * @Tmp_Cargo2 WHERE U_IM_ID = @j

SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID AND U_IM_ID > @j
END
END

-------------------------------------------------------------------------------

IF @Min_SP_ByOne is Not NULL BEGIN 
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V  WHERE IM_ID = @IM_ID And U_Cargo = 1
WHILE @j is Not NULL
BEGIN
 UPDATE IM_Units SET Min_SP = @Min_SP_ByOne WHERE U_IM_ID = @j
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_Cargo = 1 AND U_IM_ID > @j
END
END

------------------------------------------------------------------------------------------------------


--EXEC Inc_IM_QTY @IM_ID,@ST_ID,@D_Valid,@ST_QTY
SELECT @i = min(T_ID) From FRM_Details WHERE FRM_T_ID = @T_ID AND T_ID > @i
END

--2++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

--UPDATE FRM_Contents_Details SET isDepended = 1 where Bill_T_ID = @T_ID 

--SELECT @i = min(T_ID) From FRM_Contents_Details WHERE Bill_T_ID = @T_ID
--WHILE @i IS NOT NULL
--BEGIN

--SELECT @IM_ID=IM_ID,@D_Valid='',@ST_ID = ST_ID,@ST_QTY = ST_QTY,@U_Cargo=U_Cargo
--FROM FRM_Contents_Details WHERE T_ID = @i


--IF @NewSale is Not NULL BEGIN
--DECLARE @Tmp_Cargo3 Numeric(18,2)
--SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID
--WHILE @j is Not NULL
--BEGIN
--SELECT @Tmp_Cargo3 = U_Cargo FROM IM_Menu_Units_V  WHERE U_IM_ID = @j
--UPDATE IM_Units SET Price = (@NewSale/@U_Cargo) * @Tmp_Cargo3 WHERE U_IM_ID = @j

--SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID AND U_IM_ID > @j
--END
--END
------------------------------------------------------------
--IF @NewSaleByOne is Not NULL BEGIN 
--SELECT @j = min(U_IM_ID) From IM_Menu_Units_V  WHERE IM_ID = @IM_ID And U_Cargo = 1
--WHILE @j is Not NULL
--BEGIN
-- UPDATE IM_Units SET Price = @NewSaleByOne WHERE U_IM_ID = @j
--SELECT @j = min(U_IM_ID) From IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_Cargo = 1 AND U_IM_ID > @j
--END
--END
------------------------------------------------------------

----EXEC Dec_IM_QTY @IM_ID,@ST_ID,@D_Valid,@ST_QTY
--SELECT @i = min(T_ID) From FRM_Contents_Details WHERE Bill_T_ID = @T_ID AND T_ID > @i
--END

END
---------------------------------------------------------------------------------

IF @BS_Type = 16 -- ViewBill
BEGIN UPDATE ViewBill_Contents SET isDepended = 1 where Bill_T_ID = @T_ID END


ELSE
IF @BS_Type = 17 -- InSale
BEGIN
UPDATE InSale_Details SET isDepended = 1 where InSale_T_ID = @T_ID 
END



ESC:


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
	print 'DB ERROR ! __ AG_Balance_Update_isDepended'
ROLLBACK
END CATCH
















GO
