CREATE PROCEDURE [dbo].[AG_Balance_Update_Pied_On_Update] 
@B_T_ID	int,
@Bs_Type INT		
AS
DECLARE @TOTAL numeric(18,3),@Discount numeric(18,3)
BEGIN

SELECT @Discount = ISNULL(Discount,0) FROM Agents_Balance_MV WHERE T_ID = @B_T_ID

IF @Bs_Type = 1
BEGIN

SELECT @TOTAL = ISNULL(SUM(T_Price),0) FROM SB_Contents WHERE Bill_T_ID = @B_T_ID AND isDepended = 1
--IF @TOTAL IS NULL BEGIN SET @TOTAL = 0 END
