--Update Agents_Balance_MV SET Credit = (@TOTAL - ISNULL(Discount,0)),Total = @TOTAL ,Pure = (@TOTAL - ISNULL(Discount,0)) WHERE T_ID = @B_T_ID
--EXEC [AG_Balance_Update_Total] @B_T_ID,@TOTAL,@Discount

END
ELSE IF @Bs_Type = 2
BEGIN

SELECT @TOTAL = ISNULL(SUM(Total),0) FROM EXP_Details WHERE IMEX_T_ID = @B_T_ID AND isDepended = 1
--IF @TOTAL IS NULL BEGIN SET @TOTAL = 0 END
--Update Agents_Balance_MV SET Credit = (@TOTAL - ISNULL(Discount,0)),Total = @TOTAL ,Pure = (@TOTAL - ISNULL(Discount,0)) WHERE T_ID = @B_T_ID


END


EXEC [AG_Balance_Update_Total] @B_T_ID,@TOTAL,@Discount

END



























