AS

declare @isError int
BEGIN TRAN


	Update Agents_Balance_MV SET ReferNum=@ReferNum WHERE T_ID = @T_ID

	select @isError = @@ERROR 
	IF @isError <> 0 
	goto PROBLEM

	------------------------------------- For Editing Description Of Projects Paidup
	Update Agents_Balance_MV SET ReferNum=@ReferNum WHERE Pr_ID = @T_ID AND BsType_ID in (6,9)

	select @isError = @@ERROR 
	IF @isError <> 0 
	goto PROBLEM

		COMMIT TRAN

	PROBLEM:
	if @isError <> 0 begin
	print 'DB ERROR !'
	ROLLBACK TRAN

END
























































