SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[AG_Balance_Update_TB_Ordered] 
@T_ID	int,
@TB_ID INT


AS
DECLARE @Pr_ID INT , @TOTAL FLOAT
SET DEADLOCK_PRIORITY NORMAL

BEGIN TRY
BEGIN TRANSACTION

SELECT @Pr_ID = Pr_ID FROM Agents_Balance_MV WHERE T_ID = @T_ID
UPDATE Periods SET AG_Counter += 1 WHERE Pr_ID = @Pr_ID 


IF(SELECT isbusy from Tables_Balances_V WHERE TB_ID = @TB_ID) = 0
BEGIN
UPDATE Tables SET TB_ORDER_CODE = @T_ID , Start_Open = GETDATE() WHERE TB_ID = @TB_ID
Update Agents_Balance_MV SET TB_ORDER_CODE = @T_ID WHERE T_ID = @T_ID
END
ELSE
BEGIN
Update Agents_Balance_MV SET TB_ORDER_CODE = (SELECT TB_ORDER_CODE FROM Tables WHERE TB_ID = @TB_ID) WHERE T_ID = @T_ID
END


SELECT @TOTAL = ISNULL(SUM(T_Price),0) FROM SB_Contents WHERE Bill_T_ID = @T_ID
Update Agents_Balance_MV SET isDepended=1, TB_isOrderd=1,Total = @Total , Credit=@Total WHERE T_ID = @T_ID


IF (SELECT TB_Auto_Print FROM Sys_Features WHERE T_ID = (SELECT T_ID FROM Sys_Model)) = 1
BEGIN
INSERT INTO TB_AutoPrint_tmp (T_ID) VALUES(@T_ID)
END


--EXEC AG_Balance_Update_isDepended @T_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
		print 'DB ERROR ! ([AG_Balance_Update_TB_Ordered])'
ROLLBACK
END CATCH

SET ANSI_NULLS ON
GO
