CREATE PROCEDURE [dbo].[AG_Balance_Update_Title_Name] 
@T_ID	int,
@Title	nvarchar(350)
		
AS

declare @isError int
BEGIN TRAN

	Update Agents_Balance_MV SET
	Receipt_Title=@Title
	WHERE T_ID = @T_ID

	select @isError = @@ERROR 
	IF @isError <> 0 
	goto PROBLEM

		Update Agents_Balance_MV SET
	Receipt_Title=@Title
	WHERE pr_ID = @T_ID And BsType_ID  = 6

	select @isError = @@ERROR 
	IF @isError <> 0 
	goto PROBLEM

		COMMIT TRAN

	PROBLEM:
	if @isError <> 0 begin
	print 'DB ERROR !'
	ROLLBACK TRAN

END
























































