/****** Object:  StoredProcedure [dbo].[AG_MV_TRANSACTION_pros]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[AG_MV_TRANSACTION_pros](@T_ID           int OUTPUT,@DATE           dateTIME NULL,@AG_ID_FROM     int NULL,@AG_ID_TO       int NULL,@TITLE          nvarchar(2500) NULL,@ABOUT          nvarchar(Max) NULL,@USER_ID        int NULL,--@is_Void        int = NULL,@VALUE          numeric(18,3),@Process	 VARCHAR(20)) AS

BEGIN
IF @Process = 'DELETE'
BEGIN
UPDATE dbo.AG_MV_TRANSACTION SET is_Void = 1 WHERE T_ID = @T_ID 
	--DELETE FROM dbo.AG_MV_TRANSACTION	-- WHERE T_ID = @T_ID 
	RETURN 1
END
IF EXISTS (SELECT 1 FROM AG_MV_TRANSACTION WHERE T_ID = @T_ID )
BEGIN
	UPDATE dbo.AG_MV_TRANSACTION	SET [DATE]           = @DATE,       [AG_ID_FROM]     = @AG_ID_FROM,       [AG_ID_TO]       = @AG_ID_TO,       [TITLE]          = @TITLE,       [ABOUT]          = @ABOUT,       [USER_ID]        = @USER_ID,      -- [is_Void]        = @is_Void,       [VALUE]          = @VALUE	WHERE T_ID = @T_ID 
	RETURN 1
END
ELSE
BEGIN

exec @T_ID = AA_GET_MAX_ID 'AG_MV_TRANSACTION'

	INSERT INTO dbo.AG_MV_TRANSACTION	(  [T_ID],	   [DATE],       [AG_ID_FROM],       [AG_ID_TO],       [TITLE],       [ABOUT],       [USER_ID],       [BsType_ID],       [VALUE])	SELECT @T_ID,@DATE,       @AG_ID_FROM,       @AG_ID_TO,       @TITLE,       @ABOUT,       @USER_ID,      40,       @VALUE
	RETURN 1
END
 
