CREATE PROCEDURE [dbo].[Agents_Balance_MV_St_Trans_insert]
@T_ID int OUTPUT,
@BsType_ID	int,
@User_ID int,
@Date DATETIME

AS


DECLARE @START_ID int,@END_ID int,@ST_Tran_ID int,@AG_ID int


SELECT @START_ID=START_ID,@END_ID=END_ID FROM SERVERS --WHERE Serv_Name = @@SERVERNAME

BEGIN TRY
BEGIN TRANSACTION

SELECT top 1 @AG_ID = AG_ID FROM Agents WHERE is_Auto_Pied = 1 And AG_ID BETWEEN @START_ID AND @END_ID

select @ST_Tran_ID = (select isnull(max(ST_Tran_ID),@START_ID) from Agents_Balance_MV_St_Trans WHERE BsType_ID = 12   AND  ST_Tran_ID BETWEEN @START_ID AND @END_ID   ) + 1

EXEC @T_ID = [AA_GET_MAX_Agents_Balance_MV_St_Tran]
INSERT INTO 
[dbo].[Agents_Balance_MV_St_Trans]
([T_ID],[ST_Tran_ID],[AG_ID],[Pr_ID],[Date],[BsType_ID],[isDepended],[isVoid],[isPied],[User_ID])
VALUES
(@T_ID,@ST_Tran_ID,@AG_ID,NULL,@Date,@BsType_ID,0,0,NULL,@User_ID)

	
COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
	print 'DB ERROR ! __ [Agents_Balance_MV_St_Trans_insert]'
ROLLBACK
END CATCH









GO
