CREATE PROCEDURE [dbo].[Agents_BalanceMV_insert]
@T_ID int OUTPUT,
@Receipt_Num int OUTPUT,
@AG_ID	int,
@Pch_ID int OUTPUT,
@IMEX_ID int OUTPUT,
@Jrd_ID int OUTPUT,
@SRtn_ID	int	OUTPUT,
@PRtn_ID	int OUTPUT,
@ST_Tran_ID int OUTPUT,
@EXP_ID int OUTPUT,
@Frm_ID	int	OUTPUT, 
@ViewSB_ID int OUTPUT,
@InSale_ID	int	OUTPUT,
@OutSale_ID	int	OUTPUT,  
@Frm_ID_M	int	OUTPUT, 
@ST_Sett_ID	int	OUTPUT,  
@Pr_ID int = NULL,
@BsType_ID	int,
@isPied	bit = 0,
@User_ID int,
@Date DATETIME

AS


DECLARE @START_ID int,@END_ID int,@AGBalance_T_ID int , @isDepended bit = 1,@T_ID_2 INT


SELECT @START_ID=START_ID,@END_ID=END_ID FROM SERVERS --WHERE Serv_Name = @@SERVERNAME

BEGIN TRY
BEGIN TRANSACTION


if @Pr_ID = 0 begin Set @Pr_ID = NULL  end 
if @Pch_ID = 0 begin Set @Pch_ID  = NULL  end 
if @Receipt_Num = 0 begin Set @Receipt_Num  = NULL  end 
if @IMEX_ID = 0 begin Set @IMEX_ID = NULL end
if @Jrd_ID = 0 begin Set @Jrd_ID = NULL end
if @SRtn_ID = 0 begin Set @SRtn_ID = NULL end
if @PRtn_ID = 0 begin Set @PRtn_ID = NULL end
if @ST_TRAN_ID = 0 begin Set @ST_TRAN_ID = NULL end
if @EXP_ID = 0 begin Set @EXP_ID = NULL end
if @Frm_ID = 0 begin Set @Frm_ID = NULL end
if @ViewSB_ID = 0 begin Set @ViewSB_ID = NULL end
if @InSale_ID = 0 begin Set @InSale_ID = NULL end
if @OutSale_ID = 0 begin Set @OutSale_ID = NULL end
if @Frm_ID_M = 0 begin Set @Frm_ID_M = NULL end
if @ST_Sett_ID = 0 begin Set @ST_Sett_ID = NULL end
----------------------------------------------------------------------------

SELECT top 1 @AG_ID = AG_ID FROM Agents WHERE is_Auto_Pied = 1 And AG_ID BETWEEN @START_ID AND @END_ID

if @BsType_ID = 2
Begin
select @EXP_ID = (select isnull(max(EXP_ID),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 2 AND  EXP_ID BETWEEN @START_ID AND @END_ID  ) + 1
SET @Receipt_Num = NULL
SET @isDepended = 0
End

--if @BsType_ID = 3 or @BsType_ID =4
--Begin
--EXEC @Receipt_Num = AG_BalanceMV_GetMaxRecepitNum
--End

if @BsType_ID = 7
Begin
select @Pch_ID = (select isnull(max(Pch_ID),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 7  AND  Pch_ID BETWEEN @START_ID AND @END_ID    ) + 1
SET @isDepended = 0
End

if @BsType_ID = 8
Begin
select @IMEX_ID = (select isnull(max(IMEX_ID),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 8 AND  IMEX_ID BETWEEN @START_ID AND @END_ID    ) + 1
SET @isDepended = 0
End

if @BsType_ID = 9
Begin
select @Jrd_ID = (select isnull(max(Jrd_ID),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 9   AND  Jrd_ID BETWEEN @START_ID AND @END_ID    ) + 1
SET @isDepended = 0
End


if @BsType_ID = 10
Begin
select @SRtn_ID = (select isnull(max(SRtn_ID),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 10  AND  SRtn_ID BETWEEN @START_ID AND @END_ID   ) + 1
SET @isDepended = 0
end

if @BsType_ID = 11
Begin
select @PRtn_ID = (select isnull(max(PRtn_ID),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 11 AND  PRtn_ID BETWEEN @START_ID AND @END_ID    ) + 1
SET @isDepended = 0
end

--if @BsType_ID = 12
--Begin
--select @ST_Tran_ID = (select isnull(max(ST_Tran_ID),@START_ID) from Agents_Balance_MV_St_Trans WHERE BsType_ID = 12   AND  ST_Tran_ID BETWEEN @START_ID AND @END_ID   ) + 1
--SET @isDepended = 0
--end

if @BsType_ID = 13
Begin
select @Frm_ID = (select isnull(max(Frm_ID),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 13     AND  Frm_ID BETWEEN @START_ID AND @END_ID   ) + 1
SET @isDepended = 0
end

if @BsType_ID = 16
Begin
select @ViewSB_ID = (select isnull(max(ViewSB_ID),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 16    AND  ViewSB_ID BETWEEN @START_ID AND @END_ID   ) + 1
SET @isDepended = 0
end

if @BsType_ID = 17
Begin
select @InSale_ID = (select isnull(max(InSale_ID),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 17   AND  InSale_ID BETWEEN @START_ID AND @END_ID   ) + 1
SET @isDepended = 0
end

if @BsType_ID = 18
Begin
select @Frm_ID_M = (select isnull(max(Frm_ID_M),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 18   AND  Frm_ID_M BETWEEN @START_ID AND @END_ID   ) + 1
SET @isDepended = 0
end

if @BsType_ID = 35
Begin
select @OutSale_ID = (select isnull(max(OutSale_ID),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 35 AND  OutSale_ID BETWEEN @START_ID AND @END_ID  ) + 1
SET @isDepended = 0
end

if @BsType_ID = 39
Begin
select @ST_Sett_ID = (select isnull(max(ST_Sett_ID),@START_ID) from Agents_Balance_MV WHERE BsType_ID = 39 AND  ST_Sett_ID BETWEEN @START_ID AND @END_ID  ) + 1
SET @isDepended = 0
end

   EXEC @T_ID = AA_GET_MAX_ID 'Agents_Balance_MV'


	 insert into Agents_Balance_MV (T_ID,AG_ID,Pr_ID,Pch_ID,IMEX_ID,Jrd_ID,SRtn_ID,PRtn_ID,
	 ST_Tran_ID,EXP_ID,Frm_ID,ViewSB_ID,InSale_ID,OutSale_ID,Frm_ID_M,ST_Sett_ID,BsType_ID,isPied,isDepended,isVoid,User_ID,Date)

	 values(@T_ID,@AG_ID,@Pr_ID,@Pch_ID,@IMEX_ID,@Jrd_ID,@SRtn_ID,@PRtn_ID,@ST_Tran_ID,@EXP_ID,@Frm_ID,@ViewSB_ID
	 ,@InSale_ID,@OutSale_ID,@Frm_ID_M,@ST_Sett_ID,@BsType_ID,@isPied,@isDepended,0,@User_ID,@Date)

	
	COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
	print 'DB ERROR ! __ [Agents_BalanceMV_insert]'
ROLLBACK
END CATCH







GO
