CREATE PROCEDURE [dbo].[Agents_BalanceMV_Update_RCT]
@T_ID int,
@AG_ID	int,
@Pr_ID int = NULL,
@Receipt_Tran_ID INT = NULL,
@Date	datetime,
@Receipt_Title	nvarchar(MAX) = NULL,
@Pure	numeric(18, 3)= NULL,
@About	nvarchar(MAX) = NULL,
@BsType_ID	int,
@User_ID int,
---------------------------------------
@Tr_Type_ID	int = NULL,
@Tr_ID	int ,
@Bank_Name nvarchar(100) = NULL,
@CheckNum nvarchar(100) = NULL,
@Pay_ID	int	=1,
@Discount numeric(18, 3)= NULL

AS
 
declare @AGBalance_T_ID int , @isDepended bit = 1 , @Prev_AG_ID INT , @Prev_Tr_ID INT,@T_ID_2 INT

BEGIN TRY
BEGIN TRANSACTION
--BEGIN

IF @BsType_ID = 3
BEGIN
UPDATE Agents_Balance_MV_RCT SET 
AG_ID = @AG_ID
,Date = @Date
,Receipt_Title = @Receipt_Title
,About = @About
,Pure = @Pure
,DEBIT = @Pure
,Pay_ID = @Pay_ID
,Tr_ID  = @Tr_ID
,Discount = @Discount
WHERE T_ID = @T_ID


UPDATE Treasury_Balance_MV SET
Tr_ID = @Tr_ID
,Date = @Date
,notice_move = @Receipt_Title
,Pure = @Pure
,Credit = @Pure
WHERE AGBalance_T_ID = @T_ID
END



ELSE
BEGIN
UPDATE Agents_Balance_MV_RCT SET 
AG_ID = @AG_ID
,Date = @Date
,Receipt_Title = @Receipt_Title
,Pure = @Pure
,Credit = @Pure
,About = @About
,Pay_ID = @Pay_ID
,Discount = @Discount
WHERE T_ID = @T_ID


UPDATE Treasury_Balance_MV SET
Tr_ID = @Tr_ID
,Date = @Date
,notice_move = @Receipt_Title
,Pure = @Pure
,DEBIT = @Pure
WHERE AGBalance_T_ID = @T_ID
END


	
	COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
	print 'DB ERROR ! __ [Agents_BalanceMV_Update_RCT]'
ROLLBACK
END CATCH




