/****** Object:  StoredProcedure [dbo].[Agents_Bill_Num_Report_Insert]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Agents_Bill_Num_Report_Insert]
@D_F DATE,
@D_T DATE

AS
BEGIN TRY
BEGIN TRANSACTION 
 DECLARE @i INT,@T_TOTAL NUMERIC(18,3) , @T_BILLS INT, @AG_NAME NVARCHAR(500)

 DELETE FROM [Agents_Bill_Num_Report] 

 SELECT @i = MIN(AG_ID) FROM Agents  WHERE Type_ID IN (1,2)
 WHILE @i IS NOT NULL
 BEGIN


SELECT @AG_NAME = Ag_name from Agents WHERE AG_ID = @i

SELECT @T_BILLS = COUNT(T_ID) FROM Agents_Balance_MV_V WHERE AG_ID = @i AND BsType_ID =1 AND isVoid = 0
AND isDepended = 1 AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T

SELECT @T_TOTAL = ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE AG_ID = @i AND BsType_ID =1 AND isVoid = 0
AND isDepended = 1 AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T


INSERT INTO [dbo].[Agents_Bill_Num_Report]([AGENT_NAME],[Bills_QTY],[Bills_Total])
     VALUES (@AG_NAME,@T_BILLS,@T_TOTAL)


SELECT @i = MIN(AG_ID) FROM Agents  WHERE Type_ID IN (1,2) AND AG_ID > @i
END

SELECT [AGENT_NAME],[Bills_QTY],[Bills_Total] FROM [Agents_Bill_Num_Report] ORDER BY AGENT_NAME ASC

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[Agents_Bill_Num_Report_Insert]',16,1,'خطأ')
ROLLBACK
END CATCH
































GO
