/****** Object:  StoredProcedure [dbo].[Approve_Budget_Transfer]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE PROCEDURE [dbo].[Approve_Budget_Transfer]
(
    @TransferId INT,
    @ApprovedBy INT
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @OldData NVARCHAR(MAX);
    DECLARE @NewData NVARCHAR(MAX);

    /* 📌 البيانات قبل الاعتماد */
    SELECT @OldData =
    (
        SELECT *
        FROM Budget_Transfers
        WHERE TransferId = @TransferId
        FOR XML PATH('Budget_Transfer'), ROOT('Before')
    );

    /* اعتماد المناقلة */
    UPDATE Budget_Transfers
    SET IsApproved = 1,
        ApprovedBy = @ApprovedBy,
        ApprovedDate = GETDATE()
    WHERE TransferId = @TransferId;

    /* 📌 البيانات بعد الاعتماد */
    SELECT @NewData =
    (
        SELECT *
        FROM Budget_Transfers
        WHERE TransferId = @TransferId
        FOR XML PATH('Budget_Transfer'), ROOT('After')
    );

    /* تسجيل التدقيق */
    INSERT INTO Audit_Log
    (
        ActionType,
        TableName,
        RecordId,
        UserId,
        Notes
    )
    VALUES
    (
        N'APPROVE',
        N'Budget_Transfers',
        CAST(@TransferId AS NVARCHAR(100)),
        @ApprovedBy,
        N'اعتماد مناقلة'
    );

    DECLARE @AuditId BIGINT = SCOPE_IDENTITY();

    INSERT INTO Audit_Log_Details
    (
        AuditId,
        OldData,
        NewData
    )
    VALUES
    (
        @AuditId,
        @OldData,
        @NewData
    );
END;
GO
