CREATE PROCEDURE [dbo].[ApproveExchange]
(
    @ExchangeId BIGINT,
    @ApprovedBy INT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE 
            @OperationType NVARCHAR(30),
            @VaultId VARCHAR(40),
            @Total DECIMAL(18,4),
            @Commission DECIMAL(18,4),
            @Net DECIMAL(18,4),
            @StatusId INT,
            @JournalId BIGINT,
            @MainAccountId varchar(40),
            @CommissionAccountId varchar(40),
			@ForeignCurrencyId  INT,
			@SecondAccountId varchar(40),
			@ReferenceNo NVARCHAR(100),
            @Note NVARCHAR(3500),
			@BalanceBefore DECIMAL(18,4),
            @BalanceAfter DECIMAL(18,4),
            @RateSnapshot DECIMAL(18,4)



        ---------------------------------------
        -- قراءة العملية
        ---------------------------------------
        SELECT 
            @OperationType = OperationType,
            @VaultId = VaultId,
            @Total = TotalLYD,
            @Commission = CommissionLYD,
            @Net = NetLYD,
            @StatusId = StatusId,
			@ForeignCurrencyId = ForeignCurrencyId,
			@ReferenceNo = ReferenceNo,
			@Note        = Note,
			@RateSnapshot = RateSnapshot
        FROM dbo.ExchangeTransactions
        WHERE ExchangeId = @ExchangeId

        IF @StatusId <> 1
            THROW 50001, N'العملية ليست Pending', 1

        ---------------------------------------
        -- قراءة الحسابات من جدول الإعداد
        ---------------------------------------
        SELECT 
            @MainAccountId = MainAccountId,
            @CommissionAccountId = CommissionAccountId,
			@SecondAccountId = SecondAccountId
        FROM dbo.ExchangeOperationAccounts
        WHERE OperationType = @OperationType

        IF @MainAccountId IS NULL
            THROW 50002, N'لم يتم تعريف حسابات العملية في ExchangeOperationAccounts', 1

        ---------------------------------------
        -- تحقق رصيد عند الشراء
        ---------------------------------------
        IF @OperationType = 'BuyCurrency'
        BEGIN
            DECLARE @Balance DECIMAL(18,4)

            SELECT @Balance = SUM(Debit - Credit)
            FROM ACC_BALANCE
            WHERE ACC_CODE = @VaultId

            IF ISNULL(@Balance,0) < @Total
                THROW 50003, N'رصيد الخزنة غير كافي', 1
        END



			SELECT @BalanceBefore =  ( ISNULL(SUM(CREDIT),0) - ISNULL(SUM(DEBIT),0) ) FROM  ACC_BALANCE
            WHERE ACC_CODE = @VaultId AND IS_VOID = 0 AND is_Depended = 1

			SET @BalanceAfter = @BalanceBefore - @Total 


		DECLARE @Statement NVARCHAR(400),@DATE DATE = GETDATE(),@AccountingEntryId INT
        SET @Statement = N'عملية صرافة رقم ' + CAST(@ExchangeId AS NVARCHAR) + ' / ' + CAST(@Note AS NVARCHAR) 



-------------------------------------------------------------------------------------------------------- <إنشاء قيد>

		exec  [dbo].[ACC_BALANCE_proc_Receipt] 
@DATE              = @DATE,
@ACC_CODE_FROM     = @JournalId,
@ACC_CODE_TO       = @CommissionAccountId,
@DEBIT             = NULL,@CREDIT            = NULL,
@USER_ID           = @ApprovedBy,
@Notes_MASTER      = @Statement,
@COST_ID	       = 1,
@ERROR_MSG         ='',
@OP_Status         = 1,
@Receipt_Type	   = NULL,
@Receipt_Num	   = NULL,
@Bank_Name	       ='',
@Check_Number	   =NULL,
@Cr_ID             = @ForeignCurrencyId,@Currency_Equal    = 1,
@BankTransactionNumber  = NULL,
@B_T_ID                 = @AccountingEntryId OUTPUT,
@is_Only_Master         = 1



 DECLARE @T_ID_2 INT 

IF @OperationType = 'SellCurrency' -- FOR SELL
       BEGIN


EXEC  @T_ID_2 = AA_GET_MAX_ID 'ACC_BALANCE'


		   INSERT INTO DBO.ACC_BALANCE	(  [T_ID],	   [B_T_ID],       [ACC_CODE],       [DEBIT],       [CREDIT],       [USER_ID],       [Currency],       [Notes],	   [COST_ID],	   [Bill_Num],	   [is_Depended])	SELECT 	   @T_ID_2,	   @AccountingEntryId,       @VaultId ,	   @Total,       NULL,              @ApprovedBy,       1,       @Statement,
	   1,
	   @ReferenceNo,
	   1

	   	   IF @CommissionAccountId IS NOT NULL
	   BEGIN

    EXEC  @T_ID_2 = AA_GET_MAX_ID 'ACC_BALANCE'

	   		   INSERT INTO DBO.ACC_BALANCE	 (  [T_ID],	   [B_T_ID],       [ACC_CODE],       [DEBIT],       [CREDIT],       [USER_ID],       [Currency],       [Notes],	   [COST_ID],	   [Bill_Num],	   [is_Depended])	SELECT 	   @T_ID_2,	   @AccountingEntryId,       @CommissionAccountId,       @Commission,       NULL,       @ApprovedBy,       1,       @Statement,
	   1,
	   @ReferenceNo,
	   1

	   END

	       EXEC  @T_ID_2 = AA_GET_MAX_ID 'ACC_BALANCE'

	   		   INSERT INTO DBO.ACC_BALANCE	 (  [T_ID],	   [B_T_ID],       [ACC_CODE],       [DEBIT],       [CREDIT],       [USER_ID],       [Currency],       [Notes],	   [COST_ID],	   [Bill_Num],	   [is_Depended])	SELECT 	   @T_ID_2,	   @AccountingEntryId,       @SecondAccountId,       NULL,       @Net,       @ApprovedBy,       1,       @Statement,
	   1,
	   @ReferenceNo,
	   1

END


ELSE
BEGIN -- FOR BUY


EXEC  @T_ID_2 = AA_GET_MAX_ID 'ACC_BALANCE'


		   INSERT INTO DBO.ACC_BALANCE	(  [T_ID],	   [B_T_ID],       [ACC_CODE],       [DEBIT],       [CREDIT],       [USER_ID],       [Currency],       [Notes],	   [COST_ID],	   [Bill_Num],	   [is_Depended])	SELECT 	   @T_ID_2,	   @AccountingEntryId,       @VaultId ,	   NULL,       @Total,              @ApprovedBy,       1,       @Statement,
	   1,
	   @ReferenceNo,
	   1

	   IF @CommissionAccountId IS NOT NULL
	   BEGIN

    EXEC  @T_ID_2 = AA_GET_MAX_ID 'ACC_BALANCE'

	   		   INSERT INTO DBO.ACC_BALANCE	 (  [T_ID],	   [B_T_ID],       [ACC_CODE],       [DEBIT],       [CREDIT],       [USER_ID],       [Currency],       [Notes],	   [COST_ID],	   [Bill_Num],	   [is_Depended])	SELECT 	   @T_ID_2,	   @AccountingEntryId,       @CommissionAccountId,       NULL,       @Commission ,       @ApprovedBy,       1,       @Statement,
	   1,
	   @ReferenceNo,
	   1

	   END

	       EXEC  @T_ID_2 = AA_GET_MAX_ID 'ACC_BALANCE'

	   		   INSERT INTO DBO.ACC_BALANCE	 (  [T_ID],	   [B_T_ID],       [ACC_CODE],       [DEBIT],       [CREDIT],       [USER_ID],       [Currency],       [Notes],	   [COST_ID],	   [Bill_Num],	   [is_Depended])	SELECT 	   @T_ID_2,	   @AccountingEntryId,       @SecondAccountId,       @Net,       NULL,       @ApprovedBy,       1,       @Statement,
	   1,
	   @ReferenceNo,
	   1

END
-------------------------------------------------------------------------------------------------------- </إنشاء قيد>




        -----------------------------------------
        ---- إنشاء القيد الرئيسي
        -----------------------------------------
        --INSERT INTO Journals
        --(
        --    JournalDate,
        --    Description,
        --    CreatedBy
        --)
        --VALUES
        --(
        --    SYSDATETIME(),
        --    N'عملية صرافة رقم ' + CAST(@ExchangeId AS NVARCHAR),
        --    @ApprovedBy
        --)

        --SET @JournalId = SCOPE_IDENTITY()

        -----------------------------------------
        ---- تفاصيل القيد (منطق مزدوج بسيط)
        -----------------------------------------
        --IF @OperationType = 'SellCurrency'
        --BEGIN
        --    -- مدين خزنة
        --    INSERT INTO JournalDetails VALUES (@JournalId, @VaultId, @Total, 0)

        --    -- دائن عمولة
        --    INSERT INTO JournalDetails VALUES (@JournalId, @CommissionAccountId, 0, @Commission)

        --    -- دائن بيع عملة
        --    INSERT INTO JournalDetails VALUES (@JournalId, @MainAccountId, 0, @Net)
        --END
        --ELSE
        --BEGIN
        --    -- مدين شراء عملة
        --    INSERT INTO JournalDetails VALUES (@JournalId, @MainAccountId, @Net, 0)

        --    -- دائن عمولة
        --    INSERT INTO JournalDetails VALUES (@JournalId, @CommissionAccountId, 0, @Commission)

        --    -- دائن خزنة
        --    INSERT INTO JournalDetails VALUES (@JournalId, @VaultId, 0, @Total)
        --END




        ---------------------------------------
        -- تحديث العملية
        ---------------------------------------
        UPDATE dbo.ExchangeTransactions
        SET 
            StatusId = 2,
            JournalId = @AccountingEntryId,
            ApprovedAt = SYSDATETIME(),
            ApprovedBy = @ApprovedBy
        WHERE ExchangeId = @ExchangeId


--INSERT INTO dbo.ExchangeAuditLog
--(
--    ExchangeId,
--    ActionType,
--    UserId,
--    BalanceBefore,
--    BalanceAfter,
--    RateSnapshot,
--    CurrentRate,
--    Details
--)
--VALUES
--(
--    @ExchangeId,
--    'Approve',
--    @ApprovedBy,
--    @BalanceBefore,
--    @BalanceAfter,
--    @RateSnapshot,
--    @RateSnapshot,
--    N'عملية تم اعتمادها بنجاح'
--)


        COMMIT
    END TRY
    BEGIN CATCH
IF @StatusId <> 1
BEGIN
    ROLLBACK
    RAISERROR(N'العملية ليست Pending',16,1)
    RETURN
END

    END CATCH
END
