CREATE procedure [dbo].[Backup_data]
@bath nvarchar (210),
@data_name nvarchar (100),
@Counter int

as

DECLARE @DateTime Nvarchar(50) = GETDATE() 
begin
DECLARE @MyFileName nvarchar(150)
SELECT @MyFileName =  @bath +'\'+ @data_name +'__' +REPLACE(CONVERT(VARCHAR(100),GETDATE(),120),N':','-') 
+'__'+CAST(@Counter AS nvarchar(10))+ '.bak'

BACKUP DATABASE @data_name TO DISK=@MyFileName  --WITH COMPRESSION
end























































