CREATE PROCEDURE [dbo].[Balance_MV_V_SELECT]
    @Form_Type int,
	@isVoid Bit,
	@AG_ID INT
AS
BEGIN
IF @Form_Type = 1
BEGIN 
select * from SB_Balance_MV_V WHERE isVoid = @isVoid AND AG_ID = @AG_ID Order By DATE DESC 
END
ELSE
IF @Form_Type = 2
BEGIN select Top 99999 * from Pch_Balance_MV_V WHERE isVoid = @isVoid Order By DATE DESC  END
ELSE
IF @Form_Type = 3
BEGIN select Top 99999 * from IMEX_Balance_MV_V WHERE isVoid = @isVoid Order By DATE DESC  END
ELSE
IF @Form_Type = 4
BEGIN select Top 99999 * from Invoice_Balance_MV_V WHERE isVoid = @isVoid Order By DATE DESC  END
ELSE
IF @Form_Type = 7
BEGIN select Top 99999 * from ST_Trans_Balance_MV_V WHERE isVoid = @isVoid Order By DATE DESC  END

IF @Form_Type = 8
BEGIN select Top 99999 * from EXP_Balance_MV_V WHERE isVoid = @isVoid Order By DATE DESC  END

ELSE
IF @Form_Type = 11
BEGIN select Top 99999 * from InSale_Balance_MV_V WHERE isVoid = @isVoid Order By DATE DESC  END

ELSE
IF @Form_Type = 13
BEGIN select Top 99999 * from Outsale_Balance_MV_V WHERE isVoid = @isVoid Order By DATE DESC  END

END































