CREATE PROCEDURE [dbo].[Balance_sheet_2]@ACC_CODE VARCHAR(40),@ACC_NAME_1 NVARCHAR(250),@ACC_PARENT_0 int,@Pure_Income_ACC_CODE VARCHAR(40)--@SIDE CHAR(1)-- AS
--BEGIN

AS
BEGIN TRY
BEGIN TRANSACTION 

DECLARE @i VARCHAR(40) ,@ACC_PARENT INT ,@BALANCE NUMERIC(18,3) , @ACC_NAME NVARCHAR(500), @ACC_LEVEL INT , @SIDE VARCHAR(50)

select @i = min(ACC_CODE) FROM [ACCOUNTS_TREE_V] WHERE ACC_PARENT = @ACC_CODE   and ACC_CLOSING = 1


WHILE @I IS NOT NULL
BEGIN

SELECT @ACC_NAME = ACC_NAME ,@ACC_PARENT = ACC_PARENT  ,@BALANCE = BALANCE , @ACC_LEVEL = ACC_LEVEL , @SIDE = SIDE FROM [ACCOUNTS_TREE_V] WHERE ACC_CODE = @i 

--IF @BALANCE < 0 BEGIN SET @BALANCE = @BALANCE * -1 END


INSERT INTO [dbo].[Balance_sheet]
           (
            [ACC_CODE]
           ,[ACC_PARENT]
           ,[ACC_NAME_1]
           ,[ACC_NAME_2]
           ,[ACC_NAME_3]
           ,[BALANCE]
		   ,[ACC_PARENT_0]
		   ,[ACC_LEVEL]
		   ,[SIDE])
     VALUES
           (
           @i
           ,@ACC_PARENT
           ,''
           ,@ACC_NAME
           ,''
           ,NULL
		   ,@ACC_PARENT_0
		   ,@ACC_LEVEL
		   ,@SIDE)
		   EXEC [Balance_sheet_3] @i,@ACC_NAME_1,@ACC_PARENT_0,@Pure_Income_ACC_CODE



		   		   INSERT INTO [dbo].[Balance_sheet]
           (
            [ACC_CODE]
           ,[ACC_PARENT]
           ,[ACC_NAME_1]
           ,[ACC_NAME_2]
           ,[ACC_NAME_3]
           ,[BALANCE]
		   ,[ACC_LEVEL]
		   ,[SIDE])
     VALUES
           (
            0
           ,0
           ,' إجمـــالي ' + @ACC_NAME
           ,''
           ,''
		   ,(SELECT isnull(SUM(BALANCE),0) FROM Balance_sheet WHERE ACC_PARENT = @i)
           --,(SELECT CASE WHEN isnull(BALANCE,0) < 0 THEN isnull(BALANCE,0) * -1 ELSE isnull(BALANCE,0) END FROM ACCOUNTS_TREE_V WHERE ACC_PARENT = @i AND ACC_CLOSING = 1)
		   ,@ACC_LEVEL
		   ,@SIDE)

		   		   		   INSERT INTO [dbo].[Balance_sheet]
           (
            [ACC_CODE]
           ,[ACC_PARENT]
           ,[ACC_NAME_1]
           ,[ACC_NAME_2]
           ,[ACC_NAME_3]
           ,[BALANCE]
		   ,[ACC_LEVEL]
		   ,[SIDE])
     VALUES
           (
           NULL
           ,NULL
           ,NULL
           ,NULL
           ,NULL
           ,NULL
		   ,NULL
		   ,NULL)

--------------------------------------------------------------------------

--IF @SIDE = 'R' 
--BEGIN

--INSERT INTO [dbo].[Balance_sheet_Assets]
--           (
--            [ACC_CODE]
--           ,[ACC_PARENT]
--           ,[ACC_NAME_1]
--           ,[ACC_NAME_2]
--           ,[ACC_NAME_3]
--           ,[BALANCE])
--     VALUES
--           (
--           @i
--           ,@ACC_PARENT
--           ,''
--           ,@ACC_NAME
--           ,''
--           ,NULL)

--		   EXEC [Balance_sheet_3] @i,@ACC_NAME_1,@ACC_PARENT_0,@SIDE

--		   END
--		   ELSE  IF @SIDE = 'L'
--		   BEGIN

--		   INSERT INTO [dbo].[Balance_sheet_Opponents]
--           (
--            [ACC_CODE]
--           ,[ACC_PARENT]
--           ,[ACC_NAME_1]
--           ,[ACC_NAME_2]
--           ,[ACC_NAME_3]
--           ,[BALANCE])
--     VALUES
--           (
--           @i
--           ,@ACC_PARENT
--           ,''
--           ,@ACC_NAME
--           ,''
--           ,NULL)

--		   EXEC [Balance_sheet_3] @i,@ACC_NAME_1,@ACC_PARENT_0,@SIDE

--		   END


select @i = min(ACC_CODE) FROM [ACCOUNTS_TREE_V] WHERE ACC_PARENT = @ACC_CODE AND ACC_CODE > @i   and ACC_CLOSING = 1
END
 
--END


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = '[Balance_sheet_2] ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH


