/****** Object:  StoredProcedure [dbo].[Bill_Perfet_Select]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Bill_Perfet_Select] 
@D_F DATE,
@D_T DATE
AS
BEGIN
DECLARE @i INT
SELECT @i = MIN(T_ID) FROM Agents_Balance_MV WHERE BsType_ID = 1 AND
 ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T ) AND isDepended = 1 AND isVoid = 0
 WHILE @i IS NOT NULL
 BEGIN

 UPDATE Agents_Balance_MV SET 

 Bill_Berfet = 
( SELECT ISNULL(SUM(T_Price),0) - (ISNULL(SUM(SUM_Cost),0)  )  FROM SB_Contents_V WHERE Bill_T_ID = @i AND isDepended = 1
AND BsType_ID = 1 ) 

,Bill_Rtn_Berfet =
( SELECT ISNULL(SUM(T_Price),0) - (ISNULL(SUM(T_COST),0)  )  FROM Rtn_Contents_V WHERE Orginal_Bill_T_ID = @i AND isDepended = 1) 


WHERE T_ID = @i




 SELECT @i = MIN(T_ID) FROM Agents_Balance_MV WHERE BsType_ID = 1 AND
 ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T ) AND isDepended = 1 AND isVoid = 0 AND T_ID > @i
 END


SELECT [Date],[SB_ID],[Ag_name],[Total],[Discount],[Pure],(ISNULL(Bill_Berfet,0) - ISNULL([Bill_Rtn_Berfet],0)) AS Bill_Berfet 
FROM [dbo].[SB_Info_V] 
 Where ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T ) AND isDepended = 1 AND isVoid = 0
ORDER BY Date ASC


END
































GO
