AS
BEGIN

 UPDATE Agents_Balance_MV SET @VALUE = 

 Bill_Berfet = 
( SELECT ISNULL(SUM(T_Price),0) - (ISNULL(SUM(SUM_Cost),0)  )  FROM SB_Contents_V WHERE Bill_T_ID = @T_ID AND isDepended = 1
AND BsType_ID = 1 ) 

,Bill_Rtn_Berfet =
( SELECT ISNULL(SUM(T_Price),0) - (ISNULL(SUM(T_COST),0)  )  FROM Rtn_Contents_V WHERE Orginal_Bill_T_ID = @T_ID AND isDepended = 1) 

WHERE T_ID = @T_ID



END









