/****** Object:  StoredProcedure [dbo].[Budget_Approve_Entry]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  PROCEDURE [dbo].[Budget_Approve_Entry]
(
    @BudgetEntryId INT,
    @ApprovedBy INT,
    @AccountingEntryId INT OUTPUT,
    @Msg NVARCHAR(300) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        /* =========================
           1) قراءة الحركة مع قفل
           ========================= */
        DECLARE
            @BudgetItemId INT,
            @Amount DECIMAL(18,3),
            @EntryType TINYINT,
            @EntryDate DATETIME,
            @Notes NVARCHAR(500);

        SELECT
            @BudgetItemId = BudgetItemId,
            @Amount       = Amount,
            @EntryType    = EntryType,
            @EntryDate    = EntryDate,
            @Notes        = Notes,
            @AccountingEntryId = AccountingEntryId
        FROM dbo.Budget_Entries WITH (UPDLOCK, HOLDLOCK)
        WHERE BudgetEntryId = @BudgetEntryId;

        IF @BudgetItemId IS NULL
        BEGIN
            SET @Msg = N'القيد غير موجود';
            ROLLBACK;
            RETURN;
        END

        IF @AccountingEntryId IS NOT NULL
        BEGIN
            SET @Msg = N'تم اعتماد هذا الصرف مسبقًا';
            ROLLBACK;
            RETURN;
        END

        IF @EntryType <> 1
        BEGIN
            SET @Msg = N'هذا السجل ليس صرفًا فعليًا';
            ROLLBACK;
            RETURN;
        END

        /* =========================
           2) حساب المصروف من البند
           ========================= */
        DECLARE @ExpenseAccount_Code NVARCHAR(40),@account_ID INT;

        SELECT TOP 1 @account_ID = AccountId
        FROM dbo.Account_Budget_Items
        WHERE BudgetItemId = @BudgetItemId
          AND IsDefault = 1;

		      SELECT TOP 1 @ExpenseAccount_Code = ACC_CODE
        FROM dbo.ACCOUNTS_TREE
        WHERE T_ID = @account_ID
   

        IF @ExpenseAccount_Code IS NULL
        BEGIN
            SET @Msg = N'لا يوجد حساب مصروف افتراضي لهذا البند';
            ROLLBACK;
            RETURN;
        END

        /* =========================
           3) حساب الصندوق (ثابت حالياً)
           ========================= */
        DECLARE @CashAccountId nvarchar(40) = '122'; -- الصندوق العام

        /* =========================
           4) إنشاء القيد المحاسبي
           ========================= */
        DECLARE @Statement NVARCHAR(400);
        SET @Statement = N'صرف بند ميزانية - رقم حركة: ' 
                       + CAST(@BudgetEntryId AS NVARCHAR);

exec  [dbo].[ACC_BALANCE_proc_Receipt] 
@DATE              = @EntryDate,
@ACC_CODE_FROM     = @ExpenseAccount_Code,
@ACC_CODE_TO       = @CashAccountId,
@DEBIT             = @Amount,@CREDIT            = @Amount,
@USER_ID           = @ApprovedBy,
@Notes_MASTER      = @Statement,
@COST_ID	       = 1,
@ERROR_MSG         ='',
@OP_Status         = 1,
@Receipt_Type	   = 4,
@Receipt_Num	   = 0,
@Bank_Name	       ='',
@Check_Number	   ='//',
@Cr_ID             = 1,@Currency_Equal    = 1,
@BankTransactionNumber  = NULL,
@B_T_ID                 = @AccountingEntryId OUTPUT



        --EXEC dbo.Journal_Create
        --     @TransDate       = @EntryDate,
        --     @Statement       = @Statement,
        --     @DebitAccountId  = @ExpenseAccountId,
        --     @CreditAccountId = @CashAccountId,
        --     @Amount          = @Amount,
        --     @CreatedBy       = @ApprovedBy,
        --     @JournalId       = @AccountingEntryId OUTPUT;







        IF @AccountingEntryId IS NULL OR @AccountingEntryId = 0
        BEGIN
            SET @Msg = N'فشل إنشاء القيد المحاسبي';
            ROLLBACK;
            RETURN;
        END

        /* =========================
           5) ربط الصرف بالقيد
           ========================= */
        UPDATE dbo.Budget_Entries
        SET AccountingEntryId = @AccountingEntryId
        WHERE BudgetEntryId = @BudgetEntryId;

        COMMIT;
        SET @Msg = N'تم اعتماد الصرف وإنشاء القيد رقم ' 
                 + CAST(@AccountingEntryId AS NVARCHAR);

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        SET @Msg = ERROR_MESSAGE();
    END CATCH
END
GO
