CREATE PROCEDURE [dbo].[Budget_Cancel_Entry]
(
    @BudgetEntryId INT,
    @CanceledBy INT,
    @ReversalJournalId INT OUTPUT,
    @Msg NVARCHAR(300) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        /* =========================
           1) قراءة إذن الصرف مع قفل
           ========================= */
        DECLARE
            @AccountingEntryId INT,
            @EntryType TINYINT,
            @Amount DECIMAL(18,3),
            @EntryDate DATETIME,
            @Notes NVARCHAR(500);

        SELECT
            @AccountingEntryId = AccountingEntryId,
            @EntryType = EntryType,
            @Amount = Amount,
            @EntryDate = EntryDate,
            @Notes = Notes
        FROM dbo.Budget_Entries WITH (UPDLOCK, HOLDLOCK)
        WHERE BudgetEntryId = @BudgetEntryId;

        IF @AccountingEntryId IS NULL
        BEGIN
            SET @Msg = N'لا يمكن الإلغاء: إذن الصرف غير معتمد أو لا يملك قيدًا';
            ROLLBACK;
            RETURN;
        END

        IF @EntryType <> 1
        BEGIN
            SET @Msg = N'لا يمكن الإلغاء: هذا السجل ليس إذن صرف فعلي';
            ROLLBACK;
            RETURN;
        END

        /* =========================
           2) منع الإلغاء المتكرر
           ========================= */
        IF EXISTS (
            SELECT 1
            FROM dbo.ACC_BALANCE_MASTER jm
            WHERE jm.reverse_T_ID = @AccountingEntryId
        )
        BEGIN
            SET @Msg = N'تم إلغاء هذا الإذن سابقًا بقيد عكسي';
            ROLLBACK;
            RETURN;
        END

        /* =========================
           3) استخراج تفاصيل القيد الأصلي
           ========================= */
        --DECLARE
        --    @DebitAccountId INT,
        --    @CreditAccountId INT;

        ---- افتراض: لديك جدول تفاصيل قيود قياسي
        --SELECT
        --    @DebitAccountId = MAX(CASE WHEN jd.Debit > 0 THEN jd.AccountId END),
        --    @CreditAccountId = MAX(CASE WHEN jd.Credit > 0 THEN jd.AccountId END)
        --FROM dbo.Journal_Details jd
        --WHERE jd.JournalId = @AccountingEntryId;

		DECLARE @ERROR_MSG NVARCHAR(500) ='',@OP_Status int = 1 

	EXEC dbo.ACC_BALANCE_Insert_reverse
     @B_T_ID      = @AccountingEntryId,
     @OP_Status   = @OP_Status OUTPUT,
     @ERROR_MSG   = @ERROR_MSG OUTPUT,
     @USER_ID     = @CanceledBy,
     @B_T_ID_NEW  = @ReversalJournalId OUTPUT;

	
        --IF @DebitAccountId IS NULL OR @CreditAccountId IS NULL
        --BEGIN
        --    SET @Msg = N'تعذر تحديد حسابات القيد الأصلي';
        --    ROLLBACK;
        --    RETURN;
        --END

        /* =========================
           4) إنشاء القيد العكسي
           ========================= */
        DECLARE @Statement NVARCHAR(400);
        SET @Statement = N'قيد عكسي لإلغاء إذن صرف رقم '
                       + CAST(@BudgetEntryId AS NVARCHAR)
                       + N' (قيد أصلي رقم '
                       + CAST(@AccountingEntryId AS NVARCHAR) + N')';

        -- نعكس المدين/الدائن
        --EXEC dbo.Journal_Create
        --     @TransDate       = GETDATE(),
        --     @Statement       = @Statement,
        --     @DebitAccountId  = @CreditAccountId, -- عكس
        --     @CreditAccountId = @DebitAccountId,  -- عكس
        --     @Amount          = @Amount,
        --     @CreatedBy       = @CanceledBy,
        --     @JournalId       = @ReversalJournalId OUTPUT;


--EXEC  [dbo].[ACC_BALANCE_Insert_reverse]--@B_T_ID       =@AccountingEntryId,--@OP_Status    =1,--@ERROR_MSG    ='',--@USER_ID      =@CanceledBy




        IF @ReversalJournalId IS NULL OR @ReversalJournalId = 0
        BEGIN
            SET @Msg = N' فشل إنشاء القيد العكسي - ' + @ERROR_MSG
            ROLLBACK;
            RETURN;
        END

        --/* =========================
        --   5) (اختياري) ربط القيد العكسي بالأصلي
        --   ========================= */
        ---- لو عندك عمود مرجعي
        --UPDATE dbo.Journal_Master
        --SET ReversedJournalId = @AccountingEntryId
        --WHERE JournalId = @ReversalJournalId;

        COMMIT;
        SET @Msg = N'تم إلغاء إذن الصرف بنجاح وإنشاء القيد العكسي رقم '
                 + CAST(@ReversalJournalId AS NVARCHAR);

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        SET @Msg = ERROR_MESSAGE();
    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[Budget_Copy_To_New_FiscalYear]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Budget_Copy_To_New_FiscalYear]
(
    @FromFiscalYear INT,
    @ToFiscalYear INT,
    @Mode TINYINT,      -- 1 = نفس الاعتماد، 2 = نسبة، 3 = صفر
    @Rate DECIMAL(5,2) = 0, -- تستخدم فقط في Mode = 2 (مثلاً 10 = +10%)
    @CreatedBy INT
)
AS
BEGIN
    SET NOCOUNT ON;

    -- 1️⃣ التأكد أن السنة الجديدة غير موجودة
    IF EXISTS (
        SELECT 1 FROM Budget_Allocations
        WHERE FiscalYear = @ToFiscalYear
    )
    BEGIN
        RAISERROR(N'تم إنشاء موازنة لهذه السنة مسبقًا',16,1);
        RETURN;
    END

    -- 2️⃣ إدخال السنة المالية إن لم تكن موجودة
    IF NOT EXISTS (
        SELECT 1 FROM Years WHERE YEAR_ID = @ToFiscalYear
    )
    BEGIN
        INSERT INTO Fiscal_Years (FiscalYear, IsClosed)
        VALUES (@ToFiscalYear, 0);
    END

    -- 3️⃣ نسخ الاعتمادات
    INSERT INTO Budget_Allocations
    (
        BudgetItemId,
        FiscalYear,
        AllocatedAmount
    )
    SELECT
        BudgetItemId,
        @ToFiscalYear,
        CASE 
            WHEN @Mode = 1 THEN AllocatedAmount
            WHEN @Mode = 2 THEN AllocatedAmount + (AllocatedAmount * @Rate / 100)
            WHEN @Mode = 3 THEN 0
        END
    FROM Budget_Allocations
    WHERE FiscalYear = @FromFiscalYear;

END;
GO
/****** Object:  StoredProcedure [dbo].[Budget_ReleaseReserve]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Budget_ReleaseReserve]
(
    @BudgetItemId INT,
    @FiscalYear INT,
    @Amount DECIMAL(18,3),
    @Notes NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Reserved DECIMAL(18,3);

    SELECT @Reserved = ISNULL(SUM(Amount),0)
    FROM Budget_Entries
    WHERE BudgetItemId = @BudgetItemId
      AND FiscalYear = @FiscalYear
      AND EntryType = 2;

    IF @Amount > @Reserved
    BEGIN
        RAISERROR(N'قيمة فك الحجز أكبر من إجمالي المبلغ المحجوز',16,1);
        RETURN;
    END

    INSERT INTO Budget_Entries
    (
        BudgetItemId,
        FiscalYear,
        Amount,
        EntryType,
        Notes
    )
    VALUES
    (
        @BudgetItemId,
        @FiscalYear,
        -@Amount,
        2,
        @Notes
    );
END;






























