CREATE PROCEDURE [dbo].[Budget_Reserve]
(
    @BudgetItemId INT,
    @FiscalYear INT,
    @Amount DECIMAL(18,3),
    @Notes NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Available DECIMAL(18,3);

    SELECT @Available = AvailableAmount
    FROM VW_Budget_Control
    WHERE BudgetItemId = @BudgetItemId
      AND FiscalYear = @FiscalYear;

    IF @Available IS NULL
    BEGIN
        RAISERROR(N'البند غير مرتبط بموازنة معتمدة',16,1);
        RETURN;
    END

    IF @Amount > @Available
    BEGIN
        RAISERROR(N'قيمة الحجز تتجاوز الرصيد المتاح للبند',16,1);
        RETURN;
    END

    INSERT INTO Budget_Entries
    (
        BudgetItemId,
        FiscalYear,
        Amount,
        EntryType,
        Notes
    )
    VALUES
    (
        @BudgetItemId,
        @FiscalYear,
        @Amount,
        2,
        @Notes
    );
END;
