CREATE PROCEDURE [dbo].[Budget_Spend]
(
    @BudgetItemId INT,
    @FiscalYear INT,
    @Amount DECIMAL(18,3),
    @AccountingEntryId INT = NULL,
    @Notes NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Available DECIMAL(18,3);

    SELECT @Available = AvailableAmount
    FROM VW_Budget_Control
    WHERE BudgetItemId = @BudgetItemId
      AND FiscalYear = @FiscalYear;

    IF @Available IS NULL
    BEGIN
        RAISERROR(N'البند غير مرتبط بموازنة معتمدة',16,1);
        RETURN;
    END

    IF @Amount > @Available
    BEGIN
        RAISERROR(N'المبلغ المطلوب يتجاوز الرصيد المتاح للبند',16,1);
        RETURN;
    END

    INSERT INTO Budget_Entries
    (
        BudgetItemId,
        FiscalYear,
        Amount,
        EntryType,
        AccountingEntryId,
        Notes
    )
    VALUES
    (
        @BudgetItemId,
        @FiscalYear,
        @Amount,
        1,
        @AccountingEntryId,
        @Notes
    );
END;
