/****** Object:  StoredProcedure [dbo].[Budget_Spend_FromReserve]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  PROCEDURE [dbo].[Budget_Spend_FromReserve]
(
    @BudgetItemId INT,
    @FiscalYear INT,
    @Amount DECIMAL(18,3),
    @AccountingEntryId INT = NULL,
    @Notes NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Reserved DECIMAL(18,3);

    SELECT @Reserved = ISNULL(SUM(Amount),0)
    FROM Budget_Entries
    WHERE BudgetItemId = @BudgetItemId
      AND FiscalYear = @FiscalYear
      AND EntryType = 2;

    IF @Amount > @Reserved
    BEGIN
        RAISERROR(N'قيمة الصرف أكبر من المبلغ المحجوز',16,1);
        RETURN;
    END

    BEGIN TRANSACTION;

    -- 1️⃣ فك الحجز
    INSERT INTO Budget_Entries
    (
        BudgetItemId,
        FiscalYear,
        Amount,
        EntryType,
        Notes
    )
    VALUES
    (
        @BudgetItemId,
        @FiscalYear,
        -@Amount,
        2,
        N'تفريغ حجز قبل الصرف'
    );

    -- 2️⃣ تسجيل الصرف
    INSERT INTO Budget_Entries
    (
        BudgetItemId,
        FiscalYear,
        Amount,
        EntryType,
        AccountingEntryId,
        Notes
    )
    VALUES
    (
        @BudgetItemId,
        @FiscalYear,
        @Amount,
        1,
        @AccountingEntryId,
