/****** Object:  StoredProcedure [dbo].[CALC_EMP_SALARIES]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[CALC_EMP_SALARIES]
@MONTH INT,
@YEAR INT

AS
BEGIN TRY
BEGIN TRANSACTION 
 DECLARE @i INT,@SALARY NUMERIC(18,2) , @T_LOAN NUMERIC(18,2)= 0 , @AG_NAME NVARCHAR(250),@T_OtherVal_ADD NUMERIC(18,2) ,
  @T_OtherVal_Neg NUMERIC(18,2) , @Pure_Salary NUMERIC(18,2) = 0 , @Inserted_Salary NUMERIC(18,2) = 0

 DELETE FROM EMP_SALARIES_PRINT

 SELECT @i = MIN(AG_ID) FROM AGENTS_MENU_V  WHERE Type_ID = 4 AND is_Emp_Pause = 0 AND DATE_START < DATEADD(MONTH, 1, DATEFROMPARTS(@Year, @Month, 1)); --AND YEAR(DATE_START) <= @YEAR  --AND MONTH(DATE_START) <= @MONTH 
 WHILE @i IS NOT NULL
 BEGIN

SELECT @SALARY = ISNULL(AG_Salary,0) , @AG_NAME = Ag_name FROM Agents WHERE AG_ID = @i
SELECT @T_LOAN = ISNULL(SUM(Pure),0) FROM Agents_Balance_MV_RCT WHERE AG_ID = @i  AND   Year(Date) =  @YEAR AND  Month(Date) = @MONTH AND BsType_ID =4 AND isVoid = 0
AND isDepended = 1

SELECT @T_OtherVal_ADD = ISNULL(SUM(Value),0) FROM Others_Values WHERE AG_ID = @i AND ValType = 0 AND isVoid = 0 AND Year(DateOF_Order) = @YEAR AND Month(DateOF_Order) = @MONTH
SELECT @T_OtherVal_Neg = ISNULL(SUM(Value),0) FROM Others_Values WHERE AG_ID = @i AND ValType = 1 AND isVoid = 0 AND Year(DateOF_Order) = @YEAR AND Month(DateOF_Order) = @MONTH

SELECT @Pure_Salary = (@SALARY) +  (@T_OtherVal_ADD - @T_OtherVal_Neg)
SELECT @Inserted_Salary = (@SALARY - @T_LOAN) +  (@T_OtherVal_ADD - @T_OtherVal_Neg)

INSERT INTO EMP_SALARIES_PRINT (Agent_name,AG_Salary,SumDebit,T_OtherVal_ADD,T_OtherVal_Neg,PureSalary,Inserted_Salary)
VALUES(@AG_NAME,@SALARY,@T_LOAN,@T_OtherVal_ADD,@T_OtherVal_Neg,@Pure_Salary,@Inserted_Salary)

SELECT @i = MIN(AG_ID) FROM AGENTS_MENU_V  WHERE Type_ID = 4 AND is_Emp_Pause = 0 AND AG_ID > @i AND DATE_START < DATEADD(MONTH, 1, DATEFROMPARTS(@Year, @Month, 1));  --AND YEAR(DATE_START) <= @YEAR  --AND MONTH(DATE_START) <= @MONTH 
END

SELECT * FROM EMP_SALARIES_PRINT

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('CALC_EMP_SALARIES',16,1,'خطأ')
ROLLBACK
END CATCH




GO
/****** Object:  StoredProcedure [dbo].[CALC_IM_QTY_IN_specific_Range_Date]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[CALC_IM_QTY_IN_specific_Range_Date]
@IM_ID int,
@Date_IN DATETIME	
AS
--BEGIN TRY

--BEGIN TRANSACTION 

BEGIN


DECLARE @QTY FLOAT = 0 , @Date_LAST DATETIME


--IF (SELECT TOP 1 DATE FROM Pch_Details WHERE IM_ID = @IM_ID AND Date < @Date_IN AND isDepended = 1 ) IS NULL
--BEGIN
SELECT @Date_LAST = '01-01-1900 00:00:00'
--END
--ELSE
--BEGIN
--SELECT TOP 1 @Date_LAST = DATE FROM Pch_Details WHERE IM_ID = @IM_ID AND Date < @Date_IN AND isDepended = 1
--END



set @QTY = 
  (select ISNULL(SUM(ST_QTY),0) FROM Pch_Details WHERE  IM_ID=@IM_ID AND isDepended = 1 AND DATE BETWEEN @Date_LAST AND @Date_IN AND DATE <> @Date_IN )
+ ( select ISNULL(SUM(ST_QTY),0) FROM Rtn_Contents WHERE  IM_ID=@IM_ID AND isDepended = 1 and Rtn_Type_ID = 1 AND DATE BETWEEN @Date_LAST AND @Date_IN )
+ (select ISNULL(SUM(ST_QTY),0) FROM Store_Trans_Details WHERE  IM_ID=@IM_ID AND isDepended = 1 AND DATE BETWEEN @Date_LAST AND @Date_IN )
+ (select ISNULL(SUM(ST_QTY),0) FROM FRM_Details WHERE  IM_ID=@IM_ID AND isDepended = 1 AND DATE BETWEEN @Date_LAST AND @Date_IN )

- (select ISNULL(SUM(ST_QTY),0) FROM SB_Contents WHERE  IM_ID=@IM_ID AND isDepended = 1 AND DATE BETWEEN @Date_LAST AND @Date_IN )
- ( select ISNULL(SUM(ST_QTY),0) FROM Rtn_Contents WHERE  IM_ID=@IM_ID AND isDepended = 1 and Rtn_Type_ID = 7 AND DATE BETWEEN @Date_LAST AND @Date_IN )
- (select ISNULL(SUM(ST_QTY),0) FROM IMEX_Details WHERE  IM_ID=@IM_ID AND isDepended = 1 AND DATE BETWEEN @Date_LAST AND @Date_IN )
- (select ISNULL(SUM(ST_QTY),0) FROM Store_Trans_Details WHERE  IM_ID=@IM_ID AND isDepended = 1 AND DATE BETWEEN @Date_LAST AND @Date_IN )
- (select ISNULL(SUM(ST_QTY),0) FROM InSale_Details WHERE  IM_ID=@IM_ID AND isDepended = 1 AND DATE BETWEEN @Date_LAST AND @Date_IN )
- (select ISNULL(SUM(ST_QTY),0) FROM FRM_Contents_Details WHERE  IM_ID=@IM_ID AND isDepended = 1 AND DATE BETWEEN @Date_LAST AND @Date_IN )

+ (select ISNULL(SUM(ST_QTY),0) FROM [ST_QTY_Deferences] WHERE  IM_ID=@IM_ID AND DATE BETWEEN @Date_LAST AND @Date_IN )



--SELECT @QTY
RETURN @QTY



END











GO
