CREATE PROCEDURE [dbo].[CALC_INCOME] 
AS
BEGIN 

WITH CalculatedIncome AS (
    SELECT 
        d.T_ID,
        d.Group_ID,
        m.Group_Name,
        m.Result_Title,
        m.Result_Code,
        d.ACC_CODE,
        d.ACC_NAME,
        d.Group_Calc,
        d.ACC_BALANCE,
        CASE 
            WHEN d.Group_Calc = '+' THEN d.ACC_BALANCE
            WHEN d.Group_Calc = '-' THEN -d.ACC_BALANCE
            ELSE 0
        END AS Calculated_Balance
    FROM Income_Group_Details_V d
    INNER JOIN Income_Group_Master m ON d.Group_ID = m.Group_ID
),

DetailedRows AS (
    SELECT 
        T_ID,
        Group_ID,
        Group_Name,
        NULL AS Result_Title,
        ACC_CODE,
        ACC_NAME,
        Group_Calc AS Sign,
        ACC_BALANCE AS Original_Balance,
        Calculated_Balance AS Final_Balance,
        ROW_NUMBER() OVER (PARTITION BY Group_ID ORDER BY T_ID) AS Row_Num
    FROM CalculatedIncome
),

GroupHeader AS (
    SELECT 
        NULL AS T_ID,
        Group_ID,
         Group_Name AS Group_Name, -- تمييز اسم المجموعة
        NULL AS Result_Title,
        NULL AS ACC_CODE,
        NULL AS ACC_NAME,
        NULL AS Sign,
        NULL AS Original_Balance,
        NULL AS Final_Balance,
        NULL AS Total_Income,
        NULL AS Cumulative_Total,
        0 AS Row_Num -- سيظهر أولًا لكل مجموعة
    FROM CalculatedIncome
    GROUP BY Group_ID, Group_Name
),

FinalRow AS (
    SELECT 
        NULL AS T_ID,
        Group_ID,
        MAX(Group_Name) AS Group_Name,
        MAX(Result_Title) AS Result_Title,
        MAX(Result_Code) AS ACC_CODE,
        NULL AS ACC_NAME,
        MAX(Group_Calc) AS Sign,
        NULL AS Original_Balance,
        NULL AS Final_Balance,
        SUM(Calculated_Balance) AS Total_Income,
        COUNT(*) + 1 AS Row_Num
    FROM CalculatedIncome
    GROUP BY Group_ID
),

CumulativeResult AS (
    SELECT 
        Group_ID,
        Group_Name,
        Result_Title,
        ACC_CODE,
        Sign,
        Total_Income,
        SUM(
            CASE 
                WHEN Sign = '+' THEN Total_Income
                WHEN Sign = '-' THEN -Total_Income
                ELSE 0
            END
        ) OVER (ORDER BY Group_ID ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS Cumulative_Total,
        Row_Num
    FROM FinalRow
)

INSERT INTO Tmp_IncomeReport
SELECT 
    T_ID,
    Group_ID,
    Group_Name,
    Result_Title,
    ACC_CODE,
    ACC_NAME,
    Sign,
    Original_Balance,
    Final_Balance,
    NULL AS Total_Income,
    NULL AS Cumulative_Total,
    Row_Num
FROM GroupHeader -- إدراج اسم المجموعة أولًا

UNION ALL

SELECT 
    T_ID,
    Group_ID,
    Group_Name,
    Result_Title,
    ACC_CODE,
    ACC_NAME,
    Sign,
    Original_Balance,
    Final_Balance,
    NULL AS Total_Income,
    NULL AS Cumulative_Total,
    Row_Num
FROM DetailedRows -- إدراج تفاصيل المجموعة

UNION ALL

SELECT 
    NULL AS T_ID,
    Group_ID,
    Group_Name,
    Result_Title,
    ACC_CODE,
    NULL AS ACC_NAME,
    Sign,
    NULL AS Original_Balance,
    NULL AS Final_Balance,
    Total_Income,
    Cumulative_Total,
    Row_Num
FROM CumulativeResult -- إدراج النتائج النهائية

ORDER BY Group_ID, Row_Num;








------------------------------------------------------------------------------------------------
--WITH CalculatedIncome AS (
--    SELECT 
--        d.T_ID,
