--        ACC_BALANCE AS Original_Balance,
--        Calculated_Balance AS Final_Balance,
--        ROW_NUMBER() OVER (PARTITION BY Group_ID ORDER BY T_ID) AS Row_Num
--    FROM CalculatedIncome
--),

--FinalRow AS (
--    SELECT 
--        NULL AS T_ID,
--        Group_ID,
--        MAX(Group_Name) AS Group_Name,
--        MAX(Result_Title) AS Result_Title,
--        MAX(Result_Code) AS ACC_CODE,
--        NULL AS ACC_NAME,
--        MAX(Group_Calc) AS Sign,
--        NULL AS Original_Balance,
