/****** Object:  StoredProcedure [dbo].[Call_New_SalesBill]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE  [dbo].[Call_New_SalesBill]
@T_ID INT OUTPUT,
@AG_ID INT,
@Bill_Num INT OUTPUT,
@SB_ID INT OUTPUT,
@isNew INT OUTPUT,
@Pr_ID INT,
@isPied INT,
@SB_Type int=1,
@TB_ID INT = NULL,
@User_ID INT,
@Insert_New INT = 0
AS
SET DEADLOCK_PRIORITY NORMAL
DECLARE @TEST INT
BEGIN

DECLARE @START_ID int,@END_ID int
SELECT @START_ID=START_ID,@END_ID=END_ID FROM SERVERS


IF @Insert_New = 0
BEGIN

IF @Pr_ID > 1 
BEGIN 
SELECT @TEST = MAX_T_ID FROM  SB_Max_T_ID_Open_V WHERE  Pr_ID = @Pr_ID 
END
ELSE
BEGIN
SELECT @TEST = MAX(T_ID) FROM  Agents_Balance_MV WHERE  User_ID = @User_ID AND BsType_ID = 1 AND isDepended = 0  and isPause IS	NULL AND isVoid = 0 AND T_ID BETWEEN @START_ID AND @END_ID

END

IF ( @TEST IS NULL) 
BEGIN
SET @isNew = 1 

EXEC @Bill_Num = AG_BalanceMV_GetMax_BillNum
EXEC @SB_ID = AG_BalanceMV_GetMax_SB_ID
EXEC @T_ID = [AA_GET_MAX_ID] 'Agents_Balance_MV' 

INSERT INTO Agents_Balance_MV 
(T_ID,AG_ID,SB_ID,Table_ID,S_Bill_Pr_ID,S_Bills_Type,Pr_ID,Date,BsType_ID,SB_isOpen,isPied,isDepended,User_ID,TB_isOrderd,Barcode) 
VALUES (@T_ID,@AG_ID,@SB_ID,@TB_ID,@Bill_Num,@SB_Type,@Pr_ID,GETDATE(),1,1,0,0,@User_ID,0,(@SB_ID + 100))
--SELECT @T_ID = SCOPE_IDENTITY()
END

ELSE 
BEGIN
 SET @isNew = 0 
SELECT @T_ID = @TEST
END

END
ELSE IF @Insert_New = 1
BEGIN

EXEC @Bill_Num = AG_BalanceMV_GetMax_BillNum
EXEC @SB_ID = AG_BalanceMV_GetMax_SB_ID
EXEC @T_ID = [AA_GET_MAX_ID] 'Agents_Balance_MV' 

INSERT INTO Agents_Balance_MV 
(T_ID,AG_ID,SB_ID,Table_ID,S_Bill_Pr_ID,S_Bills_Type,Pr_ID,Date,BsType_ID,SB_isOpen,isPied,isDepended,User_ID,TB_isOrderd,Barcode) 
VALUES (@T_ID,@AG_ID,@SB_ID,@TB_ID,@Bill_Num,@SB_Type,@Pr_ID,GETDATE(),1,1,0,0,@User_ID,0,(@SB_ID + 100))

END


SELECT @Bill_Num = S_Bill_Pr_ID , @SB_ID = SB_ID , @isPied = isPied FROM Agents_Balance_MV WHERE T_ID = @T_ID  AND T_ID BETWEEN @START_ID AND @END_ID
SELECT @Bill_Num AS Bill_Num  , @SB_ID AS SB_ID ,@T_ID AS T_ID

END


SET ANSI_NULLS ON








GO
/****** Object:  StoredProcedure [dbo].[CASH_FLOW_balance_SELECT]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[CASH_FLOW_balance_SELECT](@CASH_FLOW_ID INT,@YEAR INT)AS
BEGIN


DECLARE @DATE_F DATE,@DATE_T DATE

DELETE FROM [CASH_FLOW_TABLE]
INSERT INTO [dbo].[CASH_FLOW_TABLE]
           ([ACC_CODE]
           ,[ACC_NAME]
           ,[FLOW_ID]
           ,[START_BALANCE]
           ,[END_BALANCE]
           ,[NET_CASH_FLOW])
    SELECT ACC_CODE,ACC_NAME,cash_flow_ID,0,0,0 FROM ACCOUNTS_TREE WHERE cash_flow_ID > 0



SET @DATE_F = '1900-01-01'
SELECT TOP 1 @DATE_T = M_FROM FROM MONTHS_CALENDR_V WHERE YEAR = @YEAR

EXEC PREPARE_ACC_BALANCE 0,@DATE_F,@DATE_T,0--,'Start'
--UPDATE ACCOUNTS_TREE SET Start_DEBIT = DEBIT , Start_CREDIT = CREDIT
UPDATE [CASH_FLOW_TABLE] SET [START_BALANCE] = (SELECT BALANCE FROM ACCOUNTS_TREE_V WHERE ACC_CODE = CASH_FLOW_TABLE.ACC_CODE)



set @DATE_F = @DATE_T
SELECT TOP 1 @DATE_T = M_TO FROM MONTHS_CALENDR_V WHERE YEAR = @YEAR ORDER BY M_ID DESC

EXEC PREPARE_ACC_BALANCE 0,@DATE_F,@DATE_T,0--,'End'
--UPDATE ACCOUNTS_TREE SET End_DEBIT = DEBIT , End_CREDIT = CREDIT
UPDATE [CASH_FLOW_TABLE] SET [END_BALANCE] = (SELECT BALANCE FROM ACCOUNTS_TREE_V WHERE ACC_CODE = CASH_FLOW_TABLE.ACC_CODE)

	SELECT  ACC_NAME,START_BALANCE,END_BALANCE,(END_BALANCE - START_BALANCE) AS NET_CASH_FLOW FROM [CASH_FLOW_TABLE] WHERE FLOW_ID = 1
	SELECT  ACC_NAME,START_BALANCE,END_BALANCE,(END_BALANCE - START_BALANCE) AS NET_CASH_FLOW FROM [CASH_FLOW_TABLE] WHERE FLOW_ID = 2
	SELECT  ACC_NAME,START_BALANCE,END_BALANCE,(END_BALANCE - START_BALANCE) AS NET_CASH_FLOW FROM [CASH_FLOW_TABLE] WHERE FLOW_ID = 3
END
GO
