/****** Object:  StoredProcedure [dbo].[Cheque_SELECT]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Cheque_SELECT] @Cheque_Type INT =NULL, 
 @DATE_TYPE NVARCHAR(100) = NULL, @DATE_F DATE ,--= NULL
 @DATE_T DATE --= NULL AS

BEGIN

--INSERT INTO [Rpt_Cheques]
--DELETE FROM [Rpt_Cheques]

DECLARE @STR NVARCHAR(MAX)
SET @STR = '

SELECT  
       [T_ID]
      ,[StatusId]
      ,[IsFinal]
	  ,BackColorHex
      ,ForeColorHex
	  ,[DATE] AS [تاريخ قيد السند]
      ,[Receipt_Num] AS [رقم السند]
	  ,[Cheque_Type] AS [نوع الشيك]
	  ,[Check_Number] AS [رقم الشيك]
      ,[ACC_NAME]    AS [الحساب]
      ,[VALUE] AS [قيمة الشيك]
      ,[IssueDate] AS [تاريخ الإصدار]
      ,[DueDate] AS [تاريخ الاستحقاق]    
      ,[ReconciliationDate] AS [تاريخ المطابقة]
      ,[BankTransactionNumber] AS [رقم الحركة البنكية]
	  ,[NameAr] AS [حالة الشيك]
      ,[Cheque_Notes] AS [ملاحظات]
  FROM [ChequeStatuses_V] WHERE 1 = 1 '


  IF @Cheque_Type > -1  BEGIN SET @STR = @STR + ' AND StatusId = ' + CONVERT(char, @Cheque_Type)  END



  IF @DATE_TYPE = 'تاريخ قيد الإيصال' 
  BEGIN
  SET @STR = @STR + ' AND [DATE] BETWEEN ''' + CONVERT(VARCHAR, @DATE_F, 23) + ''' AND ''' + CONVERT(VARCHAR, @DATE_T, 23) + ''' '
  END
  ELSE   IF @DATE_TYPE = 'تاريخ الإصدار'
  BEGIN
  SET @STR = @STR + ' AND [IssueDate] BETWEEN ''' + CONVERT(VARCHAR, @DATE_F, 23) + ''' AND ''' + CONVERT(VARCHAR, @DATE_T, 23) + ''' '
  END 
    ELSE   IF @DATE_TYPE = 'تاريخ الاستحقاق'
  BEGIN
  SET @STR = @STR + ' AND [DueDate] BETWEEN ''' + CONVERT(VARCHAR, @DATE_F, 23) + ''' AND ''' + CONVERT(VARCHAR, @DATE_T, 23) + ''' '
  END 
    ELSE   IF @DATE_TYPE = 'تاريخ المطابقة' 
  BEGIN
  SET @STR = @STR + ' AND [ReconciliationDate] BETWEEN ''' + CONVERT(VARCHAR, @DATE_F, 23) + ''' AND ''' + CONVERT(VARCHAR, @DATE_T, 23) + ''' '
  END 


  exec (@STR)

END


GO
