-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Count_Total_Balance_By_Periods]
	
@Pr_ID	int

 

AS
BEGIN

DECLARE @TABLE_STR NVARCHAR(50) = 'ديون طاولات',@SB_T_AG numeric(18,3)  , @DEF_AG_ID INT
,
@SB_T_M numeric(18,3) ,
@SB_T_Q INT ,
@SB_T_D numeric(18,3) ,

@IM_T_M numeric(18,3) ,
@IM_T_Q numeric(18,3)  ,

@CASH_T_M numeric(18,3) ,
@CASH_AG_M numeric(18,3) ,
@CASH_Costmers_M numeric(18,3) ,

@SB_Dis_Q INT ,
@SB_Dis_M numeric(18,3) ,

@SB_Cash_Q INT ,
@SB_Cash_M numeric(18,3) ,

@SB_Dis_TotalM numeric(18,3) ,

@SB_Cancel_Q INT ,
@SB_Cancel_M numeric(18,3) ,

@AG_Counter INT ,
@SB_Returns_M numeric(18,3) ,
@TB_Debit_M numeric(18,3) ,
@Exp_T numeric(18,3) ,
@CASH_T_Card numeric(18,3) 


SELECT TOP 1 @DEF_AG_ID = AG_ID FROM Agents

EXEC [UpdateAgentsBalanceIsPied]

IF EXISTS (SELECT *  FROM sys.indexes  WHERE name='IDX_2') begin DROP INDEX Agents_Balance_MV.IDX_2 end

CREATE INDEX IDX_2 ON Agents_Balance_MV(Pr_ID)

SELECT @SB_T_M = ISNULL(SUM(Total),0) FROM Agents_Balance_MV WHERE Pr_ID = @Pr_ID AND BsType_ID = 1 AND isDepended = 1
SELECT @SB_T_Q = COUNT(T_ID) FROM SB_V WHERE BSType_ID =1 AND Pr_ID = @Pr_ID AND isDepended = 1

SELECT @SB_T_AG = ISNULL(SUM(T_Price),0) FROM Agent_SB_IM_MV_V WHERE  Pr_ID = @Pr_ID AND AG_ID > @DEF_AG_ID AND ISPIED = 0

SELECT @IM_T_M = ISNULL(SUM(T_Price),0) FROM SB_Contents_Total_V WHERE Pr_ID = @Pr_ID AND isDepended = 1 
SELECT @IM_T_Q = ISNULL(SUM(QTY),0) FROM SB_Contents_Total_V WHERE Pr_ID = @Pr_ID AND isDepended = 1 

-----------------------------------
SELECT @CASH_T_M = ISNULL(SUM(Pure),0) FROM Agents_Balance_MV_RCT WHERE isVoid = 0 AND Pr_ID = @Pr_ID AND BsType_ID = 3  and isDepended = 1  --AND AG_ID NOT IN (SELECT AG_ID FROM Agents WHERE TYPE_ID = 8)

--SELECT @CASH_T_Card = ISNULL(SUM(Pure),0) FROM Agents_Balance_MV_RCT WHERE isVoid = 0 AND Pr_ID = @Pr_ID AND BsType_ID = 3  and isDepended = 1 AND AG_ID IN (SELECT AG_ID FROM Agents WHERE TYPE_ID = 8)

SELECT @CASH_AG_M = ISNULL(SUM(Pure),0) FROM Agents_Balance_MV_RCT WHERE isVoid = 0 AND Pr_ID = @Pr_ID AND BsType_ID = 3 AND AG_ID = @DEF_AG_ID  and isDepended = 1
SELECT @CASH_Costmers_M = ISNULL(SUM(Pure),0) FROM Agents_Balance_MV_RCT  WHERE isVoid = 0 AND Pr_ID = @Pr_ID AND BsType_ID = 3 AND AG_ID > @DEF_AG_ID and isDepended = 1
----------------------------------

SELECT @SB_Dis_Q = COUNT(*) FROM SB_V WHERE Discount > 0 AND Pr_ID = @Pr_ID AND isVoid = 0
SELECT @SB_Dis_M = ISNULL(SUM(Discount),0) FROM SB_V WHERE Pr_ID = @Pr_ID  AND isVoid = 0


SELECT @SB_Cancel_Q = COUNT(*) FROM SB_V WHERE isVoid = 1 AND BSType_ID =1 AND Pr_ID = @Pr_ID
SELECT @SB_Cancel_M = ISNULL(SUM(PURE),0) FROM SB_V WHERE isVoid = 1 AND BSType_ID =1 AND Pr_ID = @Pr_ID
SELECT @AG_Counter = ISNULL(AG_Counter,0) From Periods Where Pr_ID = @Pr_ID
SELECT @SB_Returns_M = ISNULL(SUM(Pure),0) FROM SB_V WHERE isDepended = 1 AND Pr_ID = @Pr_ID AND BsType_ID = 10
SELECT @TB_Debit_M = ISNULL(Debit,0) From Periods Where Pr_ID = @Pr_ID
SELECT @Exp_T=  ISNULL(SUM(Pure),0) From Agents_Balance_MV_RCT Where Pr_ID = @Pr_ID AND BsType_ID = 4 AND isVoid = 0 and isDepended = 1

IF ( SELECT Tables FROM Sys_Features WHERE T_ID = (SELECT T_ID FROM Sys_Model) ) = 0 
BEGIN 
SET @TABLE_STR = ''
SET @TB_Debit_M = 0
END


  SELECT  1,'إجمالي المقبوض',ISNULL(@CASH_T_M,0)
  --UNION
  --SELECT  2,'المقبوض كاش',ISNULL(@CASH_T_M - @CASH_T_Card ,0)
  --UNION
  --SELECT  3,'المقبوض بطاقة',ISNULL(@CASH_T_Card,0)
  UNION
  SELECT  2,'المعاملات المدخلة',ISNULL(@AG_Counter,0)
  UNION
  SELECT 3,'إجمالي المبيعات',ISNULL(@SB_T_M,0)
  UNION
  SELECT  4,'عدد الفواتير',ISNULL(@SB_T_Q,0)
  UNION 
  SELECT  5,'مبيعات نقدية',ISNULL(@CASH_AG_M,0)
  UNION 
  SELECT  6,'مبيعات عملاء',ISNULL(@CASH_Costmers_M,0)
  UNION
  SELECT  7,'مبيعات آجلة',ISNULL(@SB_T_AG,0)
  UNION
  SELECT 8,'مبيعات الأصناف',ISNULL(@IM_T_M,0)
  UNION
  SELECT  9,'عدد الطلبيات',ISNULL(@IM_T_Q,0)
  UNION
  SELECT  10, 'عدد فواتير تخفيض',ISNULL(@SB_Dis_Q,0)
  UNION 
  SELECT  11,'إجمالي قيمة التخفيض',ISNULL(@SB_Dis_M,0)
  UNION
  SELECT  12,'عدد فواتير ملغية',ISNULL(@SB_Cancel_Q,0)
  UNION
  SELECT  13,'قيمة فواتير ملغية',ISNULL(@SB_Cancel_M ,0)
  UNION 
  SELECT  14,'قيمة فواتير إرجاع',ISNULL(@SB_Returns_M ,0)
  UNION
  SELECT  15,@TABLE_STR,ISNULL(@TB_Debit_M ,0) --'ديون طاولات'
  UNION 
  SELECT  16,'قيمة مصروفات',ISNULL(@Exp_T ,0)



    -------------------------------------------------------
-- Result Set إضافي (تفصيلي / تحليلي)
  -------------------------------------------------------
  SELECT
    PM.PAYMENT_NAME AS N'طريقة الدفع',
    COUNT(MV.T_ID)  AS N'عدد المعاملات',
    ISNULL(SUM(MV.Pure), 0) AS N'القيمة',
	ISNULL(PMA.Percent_Disc, 0) AS N'عمولة الخصم%',
    ISNULL(SUM(MV.Pure), 0)
      - (ISNULL(SUM(MV.Pure), 0) * (ISNULL(PMA.Percent_Disc,0) / 100.0)) AS N'القيمة بعد الخصم',     
        CONVERT(numeric(18,3),(ISNULL(SUM(MV.Pure), 0) * (ISNULL(PMA.Percent_Disc,0) / 100.0))) AS N'القيمةالمخصومة'

FROM Agents_Balance_MV_RCT MV
INNER JOIN PAYMENT_METHOD PM 
    ON PM.P_ID = MV.Pay_ID
INNER JOIN PaymentMethodDefaultAccounts PMA 
    ON PMA.PaymentMethodID = PM.P_ID
WHERE
    MV.isVoid = 0
    AND MV.BsType_ID = 3
    AND MV.isDepended = 1
    AND  MV.[Pr_ID] = @Pr_ID
GROUP BY
    PM.P_ID,
    PM.PAYMENT_NAME,
    PMA.Percent_Disc
ORDER BY
    PM.PAYMENT_NAME;

     

DROP INDEX Agents_Balance_MV.IDX_2
END



