	[Min_SP_2_ByOne] [numeric](18, 2) NULL,
	[AVG_COSTChange] [float] NULL,
	[ST_DIF_QTY] [numeric](18, 2) NULL,
)


INSERT INTO ##Pch_Details_TMP SELECT 
       [T_ID]
      ,[Date]
