/****** Object:  StoredProcedure [dbo].[CreateExchangePending]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  PROCEDURE [dbo].[CreateExchangePending]
(
    @OperationType NVARCHAR(30),
    @VaultId INT,
    @CurrencyId INT,
    @ForeignAmount DECIMAL(18,4),
    @Rate DECIMAL(18,6),
    @CommissionPercent DECIMAL(9,4),
    @ReferenceNo NVARCHAR(100),
    @Note NVARCHAR(3500),
    @CreatedBy INT,
    @ExchangeId BIGINT OUTPUT,
	@CustomerName	nvarchar(2500),
    @CustomerIdentityNumber	nvarchar(100)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Total DECIMAL(18,4)
    DECLARE @Commission DECIMAL(18,4)
    DECLARE @Net DECIMAL(18,4)

    SET @Total = @ForeignAmount * @Rate
    SET @Commission = @Total * (@CommissionPercent / 100.0)
    SET @Net = @Total + @Commission

    INSERT INTO dbo.ExchangeTransactions
    (
        OperationType,
        VaultId,
        ForeignCurrencyId,
        ForeignAmount,
        RateSnapshot,
        CommissionPercentSnapshot,
        TotalLYD,
        CommissionLYD,
        NetLYD,
        StatusId,
        ReferenceNo,
        Note,
        CreatedBy,
		CustomerName,
		CustomerIdentityNumber
    )
    VALUES
    (
        @OperationType,
        @VaultId,
        @CurrencyId,
        @ForeignAmount,
        @Rate,
        @CommissionPercent,
        @Total,
        @Commission,
        @Net,
        1,  -- Pending
        @ReferenceNo,
        @Note,
        @CreatedBy,
		@CustomerName,
		@CustomerIdentityNumber
    )

    SET @ExchangeId = SCOPE_IDENTITY()

END
GO
/****** Object:  StoredProcedure [dbo].[Currency_Schedule_pros]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Stored Procedure

CREATE PROCEDURE [dbo].[Currency_Schedule_pros]
(@T_ID       int,
@CR_ID    int = NULL,
@Price numeric(18,4),
@BuyPrice numeric(18,4),
@D_F        date = NULL,
@Process	 VARCHAR(20)
) AS


BEGIN
IF @Process = 'DELETE'
BEGIN
	DELETE FROM dbo.Currency_Schedule
	 WHERE T_ID = @T_ID 
	RETURN 1
END
IF EXISTS (SELECT 1 FROM Currency_Schedule WHERE T_ID = @T_ID )
BEGIN
	UPDATE dbo.Currency_Schedule
	SET 
       [CR_ID]     = @CR_ID,
       [D_F]        = @D_F
	WHERE T_ID = @T_ID 
	RETURN 1
END
ELSE
BEGIN


IF NOT EXISTS (SELECT 1 FROM Currency_Schedule WHERE CR_ID = @CR_ID AND D_F = @D_F) and @CR_ID<> 0
BEGIN

exec @T_ID = AA_GET_MAX_ID 'Currency_Schedule'
	INSERT INTO dbo.Currency_Schedule
	(  [T_ID],
       [CR_ID],
	   [Price],
	   [BuyPrice],
       [D_F])
	SELECT 
	   @T_ID,
       @CR_ID,
	   @Price,
	   @BuyPrice,
       @D_F
	RETURN 1
END

END

END





GO
/****** Object:  StoredProcedure [dbo].[Current_Balances_By_Family_SELECT]    Script Date: 09/05/2026 16:40:13 ******/
