GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Current_Balances_By_Family_SELECT](@Hide_Zeros  BIT,@ACC_CODE     int,@DATE_F DATE,@DATE_T DATE,@COST_ID INT = NULL)AS--BEGIN TRY
--BEGIN TRANSACTION 
BEGIN

EXEC PREPARE_ACC_BALANCE 0,@DATE_F,@DATE_T,1,@COST_ID

IF @Hide_Zeros = 1
BEGIN

SELECT * FROM [dbo].[BALANCES_REVIEW_V]  WHERE ACC_PARENT =  @ACC_CODE AND ( [مدين - المجاميع]  <>  0
              OR  [دائــن - المجاميع]  <> 0 )
ORDER BY [إسم الحساب],[رقم الحساب]

END
ELSE
BEGIN

SELECT * FROM [dbo].[BALANCES_REVIEW_V]  WHERE ACC_PARENT =  @ACC_CODE  ORDER BY [إسم الحساب],[رقم الحساب]


END



-- COMMIT
--END TRY

--BEGIN CATCH
--IF @@TRANCOUNT > 0
--DECLARE @ERR_STR NVARCHAR(MAX)
--       SET @ERR_STR  = ' [ACC_BALANCE_proc] - ' + ERROR_MESSAGE()
--	   raiserror(@ERR_STR,16,1,'خطأ')
--ROLLBACK
--END CATCH

END

