/****** Object:  StoredProcedure [dbo].[Daily_Balance_Select]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Daily_Balance_Select] 

@DATE_F DATE,
@DATE_T DATE,
@TYPE AS INT,
@Depended INT,
@Balanced INT

AS
BEGIN 

DECLARE @STR AS NVARCHAR(MAX) , @WHERE_ST AS NVARCHAR(MAX) = ' WHERE 1=1 '




IF @TYPE = 0
BEGIN


SET @STR = '
SELECT T_ID as [رقم القيد], 
       JournalNumber AS [الإشاري],
       DATE_IN AS [تاريخ الإدراج], 
       convert(DATE,DATE)  as [التاريــخ], 
       NOTES AS [الشــرح], 
	   CREDIT AS [مدين], 
       DEBIT AS [دائن], 
       ACC_B_Status AS [\], 
       ACC_Depend_Status AS [\ ], 
       CREDIT, DEBIT  
FROM ACC_BALANCE_MASTER_V  
WHERE CONVERT(DATE, DATE) BETWEEN ''' + CONVERT(VARCHAR, @DATE_F, 23) + ''' AND ''' + CONVERT(VARCHAR, @DATE_T, 23) + ''' '

IF @Depended > 0 
BEGIN

IF @Depended = 1  SET @STR = @STR + ' AND is_Depended = 1 '

IF @Depended = 2  SET @STR = @STR + ' AND is_Depended = 0 '

END

IF @Balanced > 0 
BEGIN

IF @Balanced = 1  SET @STR = @STR + ' AND ACC_B_Status_Flag = 1 '

IF @Balanced = 2  SET @STR = @STR + ' AND ACC_B_Status_Flag = 0 '

END

SET @STR = @STR + ' ORDER BY T_ID ASC,Debit ASC '


--SET @STR = '
--SELECT T_ID as [رقم القيد], 
--       DATE_IN AS [تاريخ الإدراج], 
--       DATE as [التاريــخ], 
--       NOTES AS [الشــرح], 
--       DEBIT AS [دائن], 
--       CREDIT AS [مدين], 
--       ACC_B_Status AS [\], 
--       ACC_Depend_Status AS [\ ], 
--       CREDIT, DEBIT  
--FROM ACC_BALANCE_MASTER_V  
--WHERE CONVERT(DATE, DATE) BETWEEN ''' + FORMAT(@DATE_F, 'yyyy-MM-dd') + ''' AND ''' + FORMAT(@DATE_T, 'yyyy-MM-dd') + ''''

exec (@STR)


--SELECT T_ID as [  رقم القيد ],DATE_IN AS [ تاريخ الإدراج ],DATE as [ التاريــخ ],NOTES AS [ الشــرح  ],DEBIT AS [دائن],CREDIT AS [مدين],
-- ACC_B_Status AS [\] ,ACC_Depend_Status AS [\ ],CREDIT,DEBIT  FROM ACC_BALANCE_MASTER_V   WHERE CONVERT(DATE,DATE) BETWEEN @DATE_F AND @DATE_T




--SELECT T_ID as '  رقم القيد ',DATE_IN AS ' تاريخ الإدراج ',DATE as ' التاريــخ ',NOTES AS ' الشــرح  ',DEBIT AS 'دائن',CREDIT AS 'مدين',
-- ACC_B_Status AS '\' ,ACC_Depend_Status AS '\ ',CREDIT,DEBIT  FROM ACC_BALANCE_MASTER_V   WHERE CONVERT(DATE,DATE) BETWEEN @DATE_F AND @DATE_T







END
ELSE IF @TYPE = 1
BEGIN

SELECT B_T_ID as [  رقم القيد ],DATE_IN AS [ تاريخ الإدراج ],convert(DATE,DATE) as [ التاريــخ ],NOTES AS [ الشــرح  ],ACC_NAME as [الحساب],CREDIT AS [مدين],DEBIT AS [دائن],
 '' AS [\] ,ACC_Depend_Status AS [\ ],CREDIT,DEBIT  FROM ACC_BALANCE_V 
 WHERE CONVERT(DATE,DATE) BETWEEN @DATE_F AND @DATE_T AND is_Depended = 1
   ORDER BY B_T_ID ASC,CREDIT DESC
  --ORDER BY B_T_ID ASC
END


END


















