/****** Object:  StoredProcedure [dbo].[DEBIT_CREDIT_SWAP]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[DEBIT_CREDIT_SWAP]

AS
BEGIN

UPDATE ACC_BALANCE
SET 
    DEBIT = CASE 
                WHEN (ISNULL(DEBIT, 0) = 0 AND ISNULL(CREDIT, 0) > 0) THEN CREDIT 
                ELSE NULL 
            END,
    CREDIT = CASE 
                WHEN (ISNULL(CREDIT, 0) = 0 AND ISNULL(DEBIT, 0) > 0) THEN DEBIT 
                ELSE NULL 
             END
WHERE 
    (ISNULL(DEBIT, 0) = 0 AND ISNULL(CREDIT, 0) > 0)
    OR
    (ISNULL(CREDIT, 0) = 0 AND ISNULL(DEBIT, 0) > 0);

END


GO
