CREATE PROCEDURE [dbo].[DeleteAll_BuysAndSales]
@Jrd_ID INT = NULL,
@Delete_ALL_Qty Bit = 0

AS
BEGIN TRY
BEGIN TRANSACTION 

--AS
--BEGIN

Declare @i int , @Balance Float , @T_ID INT --,@isError int


    DELETE FROM ST_Balance_TMP
    INSERT INTO ST_Balance_TMP([T_ID],[ST_ID],[IM_ID],[D_Valid],[ST_QTY]) SELECT ROW_NUMBER() OVER(ORDER BY T_ID DESC) AS IDX,[ST_ID],[IM_ID],[D_Valid],[ST_QTY] FROM IM_STORE_View WHERE QTY <> 0
	and ST_ID between (select START_ID from SERVERS) and (select end_ID from SERVERS)

    DELETE FROM TreasuryCard_Tmp
	INSERT INTO TreasuryCard_Tmp(Tr_ID,T_Balance) SELECT Tr_ID,T_Balance FROM TR_MENU_V

	DELETE FROM Agents_Tmp	
	INSERT INTO Agents_Tmp(AG_ID,T_Debit,T_Credit,T_Balance) SELECT AG_ID,T_Debit,T_Credit,T_Balance FROM AGENTS_MENU_V WHERE T_BALANCE <> 0


UPDATE Agents_Balance_MV SET Proj_ID = NULL
UPDATE Tables SET TB_ORDER_CODE = NULL
DELETE FROM Network_Edit_Tracker
Delete From Store_Trans_Details
DELETE FROM Perform_Sparsi_ditale
DELETE FROM Perform_Sparsi
DELETE FROM Perform_Fatura
Delete from IMEX_Details
Delete from EXP_Details
Delete from AG_Projects
Delete from SB_Contents_Structers
DBCC CHECKIDENT ('[SB_Contents_Structers]', RESEED, 0);
Delete from SB_Contents
Delete from Valid_Notes
Delete from Store_Trans_Details
Delete from Rtn_Contents 
delete from SB_IM_Components
DELETE FROM Costmer_Screen
DELETE FROM CP_Bill_Screen
UPDATE Tables Set isReserve = 0
DELETE FROM FRM_Contents_Details
DELETE FROM FRM_Details
DELETE FROM ViewBill_Contents
DELETE FROM InSale_Details 
DELETE FROM OutSale_Details 
DELETE FROM Exp_Static 
DELETE FROM Others_Values
DELETE FROM Custody
DELETE FROM Agents_Balance_MV_RCT
Delete from AG_MV_TRANSACTION
--DELETE FROM ALL_BALANCES_FOR_TREE
DELETE FROM Treasury_Balance_MV
DELETE FROM Agents_Balance_MV_St_Trans
DELETE FROM OFFERS_MASTER

DELETE FROM IM_ORDERS_COMING
DELETE FROM SB_Rsv
DELETE FROM SB_Rsv_2
DELETE FROM SB_VALUE_Bercent_Details

DELETE FROM SynchroLog
DBCC CHECKIDENT ('[SynchroLog]', RESEED, 0);

DELETE FROM Upload_Files
DBCC CHECKIDENT ('[Upload_Files]', RESEED, 0);

IF @Delete_ALL_Qty = 0 AND @Jrd_ID IS NULL
BEGIN 

Delete from Pch_Exp_Values
	
Delete From Agents_Balance_MV
Delete from AG_MV_TRANSACTION


DELETE FROM [ProjectDocuments]
DBCC CHECKIDENT ('[ProjectDocuments]', RESEED, 0);
DELETE FROM [ProjectPartners]
DBCC CHECKIDENT ('[ProjectPartners]', RESEED, 0);
DELETE FROM [Projects]
DBCC CHECKIDENT ('[Projects]', RESEED, 0);
DELETE FROM [Partners]
DBCC CHECKIDENT ('[Partners]', RESEED, 0);


DELETE FROM [TB_AutoPrint_tmp]
DELETE FROM [TB_AutoPrint_Pending]
DELETE FROM [TB_AutoPrint_Notifications]
DELETE FROM [TB_AutoPrint_Log]


UPDATE IM_Menu SET Last_Pch_Cargo =0,Last_PchT_ID=0 


EXEC [DeleteAll_Jrd_For_ST_Balance]



END
ELSE IF @Jrd_ID IS NOT NULL AND @Delete_ALL_Qty = 0
BEGIN
DELETE FROM ST_Balance
DELETE FROM ST_QTY_Deferences
Delete from Pch_Exp_Values
Delete from Pch_Details	WHERE Pch_T_ID <> @Jrd_ID 
Delete From Agents_Balance_MV WHERE T_ID <> @Jrd_ID
UPDATE IM_Menu SET Last_Pch_Cargo =0,Last_PchT_ID=0
EXEC RECOUNT_IM_ALL_MainCost
END

ELSE  IF @Jrd_ID IS NULL AND @Delete_ALL_Qty = 1
BEGIN
DELETE FROM ST_Balance
DELETE FROM ST_QTY_Deferences
Delete from Pch_Exp_Values
Delete from Pch_Details	
Delete From Agents_Balance_MV
UPDATE IM_Menu SET Last_Pch_Cargo =0,Last_PchT_ID=0--,Cost = 0

END

----------------------------------------------------------------------------------------------------
--UPDATE Tables SET isbusy = 0
SELECT @i = Min(AG_ID) FROM Agents_Tmp --WHERE Ag_ID > 1
WHILE(@i is not NULL)
BEGIN
SELECT @Balance = T_BALANCE FROM Agents_Tmp WHERE AG_ID = @i

EXEC @T_ID = AA_GET_MAX_ID 'Agents_Balance_MV'

IF @Balance < 0
BEGIN
Declare @Balance_2 float = @Balance * -1
INSERT INTO Agents_Balance_MV (T_ID,AG_ID,Date,Total,Pure,BsType_ID,isDepended,User_ID)
VALUES(@T_ID,@i,GETDATE(),@Balance_2,@Balance_2,6,1,1)
GOTO NEXT_
END

IF @Balance > 0
BEGIN
INSERT INTO Agents_Balance_MV (T_ID,AG_ID,Date,Total,Pure,BsType_ID,isDepended,User_ID)
VALUES(@T_ID,@i,GETDATE(),@Balance,@Balance,37,1,1)
END

NEXT_:
SELECT @i = Min(AG_ID) FROM Agents_Tmp WHERE AG_ID > @i
END
-------------------------------------------------------------------------------------------------------

SELECT @i = Min(TR_ID) FROM TreasuryCard_Tmp
WHILE(@i is not NULL)
BEGIN
SELECT @Balance = T_BALANCE FROM TreasuryCard_Tmp WHERE TR_ID = @i
IF @Balance < 0
BEGIN
Declare @Balance_3 float = @Balance * -1
EXEC @T_ID = AA_GET_MAX_Treasury_Balance_MV
INSERT INTO Treasury_Balance_MV(T_ID,Tr_ID,Date,Debit,Balance,Tr_Type_ID,User_ID,isFirst_Time)
VALUES(@T_ID,@i,GETDATE(),@Balance_3,@Balance_3,3,1,1)

END

IF @Balance > 0
BEGIN
EXEC @T_ID = AA_GET_MAX_Treasury_Balance_MV
INSERT INTO Treasury_Balance_MV (T_ID,Tr_ID,Date,Credit,Balance,Tr_Type_ID,User_ID,isFirst_Time)
VALUES(@T_ID,@i,GETDATE(),@Balance,@Balance,3,1,1)

END

SELECT @i = Min(Tr_ID) FROM TreasuryCard_Tmp WHERE  Tr_ID > @i
END
-------------------------------------------------------------------------------------------------------
UPDATE Agents_Balance_MV SET Pr_ID = NULL

Delete from Periods

DECLARE @Pr_ID INT 
EXEC @Pr_ID = AA_GET_MAX_Periods
INSERT INTO [dbo].[Periods]
           ([Pr_ID]
		   ,[User_ID]
           ,[Pr_Start]
           ,[Pr_End]
           ,[NotesOn_Start]
           ,[NotesOn_End]
           ,[Pr_isOpen]
           ,[TB_Flate_ID]
           ,[AG_Counter]
           ,[Debit])
     VALUES
           (@Pr_ID,1,'1900-01-01',NULL,'','',0,NULL,0,0)

DECLARE @Proj_ID INT
EXEC @Proj_ID = AA_GET_MAX_ID 'AG_Projects'
INSERT INTO AG_Projects(Proj_ID,Proj_NAME,AG_ID) VALUES (@Proj_ID,'N/A',1)
UPDATE Tables SET isbusy = 0


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = '[DeleteAll_BuysAndSales] ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH



