/****** Object:  StoredProcedure [dbo].[DeleteAll_Jrd_For_ST_Balance]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[DeleteAll_Jrd_For_ST_Balance]


AS
BEGIN TRY
BEGIN TRANSACTION 


Declare @i int , @Balance Float , @T_ID INT ,@Jrd_ID int,@START_ID BIGINT

select @START_ID = ISNULL(START_ID,0) from SERVERS


--///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
   
--INSERT INTO ST_Balance_TMP([T_ID],[ST_ID],[IM_ID],[D_Valid],[ST_QTY]) SELECT [T_ID],[ST_ID],[IM_ID],[D_Valid],[QTY] FROM IM_STORE_View
      
	Delete from Pch_Details	--WHERE Pch_T_ID NOT IN(@Jrd_ID)
	--DBCC CHECKIDENT ('[Pch_Details]', RESEED, 0);
	--Delete From Agents_Balance_MV --WHERE T_ID NOT IN(@Jrd_ID) 
	--DBCC CHECKIDENT ('[Agents_Balance_MV]', RESEED, 0);
	   
	EXEC @T_ID = AA_GET_MAX_Agents_Balance_MV

	select @Jrd_ID = ISNULL(MAX(JRD_ID),@START_ID) + 1 FROM Agents_Balance_MV  

	insert into Agents_Balance_MV (T_ID,SB_ID,Receipt_Num,Receipt_Tran_ID,AG_ID,Pr_ID,Pch_ID,IMEX_ID,Jrd_ID,SRtn_ID,PRtn_ID,
	 ST_Tran_ID,EXP_ID,Frm_ID,ViewSB_ID,InSale_ID,Frm_ID_M,ReferNum,Date,Year,Month,Receipt_Title,About,BsType_ID,isPied,
	 isDepended,isVoid,User_ID,Cr_Equal_Value,Reciept_Discount)

	 values(@T_ID,NULL,NULL,NULL,1,NULL,NULL,NULL,@Jrd_ID,NULL,NULL,NULL,NULL,NULL,NULL
	 ,NULL,NULL,NULL,GETDATE(),NULL,NULL,'جردأول مدة',NULL,9,NULL,0,0,1,NULL,NULL)

     SELECT @Jrd_ID = @T_ID

Delete from ST_Balance
DELETE FROM ST_QTY_Deferences

SELECT @Jrd_ID = T_ID FROM Agents_Balance_MV WHERE Jrd_ID = @Jrd_ID

declare @IM_ID INT,@Cost numeric(18, 2),@U_ID INT,@TOTAL NUMERIC(18,3), @TOTAL_INVOICE NUMERIC(18,3)
,@U_Cargo NUMERIC(18,2),@D_Valid NVARCHAR(50),@ST_ID INT,@ST_QTY NUMERIC(18,2),@Barcode NVARCHAR(50)

--UPDATE Pch_Details SET isDepended = 1 where Pch_T_ID = @Jrd_ID 
SELECT @i = min(T_ID) From ST_Balance_TMP --WHERE Pch_T_ID = @Jrd_ID
WHILE @i IS NOT NULL
BEGIN

SELECT @IM_ID=IM_ID,@D_Valid=D_Valid,@ST_ID = ST_ID,@ST_QTY = ST_QTY FROM ST_Balance_TMP WHERE T_ID = @i
SELECT TOP 1 @U_ID = U_ID ,@Barcode=Barcode FROM IM_units_Search_V WHERE IM_ID = @IM_ID AND U_CARGO = 1
SELECT @Cost = COST FROM IM_Menu WHERE IM_ID = @IM_ID
SET @TOTAL = (@ST_QTY * @Cost)
IF @D_Valid = '' BEGIN SELECT @D_Valid = NULL END

IF @ST_QTY <> 0
BEGIN

EXEC [dbo].[Pch_Details_Insert] 
0,
@IM_ID,
@U_ID,
@Jrd_ID,
@Cost,
@ST_ID,
@D_Valid,
@ST_QTY ,
@TOTAL,
NULL,
NULL,
0,
NULL,
NULL,
NULL,
NULL,
NULL,
@Barcode

END

SELECT @i = min(T_ID) From ST_Balance_TMP  WHERE  T_ID > @i
END

UPDATE Agents_Balance_MV SET Invoice_Type = 0 WHERE T_ID = @Jrd_ID
SELECT @TOTAL_INVOICE = ISNULL(SUM(TOTAL),0) FROM Pch_Details WHERE Pch_T_ID = @Jrd_ID AND isDepended = 1 
EXEC AG_Balance_Update_Total @Jrd_ID,@TOTAL_INVOICE,0
EXEC AG_Balance_Update_isDepended @Jrd_ID

--+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
	
--END
--///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
--raiserror('[DeleteAll_Jrd_For_ST_Balance]',16,1,'خطأ')
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = '[DeleteAll_Jrd_For_ST_Balance]' + ERROR_MESSAGE() 
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH













GO
