CREATE PROCEDURE [dbo].[Deliver_Order]
	@T_ID int,
	@Order_isDeleverd bit,
	@User_ID INT,
	@Pr_ID INT,
	@Tr_ID INT

AS
BEGIN TRY
BEGIN TRANSACTION
 
declare @TRMV_T_ID INT,@B_Type INT ,@Pied FLOAT,@i int,@Receipt_Title NVARCHAR(2500),
@NEW_T_ID INT,@Bill_Num INT,@Receipt_Num INT,@AG_ID INT , @SB_ID nvarchar(25)
, @ST_QTY NUMERIC(18,2),@U_Cargo NUMERIC(18,2),@U_ID INT,@IM_ID INT,@ST_ID INT,@D_Vaild NVARCHAR(50)


Update Agents_Balance_MV SET Order_isDeleverd = @Order_isDeleverd WHERE T_ID = @T_ID 
UPDATE SB_Contents SET isDepended = 1 ,Date = GETDATE() WHERE Bill_T_ID = @T_ID
EXEC AG_Balance_Update_isDepended @T_ID



--SELECT @i = MIN(T_ID) FROM SB_Contents WHERE Bill_T_ID = @T_ID
--WHILE @i IS NOT NULL
--BEGIN
--SELECT @U_Cargo = U_Cargo ,@IM_ID=IM_ID, @ST_ID=ST_ID,@D_Vaild=D_Vaild,@ST_QTY =ST_QTY FROM SB_Contents where T_ID = @i
--EXEC Dec_IM_QTY @IM_ID,@ST_ID,@D_Vaild,@ST_QTY
--SELECT @i = MIN(T_ID) FROM SB_Contents WHERE Bill_T_ID = @T_ID AND T_ID > @i
--END







IF ( (SELECT TB_isOrderd FROM Agents_Balance_MV WHERE T_ID = @T_ID ) = 1 )
 and 
   ( (SELECT AG_ID FROM Agents_Balance_MV WHERE T_ID = @T_ID ) = 1 )
BEGIN

--------------------------------------------------------------------------
SELECT @AG_ID = AG_ID, @Bill_Num = S_Bill_Pr_ID , @SB_ID=SB_ID , @Pied = (Total - ISNULL(Discount,0)) 
FROM Agents_Balance_MV WHERE T_ID = @T_ID

UPDATE Agents_Balance_MV SET isPied = 1 , Pure =  @Pied , Receipt_Title = 'فاتورة مبيعات  : ' + @SB_ID WHERE T_ID = @T_ID

--EXEC @Receipt_Num = AG_BalanceMV_GetMaxRecepitNum

--INSERT INTO Agents_Balance_MV 
--(Receipt_Tran_ID,AG_ID,Receipt_Num,S_Bill_Pr_ID,Pr_ID,Date,BsType_ID,Receipt_Title,Credit,SB_isOpen,isDepended,User_ID) 
--VALUES (@T_ID,@AG_ID,@Receipt_Num,@Bill_Num,@Pr_ID,GETDATE(),3,'فاتورة مبيعات  : ' + @SB_ID,@Pied,0,1,@User_ID)
--SELECT @NEW_T_ID = SCOPE_IDENTITY();
----------------------------------------------------------------------------

--Insert Into Treasury_Balance_MV 
--(AGBalance_T_ID,Tran_ID,date,Tr_ID,notice_move,Bank_Name,CheckNum,Debit,Credit,Balance,
--Tr_Type_ID,isTran_From,isTran_To,User_ID,isVoid)
--Values (@NEW_T_ID,NULL,GETDATE(),@Tr_ID,'فاتورة مبيعات : ' + @SB_ID,NULL,NULL,@Pied,NULL,NULL,2,NULL,NULL,@User_ID,0)
--SELECT @TRMV_T_ID = SCOPE_IDENTITY();



SET @Receipt_Title = 'فاتورة مبيعات  : ' + @SB_ID
EXEC [Agents_BalanceMV_insert_RCT]
0,
GETDATE,
0,--@Receipt_Num
@AG_ID,
@Pr_ID,
@T_ID,--@Receipt_Tran_ID
'',--@ReferNum
@Receipt_Title,
@Pied,--@Pure
NULL,--@About
3,--@BsType_ID
@User_ID ,
@Tr_ID,
'',--BANK_NAME
''--CHECK_NUMBER








---------------------------------------------------------------------------

END 


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[Deliver_Order]',16,1,'خطأ')
ROLLBACK
END CATCH











