/****** Object:  StoredProcedure [dbo].[DocumentTypeProc]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create PROCEDURE [dbo].[DocumentTypeProc]
    @Process INT,             -- 1 Insert, 2 Delete, 3 Update
    @ID INT = NULL,           -- Used for Update/Delete
    @Name NVARCHAR(1550) = NULL   -- Used for Insert/Update
AS
BEGIN
    SET NOCOUNT ON;

    IF @Process = 1
    BEGIN
        -- INSERT
        INSERT INTO DocumentType (Name)
        VALUES (@Name);

        --SELECT SCOPE_IDENTITY() AS InsertedID;
        RETURN;
    END

    ELSE IF @Process = 2
    BEGIN
        -- DELETE
        DELETE FROM DocumentType
        WHERE ID = @ID;

        --SELECT @@ROWCOUNT AS DeletedRows;
        RETURN;
    END

    ELSE IF @Process = 3
    BEGIN
        -- UPDATE
        UPDATE DocumentType
        SET Name = @Name
        WHERE ID = @ID;

        --SELECT @@ROWCOUNT AS UpdatedRows;
        RETURN;
    END

    -- INVALID PROCESS
    --SELECT -1 AS Error, 'Invalid @Process value (must be 1,2,3)' AS Message;
END
GO
/****** Object:  StoredProcedure [dbo].[EMP_Insert_Salaries]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EMP_Insert_Salaries]
@MONTH INT,
@YEAR INT,
@USER_ID INT,
@Salary_Date datetime

AS
BEGIN TRY
BEGIN TRANSACTION 
 DECLARE @i INT,@SALARY NUMERIC(18,2) , @T_LOAN NUMERIC(18,2)= 0 , @AG_NAME NVARCHAR(250), @Month_S NVARCHAR(10),@Year_S NVARCHAR(10)
, @T_OtherVal_ADD NUMERIC(18,2) , @T_OtherVal_Neg NUMERIC(18,2), @Pure_Salary NUMERIC(18,2) = 0 , @Inserted_Salary NUMERIC(18,2) = 0,@T_ID INT

 SELECT @Month_S = @MONTH , @Year_S = @Year

 UPDATE Agents_Balance_MV SET isVoid = 1 WHERE BsType_ID = 5 AND YEAR = @YEAR and Month = @MONTH AND isDepended = 1 AND isVoid = 0

 SELECT @i = MIN(AG_ID) FROM AGENTS_MENU_V   WHERE Type_ID = 4 AND is_Emp_Pause = 0  AND DATE_START < DATEADD(MONTH, 1, DATEFROMPARTS(@Year, @Month, 1));  --AND YEAR(DATE_START) <= @YEAR  --AND MONTH(DATE_START) <= @MONTH 
 WHILE @i IS NOT NULL
 BEGIN

SELECT @SALARY = ISNULL(AG_Salary,0) , @AG_NAME = Ag_name FROM Agents WHERE AG_ID = @i
SELECT @T_LOAN = ISNULL(SUM(Pure),0) FROM Agents_Balance_MV_RCT WHERE AG_ID = @i  AND YEAR(date) = @YEAR AND Month(date) = @MONTH AND BsType_ID =4 AND isVoid = 0
AND isDepended = 1


SELECT @T_OtherVal_ADD = ISNULL(SUM(Value),0) FROM Others_Values WHERE AG_ID = @i AND ValType = 0 AND isVoid = 0 AND YEAR = @YEAR AND Month = @MONTH
SELECT @T_OtherVal_Neg = ISNULL(SUM(Value),0) FROM Others_Values WHERE AG_ID = @i AND ValType = 1 AND isVoid = 0 AND YEAR = @YEAR AND Month = @MONTH

SELECT @Pure_Salary = (@SALARY) +  (@T_OtherVal_ADD - @T_OtherVal_Neg)
SELECT @Inserted_Salary = (@SALARY - @T_LOAN) +  (@T_OtherVal_ADD - @T_OtherVal_Neg)


IF (SELECT T_ID FROM Agents_Balance_MV WHERE BsType_ID = 5 AND AG_ID = @i 
And YEAR = @YEAR and Month = @MONTH AND isDepended = 1 AND isVoid = 0) IS NULL
BEGIN
   EXEC @T_ID = [AA_GET_MAX_Agents_Balance_MV]
INSERT INTO Agents_Balance_MV 
(T_ID,AG_ID,Receipt_Title,Date,PURE,BsType_ID,isDepended,User_ID,Year,Month)
VALUES
(@T_ID,@i,(' مرتب شهر '+ @Month_S + ' لسنة ' + @Year_S) ,@Salary_Date,@Pure_Salary,5,1,@USER_ID,@YEAR,@MONTH)
--EOMONTH(CONCAT(@YEAR , '-', @MONTH ,'-01'))

END

SELECT @i = MIN(AG_ID) FROM AGENTS_MENU_V  WHERE Type_ID = 4 AND is_Emp_Pause = 0 AND AG_ID > @i  AND DATE_START < DATEADD(MONTH, 1, DATEFROMPARTS(@Year, @Month, 1)); --AND YEAR(DATE_START) <= @YEAR  --AND MONTH(DATE_START) <= @MONTH 
END


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[EMP_Insert_Salaries]',16,1,'خطأ')
ROLLBACK
END CATCH
GO
