/****** Object:  StoredProcedure [dbo].[Exp_Static_SELECT]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Author,,Name>
-- Create date: Create Date,,>
-- Description:	Description,,>
-- =============================================
CREATE PROCEDURE  [dbo].[Exp_Static_SELECT]

AS
BEGIN

SELECT [EX_ID]
      ,CONVERT(DATE,[DATE]) AS DATE
      ,[EX_NAME]
      ,[COST]
      ,[QTY]
      ,[DEF_AGE]
      ,[is_Executed]
	  --,CASE WHEN (CONVERT(NUMERIC(18,3),[R_Cost])) < 0 THEN '0' END  AS [R_Cost]  
	  --,CASE WHEN (CONVERT(NUMERIC(18,3),[R_T_Cost])) < 0 THEN '0' END  AS [R_T_Cost]  
	  , ISNULL(CONVERT(NUMERIC(18,3),[R_Cost]),0) AS [R_Cost]  
	  ,ISNULL(CONVERT(NUMERIC(18,3),[R_T_Cost]),0)  AS [R_T_Cost]  
   
  FROM [dbo].[Exp_Details_T_V]

  UNION

  SELECT [EX_ID]
      ,CONVERT(DATE,[DATE]) AS DATE
      ,[EX_NAME]
      ,[COST]
      ,[QTY]
      ,[DEF_AGE]
      ,[is_Executed]
	  ,ISNULL(CONVERT(NUMERIC(18,3),[R_Cost]),0) AS [R_Cost]
	  ,ISNULL(CONVERT(NUMERIC(18,3),[R_T_Cost]),0) AS [R_T_Cost]
 
  FROM [dbo].[Exp_Details_T_V_2]


  ORDER BY [EX_NAME] ASC



END









