CREATE PROCEDURE [dbo].[FRM_Details_Insert] 
@IM_ID	int,
@U_ID	int,
@Pch_T_ID	int,
@Price	float,
@ST_ID INT,
@D_Vaild DATE = NULL,
@QYT	numeric(18, 2),
@Total	numeric(18, 2),
@NewSale numeric(18, 2) = NULL,	
@NewSaleByOne	numeric(18, 2)	= NULL,
@Min_SP_ByOne	numeric(18, 2) = NULL,
@Min_SP	numeric(18, 2)	= NULL,
@Barcode NVARCHAR(50) = NULL

AS
BEGIN TRY
BEGIN TRANSACTION

--AS
--BEGIN


declare @T_ID INT,@T_ID_2 INT,@ST_QTY NUMERIC(18,2),@U_Cargo NUMERIC(18,2),@Valid_ST NVARCHAR(30),@COST_By_One Numeric(18,3) , @i INT

SET @Valid_ST = @D_Vaild
IF @Valid_ST IS NULL BEGIN SET @Valid_ST ='' END

SELECT @U_Cargo = U_Cargo FROM Units WHERE U_ID = @U_ID
SELECT @ST_QTY = (U_Cargo * @QYT) FROM Units WHERE U_ID = @U_ID

EXEC @T_ID = [AA_GET_MAX_FRM_Details]
INSERT INTO FRM_Details(T_ID,Date,FRM_T_ID,IM_ID,ST_ID,U_ID,Price,D_Vaild,QYT,Total,NewSale,NewSaleByOne,U_Cargo,ST_QTY,isDepended,Min_SP,Min_SP_ByOne,Barcode)
Values                 (@T_ID,GETDATE(),@Pch_T_ID,@IM_ID,@ST_ID,@U_ID,@Price,@Valid_ST,@QYT,@Total,@NewSale,@NewSaleByOne,@U_Cargo,@ST_QTY,1,@Min_SP,@Min_SP_ByOne,@Barcode)
--SELECT @T_ID = SCOPE_IDENTITY();

EXEC Inc_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY    
SET @QYT = @QYT * @U_Cargo

--EXEC @T_ID_2 = [AA_GET_MAX_FRM_Contents_Details]
INSERT INTO [dbo].[FRM_Contents_Details]
           ([Bill_T_ID]
		   ,[FRM_IM_T_ID]
		   ,[DATE]
           ,[IM_ID]
           ,[U_ID]
           ,[ST_ID]
		   ,[D_Vaild]
           ,[Cost]
           ,[QYT]
           ,[U_Cargo]
           ,[ST_QTY]
           ,[isDepended]
		   ,[Barcode])

    SELECT @Pch_T_ID,@T_ID,GETDATE(),FRM_IM_ID,U_ID,@ST_ID,'',CostVQty,(Qty * @QYT),U_Cargo,(U_CARGO * (Qty * @QYT))
	,1,Barcode FROM IM_Formating_Menu_V
	WHERE IM_ID  = @IM_ID

	select @COST_By_One =  ISNULL(SUM(CostVQty),0) FROM IM_Formating_Menu_V WHERE IM_ID = @IM_ID

	UPDATE FRM_Details SET PRICE = @COST_By_One , TOTAL = @COST_By_One * QYT WHERE T_ID = @T_ID 
          

		   exec Recalculate_Agent_Bill_Total @Pch_T_ID
              
--SELECT @i = min(T_ID) From FRM_Contents_Details WHERE FRM_IM_T_ID = @T_ID
--WHILE @i IS NOT NULL
--BEGIN

--SELECT @IM_ID=IM_ID,@Valid_ST='',@ST_ID = ST_ID,@ST_QTY = ST_QTY
--FROM FRM_Contents_Details WHERE T_ID = @i
--EXEC Dec_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY
--SELECT @i = min(T_ID) From FRM_Contents_Details WHERE FRM_IM_T_ID = @T_ID AND T_ID > @i

--END  







COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = ' [FRM_Details_Insert] ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH













