/****** Object:  StoredProcedure [dbo].[FRM_Manual_Details_Insert]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[FRM_Manual_Details_Insert] 
@IM_ID	int,
@U_ID	int,
@Pch_T_ID	int,
@Price	float,

@ST_ID INT,
@D_Vaild DATE = NULL,
@QYT	numeric(18, 2),
@Total	numeric(18, 3),
@NewSale numeric(18, 3) = NULL,	
@NewSaleByOne	numeric(18, 3)	= NULL,
@is_Product bit ,
@Current_QTY numeric(18, 2)	= NULL,
@Min_SP_ByOne	numeric(18, 3) = NULL,
@Min_SP	numeric(18, 3)	= NULL,
@Barcode NVARCHAR(50),
@is_Not_Qty	int	= 0
AS
BEGIN TRY
BEGIN TRANSACTION 

--AS
--BEGIN


declare @T_ID INT,@ST_QTY NUMERIC(18,2),@U_Cargo NUMERIC(18,2),@Valid_ST NVARCHAR(30),@COST FLOAT , @i INT

SET @Valid_ST = @D_Vaild


IF @Valid_ST IS NULL 
BEGIN 
SET @Valid_ST ='' 
END


SELECT @U_Cargo = U_Cargo FROM Units WHERE U_ID = @U_ID
SELECT @ST_QTY = (U_Cargo * @QYT) FROM Units WHERE U_ID = @U_ID


SET @COST = @Price



if @is_Product = 1
BEGIN

EXEC @T_ID = AA_GET_MAX_FRM_Details
INSERT INTO FRM_Details(T_ID,Date,FRM_T_ID,IM_ID,ST_ID,U_ID,Price,D_Vaild,QYT,Total,NewSale,NewSaleByOne,U_Cargo,ST_QTY,isDepended,Min_SP,Min_SP_ByOne,Barcode)
Values                 (@T_ID,GETDATE(),@Pch_T_ID,@IM_ID,@ST_ID,@U_ID,@Price,@Valid_ST,@QYT,@Total,@NewSale,@NewSaleByOne,@U_Cargo,@ST_QTY,1,@Min_SP,@Min_SP_ByOne,@Barcode)
--EXEC Inc_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY  
END

  ELSE BEGIN
INSERT INTO [dbo].[FRM_Contents_Details]
           ([Bill_T_ID]
		   ,[FRM_IM_T_ID]
		   ,[DATE]
           ,[IM_ID]
           ,[U_ID]
           ,[ST_ID]
           ,[Cost]
		   ,[D_Vaild]
           ,[QYT]
           ,[U_Cargo]
           ,[ST_QTY]
           ,[isDepended]
		   ,[Barcode]
		   ,[is_Not_Qty])
		   VALUES(@Pch_T_ID,NULL,GETDATE(),@IM_ID,@U_ID,@ST_ID,(@COST * @U_Cargo),@Valid_ST,@QYT,@U_Cargo,@ST_QTY,1,@Barcode,@is_Not_Qty)
		   --EXEC Dec_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY  
		   END          
		   
EXEC FRM_Manual_Set_Cost @Pch_T_ID	                                              

   exec Recalculate_Agent_Bill_Total @Pch_T_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = '[FRM_Manual_Details_Insert] ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH

--END












GO
/****** Object:  StoredProcedure [dbo].[Frm_Manual_IM_Unit_Change]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Frm_Manual_IM_Unit_Change] 
@IM_T_ID int,
@U_ID int,
@QTY Numeric(18,2) = NULL,
@Price FLOAT,

@NewSale numeric(18, 3) = NULL,	
@NewSaleByOne	numeric(18, 3)	= NULL
AS
DECLARE @Bill_T_ID INT,@U_Cargo NUMERIC(18,2),@IM_ID INT,@ST_ID int ,@D_Valid NVARCHAR(20) = '' , @NEW_ST_QTY FLOAT , @PREV_ST_QTY FLOAT
,@ST_QTY_DEF FLOAT = 0
BEGIN TRY
BEGIN TRANSACTION 


SELECT @IM_ID  = IM_ID,@Bill_T_ID = FRM_T_ID , @ST_ID = ST_ID , @D_Valid = D_Vaild FROM FRM_Details WHERE T_ID = @IM_T_ID
IF @Price IS NULL BEGIN SELECT @Price = PRICE FROM IM_Menu_Units_V WHERE U_ID = @U_ID AND IM_ID = @IM_ID  END
SELECT @U_Cargo = U_Cargo FROM IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_ID = @U_ID
SELECT @PREV_ST_QTY = ST_QTY FROM FRM_Details WHERE T_ID = @IM_T_ID


IF @QTY IS NULL
BEGIN
SELECT @NEW_ST_QTY = QYT FROM FRM_Details WHERE T_ID = @IM_T_ID 
SELECT @NEW_ST_QTY = (@NEW_ST_QTY * @U_Cargo)
UPDATE FRM_Details  SET U_ID=@U_ID,Price=@Price, Total = (@Price * QYT) , U_Cargo = @U_Cargo , ST_QTY = @NEW_ST_QTY 

 WHERE T_ID = @IM_T_ID
 END
 ELSE
 BEGIN
 SELECT @NEW_ST_QTY = (@U_Cargo * @QTY) 
 UPDATE FRM_Details SET U_ID=@U_ID , QYT=@QTY , Price=@Price , Total = (@Price * @QTY) 
 , U_Cargo = @U_Cargo , ST_QTY = @NEW_ST_QTY
 WHERE T_ID = @IM_T_ID
 END


 UPDATE FRM_Details SET U_ID=@U_ID , QYT=@QTY , Price=@Price , Total = (@Price * @QTY) , U_Cargo = @U_Cargo , ST_QTY = (@U_Cargo * @QTY) 
, NewSale = @NewSale , NewSaleByOne = @NewSaleByOne WHERE T_ID = @IM_T_ID


SELECT @ST_QTY_DEF = (@NEW_ST_QTY - @PREV_ST_QTY)
 EXEC Inc_IM_QTY @IM_ID,@ST_ID,@D_Valid,@ST_QTY_DEF


 EXEC FRM_Manual_Set_Cost @Bill_T_ID                                                                     



COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[Frm_Manual_IM_Unit_Change]',16,1,'خطأ')
ROLLBACK
END CATCH












GO
