GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[FRM_Manual_MOVE_FROM_SB] 
@SB_T_ID	int,
@FRM_T_ID INT,
@is_Not_Qty INT,
@TYPE NVARCHAR(50)
AS
BEGIN TRY
BEGIN TRANSACTION 

IF @TYPE = 'FRM_Contents_Details'
BEGIN

INSERT INTO [dbo].[FRM_Contents_Details]
           ([Bill_T_ID]
		   ,[FRM_IM_T_ID]
		   ,[DATE]
           ,[IM_ID]
           ,[U_ID]
           ,[ST_ID]
           ,[Cost]
		   ,[D_Vaild]
           ,[QYT]
           ,[U_Cargo]
		   ,[ST_QTY]
		   ,[isDepended]
           ,[Barcode]
		   ,[is_Not_Qty])

	SELECT
	   @FRM_T_ID
	   ,NULL
	   ,[Date]
	   ,[IM_ID]    
      ,[U_ID]
      ,[ST_ID]
      ,[Price]
      ,[D_Vaild]
      ,[QTY]
	  ,[U_Cargo]
	  ,[ST_QTY]
	  ,1
	  ,[Barcode]
	  ,@is_Not_Qty

  FROM [dbo].[SB_Contents] WHERE Bill_T_ID = @SB_T_ID


  EXEC FRM_Manual_Set_Cost @FRM_T_ID	


  END
  ELSE
  BEGIN


  	  ---------------------------------------------------------------------------------
	  DECLARE @i int , @T_ID INT
	  SELECT @i = MIN(T_ID) FROM [dbo].[SB_Contents] WHERE Bill_T_ID = @SB_T_ID
	  WHILE @i IS NOT NULL
	  BEGIN

	  EXEC @T_ID =  AA_GET_MAX_ID 'FRM_Details'

	  INSERT INTO [dbo].[FRM_Details]
           ([T_ID]
           ,[Date]
           ,[FRM_T_ID]
           ,[IM_ID]
           ,[U_ID]
           ,[ST_ID]
           ,[Price]
           ,[D_Vaild]
           ,[QYT]
           ,[Total]
           ,[U_Cargo]
           ,[ST_QTY]
           ,[isDepended]
           ,[Barcode])

		SELECT
	    @T_ID
	   ,GETDATE()
	   ,@FRM_T_ID
	   ,[IM_ID]    
      ,[U_ID]
      ,[ST_ID]
      ,[Price]
      ,[D_Vaild]
      ,[QTY]
	  ,[T_Price]
	  ,[U_Cargo]
	  ,[ST_QTY]
	  ,1
	  ,[Barcode]

  FROM [dbo].[SB_Contents] WHERE T_ID = @i



	  SELECT @i = MIN(T_ID) FROM [dbo].[SB_Contents] WHERE Bill_T_ID = @SB_T_ID AND T_ID > @i
	  END

	  --------------------------------------------------------------------------------------------------
     
	 END

		   
                                              

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[FRM_Manual_MOVE_FROM_SB]',16,1,'خطأ')
ROLLBACK
END CATCH















GO
/****** Object:  StoredProcedure [dbo].[FRM_Manual_Set_Cost]    Script Date: 09/05/2026 16:40:13 ******/
