-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[FRM_Manual_Set_Cost] 
@T_ID	int
AS
BEGIN TRY
BEGIN TRANSACTION 

Declare @Sum_Costs FLOAT , @Cost_By_ONE FLOAT

SELECT @Sum_Costs = ISNULL(SUM(Total),0) FROM FRM_Contents_Manuel_V WHERE Frm_ID = @T_ID
SELECT @Cost_By_ONE = @Sum_Costs / ISNULL(SUM(QYT),1) FROM FRM_Details WHERE FRM_T_ID = @T_ID
UPDATE FRM_Details SET Price =  @Cost_By_ONE , Total = ( @Cost_By_ONE * QYT ) WHERE FRM_T_ID = @T_ID



COMMIT
END TRY
BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = '[FRM_Manual_Set_Cost] ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH










GO
/****** Object:  StoredProcedure [dbo].[FRM_Select_PERFET_By_Date]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FRM_Select_PERFET_By_Date] 
@D_F DATE,
@D_T DATE
AS 

BEGIN

SELECT '' AS ' ت ',b.DATE AS ' التاريخ ',b.SB_ID AS ' رقم الفاتورة ',Ag_name AS ' الزبون ' 
,(SELECT TOP 1 EMP_NAME FROM FRM_Info_V WHERE Travel_ID = b.T_ID AND isDepended = 1 AND isVoid = 0 )  AS ' الموظف '
,(SELECT CONVERT(money,ISNULL(sum(TOTAL),0)) from Agents_Balance_MV_V  WHERE  SB_ID = b.SB_ID  ) AS ' إجمالي الفاتورة'
,(SELECT CONVERT(money,ISNULL(sum(DISCOUNT),0)) from Agents_Balance_MV_V  WHERE  SB_ID = b.SB_ID  ) AS 'تخفيض الفاتورة'
,(SELECT CONVERT(money,ISNULL(sum(PURE),0)) from Agents_Balance_MV_V  WHERE  SB_ID = b.SB_ID  ) AS 'صافي الفاتورة'

--,(SELECT  CONVERT(money,ISNULL(sum(PURE),0)) from Agents_Balance_MV_V  where Travel_ID =  b.T_ID and  BsType_ID = 18   ) AS ' تكلفة تصنيع الفاتورة '
,(SELECT CONVERT(money,ISNULL(sum(TOTAL),0)) from FRM_Contents_Manuel_V where Frm_ID IN (SELECT T_ID FROM Agents_Balance_MV_V WHERE BsType_ID = 18  AND Travel_ID =  b.T_ID ) AND isDepended = 1 AND isStore = 1 )  AS ' تكلفة المواد الخام '
,(SELECT CONVERT(money,ISNULL(sum(TOTAL),0)) from FRM_Contents_Manuel_V where Frm_ID IN (SELECT T_ID FROM Agents_Balance_MV_V WHERE BsType_ID = 18  AND Travel_ID =  b.T_ID ) AND isDepended = 1 AND isStore = 0 )  AS ' تكلفة المصنعية '


,(SELECT CONVERT( money, ISNULL(sum(Cost),0) * ISNULL(sum(QTY),0) ) from SB_Contents where Bill_T_ID IN (SELECT T_ID FROM Agents_Balance_MV_V WHERE BsType_ID = 1  AND SB_ID = B.SB_ID ) AND isDepended = 1 )  AS ' تكلفة من المبيعات '


,(SELECT  CONVERT(money,ISNULL(sum(PURE),0)) from Agents_Balance_MV_V  where Travel_ID =  b.T_ID and  BsType_ID = 18  AND isDepended = 1 AND isVoid = 0  )
+
(SELECT CONVERT( money, ISNULL(sum(Cost),0) * ISNULL(sum(QTY),0) ) from SB_Contents where Bill_T_ID IN (SELECT T_ID FROM Agents_Balance_MV_V WHERE BsType_ID = 1  AND SB_ID = B.SB_ID ) AND isDepended = 1 ) 
AS ' إجمالي التكلفة '



,( (SELECT CONVERT(money,ISNULL(sum(PURE),0)) from Agents_Balance_MV_V  WHERE  SB_ID = b.SB_ID  )
- (SELECT  CONVERT(money,ISNULL(sum(PURE),0)) from Agents_Balance_MV_V  where Travel_ID =  b.T_ID and  BsType_ID = 18  AND isDepended = 1 AND isVoid = 0  )  )
- (SELECT CONVERT( money, ISNULL(sum(Cost),0) * ISNULL(sum(QTY),0) ) from SB_Contents where Bill_T_ID IN (SELECT T_ID FROM Agents_Balance_MV_V WHERE BsType_ID = 1  AND SB_ID = B.SB_ID ) AND isDepended = 1 )
  AS 'ربح الفاتورة'
FROM SB_Info_V b  WHERE isDepended = 1 AND isVoid = 0 
AND  CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T 
ORDER BY DATE ASC



END


GO
/****** Object:  StoredProcedure [dbo].[GENERAL_REPORT_SELECT]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Author,,Name>
-- Create date: Create Date,,>
-- Description:	Description,,>
-- =============================================
CREATE PROCEDURE  [dbo].[GENERAL_REPORT_SELECT]
@D_F DATE,
@D_T DATE
AS
BEGIN

DECLARE @S_EXP_STATIC_1 Money , @S_EXP_STATIC_2 Money  , @S_EXP_STATIC_T Money
, @SUM_Credit Money , @SUM_SALES Money , @SUM_EXP Money , @SUM_SALARIES Money
,@SUM_Rtn_SB Money , @SUM_Rtn_Pch Money ,
@SUM_PCH Money , @IM_BERFET Money ,@AG_Credit Money,@Sum_Inside_Bill Money , @Sum_Outside_Bill Money
, @AG_DEBIT Money , @IM_EX Money 
,@SUM_DisCredit Money , @SUM_DisDEBIT Money, @SUM_DEBIT Money,@SUM_SB_Discount Money,@TOTAL_BERFET Money,@PURE_BERFET Money,@SUM_PCH_Discount Money
,@SUM_PURE_SB Money,@SUM_FRM Money,@SUM_ST_DEF_QTY MONEY,

@Desc01 Nvarchar(500), @Desc02 Nvarchar(500)
, @Desc04 Nvarchar(500), @Desc05 Nvarchar(500), @Desc06 Nvarchar(500), @Desc07 Nvarchar(500), @Desc08 Nvarchar(500)
, @Desc09 Nvarchar(500) , @Desc10 Nvarchar(500) , @Desc11 Nvarchar(500) , @Desc12 Nvarchar(500) , @Desc13 Nvarchar(500)
, @Desc16 Nvarchar(500) , @Desc17 Nvarchar(500) , @Desc18 Nvarchar(500) , @Desc19 Nvarchar(500) , @Desc20 Nvarchar(500)  
, @Desc21 Nvarchar(500) , @Desc22 Nvarchar(500),@Desc101 Nvarchar(500), @Desc23 Nvarchar(500) , @Desc24 Nvarchar(500) , @Desc25 Nvarchar(500)  


set @Desc01 = 'المصاريف التابثة , الأصول'
set @Desc02 = 'رأس المال , بضاعة المخازن'
set @Desc04 = ' المصروفات العامة'
set @Desc11 = 'المشتريات'
set @Desc10 = 'أذونات صرف'
set @Desc101 = 'أذونات إستلام'
set @Desc05 = 'بضاعة تالفه'
set @Desc06 = ' إجمالي المبيعات'
set @Desc07 = ' ربح المبيعات'
set @Desc08 = 'صافي المبيعات'
set @Desc09 = 'مرتبات الموظفين'

set @Desc12 = 'إرجاع مبيعات'
set @Desc13 = 'إرجاع مشتريات'
set @Desc23 = 'تخفيضات مشتريات'

set @Desc18 = 'إيصالات القبض'
set @Desc19 = 'إيصالات الصرف'

set @Desc20 = 'تخفيضات مبيعات'
set @Desc21 = 'مجمل الربح'
set @Desc22 = 'صافي الربح'
set @Desc24 = 'إستهلاك التصنيع'
set @Desc25 = 'عجز/فائض المخازن'
-------------------------------------------------------------------------


SELECT @S_EXP_STATIC_1 = ISNULL(SUM(CONVERT(Money, (CASE WHEN([R_T_Cost]) < 0 THEN '0' END) )),0)  FROM [dbo].[Exp_Details_T_V]
SELECT @S_EXP_STATIC_2 = ISNULL(SUM(CONVERT(Money,[R_T_Cost])),0) FROM [dbo].[Exp_Details_T_V_2]


SELECT @SUM_Credit = ISNULL(SUM(Pure),0) FROM Agents_Balance_MV_RCT WHERE  BsType_ID = 4 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SET @S_EXP_STATIC_T = @S_EXP_STATIC_1 + @S_EXP_STATIC_2
-----------------------------------------------------------
SELECT @SUM_SALES = ISNULL(SUM(TOTAL),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 1 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
--------------------------------------------------------------
SELECT @SUM_PURE_SB = ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 1 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SELECT @SUM_DEBIT = ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_RCT WHERE  BsType_ID = 3 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SELECT @SUM_PCH = ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 7 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SELECT @SUM_EXP = ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 2 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SELECT @SUM_SALARIES =  ISNULL(SUM(pure),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND  isVoid = 0 AND BsType_ID = 5 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --مرتبات الموظفين
----------------------------------------------------------
SELECT @IM_BERFET =   
(
  SELECT   ISNULL ( ( SUM(ISNULL(PRICE,0) * ISNULL(QTY,0)) ) ,0 )
  FROM SB_Contents where isDepended = 1 AND Bill_T_ID IN
   (  
  SELECT T_ID FROM Agents_Balance_MV_V WHERE isDepended = 1 AND BsType_ID = 1 and isVoid = 0 AND
  CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --سعر مبيعات
  )
)
-
(
  SELECT  ISNULL ( ( SUM(ISNULL(COST,0) * ISNULL(QTY,0)) ) ,0 )
  FROM SB_Contents where isDepended = 1 AND Bill_T_ID IN
   (  
  SELECT T_ID FROM Agents_Balance_MV_V WHERE isDepended = 1 AND BsType_ID = 1 and isVoid = 0 AND
  CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --تكلفة مبيعات
  )
)



-----------------------------------------------------------
SELECT @SUM_PCH_Discount = ISNULL(SUM(Discount),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 7 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SELECT @SUM_FRM =  ISNULL(SUM(TOTAL),0)  FROM FRM_CONTENTS_SUM_ONLY_STUCK_V where  CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --إستهلاك التصنيع


--------------------------------------------------------------------------------------------مجمل الربح
SELECT @TOTAL_BERFET =  ISNULL(SUM(Total),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 1 and isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --مبيعات
SELECT @TOTAL_BERFET -=  ISNULL(SUM(Discount),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --تحفيض
SELECT @TOTAL_BERFET -=  ISNULL(SUM(PURE),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 10 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --راجع

--ISNULL(SUM(Cost),0) * ISNULL(SUM(ST_QTY),0) 

----------------------------------------- حساب المشتريات
--SELECT @TOTAL_BERFET -=  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 7 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------


 SELECT  @TOTAL_BERFET -= ISNULL ( ( SUM(ISNULL(COST,0) * ISNULL(QTY,0)) ) ,0 )
  FROM SB_Contents where isDepended = 1 AND Bill_T_ID IN
   (  
  SELECT T_ID FROM Agents_Balance_MV_V WHERE isDepended = 1 AND BsType_ID = 1 and isVoid = 0 AND
  CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --تكلفة مبيعات
  )

SELECT @TOTAL_BERFET -=  @SUM_FRM--إستهلاك التصنيع


  SELECT @TOTAL_BERFET +=  ISNULL(SUM([T_Cost]),0) FROM [dbo].[IM_RtnPerfet_V] WHERE CONVERT(Date,DATE) BETWEEN @D_F AND @D_T  and BsType_ID = 10
-----------------------------------------------------------------------------------------/مجمل الربح



--------------------------------------------------------------------------------------------صافي الربح
SET @PURE_BERFET = @TOTAL_BERFET
SELECT @PURE_BERFET -=  ISNULL(SUM(Total),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 2 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --مصروفات

SELECT @PURE_BERFET -=  ISNULL(SUM(pure),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND  isVoid = 0 AND BsType_ID = 5 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --مرتبات الموظفين

SELECT @PURE_BERFET -=  ISNULL(SUM(Total),0)  FROM Agents_Balance_MV_V where isDepended = 1 And BsType_ID = 8 and isvoid  = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T  --تالف

-----------------------------------------------------------------------------------------/صافي الربح
	
	SELECT @SUM_ST_DEF_QTY =  SUM(ISNULL(Cost,0) *  ISNULL(ST_QTY,0) ) FROM ST_QTY_Deferences WHERE  CONVERT(Date,DATE) BETWEEN @D_F AND @D_T

-----------------------------------------------------------
SELECT @IM_EX =  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 8 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------------------
SELECT @Sum_Inside_Bill =  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 17 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
------------------------------------------------------------------------
SELECT @Sum_Outside_Bill =  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 35 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
--------------------------------------------------------------------------
SELECT @SUM_Rtn_SB  =  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 10 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
--------------------------------------------------------------------------
SELECT @SUM_Rtn_Pch  =  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 11 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
--------------------------------------------------------------------------
SELECT @SUM_SB_Discount = ISNULL(SUM(Discount),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 1 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------

  ----SELECT  1,@Desc06,  ISNULL(@SUM_SALES,0)   
  
  SELECT  1 AS 'ت',@Desc06 AS 'البيـــان',convert(varchar,FORMAT(@SUM_SALES,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
    UNION 
	SELECT  2 AS 'ت',@Desc20 AS 'البيـــان',convert(varchar,FORMAT(@SUM_SB_Discount,'###,###,###,##0.000','en-us')) AS 'القيمــة'   
  UNION
  SELECT  3 AS 'ت',@Desc08 AS 'البيـــان',convert(varchar,FORMAT(@SUM_PURE_SB,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  4 AS  'ت',@Desc12 AS 'البيـــان',convert(varchar,FORMAT(@SUM_Rtn_SB,'###,###,###,##0.000','en-us')) AS 'القيمــة'   
  UNION 
  SELECT  5 AS 'ت',@Desc07 AS 'البيـــان',convert(varchar,FORMAT(@IM_BERFET,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  6 AS 'ت',@Desc11 AS 'البيـــان',convert(varchar,FORMAT(@SUM_PCH,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  7 AS 'ت', @Desc13 AS 'البيـــان',convert(varchar,FORMAT(@SUM_Rtn_Pch,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  8 AS 'ت', @Desc23 AS 'البيـــان',convert(varchar,FORMAT(@SUM_PCH_Discount,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION 
  SELECT  9 AS 'ت',@Desc05 AS 'البيـــان',convert(varchar,FORMAT(@IM_EX,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  10 AS 'ت',@Desc01 AS 'البيـــان',convert(varchar,FORMAT(@S_EXP_STATIC_T,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  11 AS 'ت',@Desc10 AS 'البيـــان',convert(varchar,FORMAT(@Sum_Inside_Bill,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  12 AS 'ت',@Desc101 AS 'البيـــان',convert(varchar,FORMAT(@Sum_Outside_Bill,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  13 AS 'ت',@Desc04 AS 'البيـــان',convert(varchar,FORMAT(@SUM_EXP,'###,###,###,##0.000','en-us')) AS 'القيمــة'
   UNION
  SELECT  14 AS 'ت',@Desc09 AS 'البيـــان',convert(varchar,FORMAT(@SUM_SALARIES,'###,###,###,##0.000','en-us')) AS 'القيمــة' 
  UNION
  SELECT  15 AS 'ت',@Desc18 AS 'البيـــان',convert(varchar,FORMAT(@SUM_DEBIT ,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION 
  SELECT  16 AS 'ت',@Desc19 AS 'البيـــان',convert(varchar,FORMAT(@SUM_Credit ,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION 
  --SELECT  17,@Desc24,convert(varchar,FORMAT(@SUM_FRM ,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
    SELECT  17 AS 'ت',@Desc24 AS 'البيـــان',convert(varchar,FORMAT(@SUM_FRM ,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION 
  SELECT  18,@Desc25,convert(varchar,FORMAT(@SUM_ST_DEF_QTY ,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  --UNION
  --SELECT  16,@Desc09,convert(varchar,FORMAT(@AG_Credit,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  19 AS 'ت',@Desc21 AS 'البيـــان',convert(varchar,FORMAT(@TOTAL_BERFET,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
   UNION
  SELECT  20 AS 'ت',@Desc22 AS 'البيـــان',convert(varchar,FORMAT(@PURE_BERFET,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  
   

END







GO
/****** Object:  StoredProcedure [dbo].[GENERAL_REPORT_SELECT_2]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Author,,Name>
-- Create date: Create Date,,>
-- Description:	Description,,>
-- =============================================
CREATE PROCEDURE  [dbo].[GENERAL_REPORT_SELECT_2]
AS
BEGIN

DECLARE
@SUM_ST Money
,@TR_BALANCE Money, @TOTAL_Credit Money
,@SUM_INVOICE_FIRST Money , @SUM_INVOICE_LAST Money
,@SUM_Tr_FirstTime Money,@TOTAL_FIRST_TIME Money , @TOTAL_LAST_TIME Money,

  @Desc03 Nvarchar(500)
, @Desc18 Nvarchar(500), @Desc14 Nvarchar(500) , @Desc15 Nvarchar(500) ,@Desc08 Nvarchar(500), @Desc09 Nvarchar(500)
, @Desc19 Nvarchar(500) , @Desc20 Nvarchar(500) , @Desc21 Nvarchar(500), @Desc22 Nvarchar(500)
, @AG_Credit Money, @AG_DEBIT Money

-------------------------------------------------------------------------
set @Desc14 = 'جرد أول مدة'
set @Desc15 = 'جرد أخر مدة'

set @Desc18 = 'أرصدة الخزائن أول مدة'
set @Desc03 = 'أرصدة الخزائن أخر مدة'

SET @Desc19 = 'إجمالي رصيد أول مدة'
SET @Desc20 = 'إجمالي رصيد أخر مدة'

SET @Desc21 = 'الربح والخسارة'
SET @Desc22 = 'إجمالي فرق الديون'

set @Desc08 = 'ديون عليك'
set @Desc09 = 'ديون لك'



----------------------------------------------------------
SELECT @AG_DEBIT = SUM(T_Balance) FROM AGENTS_MENU_V WHERE T_Balance > 0
----------------------------------------------------------
SELECT @AG_Credit = SUM(T_Balance) * -1  FROM AGENTS_MENU_V WHERE T_Balance < 0 
-------------------------------------------------------------------------
SELECT @SUM_ST = ISNULL(SUM(T_Cost),0) FROM IM_STORE_View
-------------------------------------------------------------------------
SELECT @TR_BALANCE = ISNULL(SUM(T_Balance),0) FROM TR_MENU_V
-------------------------------------------------------------------------
SELECT @SUM_INVOICE_FIRST  = ISNULL(SUM(Pure),0) FROM Agents_Balance_MV_V WHERE  isDepended = 1 AND isVoid = 0 AND Invoice_Type = 0
-------------------------------------------------------------------------
SELECT @SUM_INVOICE_LAST  = ISNULL(SUM(Pure),0) FROM Agents_Balance_MV_V WHERE isDepended = 1 AND isVoid = 0 AND Invoice_Type = 1
-------------------------------------------------------------------------
SELECT @SUM_Tr_FirstTime  = ( ISNULL(SUM(Credit),0) + ISNULL(SUM(DEBIT),0)  ) FROM Treasury_Balance_MV  WHERE  isVoid = 0 And isFirst_Time = 1
-------------------------------------------------------------------------
SELECT @TOTAL_Credit  = ISNULL(SUM(T_Balance),0) FROM AGENTS_MENU_V

SET @TOTAL_FIRST_TIME = @SUM_INVOICE_FIRST + @SUM_Tr_FirstTime

SET @TOTAL_LAST_TIME = @SUM_ST + @TR_BALANCE
 
  -------------------------------------------------------------------------
  SELECT  1,@Desc08,convert(varchar,FORMAT(@AG_DEBIT,'###,###,###,##0.000','en-us'))     
  UNION
  SELECT  2,@Desc09, convert(varchar,FORMAT(@AG_Credit,'###,###,###,##0.000','en-us'))    
  UNION
  SELECT  3,@Desc22, convert(varchar,FORMAT(@TOTAL_Credit,'###,###,###,##0.000','en-us'))    
   UNION
  SELECT  4,@Desc14, convert(varchar,FORMAT(@SUM_INVOICE_FIRST,'###,###,###,##0.000','en-us'))  
   UNION 
   SELECT 5,@Desc15, convert(varchar,FORMAT(@SUM_ST,'###,###,###,##0.000','en-us'))
   UNION 
  SELECT  6,@Desc18, convert(varchar,FORMAT( @SUM_Tr_FirstTime ,'###,###,###,##0.000','en-us'))
   UNION
  SELECT  7,@Desc03, convert(varchar,FORMAT( @TR_BALANCE ,'###,###,###,##0.000','en-us'))
   UNION 
  SELECT  8,@Desc19, convert(varchar,FORMAT( @TOTAL_FIRST_TIME ,'###,###,###,##0.000','en-us'))
  UNION
  SELECT  9,@Desc20, convert(varchar,FORMAT( @TOTAL_LAST_TIME ,'###,###,###,##0.000','en-us'))



END






GO
/****** Object:  StoredProcedure [dbo].[GENERAL_REPORT_SELECT_3]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Author,,Name>
-- Create date: Create Date,,>
-- Description:	Description,,>
-- =============================================
CREATE PROCEDURE  [dbo].[GENERAL_REPORT_SELECT_3]
@TOTAL_BALANCE Money OUTPUT,
@TOTAL_FIRST_TIME Money OUTPUT,
@TOTAL_LAST_TIME Money OUTPUT,
@TOTAL_DEBIT Money OUTPUT
AS 
BEGIN

DECLARE @SUM_ST Money,@TR_BALANCE Money,@SUM_INVOICE_FIRST Money ,
@SUM_Tr_FirstTime Money,@Desc03 Nvarchar(500), @Desc14 Nvarchar(500) , @Desc15 Nvarchar(500)
,@Desc18 Nvarchar(500),@Desc19 Nvarchar(500) , @Desc20 Nvarchar(500), @Desc21 Nvarchar(500)

--------------------------------------------------------------------------
set @Desc14 = 'جرد أول مدة'
set @Desc15 = 'جرد أخر مدة'

set @Desc18 = 'أرصدة الخزائن أول مدة'
set @Desc03 = 'أرصدة الخزائن أخر مدة'

SET @Desc19 = 'إجمالي رصيد أول مدة'
SET @Desc20 = 'إجمالي رصيد أخر مدة'
SET @Desc21 = 'إجمالي فرق الديون'

--------------------------------------------------------------------------
SELECT @SUM_ST = ISNULL(SUM(T_Cost),0) FROM IM_STORE_View
--------------------------------------------------------------------------
SELECT @TR_BALANCE = ISNULL(SUM(T_Balance),0) FROM TR_MENU_V
--------------------------------------------------------------------------
SELECT @SUM_INVOICE_FIRST  = ISNULL(SUM(PURE),0) FROM Agents_Balance_MV WHERE  BsType_ID = 9 AND isDepended = 1 AND isVoid = 0 AND Invoice_Type = 0
--------------------------------------------------------------------------
SELECT @SUM_Tr_FirstTime  = ISNULL(SUM(PURE),0) FROM Treasury_Balance_MV WHERE isVoid = 0 And isFirst_Time = 1
--------------------------------------------------------------------------
SELECT @TOTAL_DEBIT  = ISNULL(SUM(T_Balance),0) FROM AGENTS_MENU_V


SET @TOTAL_FIRST_TIME = @SUM_INVOICE_FIRST + @SUM_Tr_FirstTime

SET @TOTAL_LAST_TIME = @SUM_ST + @TR_BALANCE
 
  SET  @TOTAL_BALANCE = ( ISNULL(@TOTAL_LAST_TIME,0) - ISNULL(@TOTAL_FIRST_TIME ,0) )
  
  SELECT @TOTAL_BALANCE
END






GO
/****** Object:  StoredProcedure [dbo].[GENERAL_REPORT_SELECT_NEW]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE  [dbo].[GENERAL_REPORT_SELECT_NEW]
    @D_F DATE,
    @D_T DATE
AS
BEGIN

    /* ============================
       متغيرات التقرير الأساسية
    ============================ */

    DECLARE
        @S_EXP_STATIC_1 Money , @S_EXP_STATIC_2 Money  , @S_EXP_STATIC_T Money,
        @SUM_Credit Money , @SUM_SALES Money , @SUM_EXP Money , @SUM_SALARIES Money , @DISC_PCH MONEY,
        @SUM_Rtn_SB Money , @SUM_Rtn_Pch Money , @SUM_PCH_TOTAL Money,
        @IM_BERFET Money , @AG_Credit Money, @Sum_Inside_Bill Money , @Sum_Outside_Bill Money,
        @AG_DEBIT Money , @IM_EX Money,
        @SUM_DEBIT Money, @SUM_SB_Discount Money, @TOTAL_BERFET Money, @PURE_BERFET Money, @SUM_PCH_Discount Money,
        @SUM_PURE_SB Money, @SUM_FRM Money, @SUM_ST_DEF_QTY MONEY,

        @Desc01 Nvarchar(500), @Desc02 Nvarchar(500),
        @Desc04 Nvarchar(500), @Desc05 Nvarchar(500), @Desc06 Nvarchar(500), @Desc07 Nvarchar(500), @Desc08 Nvarchar(500),
        @Desc09 Nvarchar(500), @Desc10 Nvarchar(500), @Desc11 Nvarchar(500), @Desc12 Nvarchar(500), @Desc13 Nvarchar(500),
        @Desc16 Nvarchar(500), @Desc17 Nvarchar(500), @Desc18 Nvarchar(500), @Desc19 Nvarchar(500), @Desc20 Nvarchar(500),
        @Desc21 Nvarchar(500), @Desc22 Nvarchar(500), @Desc101 Nvarchar(500), @Desc23 Nvarchar(500), @Desc24 Nvarchar(500), @Desc25 Nvarchar(500);

    /* ============================
       عناوين العرض
    ============================ */

    set @Desc01 = 'المصاريف التابثة , الأصول'
    set @Desc02 = 'رأس المال , بضاعة المخازن'
    set @Desc04 = ' المصروفات العامة'
    set @Desc11 = 'إجمالي المشتريات'
    set @Desc10 = 'أذونات صرف'
    set @Desc101 = 'أذونات إستلام'
    set @Desc05 = 'بضاعة تالفه'
    set @Desc06 = ' إجمالي المبيعات'
    set @Desc07 = ' ربح المبيعات'
    set @Desc08 = 'صافي المبيعات'
    set @Desc09 = 'مرتبات الموظفين'
    set @Desc12 = 'إرجاع مبيعات'
    set @Desc13 = 'إرجاع مشتريات'
    set @Desc23 = 'تخفيضات مشتريات'
    set @Desc18 = 'إيصالات القبض'
    set @Desc19 = 'إيصالات الصرف'
    set @Desc20 = 'تخفيضات مبيعات'
    set @Desc21 = 'مجمل الربح'
    set @Desc22 = 'صافي الربح'
    set @Desc24 = 'إستهلاك التصنيع'
    set @Desc25 = 'عجز/فائض المخازن'

    /* ============================
       1) قيم المبيعات والمشتريات والمصاريف
       (نفس مصادر بياناتك)
    ============================ */

    -- إجمالي إيصالات الصرف
    SELECT @SUM_Credit = ISNULL(SUM(Pure),0)
    FROM Agents_Balance_MV_RCT
    WHERE BsType_ID = 4 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- إجمالي المبيعات
    SELECT @SUM_SALES = ISNULL(SUM(TOTAL),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 1 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- تخفيضات المبيعات
    SELECT @SUM_SB_Discount = ISNULL(SUM(Discount),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 1 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- صافي المبيعات (مبدئيًا من PURE كما عندك)
    SELECT @SUM_PURE_SB = ISNULL(SUM(PURE),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 1 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- إرجاع مبيعات
    SELECT @SUM_Rtn_SB = ISNULL(SUM(PURE),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 10 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- تأكيد صافي المبيعات الفعلي:
    -- إذا PURE عند البيع = صافي الفاتورة بعد الخصم -> نطرح منه راجع المبيعات فقط
    SET @SUM_PURE_SB = ISNULL(@SUM_PURE_SB,0) - ISNULL(@SUM_Rtn_SB,0);

    -- إجمالي إيصالات القبض
    SELECT @SUM_DEBIT = ISNULL(SUM(PURE),0)
    FROM Agents_Balance_MV_RCT
    WHERE BsType_ID = 3 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- إجمالي المشتريات
    SELECT @SUM_PCH_TOTAL = ISNULL(SUM(TOTAL),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 7 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- تخفيضات مشتريات
    SELECT @DISC_PCH = ISNULL(SUM(Discount),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 7 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- ✅ تصحيح: كنت تطبع @SUM_PCH_Discount بدون تعبئة
    SET @SUM_PCH_Discount = ISNULL(@DISC_PCH,0);

    -- إرجاع مشتريات
    SELECT @SUM_Rtn_Pch = ISNULL(SUM(PURE),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 11 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- المصروفات العامة
    SELECT @SUM_EXP = ISNULL(SUM(PURE),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 2 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- المرتبات
    SELECT @SUM_SALARIES = ISNULL(SUM(PURE),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 5 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- التالف
    SELECT @IM_EX = ISNULL(SUM(PURE),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 8 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- أذونات صرف / استلام
    SELECT @Sum_Inside_Bill = ISNULL(SUM(PURE),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 17 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    SELECT @Sum_Outside_Bill = ISNULL(SUM(PURE),0)
    FROM Agents_Balance_MV_V
    WHERE BsType_ID = 35 AND isDepended = 1 AND isVoid = 0
      AND CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- استهلاك التصنيع (يبقى للعرض فقط ولا يدخل في مجمل الربح)
    SELECT @SUM_FRM = ISNULL(SUM(TOTAL),0)
    FROM FRM_CONTENTS_SUM_ONLY_STUCK_V
    WHERE CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    -- عجز/فائض المخازن (يبقى للعرض فقط)
    SELECT @SUM_ST_DEF_QTY = ISNULL(SUM(ISNULL(Cost,0) * ISNULL(ST_QTY,0)),0)
    FROM ST_QTY_Deferences
    WHERE CONVERT(date,[Date]) BETWEEN @D_F AND @D_T;

    /* ============================
       2) حساب مجمل الربح بالطريقة المعتمدة:
          COGS = Opening + NetPurchases - Closing
          Gross = NetSales - COGS
    ============================ */

    DECLARE @OPEN_STOCK MONEY, @CLOSE_STOCK MONEY, @NET_PURCHASES MONEY, @COGS MONEY;

    /* ⚠️ ملاحظة: هذه مصادر الجرد كما عندك (بدون فلترة تاريخية)
       إذا عندك جداول جرد بتاريخ أول/آخر فترة، نقدر نربطها لاحقًا */
    SELECT @OPEN_STOCK = ISNULL(SUM(Pure),0)
    FROM Agents_Balance_MV_V
    WHERE isDepended = 1 AND isVoid = 0 AND Invoice_Type = 0;

    SELECT @CLOSE_STOCK = ISNULL(SUM(AMOUNT),0) FROM STORES_MV_BALANCES_V WHERE  DATE < @D_T
-- ISNULL(SUM(T_Cost),0)FROM IM_STORE_View;

    -- صافي المشتريات = مشتريات - راجع مشتريات - تخفيض مشتريات
    SET @NET_PURCHASES =
        ISNULL(@SUM_PCH_TOTAL,0)
      - ISNULL(@SUM_Rtn_Pch,0)
      - ISNULL(@SUM_PCH_Discount,0);

    SET @COGS = ISNULL(@OPEN_STOCK,0) + ISNULL(@NET_PURCHASES,0) - ISNULL(@CLOSE_STOCK,0);

    -- ✅ مجمل الربح المعتمد
    SET @TOTAL_BERFET = ISNULL(@SUM_PURE_SB,0) - ISNULL(@COGS,0);

    -- ربح المبيعات (للعرض) نجعله مساويًا للمجمل حتى لا يتعارض مع التقرير
    --SET @IM_BERFET = @TOTAL_BERFET;

    /* ============================
       3) صافي الربح المعتمد:
          Net = Gross - Expenses - Salaries - Damaged
    ============================ */

    SET @PURE_BERFET = ISNULL(@TOTAL_BERFET,0)
                     - ISNULL(@SUM_EXP,0)
                     - ISNULL(@SUM_SALARIES,0)
                     - ISNULL(@IM_EX,0);

    /* ============================
       4) تقرير الذمم / الخزائن / الجرد (نفس مخرجاتك)
    ============================ */

    DECLARE
        @SUM_ST Money,
        @TR_BALANCE Money, @TOTAL_Credit Money,
        @SUM_INVOICE_FIRST Money,
        @SUM_Tr_FirstTime Money, @TOTAL_FIRST_TIME Money, @TOTAL_LAST_TIME Money,
        @Desc033 Nvarchar(500),
        @Desc188 Nvarchar(500), @Desc144 Nvarchar(500), @Desc155 Nvarchar(500), @Desc088 Nvarchar(500), @Desc099 Nvarchar(500),
        @Desc199 Nvarchar(500), @Desc200 Nvarchar(500), @Desc222 Nvarchar(500);

    set @Desc144 = 'جرد أول مدة'
    set @Desc155 = 'جرد أخر مدة'
    set @Desc188 = 'أرصدة الخزائن أول مدة'
    set @Desc033 = 'أرصدة الخزائن أخر مدة'
    SET @Desc199 = 'إجمالي رصيد أول مدة'
    SET @Desc200 = 'إجمالي رصيد أخر مدة'
    SET @Desc222 = 'إجمالي فرق الديون'
    set @Desc088 = 'ديون عليك'
    set @Desc099 = 'ديون لك'

    -- ديون عليك / لك (كما عندك)
    SELECT @AG_DEBIT  = ISNULL(SUM(T_Balance),0) FROM AGENTS_MENU_V WHERE T_Balance > 0;
    SELECT @AG_Credit = ISNULL(SUM(T_Balance),0) * -1 FROM AGENTS_MENU_V WHERE T_Balance < 0;

    -- جرد آخر مدة (كما عندك)
    --SELECT @SUM_ST = ISNULL(SUM(T_Cost),0) FROM IM_STORE_View;
	SELECT @SUM_ST = @CLOSE_STOCK

    -- أرصدة خزائن آخر مدة (كما عندك)
    SELECT @TR_BALANCE = ISNULL(SUM(T_Balance),0) FROM TR_MENU_V;

    -- جرد أول مدة (كما عندك)
    --SELECT @SUM_INVOICE_FIRST = ISNULL(SUM(Pure),0)
    --FROM Agents_Balance_MV_V
    --WHERE isDepended = 1 AND isVoid = 0 AND Invoice_Type = 0;

	SELECT @SUM_INVOICE_FIRST = ISNULL(SUM(AMOUNT),0) FROM STORES_MV_BALANCES_V WHERE  DATE < @D_F


    -- خزائن أول مدة
    SELECT @SUM_Tr_FirstTime = (ISNULL(SUM(Credit),0) + ISNULL(SUM(DEBIT),0))
    FROM Treasury_Balance_MV
    WHERE isVoid = 0 AND isFirst_Time = 1;

    -- إجمالي فرق الديون
    SELECT @TOTAL_Credit = ISNULL(SUM(T_Balance),0) FROM AGENTS_MENU_V;

    SET @TOTAL_FIRST_TIME = ISNULL(@SUM_INVOICE_FIRST,0) + ISNULL(@SUM_Tr_FirstTime,0);
    SET @TOTAL_LAST_TIME  = ISNULL(@SUM_ST,0) + ISNULL(@TR_BALANCE,0);

    -- ✅ المخرجات الأولى (كما عندك)
	SELECT  1 AS 'ت',
        @Desc088 AS 'البيـــان',
        convert(varchar,FORMAT(@AG_DEBIT,'###,###,###,##0.000','en-us')) AS 'القيمــة',
        N'إجمالي المبالغ التي على المحل دفعها للغير ولم يتم سدادها حتى الآن.' AS Description
UNION ALL
SELECT  2 AS 'ت',
        @Desc099 AS 'البيـــان',
        convert(varchar,FORMAT(@AG_Credit,'###,###,###,##0.000','en-us')) AS 'القيمــة',
        N'إجمالي المبالغ المستحقة للمحل لدى العملاء ولم يتم تحصيلها بعد.' AS Description
UNION ALL
SELECT  3 AS 'ت',
        @Desc222 AS 'البيـــان',
        convert(varchar,FORMAT(@TOTAL_Credit,'###,###,###,##0.000','en-us')) AS 'القيمــة',
        N'الفرق الصافي بين الديون المستحقة للمحل والديون المستحقة عليه.' AS Description
UNION ALL
SELECT  4 AS 'ت',
        @Desc144 AS 'البيـــان',
        convert(varchar,FORMAT(@SUM_INVOICE_FIRST,'###,###,###,##0.000','en-us')) AS 'القيمــة',
        N'قيمة البضاعة الموجودة في المخازن عند بداية الفترة المالية.' AS Description
UNION ALL
SELECT  5 AS 'ت',
        @Desc155 AS 'البيـــان',
        convert(varchar,FORMAT(@SUM_ST,'###,###,###,##0.000','en-us')) AS 'القيمــة',
        N'قيمة البضاعة المتبقية في المخازن عند نهاية الفترة المالية.' AS Description
UNION ALL
SELECT  6 AS 'ت',
        @Desc188 AS 'البيـــان',
        convert(varchar,FORMAT(@SUM_Tr_FirstTime,'###,###,###,##0.000','en-us')) AS 'القيمــة',
        N'إجمالي النقدية الموجودة في الخزائن عند بداية الفترة.' AS Description
UNION ALL
SELECT  7 AS 'ت',
        @Desc033 AS 'البيـــان',
        convert(varchar,FORMAT(@TR_BALANCE,'###,###,###,##0.000','en-us')) AS 'القيمــة',
        N'إجمالي النقدية الموجودة في الخزائن عند نهاية الفترة.' AS Description
UNION ALL
SELECT  8 AS 'ت',
        @Desc199 AS 'البيـــان',
        convert(varchar,FORMAT(@TOTAL_FIRST_TIME,'###,###,###,##0.000','en-us')) AS 'القيمــة',
        N'إجمالي قيمة الموجودات (مخزون + خزائن) عند بداية الفترة.' AS Description
UNION ALL
SELECT  9 AS 'ت',
        @Desc200 AS 'البيـــان',
        convert(varchar,FORMAT(@TOTAL_LAST_TIME,'###,###,###,##0.000','en-us')) AS 'القيمــة',
        N'إجمالي قيمة الموجودات (مخزون + خزائن) عند نهاية الفترة.' AS Description
 UNION ALL

 --   SELECT  1 AS 'ت',@Desc088 AS 'البيـــان', convert(varchar,FORMAT(@AG_DEBIT,'###,###,###,##0.000','en-us')) AS 'القيمــة' ,'' AS Description
 --   UNION ALL
 --   SELECT  2 AS 'ت',@Desc099 AS 'البيـــان', convert(varchar,FORMAT(@AG_Credit,'###,###,###,##0.000','en-us')) AS 'القيمــة','' AS Description
 --   UNION ALL
 --   SELECT  3 AS 'ت',@Desc222 AS 'البيـــان', convert(varchar,FORMAT(@TOTAL_Credit,'###,###,###,##0.000','en-us')) AS 'القيمــة','' AS Description
 --   UNION ALL
 --   SELECT  4 AS 'ت',@Desc144 AS 'البيـــان', convert(varchar,FORMAT(@SUM_INVOICE_FIRST,'###,###,###,##0.000','en-us')) AS 'القيمــة','' AS Description
 --   UNION ALL
 --   SELECT  5 AS 'ت',@Desc155 AS 'البيـــان', convert(varchar,FORMAT(@SUM_ST,'###,###,###,##0.000','en-us')) AS 'القيمــة','' AS Description
 --   UNION ALL
 --   SELECT  6 AS 'ت',@Desc188 AS 'البيـــان', convert(varchar,FORMAT(@SUM_Tr_FirstTime,'###,###,###,##0.000','en-us')) AS 'القيمــة','' AS Description
 --   UNION ALL
 --   SELECT  7 AS 'ت',@Desc033 AS 'البيـــان', convert(varchar,FORMAT(@TR_BALANCE,'###,###,###,##0.000','en-us')) AS 'القيمــة','' AS Description
 --   UNION ALL
 --   SELECT  8 AS 'ت',@Desc199 AS 'البيـــان', convert(varchar,FORMAT(@TOTAL_FIRST_TIME,'###,###,###,##0.000','en-us')) AS 'القيمــة','' AS Description
 --   UNION ALL
 --   SELECT  9 AS 'ت',@Desc200 AS 'البيـــان', convert(varchar,FORMAT(@TOTAL_LAST_TIME,'###,###,###,##0.000','en-us')) AS 'القيمــة','' AS Description

    /* ============================
       5) المخرجات الثانية (التقرير العام) - نفس ترتيبك
    ============================ */
	SELECT  1 AS 'ت',
        @Desc06 AS 'البيـــان',
        convert(varchar,FORMAT(@SUM_SALES,'###,###,###,##0.000','en-us')) AS 'القيمــة',
        N'إجمالي قيمة فواتير البيع خلال الفترة قبل الخصومات والإرجاع.' AS Description

UNION ALL
SELECT  2,
        @Desc20,
        convert(varchar,FORMAT(@SUM_SB_Discount,'###,###,###,##0.000','en-us')),
        N'مجموع الخصومات التي مُنحت للعملاء على فواتير البيع.'

UNION ALL
SELECT  3,
        @Desc08,
        convert(varchar,FORMAT(@SUM_PURE_SB,'###,###,###,##0.000','en-us')),
        N'المبيعات الفعلية بعد خصم التخفيضات وإرجاع المبيعات.'

UNION ALL
SELECT  4,
        @Desc12,
        convert(varchar,FORMAT(@SUM_Rtn_SB,'###,###,###,##0.000','en-us')),
        N'قيمة البضائع التي أعادها العملاء وتم خصمها من المبيعات.'

--UNION ALL
--SELECT  5,
--        @Desc07,
--        convert(varchar,FORMAT(@IM_BERFET,'###,###,###,##0.000','en-us')),
--        N'الربح الناتج من البيع بعد طرح تكلفة البضاعة المباعة.'

UNION ALL
SELECT  5,
        @Desc11,
        convert(varchar,FORMAT(@SUM_PCH_TOTAL,'###,###,###,##0.000','en-us')),
        N'إجمالي فواتير الشراء خلال الفترة قبل الخصومات والإرجاع.'

UNION ALL
SELECT  6,
        @Desc13,
        convert(varchar,FORMAT(@SUM_Rtn_Pch,'###,###,###,##0.000','en-us')),
        N'قيمة البضائع التي أُعيدت للموردين.'

UNION ALL
SELECT  7,
        @Desc23,
        convert(varchar,FORMAT(@SUM_PCH_Discount,'###,###,###,##0.000','en-us')),
        N'الخصومات التي حصل عليها المحل من الموردين.'

UNION ALL
SELECT  8,
        @Desc05,
        convert(varchar,FORMAT(@IM_EX,'###,###,###,##0.000','en-us')),
        N'قيمة البضاعة التالفة التي لا يمكن بيعها.'

UNION ALL
SELECT 9,
        @Desc10,
        convert(varchar,FORMAT(@Sum_Inside_Bill,'###,###,###,##0.000','en-us')),
        N'قيمة البضائع أو الأموال المصروفة بموجب أذونات صرف.'

UNION ALL
SELECT 10,
        @Desc101,
        convert(varchar,FORMAT(@Sum_Outside_Bill,'###,###,###,##0.000','en-us')),
        N'قيمة البضائع أو الأموال المستلمة بموجب أذونات استلام.'

UNION ALL
SELECT 11,
        @Desc04,
        convert(varchar,FORMAT(@SUM_EXP,'###,###,###,##0.000','en-us')),
        N'المصروفات التشغيلية العامة مثل الإيجار والكهرباء والخدمات.'

UNION ALL
SELECT 12,
        @Desc09,
        convert(varchar,FORMAT(@SUM_SALARIES,'###,###,###,##0.000','en-us')),
        N'إجمالي الرواتب المدفوعة للموظفين خلال الفترة.'

UNION ALL
SELECT 13,
        @Desc18,
        convert(varchar,FORMAT(@SUM_DEBIT,'###,###,###,##0.000','en-us')),
        N'المبالغ التي تم تحصيلها نقدًا أو عبر الخزينة.'

UNION ALL
SELECT 14,
        @Desc19,
        convert(varchar,FORMAT(@SUM_Credit,'###,###,###,##0.000','en-us')),
        N'المبالغ التي تم صرفها من الخزينة.'

UNION ALL
SELECT 15,
        @Desc24,
        convert(varchar,FORMAT(@SUM_FRM,'###,###,###,##0.000','en-us')),
        N'تكلفة المواد أو الموارد المستهلكة في عمليات التصنيع.'

UNION ALL
SELECT 16,
        @Desc25,
        convert(varchar,FORMAT(@SUM_ST_DEF_QTY,'###,###,###,##0.000','en-us')),
        N'الفرق الناتج عن الجرد الفعلي مقارنة بسجلات المخزون.'

UNION ALL
SELECT 17,
        @Desc21,
        convert(varchar,FORMAT(@TOTAL_BERFET,'###,###,###,##0.000','en-us')),
       N'تم احتساب مجمل الربح كالتالي:
(صافي المبيعات بعد الخصومات والإرجاع)
ناقص
(تكلفة البضاعة المباعة = جرد أول المدة + صافي المشتريات − جرد آخر المدة).
هذا المؤشر يوضح كفاءة البيع والتسعير.'

	   --N'الربح الناتج من النشاط التجاري الأساسي قبل خصم المصروفات.'

UNION ALL
SELECT 18,
        @Desc22,
        convert(varchar,FORMAT(@PURE_BERFET,'###,###,###,##0.000','en-us')),
		N'تم احتساب صافي الربح على النحو التالي:
أولًا: حساب مجمل الربح من المبيعات.
ثانيًا: خصم المصروفات التشغيلية.
ثالثًا: خصم مرتبات الموظفين.
رابعًا: خصم قيمة البضاعة التالفة.
النتيجة النهائية تمثل الربح أو الخسارة الفعلية للمحل.'

        --N'الربح النهائي بعد خصم جميع المصروفات والمرتبات والتالف.';


END
GO
/****** Object:  StoredProcedure [dbo].[GENERAL_REPORT_SELECT_OLD]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Author,,Name>
-- Create date: Create Date,,>
-- Description:	Description,,>
-- =============================================
CREATE PROCEDURE  [dbo].[GENERAL_REPORT_SELECT_OLD]
@D_F DATE,
@D_T DATE
AS
BEGIN

DECLARE @S_EXP_STATIC_1 Money , @S_EXP_STATIC_2 Money  , @S_EXP_STATIC_T Money
, @SUM_Credit Money , @SUM_SALES Money , @SUM_EXP Money , @SUM_SALARIES Money
,@SUM_Rtn_SB Money , @SUM_Rtn_Pch Money ,
@SUM_PCH Money , @IM_BERFET Money ,@AG_Credit Money,@Sum_Inside_Bill Money , @Sum_Outside_Bill Money
, @AG_DEBIT Money , @IM_EX Money 
,@SUM_DisCredit Money , @SUM_DisDEBIT Money, @SUM_DEBIT Money,@SUM_SB_Discount Money,@TOTAL_BERFET Money,@PURE_BERFET Money,@SUM_PCH_Discount Money
,@SUM_PURE_SB Money,@SUM_FRM Money,@SUM_ST_DEF_QTY MONEY,

@Desc01 Nvarchar(500), @Desc02 Nvarchar(500)
, @Desc04 Nvarchar(500), @Desc05 Nvarchar(500), @Desc06 Nvarchar(500), @Desc07 Nvarchar(500), @Desc08 Nvarchar(500)
, @Desc09 Nvarchar(500) , @Desc10 Nvarchar(500) , @Desc11 Nvarchar(500) , @Desc12 Nvarchar(500) , @Desc13 Nvarchar(500)
, @Desc16 Nvarchar(500) , @Desc17 Nvarchar(500) , @Desc18 Nvarchar(500) , @Desc19 Nvarchar(500) , @Desc20 Nvarchar(500)  
, @Desc21 Nvarchar(500) , @Desc22 Nvarchar(500),@Desc101 Nvarchar(500), @Desc23 Nvarchar(500) , @Desc24 Nvarchar(500) , @Desc25 Nvarchar(500)  


set @Desc01 = 'المصاريف التابثة , الأصول'
set @Desc02 = 'رأس المال , بضاعة المخازن'
set @Desc04 = ' المصروفات العامة'
set @Desc11 = 'المشتريات'
set @Desc10 = 'أذونات صرف'
set @Desc101 = 'أذونات إستلام'
set @Desc05 = 'بضاعة تالفه'
set @Desc06 = ' إجمالي المبيعات'
set @Desc07 = ' ربح المبيعات'
set @Desc08 = 'صافي المبيعات'
set @Desc09 = 'مرتبات الموظفين'

set @Desc12 = 'إرجاع مبيعات'
set @Desc13 = 'إرجاع مشتريات'
set @Desc23 = 'تخفيضات مشتريات'

set @Desc18 = 'إيصالات القبض'
set @Desc19 = 'إيصالات الصرف'

set @Desc20 = 'تخفيضات مبيعات'
set @Desc21 = 'مجمل الربح'
set @Desc22 = 'صافي الربح'
set @Desc24 = 'إستهلاك التصنيع'
set @Desc25 = 'عجز/فائض المخازن'
-------------------------------------------------------------------------


SELECT @S_EXP_STATIC_1 = ISNULL(SUM(CONVERT(Money, (CASE WHEN([R_T_Cost]) < 0 THEN '0' END) )),0)  FROM [dbo].[Exp_Details_T_V]
SELECT @S_EXP_STATIC_2 = ISNULL(SUM(CONVERT(Money,[R_T_Cost])),0) FROM [dbo].[Exp_Details_T_V_2]


SELECT @SUM_Credit = ISNULL(SUM(Pure),0) FROM Agents_Balance_MV_RCT WHERE  BsType_ID = 4 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SET @S_EXP_STATIC_T = @S_EXP_STATIC_1 + @S_EXP_STATIC_2
-----------------------------------------------------------
SELECT @SUM_SALES = ISNULL(SUM(TOTAL),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 1 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
--------------------------------------------------------------
SELECT @SUM_PURE_SB = ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 1 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SELECT @SUM_DEBIT = ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_RCT WHERE  BsType_ID = 3 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SELECT @SUM_PCH = ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 7 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SELECT @SUM_EXP = ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 2 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SELECT @SUM_SALARIES =  ISNULL(SUM(pure),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND  isVoid = 0 AND BsType_ID = 5 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --مرتبات الموظفين
----------------------------------------------------------
SELECT @IM_BERFET =   
(
  SELECT   ISNULL ( ( SUM(ISNULL(PRICE,0) * ISNULL(QTY,0)) ) ,0 )
  FROM SB_Contents where isDepended = 1 AND Bill_T_ID IN
   (  
  SELECT T_ID FROM Agents_Balance_MV_V WHERE isDepended = 1 AND BsType_ID = 1 and isVoid = 0 AND
  CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --سعر مبيعات
  )
)
-
(
  SELECT  ISNULL ( ( SUM(ISNULL(COST,0) * ISNULL(QTY,0)) ) ,0 )
  FROM SB_Contents where isDepended = 1 AND Bill_T_ID IN
   (  
  SELECT T_ID FROM Agents_Balance_MV_V WHERE isDepended = 1 AND BsType_ID = 1 and isVoid = 0 AND
  CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --تكلفة مبيعات
  )
)



-----------------------------------------------------------
SELECT @SUM_PCH_Discount = ISNULL(SUM(Discount),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 7 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------
SELECT @SUM_FRM =  ISNULL(SUM(TOTAL),0)  FROM FRM_CONTENTS_SUM_ONLY_STUCK_V where  CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --إستهلاك التصنيع


--------------------------------------------------------------------------------------------مجمل الربح
SELECT @TOTAL_BERFET =  ISNULL(SUM(Total),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 1 and isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --مبيعات
SELECT @TOTAL_BERFET -=  ISNULL(SUM(Discount),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --تحفيض
SELECT @TOTAL_BERFET -=  ISNULL(SUM(PURE),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 10 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --راجع

--ISNULL(SUM(Cost),0) * ISNULL(SUM(ST_QTY),0) 

----------------------------------------- حساب المشتريات
--SELECT @TOTAL_BERFET -=  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 7 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------


 SELECT  @TOTAL_BERFET -= ISNULL ( ( SUM(ISNULL(COST,0) * ISNULL(QTY,0)) ) ,0 )
  FROM SB_Contents where isDepended = 1 AND Bill_T_ID IN
   (  
  SELECT T_ID FROM Agents_Balance_MV_V WHERE isDepended = 1 AND BsType_ID = 1 and isVoid = 0 AND
  CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --تكلفة مبيعات
  )

SELECT @TOTAL_BERFET -=  @SUM_FRM--إستهلاك التصنيع


  SELECT @TOTAL_BERFET +=  ISNULL(SUM([T_Cost]),0) FROM [dbo].[IM_RtnPerfet_V] WHERE CONVERT(Date,DATE) BETWEEN @D_F AND @D_T  and BsType_ID = 10
-----------------------------------------------------------------------------------------/مجمل الربح



--------------------------------------------------------------------------------------------صافي الربح
SET @PURE_BERFET = @TOTAL_BERFET
SELECT @PURE_BERFET -=  ISNULL(SUM(Total),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND BsType_ID = 2 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --مصروفات

SELECT @PURE_BERFET -=  ISNULL(SUM(pure),0)  FROM Agents_Balance_MV_V where isDepended = 1 AND  isVoid = 0 AND BsType_ID = 5 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T --مرتبات الموظفين

SELECT @PURE_BERFET -=  ISNULL(SUM(Total),0)  FROM Agents_Balance_MV_V where isDepended = 1 And BsType_ID = 8 and isvoid  = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T  --تالف

-----------------------------------------------------------------------------------------/صافي الربح
	
	SELECT @SUM_ST_DEF_QTY =  SUM(ISNULL(Cost,0) *  ISNULL(ST_QTY,0) ) FROM ST_QTY_Deferences WHERE  CONVERT(Date,DATE) BETWEEN @D_F AND @D_T

-----------------------------------------------------------
SELECT @IM_EX =  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 8 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------------------
SELECT @Sum_Inside_Bill =  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 17 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
------------------------------------------------------------------------
SELECT @Sum_Outside_Bill =  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 35 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
--------------------------------------------------------------------------
SELECT @SUM_Rtn_SB  =  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 10 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
--------------------------------------------------------------------------
SELECT @SUM_Rtn_Pch  =  ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 11 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
--------------------------------------------------------------------------
SELECT @SUM_SB_Discount = ISNULL(SUM(Discount),0) FROM Agents_Balance_MV_V WHERE  BsType_ID = 1 AND isDepended = 1 AND isVoid = 0 AND CONVERT(Date,DATE) BETWEEN @D_F AND @D_T
-----------------------------------------------------------

  ----SELECT  1,@Desc06,  ISNULL(@SUM_SALES,0)   
  
  SELECT  1 AS 'ت',@Desc06 AS 'البيـــان',convert(varchar,FORMAT(@SUM_SALES,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
    UNION 
	SELECT  2 AS 'ت',@Desc20 AS 'البيـــان',convert(varchar,FORMAT(@SUM_SB_Discount,'###,###,###,##0.000','en-us')) AS 'القيمــة'   
  UNION
