  UNION 
  SELECT  9 AS 'ت',@Desc05 AS 'البيـــان',convert(varchar,FORMAT(@IM_EX,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  10 AS 'ت',@Desc01 AS 'البيـــان',convert(varchar,FORMAT(@S_EXP_STATIC_T,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  11 AS 'ت',@Desc10 AS 'البيـــان',convert(varchar,FORMAT(@Sum_Inside_Bill,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  12 AS 'ت',@Desc101 AS 'البيـــان',convert(varchar,FORMAT(@Sum_Outside_Bill,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION
  SELECT  13 AS 'ت',@Desc04 AS 'البيـــان',convert(varchar,FORMAT(@SUM_EXP,'###,###,###,##0.000','en-us')) AS 'القيمــة'
   UNION
  SELECT  14 AS 'ت',@Desc09 AS 'البيـــان',convert(varchar,FORMAT(@SUM_SALARIES,'###,###,###,##0.000','en-us')) AS 'القيمــة' 
  UNION
  SELECT  15 AS 'ت',@Desc18 AS 'البيـــان',convert(varchar,FORMAT(@SUM_DEBIT ,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION 
  SELECT  16 AS 'ت',@Desc19 AS 'البيـــان',convert(varchar,FORMAT(@SUM_Credit ,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
  UNION 
  --SELECT  17,@Desc24,convert(varchar,FORMAT(@SUM_FRM ,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
    SELECT  17 AS 'ت',@Desc24 AS 'البيـــان',convert(varchar,FORMAT(@SUM_FRM ,'###,###,###,##0.000','en-us')) AS 'القيمــة'  
