-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE  [dbo].[GET_ACC_CODE_MV]
@ACC_CODE NVARCHAR(100)
AS
BEGIN

SELECT 

    ACC_CODE,DATE,CREDIT,DEBIT,MASTER_NOTES,
    SUM(BALANCE) OVER (ORDER BY ACC_CODE ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS BALANCE  FROM ACC_BALANCE_V   WHERE ACC_CODE = @ACC_CODE


end


GO
/****** Object:  StoredProcedure [dbo].[GET_CR_EQUAL]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GET_CR_EQUAL](@CR_ID     int = NULL,@Currency_Equal numeric(18,2) = 1 OUTPUT,@DATE DATE,@Type_id int = 0)ASBEGIN TRY
BEGIN TRANSACTION 


IF @CR_ID <> 1
BEGIN

if @Type_id  = 0 or @Type_id = 3
begin
select @Currency_Equal = PRICE  from Currency_Schedule_V WHERE @DATE BETWEEN  D_F AND D_T AND CR_ID = @CR_ID
end
else if @Type_id = 4
begin
select @Currency_Equal = BuyPrice  from Currency_Schedule_V WHERE @DATE BETWEEN  D_F AND D_T AND CR_ID = @CR_ID
end

IF @Currency_Equal IS NULL
BEGIN
SELECT @Currency_Equal = isnull(Cr_Equal,0) FROM [Currency] WHERE Cr_ID = @CR_ID
END

END
ELSE
BEGIN
SET @Currency_Equal =1
END

 COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = ' [GET_CR_EQUAL] - ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH



GO
/****** Object:  StoredProcedure [dbo].[Get_FinancialYear_Summary]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Get_FinancialYear_Summary]
    @FinancialYear INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        -- 1️⃣ عدد القيود (من جدول القيود فقط)
        (
            SELECT COUNT(*)
            FROM ACC_BALANCE_MASTER
            --WHERE YEAR(YEAR) = @FinancialYear
        ) AS JournalCount,

		-- 1️⃣ عدد القيود اليوم (من جدول القيود فقط)
		        (
            SELECT COUNT(*)
            FROM ACC_BALANCE_MASTER
            WHERE CONVERT(DATE,DATE) = CONVERT(DATE,GETDATE())
        ) AS JournalCount_DAY,

        -- 2️⃣ عدد الحسابات (من جدول الحسابات فقط)
        (
            SELECT COUNT(T_ID)
            FROM ACCOUNTS_TREE
        ) AS AccountsCount,

        -- 3️⃣ إجمالي الرصيد (من تفاصيل القيود)
        (
            SELECT 
                ISNULL(SUM(Debit),0)
            FROM ACC_BALANCE JD
            --WHERE YEAR(JD.YEAR) = @FinancialYear
        ) AS BalanceTotal_D,


		        -- 3️⃣ إجمالي الرصيد (من تفاصيل القيود)
        (
            SELECT 
                ISNULL(SUM(Credit),0)
            FROM ACC_BALANCE JD
            --WHERE YEAR(JD.YEAR) = @FinancialYear
        ) AS BalanceTotal_C;
END
GO
/****** Object:  StoredProcedure [dbo].[GetCostCenterBalances]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE PROCEDURE [dbo].[GetCostCenterBalances]
    @DATE_F DATE,
    @DATE_T DATE,
    @Cost_ID INT = NULL  -- 0 = إجمالي فقط، 1 = تفصيلي
AS
BEGIN
    SET NOCOUNT ON;

    IF @Cost_ID = 0
    BEGIN
        -- 🔹 الوضع الإجمالي: يعرض رصيد كل مركز تكلفة
        SELECT 
            --C.COST_ID,
            C.COST_NAME  AS [مركز التكلفة],
            SUM(ISNULL(A.DEBIT, 0)) AS [مدين],
            SUM(ISNULL(A.CREDIT, 0)) AS [دائن],
            SUM(ISNULL(A.DEBIT, 0) - ISNULL(A.CREDIT, 0)) AS [الرصيد],
            CASE 
                WHEN SUM(ISNULL(A.DEBIT, 0) - ISNULL(A.CREDIT, 0)) > 0 THEN N'مدين'
                WHEN SUM(ISNULL(A.DEBIT, 0) - ISNULL(A.CREDIT, 0)) < 0 THEN N'دائن'
                ELSE N'متزن'
            END AS [الحالة]
        FROM 
            dbo.COST_CENTER AS C
            LEFT JOIN dbo.ACC_BALANCE AS A 
                ON C.COST_ID = A.COST_ID
                AND A.IS_VOID = 0 
                AND CONVERT(DATE,A.DATE_IN) BETWEEN @DATE_F AND @DATE_T
        GROUP BY 
            C.COST_ID, C.COST_NAME
        ORDER BY 
            C.COST_NAME;
    END
    ELSE
    BEGIN
        -- 🔹 الوضع التفصيلي: يعرض كل حركة داخل المركز
        SELECT 
            --C.COST_ID,
            --C.COST_NAME  AS [مركز التكلفة],
            --A.T_ID,
            A.DATE_IN AS [التاريخ],
			A.B_T_ID AS [رقم القيد],
			A.JournalNumber AS [الإشاري],
            A.ACC_CODE AS [كود الحساب],
			A.ACC_NAME AS [إسم الحساب],
            A.Notes AS [ملاحظة],
            A.Bill_Num AS [رقم الفاتورة],
			A.DEBIT AS [مدين],
            A.CREDIT AS [دائن],
            --(ISNULL(A.DEBIT, 0) - ISNULL(A.CREDIT, 0)) AS Movement
			SUM(ISNULL(A.DEBIT, 0) - ISNULL(A.CREDIT, 0)) 
                OVER (PARTITION BY C.COST_ID ORDER BY A.DATE_IN, A.T_ID ROWS UNBOUNDED PRECEDING) AS [الرصيد]
       
        FROM 
            dbo.COST_CENTER AS C
            INNER JOIN dbo.ACC_BALANCE_V AS A 
                ON C.COST_ID = A.COST_ID
        WHERE 
            A.IS_VOID = 0
            AND CONVERT(DATE,A.DATE_IN) BETWEEN @DATE_F AND @DATE_T AND A.COST_ID = @COST_ID
        ORDER BY 
             A.DATE_IN;
    END
END
GO
/****** Object:  StoredProcedure [dbo].[GetExchangeTransactions]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetExchangeTransactions]
(
    @DateFrom DATE = NULL,
    @DateTo DATE = NULL,
    @StatusId INT = NULL,
    @VaultId INT = NULL
)
AS
BEGIN

    SELECT
        E.ExchangeId,
        E.CreatedAt,
        E.OperationType,
        E.ACC_NAME AS VaultName,
        E.Cr_Name AS CurrencyName,
        E.ForeignAmount,
        E.RateSnapshot,
		E.CommissionPercentSnapshot,
        E.TotalLYD,
        E.CommissionLYD,
        E.NetLYD,
        E.StatusName,
        E.StatusId,
		E.ForeignCurrencyId,
		E.VaultId,
		E.CustomerName,
		E.CustomerIdentityNumber,
		E.ReferenceNo,
		'' AS Print_CL
    FROM ExchangeTransactions_V E
    --LEFT JOIN Rct_Mang_V V ON E.VaultId = V.T_ID
    --LEFT JOIN Currency_Schedule_V C ON E.ForeignCurrencyId = C.Cr_ID
    --LEFT JOIN ExchangeStatus S ON E.StatusId = S.StatusId
    WHERE  
	     CONVERT(DATE,CreatedAt) BETWEEN @DateFrom AND @DateTo

        --(@DateFrom IS NULL OR CAST(E.CreatedAt AS DATE) >= @DateFrom)
        --AND (@DateTo IS NULL OR CAST(E.CreatedAt AS DATE) <= @DateTo)

       AND (@StatusId IS NULL OR E.StatusId = @StatusId)
        AND (@VaultId IS NULL OR E.VaultId = @VaultId)
    ORDER BY E.ExchangeId DESC

END
GO
