/****** Object:  StoredProcedure [dbo].[GetNextJournalNumber]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetNextJournalNumber]
    @BranchId INT,
    @FiscalYear INT,
    @EntryType NVARCHAR(50),
    @EntryDate DATE,
    @NextNumber NVARCHAR(50) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE 
        @LastNumber INT = 0,
        @Prefix NVARCHAR(20),
        @NumberLength INT = 5,
        @ResetType NVARCHAR(10),
        @MonthNumber INT = MONTH(@EntryDate);

    -- الأفضل: عزل يمنع phantom reads أثناء حساب MAX
    SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- إعدادات الترقيم
        SELECT TOP 1
            @Prefix = Prefix,
            @NumberLength = ISNULL(NumberLength, 5),
            @ResetType = ResetType
        FROM dbo.SYS_Features_ACOUNTING;

        IF @ResetType = 'YEAR'
        BEGIN
            SELECT
                @LastNumber = ISNULL(MAX(TRY_CAST(RIGHT(JournalNumber, @NumberLength) AS INT)), 0)
            FROM dbo.ACC_BALANCE_MASTER WITH (UPDLOCK, HOLDLOCK)
            WHERE
                --BranchId = @BranchId
                --AND
				 YEAR(CONVERT(date, [DATE])) = @FiscalYear;
                -- لو تبي لكل نوع قيد:
                -- AND EntryType = @EntryType;
        END
        ELSE IF @ResetType = 'MONTH'
        BEGIN
            SELECT
                @LastNumber = ISNULL(MAX(TRY_CAST(RIGHT(JournalNumber, @NumberLength) AS INT)), 0)
            FROM dbo.ACC_BALANCE_MASTER WITH (UPDLOCK, HOLDLOCK)
            WHERE
                --BranchId = @BranchId
                --AND
				 YEAR(CONVERT(date, [DATE])) = @FiscalYear
                AND
				 MONTH(CONVERT(date, [DATE])) = @MonthNumber;
                -- AND EntryType = @EntryType;
        END

        SET @LastNumber = @LastNumber + 1;

        -- توليد الرقم النهائي داخل نفس الـTransaction
        IF @ResetType = 'YEAR'
        BEGIN
            SET @NextNumber = @Prefix + '-' + CAST(@FiscalYear AS NVARCHAR(4)) + '-' +
                              RIGHT(REPLICATE('0', @NumberLength) + CAST(@LastNumber AS NVARCHAR(20)), @NumberLength);
        END
        ELSE
        BEGIN
            SET @NextNumber = @Prefix + '-' + CAST(@FiscalYear AS NVARCHAR(4)) +
                              RIGHT('0' + CAST(@MonthNumber AS NVARCHAR(2)), 2) + '-' +
                              RIGHT(REPLICATE('0', @NumberLength) + CAST(@LastNumber AS NVARCHAR(20)), @NumberLength);
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO
