CREATE PROCEDURE [dbo].[GM_update]
@GM_ID int,
@GM_name nvarchar(200),
@Printer_ID int,
@BK_R int = NULL,
@BK_G int = NULL,
@BK_B int = NULL,
@FK_R int = NULL,
@FK_G int = NULL,
@FK_B int = NULL,
@POS_isShow int,
@Rank_Num int = NULL,
@Ksh_Screen Nvarchar(200)--,
--@Cat_ID int

AS
BEGIN

IF @Rank_Num IS NULL BEGIN  SELECT @Rank_Num = ( SELECT ISNULL(MAX(Rank_Num),0) FROM General_menu ) + 1 END

update general_menu set GM_name = @GM_name ,Printer_ID = @Printer_ID,
BK_R = @BK_R , BK_G = @BK_G , BK_B = @BK_B , FK_R = @FK_R , FK_G = @FK_G , FK_B = @FK_B,
POS_isShow=@POS_isShow , Rank_Num = @Rank_Num  , Ksh_Screen = @Ksh_Screen 
--, Cat_ID =@Cat_ID
 where GM_ID = @GM_ID 
END


































































