/****** Object:  StoredProcedure [dbo].[IM_Check_Neg_QTY_]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[IM_Check_Neg_QTY_]
@F int OUTPUT,
@IM_ID INT,
@ST_ID INT,
@D_Vaild Nvarchar(20),
@Enterd_Qty Float,
@Cargo Float = null,
@U_ID INT = NULL
AS
Declare @End_QTY FLOAT , @Current_QTY FLOAT = 0 , @ALL_QTY FLOAT 
BEGIN 

if @Cargo is null begin select @Cargo = U_Cargo from Units WHERE U_ID = @U_ID  end

IF (SELECT isStore FROM IM_Menu WHERE IM_ID = @IM_ID) IN (1,2)
BEGIN

SELECT @Current_QTY = ISNULL(SUM(QTY),0) FROM ST_Balance_V WHERE IM_ID = @IM_ID AND ST_ID = @ST_ID AND D_Vaild =@D_Vaild
SELECT @ALL_QTY = @Current_QTY - (@Enterd_Qty*@Cargo)

IF @ALL_QTY < 0
BEGIN
SELECT @F = 1
END
ELSE
BEGIN
SELECT @F = 0
END

END
ELSE
BEGIN
SELECT @F = 0
END

END











GO
