GO
CREATE PROCEDURE [dbo].[IM_Check_Neg_QTY_For_Cancel_FRM_Details]
@F int OUTPUT,
@T_ID INT,
@Str_Name NVARCHAR(1500) OUTPUT

AS
Declare @End_QTY FLOAT , @Current_QTY FLOAT = 0 ,@ALL_QTY FLOAT , @i INT
,@IM_NAME NVARCHAR(500) = '',@IM_ID INT,@ST_ID INT,@Enterd_ST_QTY Float , @D_Vaild nvarchar(50)=''
BEGIN
SET @F = 0
SELECT @Str_Name = ''

SELECT @i = MIN(T_ID) FROM FRM_Details_V WHERE FRM_T_ID = @T_ID
WHILE @i IS NOT NULL
BEGIN

SELECT @IM_ID = IM_ID , @ST_ID = ST_ID ,  @Enterd_ST_QTY= ST_QTY ,@D_Vaild=D_Vaild, @IM_NAME = item_name FROM FRM_Details_V WHERE T_ID = @i

IF (SELECT isStore FROM IM_Menu WHERE IM_ID = @IM_ID) IN (1,2)
BEGIN

SELECT @Current_QTY = ISNULL(SUM(QTY),0) FROM ST_Balance_V WHERE IM_ID = @IM_ID AND D_Vaild=@D_Vaild  AND ST_ID = @ST_ID 
SELECT @ALL_QTY = @Current_QTY - @Enterd_ST_QTY

IF @ALL_QTY < 0
BEGIN
SELECT @F = 1
SELECT @Str_Name = @Str_Name +' , ' + @IM_NAME
--raiserror(' لا يمكن سحب كمية بالسالب للصنف %s',16,1,@IM_NAME)
--GOTO END_FUN
END
--ELSE
--BEGIN
--SELECT @F = 0
--END

END

SELECT @i = MIN(T_ID) FROM FRM_Details_V WHERE FRM_T_ID = @T_ID AND T_ID > @i
END


--END_FUN:

END




























GO
