BEGIN 

SELECT @IM_ID=IM_ID, @ST_ID = ST_ID , @U_ID=U_ID , @D_Vaild=D_Vaild FROM SB_Contents WHERE T_ID = @T_ID
SELECT @Cargo = U_Cargo FROM Units WHERE U_ID = @U_ID

