BEGIN

SELECT @Current_QTY = ISNULL(SUM(QTY),0) FROM ST_Balance_V WHERE IM_ID = @IM_ID AND ST_ID = @ST_ID AND D_Vaild =@D_Vaild
SELECT @ALL_QTY = @Current_QTY - (1*@Cargo)

IF @ALL_QTY < 0
BEGIN
SELECT @F = 1
END
ELSE
BEGIN
SELECT @F = 0
END

END
ELSE
BEGIN
SELECT @F = 0
END

END






















GO
/****** Object:  StoredProcedure [dbo].[IM_Check_Neg_QTY_POS_Unit_Change]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[IM_Check_Neg_QTY_POS_Unit_Change]
@T_ID INT,
@F int OUTPUT,
@IM_ID INT,
@Enterd_U_ID Float

AS
Declare @Current_QTY FLOAT = 0 , @ALL_QTY FLOAT ,@Enterd_Qty Float,@Prev_Qty Float ,@ST_ID INT,@D_Vaild Nvarchar(20),
@Cargo Float = 1
BEGIN 

IF (SELECT isStore FROM IM_Menu WHERE IM_ID = @IM_ID) IN (1,2)
BEGIN

SELECT @Prev_Qty = ST_QTY , @ST_ID = ST_ID , @D_Vaild = D_Vaild FROM SB_Contents WHERE T_ID = @T_ID
SELECT @Cargo = U_Cargo FROM IM_Menu_Units_V  WHERE U_ID = @Enterd_U_ID
SELECT @Enterd_Qty = QTY FROM SB_Contents WHERE T_ID = @T_ID
SELECT @Enterd_Qty = ( @Enterd_Qty * @Cargo )

SELECT @Current_QTY = ISNULL(SUM(QTY),0) FROM ST_Balance_V WHERE IM_ID = @IM_ID AND ST_ID = @ST_ID AND D_Vaild =@D_Vaild
SELECT @ALL_QTY = (@Current_QTY + @Prev_Qty) - @Enterd_Qty

IF @ALL_QTY < 0
BEGIN
SELECT @F = 1
END
ELSE
BEGIN
SELECT @F = 0
END


END
ELSE
BEGIN
SELECT @F = 0
END

END























GO
