/****** Object:  StoredProcedure [dbo].[IM_Conferm_NewPrice]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[IM_Conferm_NewPrice] 
@IM_T_ID INT,
@New_Price FLOAT,
@On_Update BIT
AS 
BEGIN

DECLARE  @Total NUMERIC(18,3),@AG_ID INT,@SB_T_ID INT

SELECT @SB_T_ID = Bill_T_ID FROM SB_Contents WHERE T_ID = @IM_T_ID


Update SB_Contents Set Price = @New_Price , T_Price = (QTY * @New_Price) WHERE T_ID = @IM_T_ID


SELECT @Total = ISNULL(SUM(T_Price),0) FROM SB_Contents WHERE Bill_T_ID = @SB_T_ID
UPDATE Agents_Balance_MV SET Total = @Total , Pure = @Total - ISNULL(Discount,0),
Bill_Berfet = ((SELECT SUM(T_Price) FROM SB_Contents_V WHERE Bill_T_ID = @SB_T_ID)  -
(SELECT SUM(SUM_Cost) FROM SB_Contents_V WHERE Bill_T_ID = @SB_T_ID ))
WHERE T_ID = @SB_T_ID


IF @On_Update = 1 BEGIN EXEC AG_Balance_Update_Pied_On_Update @SB_T_ID,1 END

END








GO
