/****** Object:  StoredProcedure [dbo].[IM_GROUPING_BY_GM]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[IM_GROUPING_BY_GM] 
@D_F DATE,
@D_T DATE
AS 

BEGIN

SELECT a.GM_Name AS 'الإسم' ,


--PCH
(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_OUT),0)) from IM_FULL_MV_V WHERE  GM_ID = a.GM_ID  AND TYPE_ID = 7 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'مشتريات'
,(SELECT CONVERT(FLOAT,ISNULL(sum(Q_OUT),0)) from IM_FULL_MV_V WHERE  GM_ID = a.GM_ID  AND TYPE_ID = 7 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'ك.مشتريات'

--RTN_PCH
,(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_IN),0)) from IM_FULL_MV_V WHERE  GM_ID = a.GM_ID  AND TYPE_ID = 11 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'راجع مشتريات'
,(SELECT CONVERT(FLOAT,ISNULL(sum(Q_IN),0)) from IM_FULL_MV_V WHERE  GM_ID = a.GM_ID  AND TYPE_ID = 11 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'ك.راجع مشتريات'

--SB
,(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_IN),0)) from IM_FULL_MV_V WHERE  GM_ID = a.GM_ID  AND TYPE_ID = 1 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'مبيعات'
,(SELECT CONVERT(FLOAT,ISNULL(sum(Q_IN),0)) from IM_FULL_MV_V WHERE  GM_ID = a.GM_ID  AND TYPE_ID = 1 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'ك.مبيعات'


--RTN_SB
,(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_OUT),0)) from IM_FULL_MV_V WHERE  GM_ID = a.GM_ID  AND TYPE_ID = 10 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'راجع مبيعات'
,(SELECT CONVERT(FLOAT,ISNULL(sum(Q_OUT),0)) from IM_FULL_MV_V WHERE  GM_ID = a.GM_ID  AND TYPE_ID = 10  AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T   ) AS 'ك.راجع مبيعات'


--Perfet_SB
,(SELECT CONVERT(money,ISNULL(sum([Total_Perfet]),0)) from [IM_Perfet_V] WHERE  GM_ID = a.GM_ID  AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T  ) AS 'هامش الربح '



--IM_EX
,(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_IN),0)) from IM_FULL_MV_V WHERE  GM_ID = a.GM_ID  AND TYPE_ID = 8 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'تالف'
,(SELECT CONVERT(FLOAT,ISNULL(sum(Q_IN),0)) from IM_FULL_MV_V WHERE  GM_ID = a.GM_ID  AND TYPE_ID = 8 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'ك.تالف'


--ST_BALANCE
,(SELECT CONVERT(FLOAT,ISNULL(sum(QTY),0)) from IM_STORE_View WHERE  GM_ID = a.GM_ID )  AS 'ك.الحالية'
 ,(SELECT sum(T_Cost) from IM_STORE_View WHERE  GM_ID = a.GM_ID  ) AS 'تكلفة ك. الحالية'

FROM General_menu a 



END


--SELECT  A.GM_ID,A.GM_Name,
--(SELECT SUM(S_TOTAL) AS TOTAL_INCOME FROM CARS_MV_INCOME_V WHERE GM_ID = A.GM_ID )


--FROM General_menu A




GO
