--Perfet_SB
,(SELECT CONVERT(money,ISNULL(sum([Total_Perfet]),0)) from [IM_Perfet_V] WHERE  IM_ID = a.IM_ID  AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T  ) AS 'هامش الربح '



--IM_EX
,(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_IN),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 8 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'تالف'
,(SELECT CONVERT(FLOAT,ISNULL(sum(Q_IN),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 8 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'ك.تالف'


--ST_BALANCE
,(SELECT CONVERT(FLOAT,ISNULL(sum(QTY),0)) from IM_STORE_View WHERE  IM_ID = a.IM_ID )  AS 'ك.الحالية'
 ,(SELECT sum(T_Cost) from IM_STORE_View WHERE  IM_ID = a.IM_ID  ) AS 'تكلفة ك. الحالية'

FROM IM_MENU a 



END






