/****** Object:  StoredProcedure [dbo].[IM_MV_SELECT]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[IM_MV_SELECT]
@ST_ID	INT,
@ALL_TIME	BIT,
@D_F	DATE,
@D_T DATE,
@IM_ID	INT


AS
BEGIN
DECLARE @U_Cargo numeric(18, 3),@U_ID INT
select @U_Cargo = U_Cargo,@U_ID = U_ID FROM IM_Menu_Units_V WHERE IM_ID = @IM_ID AND is_Default = 1

DELETE FROM IM_MV
DBCC CHECKIDENT ('[IM_MV]', RESEED, 0);
	
INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Negitave,Valid) SELECT Bill_T_ID,1,DATE,@U_ID,(ST_QTY/@U_Cargo),D_Vaild FROM SB_Contents WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1 --مبيعات
INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Pluse,Valid) SELECT Pch_T_ID,7,DATE,@U_ID,(ST_QTY/@U_Cargo),D_Vaild FROM Pch_Details_V WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID AND ID=7 AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1   --مشتريات

INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Pluse,Valid) SELECT Pch_T_ID,9,DATE,@U_ID,(ST_QTY/@U_Cargo),D_Vaild FROM Pch_Details_V WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID AND ID=9 AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1  --جرد

INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Pluse,Valid) SELECT Bill_T_ID,10,DATE,@U_ID,(ST_QTY/@U_Cargo),D_Vaild FROM Rtn_Contents WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID AND Rtn_Type_ID =1 AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1  --ترجيع مبيعات
INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Negitave,Valid) SELECT Bill_T_ID,11,DATE,@U_ID,(ST_QTY/@U_Cargo),D_Vaild FROM Rtn_Contents WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID AND Rtn_Type_ID =7 AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1  --ترجيع مشتريات

INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Negitave,NOTES,Valid) SELECT B_T_ID,12,DATE,@U_ID,(ST_QTY/@U_Cargo),'صرف من المخزن',D_Vaild FROM Store_Trans_Details WHERE ST_F_ID = @ST_ID AND IM_ID=@IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1  --تحويل من مخزن
INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Pluse,NOTES,Valid) SELECT B_T_ID,12,DATE,@U_ID,(ST_QTY/@U_Cargo),'إستلام للمخزن',D_Vaild FROM Store_Trans_Details WHERE ST_To_ID = @ST_ID AND IM_ID=@IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1  --تحويل إلى مخزن

INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Negitave,Valid) SELECT IMEX_T_ID,8,DATE,@U_ID,(ST_QTY/@U_Cargo),D_Vaild FROM IMEX_Details WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1  --تالف

INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Pluse,Valid) SELECT FRM_T_ID,13,DATE,@U_ID,(ST_QTY/@U_Cargo),D_Vaild FROM FRM_Auto_Show_V  WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1 AND BsType_ID = 13  --تصنيع ألي
INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Pluse,Valid) SELECT FRM_T_ID,18,DATE,@U_ID,(ST_QTY/@U_Cargo),D_Vaild FROM FRM_Manuel_Show_V  WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1 AND BsType_ID = 18  --تصنيع يدوي

INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Negitave,Valid) SELECT Bill_T_ID,14,DATE,@U_ID,(ST_QTY/@U_Cargo),NULL FROM FRM_Contents_Details WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1  --تصنيع استهلاك

INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Negitave,Valid) SELECT InSale_T_ID,17,DATE,@U_ID,(ST_QTY/@U_Cargo),D_Vaild FROM InSale_Details WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID  AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1  --إذن صرف

INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Pluse,Valid) SELECT OutSale_T_ID,35,DATE,@U_ID,(ST_QTY/@U_Cargo),D_Vaild FROM OutSale_Details WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID  AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1  --إذن إستلام



INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Negitave,NOTES,Valid) SELECT NULL,15,DATE,@U_ID,((ST_QTY/@U_Cargo)*-1),'تعديل من المخزن',Valid_D FROM ST_QTY_Deferences
 WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND ST_QTY < 0  --خصم كمية من المخزن

 INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Pluse,NOTES,Valid) SELECT NULL,15,DATE,@U_ID,(ST_QTY/@U_Cargo),'تعديل من المخزن',Valid_D FROM ST_QTY_Deferences
 WHERE ST_ID = @ST_ID AND IM_ID=@IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND ST_QTY > 0  --زيادة كمية من المخزن


 INSERT INTO IM_MV(T_ID,Type_ID,DATE,U_ID,Negitave,Valid) SELECT NULL,19,DATE,@U_ID,(ST_QTY/@U_Cargo),'' FROM SB_Contents_Structers WHERE ST_ID = @ST_ID AND Struct_ID=@IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND isDepended = 1 --تركيبة صنف


 declare @bal numeric(18,3) = 0

;WITH q AS (
    SELECT top 10000000  * FROM IM_MV
    ORDER BY [date]
)            
UPDATE  q  set @bal=balance = @bal + (  ISNULL(Pluse,0) - ISNULL(Negitave,0) )



SELECT * FROM IM_MV_V ORDER BY DATE ASC

END






















GO
