/****** Object:  StoredProcedure [dbo].[IM_ORDERS_COMING_pros]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--IF OBJECT_ID('IM_ORDERS_COMING_pros','P') IS NOT NULL
--DROP PROC IM_ORDERS_COMING_pros
--GO
CREATE PROCEDURE [dbo].[IM_ORDERS_COMING_pros]
(@T_ID              int,
@DATE              datetime = NULL,
@ST_ID             int = NULL,
@IM_ID             int = NULL,
@U_ID              int = NULL,
@QTY               nchar(10) = NULL,
@DATE_OF_ARRIV     datetime = NULL,
@NOTES	nvarchar(MAX) = NULL,
@USER_ID int,
@Process	 VARCHAR(20)

) AS


BEGIN
IF @Process = 'DELETE'
BEGIN
	DELETE FROM dbo.IM_ORDERS_COMING
	 WHERE T_ID = @T_ID 
	RETURN 1
END
IF EXISTS (SELECT 1 FROM IM_ORDERS_COMING WHERE T_ID = @T_ID )
BEGIN
	UPDATE dbo.IM_ORDERS_COMING
	SET 
	--[DATE]              = @DATE,
       [ST_ID]             = @ST_ID,
       [IM_ID]             = @IM_ID,
       [U_ID]              = @U_ID,
       [QTY]               = @QTY,
       [DATE_OF_ARRIV]     = @DATE_OF_ARRIV,
	   [NOTES]             = @NOTES,
	   [USER_ID]           = @USER_ID
	WHERE T_ID = @T_ID 
	RETURN 1
END
ELSE
BEGIN

   exec @T_ID = AA_GET_MAX_ID 'IM_ORDERS_COMING'

	INSERT INTO dbo.IM_ORDERS_COMING
	(  [T_ID],
	   [DATE],
       [ST_ID],
       [IM_ID],
       [U_ID],
       [QTY],
       [DATE_OF_ARRIV],
	   [NOTES],
	   [USER_ID])
	SELECT @T_ID,GETDATE(),
       @ST_ID,
       @IM_ID,
       @U_ID,
       @QTY,
       @DATE_OF_ARRIV,
	   @NOTES,
	   @USER_ID
	RETURN 1
END
 
END
GO
/****** Object:  StoredProcedure [dbo].[IM_OTHER_STORE_V_SELECT]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[IM_OTHER_STORE_V_SELECT]
	@ST_ID INT
AS
BEGIN

SELECT
    s1.St_Name,
    s1.item_name,
    s1.U_Name,
    s1.IM_Num,
    s1.Barcode,
    SUM(s1.QTY) AS QTY
FROM IM_STORE_View s1
WHERE NOT EXISTS (
    SELECT 1
    FROM ST_Balance_V s2
    WHERE s2.IM_ID = s1.IM_ID
      AND s2.ST_ID = @ST_ID
      AND ISNULL(s2.QTY,0) > 0
)
GROUP BY
    s1.IM_ID,
    s1.St_Name,
    s1.item_name,
    s1.U_Name,
    s1.IM_Num,
    s1.Barcode
HAVING SUM(s1.QTY) > 0;



--SELECT s1.St_Name,s1.item_name,s1.U_Name ,s1.IM_Num,s1.Barcode, SUM(s1.QTY) AS QTY
--FROM IM_STORE_View s1
--WHERE s1.ST_ID <> @ST_ID --(1, 3, 5)  -- قائمة المخازن الرئيسية
--  AND NOT EXISTS (
--    SELECT 1
--    FROM ST_Balance_V s2
--    WHERE s2.ST_ID = @ST_ID       -- مخزن المحل
--      AND s2.IM_ID = s1.IM_ID
--  )
