/****** Object:  StoredProcedure [dbo].[IM_OUT_SB_MV]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[IM_OUT_SB_MV] 
@D_F DATE,
--@D_T DATE,
@IM_ID INT
AS 

BEGIN

SELECT @D_F as 'التاريــخ',a.ITEM_NAME AS 'الصنــف' ,


--PCH
--(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_OUT),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 7 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'مشتريات'
--,(SELECT CONVERT(FLOAT,ISNULL(sum(Q_OUT),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 7 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'ك.مشتريات'

----OUT_SALE
--,(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_OUT),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 35 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'المستلم'
--,
(SELECT CONVERT(FLOAT,ISNULL(sum(Q_OUT),0)) from IM_FULL_MV_V WHERE  IM_ID = @IM_ID AND TYPE_ID = 35 AND CONVERT(DATE,[التاريخ]) = @D_F  ) AS 'الكمية المستلمة من الصنف'


----RTN_PCH
--,(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_IN),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 11 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'راجع مشتريات'
--,(SELECT CONVERT(FLOAT,ISNULL(sum(Q_IN),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 11 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'ك.راجع مشتريات'

----SB
--,(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_IN),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 1 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'مبيعات'
,(SELECT CONVERT(FLOAT,ISNULL(sum(Q_IN),0)) from IM_FULL_MV_V WHERE  IM_ID = @IM_ID  AND TYPE_ID = 1 AND CONVERT(DATE,[التاريخ]) = @D_F  ) AS 'الكمية التي تم تسليمها للزبون'


----RTN_SB
--,(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_OUT),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 10 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'راجع مبيعات'
--,(SELECT CONVERT(FLOAT,ISNULL(sum(Q_OUT),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 10 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T ) AS 'ك.راجع مبيعات'


----Perfet_SB
--,(SELECT CONVERT(money,ISNULL(sum([Total_Perfet]),0)) from [IM_Perfet_V] WHERE  IM_ID = a.IM_ID  AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T  ) AS 'هامش الربح '



----IM_EX
--,(SELECT CONVERT(money,ISNULL(sum([السعر] * Q_IN),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 8 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'تالف'
--,(SELECT CONVERT(FLOAT,ISNULL(sum(Q_IN),0)) from IM_FULL_MV_V WHERE  IM_ID = a.IM_ID  AND TYPE_ID = 8 AND CONVERT(DATE,[التاريخ]) BETWEEN @D_F AND @D_T  ) AS 'ك.تالف'


--ST_BALANCE
,(SELECT CONVERT(FLOAT,ISNULL(sum(QTY),0)) from IM_STORE_View WHERE  IM_ID = a.IM_ID )  AS 'الكمية الحالية'
 --,(SELECT sum(T_Cost) from IM_STORE_View WHERE  IM_ID = a.IM_ID  ) AS 'تكلفة ك. الحالية'

FROM IM_MENU a WHERE IM_ID = @IM_ID 



END






GO
