,[GM_ID],[Markter_Val]  FROM [dbo].[IM_Perfet_V] Where ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T ) AND ST_ID = @ST_ID AND GM_ID = @GM_ID
