CREATE PROCEDURE [dbo].[IM_Units_insert]
@IM_ID int OUTPUT,
@U_ID int,
@Barcode	nvarchar(MAX) =NULL,
@Price  numeric(18,3),
@Min_SP numeric(18,3) = NULL,
@Min_SP_2 numeric(18,3) = NULL,
@User_ID	int,
@Row_Enabled Bit = 0
AS
DECLARE @U_IM_ID int
BEGIN 

IF @Barcode IS NULL BEGIN EXEC @BARCODE = [AG_BalanceMV_GetSerial_Barcode] END
EXEC @U_IM_ID = [AA_GET_MAX_IM_UNITS]
