CREATE PROCEDURE [dbo].[IMEX_Details_Delete] 
@T_ID	int
AS
BEGIN TRY
BEGIN TRANSACTION 

DECLARE @ST_QTY NUMERIC(18,2),@IM_ID INT,@ST_ID INT,@D_Vaild NVARCHAR(50) , @IMEX_T_ID  INT
SELECT @IM_ID=IM_ID, @ST_ID=ST_ID,@D_Vaild=D_Vaild,@ST_QTY =ST_QTY,@IMEX_T_ID = IMEX_T_ID   FROM IMEX_Details where T_ID = @T_ID


DELETE FROM IMEX_Details WHERE T_ID = @T_ID

EXEC [Recalculate_Agent_Bill_Total] @IMEX_T_ID


--EXEC Inc_IM_QTY @IM_ID,@ST_ID,@D_Vaild,@ST_QTY

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[IMEX_Details_Delete]',16,1,'خطأ')
ROLLBACK
END CATCH












GO
/****** Object:  StoredProcedure [dbo].[IMEX_Details_Insert]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[IMEX_Details_Insert] 
@IM_ID	int,
@U_ID	int,
@ST_ID	int,
@IMEX_T_ID	int,
@Price	numeric(18, 2),
@D_Vaild DATE = NULL,
@QYT	numeric(18, 2),
@Total	numeric(18, 2),
@ON_Update bit,
@Barcode nvarchar(50)
AS
BEGIN TRY
BEGIN TRANSACTION 
declare @ST_QTY NUMERIC(18,2),@U_Cargo NUMERIC(18,2),@Valid_ST NVARCHAR(50), @T_ID INT,@AG_ID int,@Current_QTY float

--SET @Valid_ST = @D_Vaild
--IF @Valid_ST IS NULL BEGIN SET @Valid_ST ='' END

SET @Valid_ST = @D_Vaild
IF @Valid_ST IS NULL 
BEGIN 
SET @Valid_ST ='' 
END
ELSE
BEGIN
SELECT @Current_QTY = ISNULL(SUM(QTY),0) FROM ST_Balance_V WHERE IM_ID = @IM_ID
IF @Current_QTY <= 0 BEGIN SET @Valid_ST = (SELECT  Top 1 D_Vaild FROM SB_Contents WHERE ST_ID = @ST_ID  AND IM_ID = @IM_ID ORDER BY T_ID DESC) END
--IF @Valid_ST IS NULL BEGIN SET @Valid_ST = '01-01-1900' END
END


SELECT @U_Cargo = U_Cargo FROM Units WHERE U_ID = @U_ID
SELECT @ST_QTY = (U_Cargo * @QYT) FROM Units WHERE U_ID = @U_ID


EXEC @T_ID = [AA_GET_MAX_IMEX_Details]
INSERT INTO IMEX_Details(T_ID,Date,IMEX_T_ID,IM_ID,U_ID,ST_ID,Cost,D_Vaild,QYT,Total,U_Cargo,ST_QTY,isDepended,Barcode)
                  Values(@T_ID,GETDATE(),@IMEX_T_ID,@IM_ID,@U_ID,@ST_ID,@Price,@Valid_ST,@QYT,@Total,@U_Cargo,@ST_QTY,1,@Barcode)

IF @ON_Update = 1 BEGIN UPDATE IMEX_Details  SET isDepended = 1 WHERE T_ID = @T_ID  END


--EXEC Dec_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY

EXEC [Recalculate_Agent_Bill_Total] @IMEX_T_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('IMEX_Details_Insert Proc',16,1,'خطأ')
ROLLBACK
END CATCH







































GO
