CREATE PROCEDURE [dbo].[Income_Group_Details_proc](@T_ID            int,@Group_ID        nchar(10) = NULL,@Group_Calc      char(1) = NULL,@ACC_CODE        int = NULL,@ACC_NAME        nvarchar(2500) = NULL,@ACC_BALANCE     numeric = NULL,@Process	 VARCHAR(20)) AS
BEGIN
IF @Process = 'DELETE'
BEGIN
	DELETE FROM dbo.Income_Group_Details	 WHERE T_ID = @T_ID 
	RETURN 1
END
IF EXISTS (SELECT 1 FROM Income_Group_Details WHERE T_ID = @T_ID )
BEGIN
	UPDATE dbo.Income_Group_Details	SET [Group_ID]        = @Group_ID,       [Group_Calc]      = @Group_Calc,       [ACC_CODE]        = @ACC_CODE,       [ACC_NAME]        = @ACC_NAME,       [ACC_BALANCE]     = @ACC_BALANCE	WHERE T_ID = @T_ID 
	RETURN 1
END
ELSE
BEGIN
	INSERT INTO dbo.Income_Group_Details	([Group_ID],       [Group_Calc],       [ACC_CODE],       [ACC_NAME],       [ACC_BALANCE])	SELECT @Group_ID,       @Group_Calc,       @ACC_CODE,       @ACC_NAME,       @ACC_BALANCE
	RETURN 1
END
 
END


