IF EXISTS (SELECT 1 FROM Income_Group_Results WHERE T_ID = @T_ID )
BEGIN
	UPDATE dbo.Income_Group_Results	SET [RESULT_TITLE]             = @RESULT_TITLE,       [RESULT_ONE_CODE]          = @RESULT_ONE_CODE,       [Calc_BETWEEN_ONE_TWO]     = @Calc_BETWEEN_ONE_TWO,       [RESULT_TWO_CODE]          = @RESULT_TWO_CODE,       --[BALANCE]                  = @BALANCE,       [RESULT_Calc]              = @RESULT_Calc,       [RESULT_CODE]              = @RESULT_CODE,       [Column_Num]               = @Column_Num	WHERE T_ID = @T_ID 
	RETURN 1
END
ELSE
BEGIN
	INSERT INTO dbo.Income_Group_Results	([RESULT_TITLE],       [RESULT_ONE_CODE],       [Calc_BETWEEN_ONE_TWO],       [RESULT_TWO_CODE],      -- [BALANCE],       [RESULT_Calc],       [RESULT_CODE],       [Column_Num])	SELECT @RESULT_TITLE,       @RESULT_ONE_CODE,       @Calc_BETWEEN_ONE_TWO,       @RESULT_TWO_CODE,     --  @BALANCE,       @RESULT_Calc,       @RESULT_CODE,       @Column_Num
	RETURN 1
END
 
END


