/****** Object:  StoredProcedure [dbo].[Income_Setting_Move_By_ACC_CODE]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Income_Setting_Move_By_ACC_CODE]
(
    @ACC_CODE   NVARCHAR(40),
    @GroupID    INT,
    @GroupCalc  CHAR(1),
	@isOverWrite  bit
)
AS
--BEGIN
BEGIN TRY
BEGIN TRANSACTION 

    SET NOCOUNT ON;


    DECLARE @ACC_PARENT NVARCHAR(40);

	if @isOverWrite = 0
	begin
	DELETE FROM Income_Group_Details WHERE Group_ID = @GroupID
	end


    -- جلب الأب المباشر للحساب
    SELECT @ACC_PARENT = ACC_PARENT
    FROM ACCOUNTS_TREE
    WHERE ACC_CODE = @ACC_CODE;

    ;WITH RecursiveHierarchy AS
    (
        -- 1️⃣ نقطة البداية: الحساب نفسه
        SELECT 
            T_ID,
            ACC_CODE,
            ACC_NAME,
            ACC_PARENT,
            ACC_LEVEL,
            is_Balance_View,
            ACC_CLOSING,
            SIDE,
            is_Lock_Trans
        FROM ACCOUNTS_TREE
        WHERE ACC_CODE = @ACC_CODE

        UNION ALL

        -- 2️⃣ جميع الأبناء
        SELECT 
            d.T_ID,
            d.ACC_CODE,
            d.ACC_NAME,
            d.ACC_PARENT,
            d.ACC_LEVEL,
            d.is_Balance_View,
            d.ACC_CLOSING,
            d.SIDE,
            d.is_Lock_Trans
        FROM ACCOUNTS_TREE d
        INNER JOIN RecursiveHierarchy r
            ON d.ACC_PARENT = r.ACC_CODE
    )

    INSERT INTO Income_Group_Details
(
    T_ID,      -- PK غير Identity
    Group_ID,
    Group_Calc,
    ACC_CODE
)
SELECT
    NEXT VALUE FOR dbo.Seq_Income_Group_Details, -- أو أي Generator
    @GroupID,
    @GroupCalc,
    ACC_CODE
FROM RecursiveHierarchy
WHERE ACC_CODE <> @ACC_CODE AND ACC_PARENT = @ACC_CODE ;


--END


 COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = ' [Income_Setting_Move_By_ACC_CODE] - ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH

GO
