           ,[ACC_NAME_2]
           ,[ACC_NAME_3]
           ,[BALANCE])
     VALUES
           (
           @i
           ,@ACC_PARENT
           ,@ACC_NAME
           ,''
           ,''
           ,NULL)

		   EXEC [Income_Statement_2] @i,@ACC_NAME,@i
		   ------------------------------------------------------------------------
		   INSERT INTO [dbo].[Balance_sheet]
           (
            [ACC_CODE]
           ,[ACC_PARENT]
           ,[ACC_NAME_1]
