SELECT @ACC_NAME = ACC_NAME ,@ACC_PARENT = ACC_PARENT  ,@BALANCE = BALANCE FROM [ACCOUNTS_TREE_V] WHERE ACC_CODE = @i

IF @BALANCE < 0 BEGIN SET @BALANCE = @BALANCE * -1 END

INSERT INTO [dbo].[Balance_sheet]
