           ,''
           ,''
           ,NULL)

		   EXEC [Income_Statement_2] @i,@ACC_NAME,@i
		   ------------------------------------------------------------------------
		   INSERT INTO [dbo].[Balance_sheet]
           (
            [ACC_CODE]
           ,[ACC_PARENT]
           ,[ACC_NAME_1]
           ,[ACC_NAME_2]
           ,[ACC_NAME_3]
           ,[BALANCE])
     VALUES
           (
           0
           ,0
           ,' صـــافي ' + @ACC_NAME
           ,''
           ,''
           ,(SELECT isnull(SUM(BALANCE),0) FROM Balance_sheet WHERE ACC_PARENT_0 = @i)
		   )
		   ----------------------------------------------------------------------------------------------

		   		   INSERT INTO [dbo].[Balance_sheet]
           (
            [ACC_CODE]
           ,[ACC_PARENT]
           ,[ACC_NAME_1]
