/****** Object:  StoredProcedure [dbo].[Income_Statement_BY_QUART_YEAR]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Income_Statement_BY_QUART_YEAR]
 @YEAR INT,
 @ORG_ST_ACC_CODE VARCHAR(40),@Income_ST_ACC_CODE VARCHAR(40)
 AS
BEGIN


--DECLARE @Year INT = 2024; -- السنة المطلوبة

-- إنشاء جدول مؤقت
CREATE TABLE #TempQuarters (
    Quarter INT,
    StartDate DATE,
    EndDate DATE
);

-- إدخال البيانات إلى الجدول المؤقت
INSERT INTO #TempQuarters (Quarter, StartDate, EndDate)
SELECT 
    1 AS Quarter, 
    CAST(@Year AS VARCHAR) + '-01-01' AS StartDate, 
    CAST(@Year AS VARCHAR) + '-03-31' AS EndDate
UNION ALL
SELECT 
    2 AS Quarter, 
    CAST(@Year AS VARCHAR) + '-04-01' AS StartDate, 
    CAST(@Year AS VARCHAR) + '-06-30' AS EndDate
UNION ALL
SELECT 
    3 AS Quarter, 
    CAST(@Year AS VARCHAR) + '-07-01' AS StartDate, 
    CAST(@Year AS VARCHAR) + '-09-30' AS EndDate
UNION ALL
SELECT 
    4 AS Quarter, 
    CAST(@Year AS VARCHAR) + '-10-01' AS StartDate, 
    CAST(@Year AS VARCHAR) + '-12-31' AS EndDate;

-- استرجاع البيانات من الجدول المؤقت (اختياري)
--SELECT * FROM #TempQuarters;

-- حذف الجدول المؤقت بعد الانتهاء (اختياري)
-- DROP TABLE #TempQuarters;

DELETE FROM [Balance_sheet_OVER_YEAR]
DBCC CHECKIDENT ('[Balance_sheet_OVER_YEAR]', RESEED, 0);




DECLARE @i int,@START_DATE DATE,@END_DATE DATE 

select @i = MIN(Quarter) FROM #TempQuarters
WHILE @I IS NOT NULL
BEGIN

SELECT @START_DATE = #TempQuarters.StartDate , @END_DATE = #TempQuarters.EndDate FROM #TempQuarters WHERE Quarter = @i

EXEC PREPARE_ACC_BALANCE 0,@START_DATE,@END_DATE

--[dbo].[INCOME_STATMENT_FULL_STEPS]--(--@DATE_F    DATE,--@DATE_T DATE,--@Hide_Zeros Bit,--@Show_Symbol_Code Bit = 0EXEC INCOME_STATMENT_FULL_STEPS   @START_DATE,@END_DATE,0,0,0
--EXEC Income_Statement_1 1, @ORG_ST_ACC_CODE,@Income_ST_ACC_CODE

IF @i = 1
BEGIN
INSERT INTO [dbo].[Balance_sheet_OVER_YEAR]
           ([ACC_NAME],[ACC_CODE]
           ,[FIRST_QUART_INCOME])
           SELECT [ACC_NAME],[ACC_CODE],[Original_Balance] FROM [Tmp_IncomeReport_2] WHERE ACC_NAME <> '' AND ACC_NAME IS NOT NULL AND ACC_NAME <> '='
END


IF @i = 2
BEGIN
UPDATE [dbo].[Balance_sheet_OVER_YEAR]
           SET
           [SECOND_QUART_INCOME] = (SELECT [Original_Balance] FROM [Tmp_IncomeReport_2]  WHERE [Balance_sheet_OVER_YEAR].ACC_CODE = [Tmp_IncomeReport_2].ACC_CODE)
END

IF @i = 3
BEGIN
UPDATE [dbo].[Balance_sheet_OVER_YEAR]
           SET
           [THIRD_QUART_INCOME] = (SELECT [Original_Balance] FROM [Tmp_IncomeReport_2]  WHERE [Balance_sheet_OVER_YEAR].ACC_CODE = [Tmp_IncomeReport_2].ACC_CODE)
END

IF @i = 4
BEGIN
UPDATE [dbo].[Balance_sheet_OVER_YEAR]
           SET
           [FOURTH_QUART_INCOME] = (SELECT [Original_Balance] FROM [Tmp_IncomeReport_2]  WHERE [Balance_sheet_OVER_YEAR].ACC_CODE = [Tmp_IncomeReport_2].ACC_CODE)
END



select @i = MIN(Quarter) FROM #TempQuarters WHERE Quarter > @i
END



-- تحديث التغير بين الربع الأول والثاني مع النسبة بالشكل المطلوب
UPDATE [Balance_sheet_OVER_YEAR]
SET FIRST_QUART_CHANGE_PERCENT_BETWEEN_FIRST_AND_SECOND = 
    CONCAT(CAST(((SECOND_QUART_INCOME - FIRST_QUART_INCOME) * 100.0 / FIRST_QUART_INCOME) AS DECIMAL(10, 1)), '%') WHERE FIRST_QUART_INCOME <> 0  --AND SECOND_QUART_INCOME <> 0  ;

-- تحديث التغير بين الربع الثالث والرابع مع النسبة بالشكل المطلوب
UPDATE [Balance_sheet_OVER_YEAR]
SET FIRST_QUART_CHANGE_PERCENT_BETWEEN_THIRD_AND_FOURTH = 
    CONCAT(CAST(((FOURTH_QUART_INCOME - THIRD_QUART_INCOME) * 100.0 / THIRD_QUART_INCOME) AS DECIMAL(10, 1)), '%') WHERE THIRD_QUART_INCOME <> 0  --AND FOURTH_QUART_INCOME <> 0 ;



	SELECT [T_ID] --AS 'ت'
      ,[ACC_NAME] --AS ' إسم الحساب '
      ,[ACC_CODE] --AS ' كود الحساب '
      ,[FIRST_QUART_INCOME] --AS ' الربــع الأول '
      ,[SECOND_QUART_INCOME]  --AS ' الربــع الثاني '
      ,[FIRST_QUART_CHANGE_PERCENT_BETWEEN_FIRST_AND_SECOND] --AS 'نسبة التغيــر'
      ,[THIRD_QUART_INCOME]  --AS ' الربــع الثالــث '
      ,[FOURTH_QUART_INCOME]  --AS ' الربــع الرابــع '
      ,[FIRST_QUART_CHANGE_PERCENT_BETWEEN_THIRD_AND_FOURTH]  --AS 'نسبة التغيــر'
  FROM [dbo].[Balance_sheet_OVER_YEAR]


 
END


GO
/****** Object:  StoredProcedure [dbo].[INCOME_STATMENT_FULL_STEPS]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[INCOME_STATMENT_FULL_STEPS](@DATE_F    DATE,@DATE_T DATE,@Hide_Zeros Bit,@Show_Symbol_Code Bit = 0,@Hide_ACC_CODE Bit = 1)ASBEGIN TRY
BEGIN TRANSACTION 

EXEC PREPARE_ACC_BALANCE 0,@DATE_F,@DATE_T,0

EXEC [Prepare_Income_Sheet] 

IF @Hide_Zeros = 1 BEGIN DELETE FROM Tmp_IncomeReport_2 WHERE Original_Balance = 0 and Total_Income is NULL END

UPDATE Tmp_IncomeReport_2 SET Result_Title = Group_Name     WHERE T_ID IS NULL AND ACC_CODE IS NULL
UPDATE Tmp_IncomeReport_2 SET Group_Name = NULL 


if @Show_Symbol_Code = 1
BEGIN

UPDATE Tmp_IncomeReport_2 SET Group_Name = ACC_CODE WHERE Total_Income IS NOT NULL
UPDATE Tmp_IncomeReport_2 SET ACC_CODE = 
(
SELECT concat(' ( ',[RESULT_ONE_CODE],' ',[Calc_BETWEEN_ONE_TWO],' ',[RESULT_TWO_CODE],' ) ') FROM Income_Group_Results WHERE [RESULT_CODE] = Tmp_IncomeReport_2.[ACC_CODE]
) 

END
ELSE
BEGIN
UPDATE Tmp_IncomeReport_2 SET Group_Name = NULL --,ACC_CODE = NULL 
if @Hide_ACC_CODE = 1 begin UPDATE Tmp_IncomeReport_2 SET ACC_CODE = NULL  end

END



SELECT
       [ACC_CODE]
      ,[Group_Name]
      ,[Result_Title]
      ,[ACC_NAME]
      ,[Sign]
      ,[Original_Balance]
      ,[Total_Income]
	  FROM Tmp_IncomeReport_2

 COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = ' [INCOME_STATMENT_FULL_STEPS] - ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH



GO
/****** Object:  StoredProcedure [dbo].[InSale_ALL_ST]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE PROCEDURE [dbo].[InSale_ALL_ST]
    @T_ID INT,
	@ST_ID int

AS
BEGIN
DECLARE @i INT ,
--@IM_ID	int,
@U_ID	int,
@Price	numeric(18, 2),
@D_Vaild NVARCHAR(50) = '',
@QYT	numeric(18, 2),
@Total	numeric(18, 2),
@ON_Update bit,
@Barcode nvarchar(50)



SELECT @i = min(IM_ID) from IM_STORE_View where ST_ID = @ST_ID and QTY > 0
while @i is not NULL
BEGIN

SELECT @U_ID = U_ID , @Price = COST , @D_Vaild = @D_Vaild , @QYT = QTY , @Total = T_Cost , @Barcode = Barcode 
FROM IM_STORE_View WHERE IM_ID = @i and QTY > 0 AND ST_ID = @ST_ID

IF @D_Vaild = '' BEGIN  SET @D_Vaild = NULL END

exec [dbo].[InSale_Details_Insert] 
@i,
@U_ID,
@ST_ID,
@T_ID,
@Price,
@D_Vaild,
@QYT,
@Total,
@ON_Update,
@Barcode


SELECT @i = min(IM_ID) from IM_STORE_View where ST_ID = @ST_ID AND IM_ID > @i  and QTY > 0
END




END
