CREATE PROCEDURE [dbo].[InSale_Details_Insert] 
@IM_ID	int,
@U_ID	int,
@ST_ID	int,
@InSale_T_ID	int,
@Price	numeric(18, 2),
@D_Vaild DATE = NULL,
@QYT	numeric(18, 2),
@Total	numeric(18, 2),
@ON_Update bit,
@Barcode nvarchar(50)

AS
BEGIN TRY
BEGIN TRANSACTION 


declare @ST_QTY NUMERIC(18,3),@U_Cargo FLOAT,@Valid_ST NVARCHAR(50) , @T_ID INT, @SPRICE FLOAT

SET @Valid_ST = @D_Vaild
IF @Valid_ST IS NULL BEGIN SET @Valid_ST ='' END

SELECT @U_Cargo = U_Cargo FROM Units WHERE U_ID = @U_ID
SELECT @ST_QTY = (U_Cargo * @QYT) FROM Units WHERE U_ID = @U_ID

SELECT @SPRICE = PRICE FROM IM_Units WHERE IM_ID = @IM_ID AND U_ID = @U_ID

EXEC @T_ID = [AA_GET_MAX_InSale_Details] 
INSERT INTO InSale_Details(T_ID,Date,InSale_T_ID,IM_ID,U_ID,ST_ID,Cost,D_Vaild,QYT,Total,U_Cargo,ST_QTY,isDepended,Barcode,PRICE)
Values(@T_ID,GETDATE(),@InSale_T_ID,@IM_ID,@U_ID,@ST_ID,@Price,@Valid_ST,@QYT,@Total,@U_Cargo,@ST_QTY,1,@Barcode,@SPRICE)

--SELECT @T_ID = SCOPE_IDENTITY()
IF @ON_Update = 1 BEGIN UPDATE InSale_Details  SET isDepended = 1 WHERE T_ID = @T_ID  END


--EXEC Dec_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY

EXEC [Recalculate_Agent_Bill_Total] @InSale_T_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('InSale_Details_Insert Proc',16,1,'خطأ')
ROLLBACK
END CATCH









































GO
