CREATE PROCEDURE [dbo].[InSale_Details_Update] 
@T_ID	int,
@Price	money,
@QYT	numeric(18, 2)

AS

declare @isError int
BEGIN TRAN

	UPDATE InSale_Details SET Cost =@Price , QYT = @QYT, Total = (@QYT*@Price),ST_QTY = (@QYT * U_Cargo)
	WHERE T_ID =@T_ID

	select @isError = @@ERROR 
	IF @isError <> 0 
	goto PROBLEM

		COMMIT TRAN

	PROBLEM:
	if @isError <> 0 begin
	print 'DB ERROR ! __ InSale_Details_Update'
	ROLLBACK TRAN

END






















































GO
