CREATE PROCEDURE [dbo].[InSale_SelectDetails_By_Date] 
@D_F DATE,
@D_T DATE,
@ST_ID INT,
@AG_ID INT
AS 

BEGIN

IF @ST_ID = 0 AND @AG_ID = 0
BEGIN
SELECT St_Name,Item_name,U_Name,SUM(QYT) AS S_QTY ,SUM(Price) AS S_T_Price FROM InSale_Details_Report_V
WHERE ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T ) Group By Item_name,U_Name,St_Name
END

ELSE IF @ST_ID > 0 AND @AG_ID = 0
BEGIN
SELECT St_Name,Item_name,U_Name,SUM(QYT) AS S_QTY ,SUM(Price) AS S_T_Price FROM InSale_Details_Report_V
WHERE ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T ) AND ST_ID = @ST_ID Group By Item_name,U_Name,St_Name
END

ELSE IF @ST_ID = 0 AND @AG_ID > 0
BEGIN
SELECT St_Name,Item_name,U_Name,SUM(QYT) AS S_QTY ,SUM(Price) AS S_T_Price FROM InSale_Details_Report_V
WHERE ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T ) AND AG_ID = @AG_ID Group By Item_name,U_Name,St_Name
END

ELSE IF @ST_ID > 0 AND @AG_ID > 0
BEGIN
SELECT St_Name,Item_name,U_Name,SUM(QYT) AS S_QTY ,SUM(Price) AS S_T_Price FROM InSale_Details_Report_V
WHERE ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T ) AND AG_ID = @AG_ID AND ST_ID = @ST_ID Group By Item_name,U_Name,St_Name
END


END































































