CREATE PROCEDURE [dbo].[item_menu_delete]
@IM_ID int


--AS
--BEGIN TRY
--BEGIN TRANSACTION 

AS
BEGIN



IF ( SELECT COUNT(IM_ID) FROM ST_Balance WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM IM_QTY_ALERT WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM FRM_Contents_Details WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM FRM_Details WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM Pch_Details WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM SB_Contents WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM Rtn_Contents WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM InSale_Details WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM IMEX_Details WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM ViewBill_Contents WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM ShortcutMenu WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM outSale_Details WHERE IM_ID = @IM_ID )  = 0
AND ( SELECT COUNT(IM_ID) FROM Store_Trans_Details WHERE IM_ID = @IM_ID )  = 0


BEGIN
delete from ST_QTY_Deferences where IM_ID=@IM_ID
delete from IM_Units where IM_ID = @IM_ID
delete from IM_Formating_Menu where IM_ID =@IM_ID
delete from IM_menu where IM_ID = @IM_ID

END
ELSE
BEGIN
raiserror('لايمكن حذف صنف عليها حركة',16,1,'خطأ')
END

END

