CREATE PROCEDURE [dbo].[item_menu_insert]
@IM_ID int OUTPUT,
@User_ID int,
@GM_ID int = NULL,
@isStore INT
AS
DECLARE @isError int,@Grp_ID INT ,@START_ID INT , @END_ID INT
BEGIN TRAN

SELECT @START_ID = START_ID ,@END_ID = END_ID FROM SERVERS

IF (SELECT TOP 1 IM_ID FROM IM_Menu WHERE Row_Enabled = 0 AND User_ID = @User_ID AND IM_ID BETWEEN @START_ID AND @END_ID) IS NULL

BEGIN

IF @GM_ID IS NULL BEGIN SELECT TOP 1 @GM_ID = GM_ID FROM General_menu END
SELECT TOP 1 @Grp_ID =  Grp_ID FROM Comp_Groups

EXEC @IM_ID = [AA_GET_MAX_IM_MENU]

INSERT INTO IM_Menu (IM_ID,item_name,item_nameSales,GM_ID,isStore,isValid,Cost,User_ID,Row_Enabled,isActive,is_Shortcut,Grp_ID)
VALUES(@IM_ID,'','',@GM_ID,@isStore,0,0,@User_ID,0,1,0,@Grp_ID)
--SELECT @IM_ID = SCOPE_IDENTITY()

END
ELSE
BEGIN
SELECT @IM_ID = IM_ID FROM IM_Menu WHERE User_ID = @User_ID AND Row_Enabled = 0 AND IM_ID BETWEEN @START_ID AND @END_ID
END

select @isError = @@ERROR 
IF @isError <> 0 
goto PROBLEM


		COMMIT TRAN

	PROBLEM:
	if @isError <> 0 begin
	raiserror ('DB ERROR [item_menu_insert]',16,1,'خطأ')
	ROLLBACK TRAN

END













































