SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[item_menu_update]
@IM_ID int,
@item_name nvarchar(200) ,
@item_nameSales nvarchar(100) = NULL,
@GM_ID int,
@photo image = null,
@isActive bit,
@isStore	int,
@isValid int,
@isNotif	bit = NULL,
@isChangePrice int,
@Cost FLOAT = 0,

@BK_R int = NULL,
@BK_G int = NULL,
@BK_B int = NULL,
@FK_R int = NULL,
@FK_G int = NULL,
@FK_B int = NULL,

@User_ID INT,
@is_Shortcut int,
@IM_Num	nvarchar(100),
@Grp_ID int =1,
@IM_Full_Photo	nvarchar(MAX) = NULL,
@Notes	nvarchar(MAX),
@Def_U_ID int,
@Markter_Val Numeric(18,3) = 0,
@Price_ONE Numeric(18,3) = NULL



--AS
--BEGIN

AS
BEGIN TRY
DECLARE @is_Default Bit , @U_IM_ID int , @U_Cargo Numeric(18,2), @Price Numeric(18,2) , @Auto_U_ID int,@BARCODE NVARCHAR(50)
BEGIN TRANSACTION 

EXEC @BARCODE = [AG_BalanceMV_GetSerial_Barcode]
--, photo=@photo
update IM_Menu set  item_name=@item_name
  , isActive=@isActive,item_nameSales=@item_nameSales,
GM_ID=@GM_ID,isStore=@isStore , isValid=@isValid , isChangePrice = @isChangePrice,Cost=@Cost,
BK_R = @BK_R , BK_G = @BK_G , BK_B = @BK_B , FK_R = @FK_R , FK_G = @FK_G , FK_B = @FK_B  ,Row_Enabled = 1 , is_Shortcut=@is_Shortcut
 , IM_Num = @IM_Num , Grp_ID = @Grp_ID , IM_Full_Photo = @IM_Full_Photo , Notes = @Notes , Markter_Val = @Markter_Val , photo=@photo
 WHERE IM_ID=@IM_ID

 IF @isValid = 0 BEGIN UPDATE ST_Balance SET D_Valid = '' WHERE IM_ID = @IM_ID END

 IF @isStore = 1 BEGIN SET @Auto_U_ID = @Def_U_ID END
 ELSE BEGIN SELECT TOP 1 @Auto_U_ID = U_ID FROM UNITS END

UPDATE IM_Units SET Row_Enabled = 1 WHERE IM_ID = @IM_ID
UPDATE IM_QTY_ALERT SET Row_Enabled = 1 WHERE IM_ID = @IM_ID


IF (SELECT COUNT(*) FROM IM_Units WHERE IM_ID = @IM_ID AND is_Default = 1) = 0
BEGIN
UPDATE IM_Units SET is_Default = 1
 WHERE U_IM_ID = (SELECT Top 1 U_IM_ID FROM IM_Units WHERE IM_ID = @IM_ID ORDER BY U_IM_ID DESC)


 SELECT @U_Cargo = U_Cargo FROM IM_Menu_Units_V WHERE IM_ID = @IM_ID

IF @U_Cargo > 1  AND (SELECT COUNT(*) FROM IM_Units WHERE IM_ID = @IM_ID) = 1
BEGIN
SELECT @Price = Price FROM IM_Menu_Units_V WHERE IM_ID = @IM_ID
EXEC @U_IM_ID = [AA_GET_MAX_IM_UNITS]
INSERT INTO IM_Units (U_IM_ID,IM_ID,U_ID,Price,is_Default,Row_Enabled,USER_ID,Barcode)
VALUES(@U_IM_ID,@IM_ID,@Def_U_ID,(@Price/@U_Cargo),0,1,@User_ID,@BARCODE)

END
END


IF (SELECT COUNT(*) FROM IM_Units WHERE IM_ID = @IM_ID) = 0  OR ( SELECT COUNT(*) FROM IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_CARGO = 1) = 0
BEGIN
EXEC @U_IM_ID = [AA_GET_MAX_IM_UNITS]
INSERT INTO IM_Units (U_IM_ID,IM_ID,U_ID,Price,is_Default,Row_Enabled,USER_ID,Barcode)
VALUES(@U_IM_ID,@IM_ID,@Auto_U_ID,0,1,1,@User_ID,@BARCODE)
END


IF @Price_ONE IS NOT NULL
BEGIN
UPDATE IM_Units SET Price = @Price_ONE WHERE IM_ID = @IM_ID AND is_Default = 1
END

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[item_menu_update] Proc',16,1,'خطأ')
ROLLBACK
END CATCH



--END








GO
/****** Object:  StoredProcedure [dbo].[item_menu_update_On_Mange_Form]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[item_menu_update_On_Mange_Form]
@IM_ID int,
@item_name nvarchar(200) ,
@item_nameSales nvarchar(100) = NULL,
@GM_ID int,
@photo image = null,
@isActive bit,
@User_ID INT,
@Def_U_ID int,
@Price_ONE Numeric(18,3) = NULL,
@IM_NUM NVARCHAR(500)
--AS
--BEGIN

AS
BEGIN TRY
DECLARE @is_Default Bit , @U_IM_ID int , @U_Cargo Numeric(18,2), @Price Numeric(18,2) , @Auto_U_ID INT,@BARCODE NVARCHAR(50)
BEGIN TRANSACTION 

EXEC @BARCODE = [AG_BalanceMV_GetSerial_Barcode]

update IM_Menu set  item_name=@item_name
, photo=@photo , isActive=@isActive,item_nameSales=@item_nameSales,GM_ID=@GM_ID ,Row_Enabled = 1, IM_Num = @IM_Num
 WHERE IM_ID=@IM_ID

SET @Auto_U_ID = 1

UPDATE IM_Units SET Row_Enabled = 1 WHERE IM_ID = @IM_ID
UPDATE IM_QTY_ALERT SET Row_Enabled = 1 WHERE IM_ID = @IM_ID

IF (SELECT COUNT(*) FROM IM_Units WHERE IM_ID = @IM_ID AND is_Default = 1) = 0
BEGIN
UPDATE IM_Units SET is_Default = 1
 WHERE U_IM_ID = (SELECT Top 1 U_IM_ID FROM IM_Units WHERE IM_ID = @IM_ID ORDER BY U_IM_ID DESC)


SELECT @U_Cargo = U_Cargo FROM IM_Menu_Units_V WHERE IM_ID = @IM_ID

IF @U_Cargo > 1  AND (SELECT COUNT(*) FROM IM_Units WHERE IM_ID = @IM_ID) = 1
BEGIN
SELECT @Price = Price FROM IM_Menu_Units_V WHERE IM_ID = @IM_ID

EXEC @U_IM_ID = [AA_GET_MAX_IM_UNITS]
INSERT INTO IM_Units (U_IM_ID,IM_ID,U_ID,Price,is_Default,Row_Enabled,USER_ID,Barcode)
VALUES(@U_IM_ID,@IM_ID,@Def_U_ID,(@Price/@U_Cargo),0,1,@User_ID,@BARCODE)

END
END


IF (SELECT COUNT(*) FROM IM_Units WHERE IM_ID = @IM_ID) = 0
BEGIN
EXEC @U_IM_ID = [AA_GET_MAX_IM_UNITS]
INSERT INTO IM_Units (U_IM_ID,IM_ID,U_ID,Price,is_Default,Row_Enabled,USER_ID,Barcode)
VALUES(@U_IM_ID,@IM_ID,@Auto_U_ID,0,1,1,@User_ID,@BARCODE)
END


IF @Price_ONE IS NOT NULL
BEGIN
UPDATE IM_Units SET Price = @Price_ONE WHERE IM_ID = @IM_ID AND is_Default = 1
END

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[item_menu_update_On_Mange_Form] Proc',16,1,'خطأ')
ROLLBACK
END CATCH



--END








GO
