CREATE PROCEDURE [dbo].[Outsale_Details_Delete] 
@T_ID	int		
AS
BEGIN TRY
BEGIN TRANSACTION 

DECLARE @ST_QTY NUMERIC(18,3),@IM_ID INT,@ST_ID INT,@D_Vaild NVARCHAR(50),@Outsale_T_ID INT
SELECT @IM_ID=IM_ID, @ST_ID=ST_ID,@D_Vaild=D_Vaild,@ST_QTY =ST_QTY , @Outsale_T_ID=Outsale_T_ID FROM Outsale_Details where T_ID = @T_ID


DELETE FROM Outsale_Details WHERE T_ID = @T_ID

--EXEC Dec_IM_QTY @IM_ID,@ST_ID,@D_Vaild,@ST_QTY

EXEC [Recalculate_Agent_Bill_Total]  @Outsale_T_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[Outsale_Details_Delete]',16,1,'خطأ')
ROLLBACK
END CATCH










GO
/****** Object:  StoredProcedure [dbo].[Outsale_Details_Insert]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Outsale_Details_Insert] 
@IM_ID	int,
@U_ID	int,
@ST_ID	int,
@Outsale_T_ID	int,
@Price	numeric(18, 3),
@D_Vaild DATE = NULL,
@QYT	numeric(18, 3),
@Total	numeric(18, 3),
@ON_Update bit,
@Barcode nvarchar(50),
@SPRICE FLOAT = 0

AS
BEGIN TRY
BEGIN TRANSACTION 
declare @ST_QTY NUMERIC(18,3),@U_Cargo FLOAT,@Valid_ST NVARCHAR(50) , @T_ID INT

SET @Valid_ST = @D_Vaild
IF @Valid_ST IS NULL BEGIN SET @Valid_ST ='' END

SELECT @U_Cargo = U_Cargo FROM Units WHERE U_ID = @U_ID
SELECT @ST_QTY = (U_Cargo * @QYT) FROM Units WHERE U_ID = @U_ID

--SELECT @SPRICE = PRICE FROM IM_Units WHERE IM_ID = @IM_ID AND U_ID = @U_ID

EXEC @T_ID = [AA_GET_MAX_Outsale_Details] 
INSERT INTO Outsale_Details(T_ID,Date,Outsale_T_ID,IM_ID,U_ID,ST_ID,Cost,D_Vaild,QYT,Total,U_Cargo,ST_QTY,isDepended,Barcode,PRICE)
Values(@T_ID,GETDATE(),@Outsale_T_ID,@IM_ID,@U_ID,@ST_ID,@Price,@Valid_ST,@QYT,@Total,@U_Cargo,@ST_QTY,1,@Barcode,@SPRICE)

--SELECT @T_ID = SCOPE_IDENTITY()
IF @ON_Update = 1 BEGIN UPDATE Outsale_Details  SET isDepended = 1 WHERE T_ID = @T_ID  END

EXEC [Recalculate_Agent_Bill_Total]  @Outsale_T_ID

--EXEC Inc_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('Outsale_Details_Insert Proc',16,1,'خطأ')
ROLLBACK
END CATCH
GO
