/****** Object:  StoredProcedure [dbo].[Pch_Details_Calc_Dis]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Pch_Details_Calc_Dis] 
@Pch_T_ID	int	,
@Dis	numeric(18, 3)
AS
BEGIN TRY
BEGIN TRANSACTION 
DECLARE   @SUM_QTY  NUMERIC(18,2) , @SUM_ADD_M NUMERIC(18,3) ,@i INT,@IM_ID INT

SELECT @SUM_QTY = ISNULL(SUM(QYT),0) FROM Pch_Details WHERE Pch_T_ID = @Pch_T_ID
SET @SUM_ADD_M = @Dis / @SUM_QTY
UPDATE Pch_Details SET Price = (Price - @SUM_ADD_M) , Total = ((Price - @SUM_ADD_M) * QYT ) WHERE Pch_T_ID = @Pch_T_ID


SELECT @i = min(T_ID) From Pch_Details WHERE Pch_T_ID = @Pch_T_ID
WHILE @i IS NOT NULL
BEGIN
SELECT @IM_ID = IM_ID FROM Pch_Details WHERE T_ID = @i
EXEC ReCount_IM_Main_COST @IM_ID
SELECT @i = min(T_ID) From Pch_Details WHERE Pch_T_ID = @Pch_T_ID AND T_ID > @i
END

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[Pch_Details_Calc_Dis]',16,1,'خطأ')
ROLLBACK
END CATCH












GO
