CREATE PROCEDURE [dbo].[Pch_Details_Calc_Tax] 
@Pch_T_ID	int	,
@Value	numeric(18, 3)
AS
--DECLARE   @SUM_QTY  NUMERIC(18,2) , @SUM_ADD_M NUMERIC(18,6) = 0
BEGIN
 
DECLARE @EXP_VALUE Numeric(18,3),@i INT, @DistributionType NVARCHAR(10), -- 'VALUE', 'WEIGHT', 'QUANTITY'
    @ItemValue Numeric(18,3),      -- قيمة الصنف
    @ItemWeight Numeric(18,3),     -- وزن الصنف
    @ItemQuantity Numeric(18,3),   -- كمية الصنف
    @TotalValues Numeric(18,3),    -- إجمالي القيم
    @TotalWeights Numeric(18,3),   -- إجمالي الأوزان
    @TotalQuantities Numeric(18,3),-- إجمالي الكميات
    @TotalExpenses Numeric(18,3),   -- إجمالي المصاريف (نقل + شحن + جمرك)
	@TotalExpenses_OUT Numeric(18,3)   -- إجمالي المصاريف (نقل + شحن + جمرك)
	 --@CalculatedTotal Numeric(18,3)
	


	SELECT @TotalValues = SUM(TOTAL) FROM Pch_Details WHERE Pch_T_ID = @Pch_T_ID
	SELECT @TotalWeights = SUM(QYT) FROM Pch_Details WHERE Pch_T_ID = @Pch_T_ID
	SELECT @TotalQuantities = SUM(QYT) FROM Pch_Details WHERE Pch_T_ID = @Pch_T_ID
	SELECT @TotalExpenses = SUM(VALUE) FROM [Pch_Exp_Values] WHERE Pch_T_ID = @Pch_T_ID --and isWithBill = 1


	SELECT @TotalExpenses_OUT = ISNULL(SUM(VALUE),0) FROM [Pch_Exp_Values] WHERE Pch_T_ID = @Pch_T_ID and isWithBill = 0
	UPDATE Agents_Balance_MV SET Reciept_Discount = @TotalExpenses_OUT WHERE T_ID = @Pch_T_ID


	UPDATE Pch_Details SET EXP_VALUE = 0 , Price = Org_Price  ,Total = (Org_Price * QYT ) WHERE Pch_T_ID = @Pch_T_ID



	--SELECT @CalculatedTotal = SUM(TOTAL) FROM Pch_Details WHERE Pch_T_ID = @Pch_T_ID;
	-- DECLARE @ExpectedTotal Numeric(18,3) = @CalculatedTotal + @TotalExpenses



	SELECT @i = min(T_ID) FROM Pch_Details WHERE Pch_T_ID = @Pch_T_ID
	WHILE @i IS NOT NULL
	BEGIN

		SELECT @ItemValue = Total ,@ItemWeight = QYT , @ItemQuantity = QYT    FROM Pch_Details WHERE T_ID = @i

	SET @EXP_VALUE = dbo.CalculateExpenseShare(
        'VALUE',           
        @ItemValue,
        @ItemWeight,
        @ItemQuantity,
        @TotalValues,
        @TotalWeights,
        @TotalQuantities,
        @TotalExpenses)/@ItemQuantity; 



	if @EXP_VALUE is not NULL BEGIN
	UPDATE Pch_Details SET EXP_VALUE = @EXP_VALUE , Price = (Org_Price + @EXP_VALUE) ,Total = ((Org_Price + @EXP_VALUE) * QYT ) WHERE T_ID = @i
	END



	SELECT @i = min(T_ID) FROM Pch_Details WHERE Pch_T_ID = @Pch_T_ID AND T_ID > @i
	END


	--SELECT @CalculatedTotal = SUM(TOTAL) FROM Pch_Details WHERE Pch_T_ID = @Pch_T_ID;
	
	--DECLARE @Difference Numeric(18,3) = @ExpectedTotal - @CalculatedTotal;

	--insert into a select @Difference

	--IF @Difference IS NOT NULL OR @Difference <> 0
	--BEGIN
	--UPDATE Pch_Details SET EXP_VALUE = (EXP_VALUE + @Difference) , Price = (Org_Price + EXP_VALUE + @Difference) ,Total = ((Org_Price + EXP_VALUE + @Difference) * QYT ) WHERE T_ID = 
	--(SELECT TOP 1 T_ID FROM Pch_Details ORDER BY Price DESC)
	--END


--SELECT @SUM_QTY = ISNULL(SUM(QYT),0) FROM Pch_Details WHERE Pch_T_ID = @Pch_T_ID
--SET @SUM_ADD_M = @Value / @SUM_QTY
--UPDATE Pch_Details SET Price = (Price + @SUM_ADD_M) , Total = ((Price + @SUM_ADD_M) * QYT ) WHERE Pch_T_ID = @Pch_T_ID

END












GO
