-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Pch_Details_Delete] 
@T_ID	int,
@On_Update bit

AS
BEGIN TRY
BEGIN TRANSACTION


DECLARE @ST_QTY NUMERIC(18,2),@U_Cargo NUMERIC(18,2),@U_ID INT,@IM_ID INT,@ST_ID INT,@D_Vaild NVARCHAR(50),@Pch_Bill_ID INT , @AG_ID INT
,@T_ID_ALTER INT
SELECT @U_Cargo = U_Cargo ,@IM_ID=IM_ID, @ST_ID=ST_ID,@D_Vaild=D_Vaild,@ST_QTY =ST_QTY,@Pch_Bill_ID = Pch_T_ID 
  FROM Pch_Details where T_ID = @T_ID


DELETE FROM Pch_Details WHERE T_ID = @T_ID

DELETE FROM Valid_Notes WHERE Pch_T_ID = @T_ID

IF (SELECT isStore FROM IM_Menu WHERE IM_ID = @IM_ID) IN (1,2)

BEGIN 
EXEC [CREATE_PCH_TMP_TABLE]
EXEC [ReCount_IM_Main_COST] @IM_ID
END

IF @On_Update = 1 BEGIN EXEC AG_Balance_Update_Pied_On_Update @Pch_Bill_ID,7 END 

--EXEC Dec_IM_QTY @IM_ID,@ST_ID,@D_Vaild,@ST_QTY 

 exec Recalculate_Agent_Bill_Total @Pch_Bill_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
 DECLARE @ErrorMessage NVARCHAR(4000);
  SELECT @ErrorMessage = ERROR_MESSAGE()
raiserror(@ErrorMessage,16,1,'خطأ')
ROLLBACK
END CATCH
GO
/****** Object:  StoredProcedure [dbo].[Pch_Details_Insert]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
