GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Pch_Details_Insert] 
@T_ID	int output,
@IM_ID	int,
@U_ID	int,
@Pch_T_ID	int ,
@Price	FLOAT,
@ST_ID int,
@D_Vaild DATE = NULL,
@QYT	numeric(18, 2),
@Total	FLOAT,
@NewSale numeric(18, 2) = NULL,	
@NewSaleByOne	numeric(18, 2)	= NULL,
@On_Update Bit,
@Min_SP_ByOne	numeric(18, 2) = NULL,
@Min_SP	numeric(18, 2) = NULL,
@Invoice_Type INT = NULL,
@Min_SP_2	numeric(18, 2) = NULL,
@Min_SP_2_ByOne	numeric(18, 2) = NULL,
@Barcode Nvarchar(100) = NULL,
@Price_By_Foriegn_Cr float	= NULL,
@Price_By_Equal	float	= NULL,
@Cr_ID	int	= NULL
AS
BEGIN TRY
BEGIN TRANSACTION 
declare @ST_QTY NUMERIC(18,2),@U_Cargo NUMERIC(18,2),@Valid_ST NVARCHAR(30),@j int , @PreQty numeric(18, 2) = 0 , @PrevCost FLOAT
,@AG_ID INT , @NEW_COST FLOAT = 0

SET @Valid_ST = @D_Vaild
IF @Valid_ST IS NULL BEGIN SET @Valid_ST ='' END

SELECT @U_Cargo = U_Cargo FROM Units WHERE U_ID = @U_ID
SELECT @ST_QTY = (U_Cargo * @QYT) FROM Units WHERE U_ID = @U_ID

EXEC @T_ID = [AA_GET_MAX_ID] 'Pch_Details'

INSERT INTO Pch_Details(T_ID,Date,Pch_T_ID,IM_ID,ST_ID,U_ID,Price,D_Vaild,QYT,Total,NewSale,NewSaleByOne,
U_Cargo,ST_QTY,isDepended,Min_SP_ByOne,Min_SP,Min_SP_2,Min_SP_2_ByOne,Barcode,Org_Price,Price_By_Foriegn_Cr,Price_By_Equal,Cr_ID)

Values(@T_ID,GETDATE(),@Pch_T_ID,@IM_ID,@ST_ID,@U_ID,@Price,@Valid_ST,@QYT,@Total,@NewSale,@NewSaleByOne,
@U_Cargo,@ST_QTY,1,@Min_SP_ByOne,@Min_SP,@Min_SP_2,@Min_SP_2_ByOne,@Barcode,@Price,@Price_By_Foriegn_Cr,@Price_By_Equal,@Cr_ID)

--SELECT @T_ID = SCOPE_IDENTITY();

  EXEC Inc_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY 

 IF (SELECT isStore FROM IM_Menu WHERE IM_ID = @IM_ID) IN (1,2) BEGIN 

--IF @Invoice_Type = 1 BEGIN
--DELETE FROM ST_Balance WHERE IM_ID = @IM_ID AND ST_ID = @ST_ID AND D_Valid = @Valid_ST
--IF (SELECT COUNT(*) FROM ST_Balance WHERE IM_ID = @IM_ID) = 0 BEGIN UPDATE IM_Menu SET Cost = 0 ,Last_Pch_Cargo = NULL , Last_PchT_ID = NULL END
--END

 UPDATE IM_Menu SET Last_PchT_ID = @T_ID , Last_Pch_Cargo = (@Price / @U_Cargo) Where IM_ID = @IM_ID

IF (SELECT isStore FROM IM_Menu WHERE IM_ID = @IM_ID) IN (1,2)
BEGIN
SELECT @PreQty = (ISNULL(SUM(QTY),0) - @ST_QTY) FROM ST_Balance_V WHERE IM_ID = @IM_ID
IF @PreQty > 0 
BEGIN
 SELECT @PrevCost = Cost From IM_Menu WHERE IM_ID = @IM_ID
 SELECT @NEW_COST = ( (@PrevCost * @PreQty) + ( (@Price/@U_Cargo) *  @ST_QTY ) ) / ( @PreQty + @ST_QTY  )

 UPDATE IM_Menu SET Cost = @NEW_COST  WHERE IM_ID = @IM_ID
 UPDATE Pch_Details SET AVG_COST =  @NEW_COST , AVG_COSTChange = ( @NEW_COST - @PrevCost) WHERE T_ID = @T_ID
END
ELSE
BEGIN UPDATE IM_Menu SET Cost = (@Price/@U_Cargo) WHERE IM_ID = @IM_ID 
UPDATE Pch_Details SET AVG_COST = (@Price/@U_Cargo) , AVG_COSTChange = (@Price/@U_Cargo)  WHERE T_ID = @T_ID 
END
END
-------------------------------------------------------------------------------

 IF @NewSale is Not NULL BEGIN
DECLARE @Tmp_Cargo Numeric(18,2)
SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID
WHILE @j is Not NULL
BEGIN
SELECT @Tmp_Cargo = U_Cargo FROM IM_Menu_Units_V  WHERE U_IM_ID = @j
UPDATE IM_Units SET Price = (@NewSale/@U_Cargo) * @Tmp_Cargo WHERE U_IM_ID = @j
SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID AND U_IM_ID > @j
END
END
---------------------------------------------------------------------------------
IF @NewSaleByOne is Not NULL BEGIN 
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V  WHERE IM_ID = @IM_ID And U_Cargo = 1
WHILE @j is Not NULL
BEGIN
 UPDATE IM_Units SET Price = @NewSaleByOne WHERE U_IM_ID = @j
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_Cargo = 1 AND U_IM_ID > @j
END
END
---------------------------------------------------------------------------------
IF @Min_SP is Not NULL BEGIN
SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID
WHILE @j is Not NULL
BEGIN
SELECT @Tmp_Cargo = U_Cargo FROM IM_Menu_Units_V  WHERE U_IM_ID = @j
UPDATE IM_Units SET Min_SP = (@Min_SP/@U_Cargo) * @Tmp_Cargo WHERE U_IM_ID = @j

SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID AND U_IM_ID > @j
END
END

-------------------------------------------------------------------------------

IF @Min_SP_ByOne is Not NULL BEGIN 
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V  WHERE IM_ID = @IM_ID And U_Cargo = 1
WHILE @j is Not NULL
BEGIN
 UPDATE IM_Units SET Min_SP = @Min_SP_ByOne WHERE U_IM_ID = @j
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_Cargo = 1 AND U_IM_ID > @j
END
END

----------------------------------------------------------------------------------------------------
IF @Min_SP_2 is Not NULL BEGIN
SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID
WHILE @j is Not NULL
BEGIN
SELECT @Tmp_Cargo = U_Cargo FROM IM_Menu_Units_V  WHERE U_IM_ID = @j
UPDATE IM_Units SET Min_SP_2 = (@Min_SP_2/@U_Cargo) * @Tmp_Cargo WHERE U_IM_ID = @j

SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID AND U_IM_ID > @j
END
END

-------------------------------------------------------------------------------

IF @Min_SP_2_ByOne is Not NULL BEGIN 
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V  WHERE IM_ID = @IM_ID And U_Cargo = 1
WHILE @j is Not NULL
BEGIN
 UPDATE IM_Units SET Min_SP_2 = @Min_SP_2_ByOne WHERE U_IM_ID = @j
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_Cargo = 1 AND U_IM_ID > @j
END
END

----------------------------------------------------------------------------------------------------

 END

 IF @On_Update = 1
 BEGIN
 UPDATE Pch_Details SET isDepended = 1 WHERE T_ID = @T_ID
 EXEC AG_Balance_Update_Pied_On_Update @Pch_T_ID,7
 END


 exec Recalculate_Agent_Bill_Total @Pch_T_ID


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = '[Pch_Details_Insert] ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH




































GO
