SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Pch_Details_Make_SP_SAME_COST]
@T_ID	int
AS
declare @i int,@IM_ID INT,@j int,@NewSale numeric(18, 2) = NULL,@NewSaleByOne NUMERIC(18,3),@Cost numeric(18, 2),
@PreQty numeric(18,2),@U_Cargo NUMERIC(18,2),@ST_ID INT ,@ST_QTY NUMERIC(18,2) ,@Price NUMERIC(18,2),@PrevCost NUMERIC(18,2) 
, @NEW_Cost NUMERIC(18,2)
 
BEGIN

SELECT @i = min(T_ID) From Pch_Details WHERE Pch_T_ID = @T_ID
WHILE @i IS NOT NULL
BEGIN

SELECT @IM_ID=IM_ID , @U_Cargo = U_Cargo , @Cost = Price ,  @ST_QTY = ST_QTY FROM Pch_Details WHERE T_ID = @i

SELECT @PreQty = ISNULL(SUM(ST_QTY),0) FROM ST_Balance WHERE IM_ID = @IM_ID

IF @PreQty > 0 
BEGIN
 SELECT @PrevCost = ISNULL(Cost,0) From IM_Menu WHERE IM_ID = @IM_ID
 SET @NEW_Cost = ( (@PrevCost * @PreQty) + ( (@Cost/@U_Cargo) *  @ST_QTY ) ) / ( @PreQty + @ST_QTY  )
END
ELSE
BEGIN
SET @NEW_Cost = (@Cost/@U_Cargo)
END

UPDATE Pch_Details SET NewSale = @NEW_Cost * @U_Cargo , NewSaleByOne = @NEW_Cost WHERE T_ID = @i


SELECT @i = min(T_ID) From Pch_Details WHERE Pch_T_ID = @T_ID AND T_ID > @i
END

END














GO
