GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Pch_Details_Ret_Dis] 
@Pch_T_ID	int	

AS
BEGIN TRY
BEGIN TRANSACTION 

DECLARE   @SUM_QTY  NUMERIC(18,2) , @SUM_ADD_M NUMERIC(18,3),@Dis	numeric(18, 3)

SELECT @SUM_QTY = ISNULL(SUM(QYT),0) FROM Pch_Details WHERE Pch_T_ID = @Pch_T_ID

SELECT @Dis = ISNULL(Discount,0) FROM Agents_Balance_MV WHERE T_ID = @Pch_T_ID 
SET @SUM_ADD_M = @Dis / @SUM_QTY
UPDATE Pch_Details SET Price = (Price + @SUM_ADD_M) , Total = ((Price + @SUM_ADD_M) * QYT ) WHERE Pch_T_ID = @Pch_T_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[Pch_Details_Ret_Dis]',16,1,'خطأ')
ROLLBACK
END CATCH












GO
