AS
DECLARE @Pch_T_ID INT , @VALUE_EXP NUMERIC(18,2) = 0 , @SUM_QTY  NUMERIC(18,2) , @SUM_ADD_M NUMERIC(18,2) = 0
BEGIN

SELECT @Pch_T_ID = Pch_T_ID , @VALUE_EXP = VALUE   FROM [Pch_Exp_Values] WHERE T_ID = @T_ID

DELETE FROM  [dbo].[Pch_Exp_Values] WHERE T_ID = @T_ID


--SELECT @SUM_QTY = ISNULL(SUM(QYT),0) FROM Pch_Details WHERE Pch_T_ID = @Pch_T_ID

--IF @SUM_QTY > 0 
