@isWithBill BIT
AS
DECLARE   @SUM_QTY  NUMERIC(18,2) , @SUM_ADD_M NUMERIC(18,6) = 0
BEGIN
INSERT INTO [dbo].[Pch_Exp_Values]
           ([Pch_T_ID]
           ,[Value]
           ,[Notes_ID]
		   ,[isWithBill])
     VALUES (@Pch_T_ID,@Value,@Notes_ID,@isWithBill)


EXEC Pch_Details_Calc_Tax @Pch_T_ID,@Value

END














