/****** Object:  StoredProcedure [dbo].[Pch_IM_Unit_Change]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Pch_IM_Unit_Change] 
@Pch_T_ID int,
@IM_T_ID int,
@U_ID int,
@QTY Numeric(18,2) = NULL,
@Price FLOAT,
@Notes NVARCHAR(MAX),
@NewSale numeric(18, 3) = NULL,	
@NewSaleByOne	numeric(18, 3)	= NULL,
@On_Update Bit
AS
DECLARE @Bill_T_ID INT,@U_Cargo NUMERIC(18,2),@IM_ID INT,@ST_ID int ,@D_Valid NVARCHAR(20) = '' , @NEW_ST_QTY FLOAT , @PREV_ST_QTY FLOAT,@j int
,@ST_QTY_DEF FLOAT = 0, @PreQty numeric(18, 2),@PrevCost FLOAT,@AG_ID INT , @DATE DATETIME ,  @PreQty_Past numeric(18, 2)
,@TMP_COSTChange FLOAT = 0, @TMP_AVG_CHANGE FLOAT = 0 , @AVG_COST FLOAT = 0 , @LAST_AVG_COST FLOAT = 0 , @TOTAL NUMERIC(18,3)

BEGIN TRY
BEGIN TRANSACTION 


SELECT @IM_ID  = IM_ID,@Bill_T_ID = PCH_T_ID , @ST_ID = ST_ID , @D_Valid = D_Vaild , @DATE = DATE FROM Pch_Details WHERE T_ID = @IM_T_ID
IF @Price IS NULL BEGIN SELECT @Price = PRICE FROM IM_Menu_Units_V WHERE U_ID = @U_ID AND IM_ID = @IM_ID  END
SELECT @U_Cargo = U_Cargo FROM IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_ID = @U_ID
SELECT @PREV_ST_QTY = ST_QTY FROM Pch_Details WHERE T_ID = @IM_T_ID


IF @QTY IS NULL
BEGIN
SELECT @NEW_ST_QTY = QYT FROM Pch_Details WHERE T_ID = @IM_T_ID 
SELECT @NEW_ST_QTY = (@NEW_ST_QTY * @U_Cargo)
UPDATE Pch_Details SET U_ID=@U_ID,Price=@Price, Total = (@Price * QYT) , U_Cargo = @U_Cargo , ST_QTY = @NEW_ST_QTY 
, Notes=@Notes
 WHERE T_ID = @IM_T_ID
 END
 ELSE
 BEGIN
 SELECT @NEW_ST_QTY = (@U_Cargo * @QTY) 
 UPDATE Pch_Details SET U_ID=@U_ID , QYT=@QTY , Price=@Price , Total = (@Price * @QTY) 
 , U_Cargo = @U_Cargo , ST_QTY = @NEW_ST_QTY , Notes=@Notes
 WHERE T_ID = @IM_T_ID
 END


 UPDATE Pch_Details SET U_ID=@U_ID , QYT=@QTY , Price=@Price , Total = (@Price * @QTY) , U_Cargo = @U_Cargo , ST_QTY = (@U_Cargo * @QTY) 
,Notes = @Notes , NewSale = @NewSale , NewSaleByOne = @NewSaleByOne WHERE T_ID = @IM_T_ID

SELECT @ST_QTY_DEF = (@NEW_ST_QTY - @PREV_ST_QTY)


--IF ( (SELECT isStore FROM IM_Menu WHERE IM_ID = @IM_ID) IN (1,2) )
-- AND ( @On_Update = 1 )
--AND (SELECT MAX(T_ID) FROM Pch_Details WHERE IM_ID = @IM_ID) > @IM_T_ID
--BEGIN
EXEC [ReCount_IM_Main_COST] @IM_ID
--END

---------------------------------------------------------------------------------------------------------------------------------
--SELECT @PreQty = (ISNULL(SUM(ST_QTY),0) - @NEW_ST_QTY) FROM ST_Balance WHERE IM_ID = @IM_ID
--EXEC @PreQty_Past  =  CALC_IM_QTY_IN_specific_Range_Date @IM_ID,@DATE


--SELECT @TMP_COSTChange = ISNULL(AVG_COSTChange,0) FROM Pch_Details WHERE T_ID = @IM_T_ID
--SELECT @TMP_AVG_CHANGE = ISNULL(AVG_COST,0) FROM Pch_Details WHERE T_ID = @IM_T_ID

--IF @TMP_COSTChange = @TMP_AVG_CHANGE
--BEGIN
--SELECT @PrevCost = @TMP_COSTChange
--END
--ELSE
--BEGIN

--IF @TMP_COSTChange < 0
--BEGIN SELECT @PrevCost = @TMP_AVG_CHANGE + ( @TMP_COSTChange * -1) END
--ELSE
--BEGIN  SELECT @PrevCost = @TMP_AVG_CHANGE - @TMP_COSTChange END

--END


--IF @PreQty_Past > 0 
--BEGIN


--SELECT @AVG_COST = ( (@PrevCost * @PreQty_Past) + ( (@Price/@U_Cargo) *  @NEW_ST_QTY ) ) / ( @PreQty_Past + @NEW_ST_QTY  )

--UPDATE Pch_Details SET AVG_COST = @AVG_COST WHERE T_ID = @IM_T_ID


--SELECT TOP 1 @LAST_AVG_COST = ISNULL(AVG_COST,0) FROM Pch_Details  WHERE isDepended = 1 AND DATE < @DATE AND IM_ID = @IM_ID ORDER BY DATE DESC


--DECLARE @T FLOAT = 0
--SELECT @T = ( AVG_COST - @LAST_AVG_COST ) -  AVG_COSTChange FROM Pch_Details WHERE T_ID = @IM_T_ID
--INSERT INTO A VALUES (@T,0,0,0)


--UPDATE Pch_Details SET AVG_COSTChange =  ( AVG_COST - @LAST_AVG_COST )  WHERE T_ID = @IM_T_ID


--UPDATE Pch_Details SET AVG_COST = AVG_COST + ( @T * ST_QTY) 
--, AVG_COSTChange = AVG_COSTChange +  @T   WHERE isDepended = 1 AND DATE > @DATE AND IM_ID = @IM_ID 


--END
--ELSE
--BEGIN
--UPDATE Pch_Details SET AVG_COST = (@Price/@U_Cargo) ,  AVG_COSTChange = (@Price/@U_Cargo) WHERE T_ID = @IM_T_ID 
--END

--IF @PreQty > 0 
--BEGIN
--UPDATE IM_Menu SET Cost =  (SELECT ISNULL(SUM(AVG_COSTChange),0) FROM Pch_Details WHERE isDepended = 1 AND IM_ID = @IM_ID )
--END
--ELSE
--BEGIN UPDATE IM_Menu SET Cost = (@Price/@U_Cargo) WHERE IM_ID = @IM_ID 
--END
----------------------------------------------------------------------------------------------------------------------------------------------------



 EXEC Inc_IM_QTY @IM_ID,@ST_ID,@D_Valid,@ST_QTY_DEF
 EXEC Pch_Details_SELECT_Bill @Bill_T_ID 

  IF @NewSale is Not NULL BEGIN
DECLARE @Tmp_Cargo Numeric(18,2)
SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID
WHILE @j is Not NULL
BEGIN
SELECT @Tmp_Cargo = U_Cargo FROM IM_Menu_Units_V  WHERE U_IM_ID = @j
UPDATE IM_Units SET Price = (@NewSale/@U_Cargo) * @Tmp_Cargo WHERE U_IM_ID = @j
SELECT @j = min(U_IM_ID) From IM_Units WHERE IM_ID = @IM_ID AND U_IM_ID > @j
END
END
---------------------------------------------------------------------------------
IF @NewSaleByOne is Not NULL BEGIN 
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V  WHERE IM_ID = @IM_ID And U_Cargo = 1
WHILE @j is Not NULL
BEGIN
 UPDATE IM_Units SET Price = @NewSaleByOne WHERE U_IM_ID = @j
SELECT @j = min(U_IM_ID) From IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_Cargo = 1 AND U_IM_ID > @j
END
END



 IF @On_Update = 1 BEGIN EXEC AG_Balance_Update_Pied_On_Update @Pch_T_ID,7 END

  exec Recalculate_Agent_Bill_Total @Pch_T_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
declare  @err nvarchar(3000)= ERROR_MESSAGE()
raiserror(@err,16,1,'خطأ')
ROLLBACK
END CATCH



--END






GO
