CREATE PROCEDURE [dbo].[Pch_SelectDetails_By_Date] 
@D_F DATE,
@D_T DATE,
@ST_ID INT
AS 

BEGIN
IF @ST_ID = 0
BEGIN
SELECT St_Name,Item_name,U_Name,SUM(QYT) AS S_QTY ,SUM(Price) AS S_T_Price FROM Pch_Details_Report_V
WHERE ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T ) Group By Item_name,U_Name,St_Name
END
ELSE
BEGIN
SELECT St_Name,Item_name,U_Name,SUM(QYT) AS S_QTY ,SUM(Price) AS S_T_Price FROM Pch_Details_Report_V
WHERE ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T ) AND ST_ID = @ST_ID  Group By Item_name,U_Name,St_Name
END


END




































































