/****** Object:  StoredProcedure [dbo].[PiedUp_Table]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[PiedUp_Table] 
@Pr_ID INT,
@TB_ID	INT,	
@AG_ID INT,
@Tr_ID INT,
@USER_ID INT,
@Total FLOAT,
@TB_Info NVARCHAR(100),
@is_Debit BIT,
@Pay_ID int = 1
AS
SET DEADLOCK_PRIORITY NORMAL

BEGIN TRY
BEGIN TRANSACTION



declare @T_ID int,@Receipt_Num int,@TRMV_T_ID INT,@T_ID_2 INT ,@Receipt_Title NVARCHAR(2500),@DATE DATETIME

-------------------------------------------------------------------
SELECT @DATE = GETDATE()
UPDATE TABLES SET TB_ORDER_CODE = NULL , Start_Open = NULL , is_Print = 0 WHERE TB_ID = @TB_ID

--UPDATE SB_Contents SET isDepended = 1 WHERE Bill_T_ID IN 
--(SELECT T_ID FROM Agents_Balance_MV WHERE Table_ID = @TB_ID AND isPied = 0 AND isDepended = 1 AND isVoid = 0)


IF @is_Debit = 0
BEGIN
Update Agents_Balance_MV SET Total = Pure ,  Credit = Pure ,isPied = 1,isDepended = 1 , Receipt_Title = @TB_Info ,
User_ID = @USER_ID , Pr_ID = @Pr_ID WHERE T_ID IN 
(
SELECT T_ID FROM Agents_Balance_MV WHERE Table_ID = @TB_ID AND isPied = 0 AND isDepended = 1 AND isVoid = 0
)
END
ELSE
BEGIN
Update Agents_Balance_MV SET AG_ID = @AG_ID , Total = Pure ,  Credit = Pure ,isPied = 1,isDepended = 1 , Receipt_Title = ' ديـن لـ  ' + @TB_Info 
,User_ID = @USER_ID , Pr_ID = @Pr_ID WHERE T_ID IN 
(
SELECT T_ID FROM Agents_Balance_MV WHERE Table_ID = @TB_ID AND isPied = 0 AND isDepended = 1 AND isVoid = 0
)

UPDATE Periods SET Debit += @Total  WHERE Pr_ID = @Pr_ID
END



IF @Total > 0 AND @is_Debit = 0
BEGIN

SET @Receipt_Title = ' تسديد ' + @TB_Info
EXEC [Agents_BalanceMV_insert_RCT]
0,
@DATE,
0,--@Receipt_Num
@AG_ID,
@Pr_ID,
@T_ID,--@Receipt_Tran_ID
'',--@ReferNum
@Receipt_Title,
@Total,--@Pure
NULL,--@About
3,--@BsType_ID
@User_ID ,
@Tr_ID,
'',--BANK_NAME
'',--CHECK_NUMBER
@Pay_ID

END


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
	print 'DB ERROR ! __ [PiedUp_Table]'
ROLLBACK
END CATCH
















GO
/****** Object:  StoredProcedure [dbo].[PostAgentBalanceInvoiceToAccounting]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PostAgentBalanceInvoiceToAccounting]
    @T_ID INT,
    @UserId INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

		DECLARE @Rows dbo.ACC_BALANCE_BULK_TYPE,@DATE DATETIME,@OP_Status NVARCHAR(2500),@ERROR_MSG NVARCHAR(2500),@NextNumber NVARCHAR(50),@New_B_T_ID INT,
           @SB_ID INT,@Pch_ID int ,@IMEX_ID int ,@Jrd_ID int ,@SRtn_ID int ,@PRtn_ID	int ,@ST_Tran_ID int ,@EXP_ID int ,@InSale_ID int ,@OutSale_ID int, @Frm_ID int;


        ------------------------------------------------------------
        -- المتغيرات العامة
        ------------------------------------------------------------
        DECLARE
            @BsType_ID INT,
            @DocDate DATETIME,
            @ReceiptTitle NVARCHAR(550),
            @AG_ID INT,
            @Total NUMERIC(18,3),
            @Discount NUMERIC(18,3),
            @Pure NUMERIC(18,3),
            @IsDepended INT,
            @IsVoid INT,
            @ExistingJournalId INT,

            @JournalId INT,
            @DetailId INT,

            @AgentAccountCode VARCHAR(50),

            @SalesAccountCode VARCHAR(50),
            @SalesReturnAccountCode VARCHAR(50),
            @CapitalAccountCode VARCHAR(50),
            @CostOfGoodsSoldAccountCode VARCHAR(50),
            @PurchaseAccountCode VARCHAR(50),
            @PurchaseReturnAccountCode VARCHAR(50),
            @DamageExpenseAccountCode VARCHAR(50),
            @ManufacturingExpenseAccountCode VARCHAR(50),
            @InventoryAdjustmentGainAccountCode VARCHAR(50),
            @InventoryAdjustmentLossAccountCode VARCHAR(50),
            @DiscountAllowedAccountCode VARCHAR(50),
            @DiscountReceivedAccountCode VARCHAR(50),
            @GeneralExpenseAccountCode VARCHAR(50),

            @CurrencyId INT,
            @CurrencyEqual NUMERIC(18,3),

            @DebitTotal NUMERIC(18,3),
            @CreditTotal NUMERIC(18,3),

            @SalesTotal NUMERIC(18,3),
            @CostTotal NUMERIC(18,3),
            @ExpenseTotal NUMERIC(18,3),
            @DamageTotal NUMERIC(18,3),
            @ReturnTotal NUMERIC(18,3),
            @ManufacturingTotal NUMERIC(18,3),
			@PurchaseTotal NUMERIC(18,3),
			@InventoryGainTotal NUMERIC(18,3),
            @InventoryLossTotal NUMERIC(18,3),
			@TransferTotal NUMERIC(18,3);
        ------------------------------------------------------------
        -- 1. قراءة رأس الحركة من Agents_Balance_MV
        ------------------------------------------------------------
        SELECT
            @BsType_ID = BsType_ID,
            @DocDate = [Date],
            @ReceiptTitle = Receipt_Title,
            @AG_ID = AG_ID,
            @Total = ISNULL(Total, 0),
            @Discount = ISNULL(Discount, 0),
            @Pure = ISNULL(Pure, 0),
            @IsDepended = isDepended,
            @IsVoid = isVoid,
            @ExistingJournalId = JournalId,
			@DATE = DATE,
			@SB_ID = SB_ID,
			@Pch_ID = Pch_ID ,
			@IMEX_ID = IMEX_ID,
			@SRtn_ID = SRtn_ID,
			@PRtn_ID = PRtn_ID,
			@EXP_ID = EXP_ID,
			@Frm_ID = Frm_ID,
			@Jrd_ID = Jrd_ID,
            @ST_Tran_ID = ST_Tran_ID

        FROM dbo.Agents_Balance_MV
        WHERE T_ID = @T_ID;

        IF @BsType_ID IS NULL
        BEGIN
            RAISERROR(N'الحركة غير موجودة في جدول Agents_Balance_MV.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        IF ISNULL(@IsVoid, 0) = 1
        BEGIN
            RAISERROR(N'لا يمكن ترحيل حركة ملغاة.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        IF ISNULL(@IsDepended, 0) <> 1
        BEGIN
            RAISERROR(N'لا يمكن ترحيل حركة غير معتمدة.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        IF @ExistingJournalId IS NOT NULL
        BEGIN
            RAISERROR(N'هذه الحركة مرحلة محاسبياً من قبل.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        ------------------------------------------------------------
        -- منع ترحيل الإيصالات من هذا الإجراء
        ------------------------------------------------------------
        IF @BsType_ID IN (3, 4)
        BEGIN
            RAISERROR(N'الإيصالات لا ترحل من هذا الإجراء. استخدم إجراء ترحيل الإيصالات.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        ------------------------------------------------------------
        -- 2. قراءة إعدادات الحسابات الافتراضية
        ------------------------------------------------------------
        SELECT TOP 1
            @SalesAccountCode = SalesAccountCode,
            @SalesReturnAccountCode = SalesReturnAccountCode,
            @CapitalAccountCode = CapitalAccountCode,
            @CostOfGoodsSoldAccountCode = CostOfGoodsSoldAccountCode,
            @PurchaseAccountCode = PurchaseAccountCode,
            @PurchaseReturnAccountCode = PurchaseReturnAccountCode,
            @DamageExpenseAccountCode = DamageExpenseAccountCode,
            @ManufacturingExpenseAccountCode = ManufacturingExpenseAccountCode,
            @InventoryAdjustmentGainAccountCode = InventoryAdjustmentGainAccountCode,
            @InventoryAdjustmentLossAccountCode = InventoryAdjustmentLossAccountCode,
            @DiscountAllowedAccountCode = DiscountAllowedAccountCode,
            @DiscountReceivedAccountCode = DiscountReceivedAccountCode,
            @GeneralExpenseAccountCode = GeneralExpenseAccountCode,
            @CurrencyId = DefaultCurrencyId,
            @CurrencyEqual = DefaultCurrencyEqual
        FROM dbo.AccountingPostingSettings
        WHERE IsActive = 1
        ORDER BY Id DESC;

        IF @SalesAccountCode IS NULL
        BEGIN
            RAISERROR(N'لا توجد إعدادات ربط محاسبي فعالة في AccountingPostingSettings.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        IF @CurrencyId IS NULL
            SET @CurrencyId = 1;

        IF @CurrencyEqual IS NULL OR @CurrencyEqual = 0
            SET @CurrencyEqual = 1;

        ------------------------------------------------------------
        -- 3. قراءة حساب الطرف AG_ID
        -- لا نحتاجه في التالف أو التصنيع غالباً، لكنه مطلوب للمبيعات والمرتجعات والمصروفات
        ------------------------------------------------------------
        IF @AG_ID IS NOT NULL
        BEGIN
            SELECT @AgentAccountCode = Tree_Code FROM dbo.Agents WHERE  AG_ID = @AG_ID
        END

        ------------------------------------------------------------
        -- 6. فاتورة مبيعات BsType_ID = 1
        --
        -- القيد:
        -- من حـ/ العميل              Pure
        -- من حـ/ الخصم المسموح       Discount إن وجد
        --      إلى حـ/ المبيعات       إجمالي تفاصيل البيع
        --
        -- وقيد التكلفة:
        -- من حـ/ تكلفة المبيعات
        --      إلى حـ/ المخزون
        ------------------------------------------------------------
        IF @BsType_ID = 1
        BEGIN
            IF @AgentAccountCode IS NULL
            BEGIN
                RAISERROR(N'لا يمكن ترحيل فاتورة المبيعات: العميل غير مربوط بحساب محاسبي.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

            IF @Discount > 0 AND @DiscountAllowedAccountCode IS NULL
            BEGIN
                RAISERROR(N'يوجد خصم في فاتورة المبيعات ولم يتم تحديد حساب الخصم المسموح.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

            SELECT
                @SalesTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0),
                @CostTotal = ISNULL(SUM(ISNULL(Cost, 0) * ISNULL(QTY, 0)), 0)
            FROM dbo.SB_Contents
            WHERE Bill_T_ID = @T_ID
              AND ISNULL(isDepended, 0) = 1;

            IF ISNULL(@SalesTotal, 0) <= 0
            BEGIN
                RAISERROR(N'لا توجد تفاصيل مبيعات معتمدة لهذه الفاتورة.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

            ---- مدين العميل بالصافي Pure

INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
VALUES           (1, @AgentAccountCode, NULL, @Pure, 1, N'طرف مدين', N'', 1)

            -- مدين الخصم المسموح إن وجد
            IF ISNULL(@Discount, 0) > 0
            BEGIN

			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            VALUES           (2, @DiscountAllowedAccountCode, NULL, @Discount, 1, N'خصم مسموح لفاتورة مبيعات رقم ' + CAST(@SB_ID AS NVARCHAR(50)),N'', 1)

            END

            -- دائن المبيعات

			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            VALUES           (3, @SalesAccountCode, @SalesTotal, NULL, 1, N'إيراد فاتورة مبيعات رقم ' + CAST(@SB_ID AS NVARCHAR(50)),N'', 1)

            -- تكلفة المبيعات / المخزون
            IF ISNULL(@CostTotal, 0) > 0
            BEGIN
                IF @CostOfGoodsSoldAccountCode IS NULL --OR @InventoryAccountCode IS NULL
                BEGIN
                    RAISERROR(N'لا يمكن ترحيل تكلفة المبيعات: حساب التكلفة غير محدد.', 16, 1);
                    ROLLBACK TRANSACTION;
                    RETURN;
                END


			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            VALUES           (4, @CostOfGoodsSoldAccountCode, NULL, @CostTotal, 1, N'تكلفة بضاعة مباعة لفاتورة رقم ' + CAST(@SB_ID AS NVARCHAR(50)),N'', 1)


   -- تحقق أن كل المخازن الموجودة في تفاصيل الفاتورة مربوطة بحساب مخزون
IF EXISTS
(
    SELECT 1
    FROM dbo.SB_Contents_V  
    WHERE Bill_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1
      AND ISNULL(Cost, 0) * ISNULL(QTY, 0) > 0
      AND TREE_CODE IS NULL
)
BEGIN
    RAISERROR(N'لا يمكن الترحيل: يوجد مخزن غير مربوط بحساب مخزون في الدليل.', 16, 1);
    ROLLBACK TRANSACTION;
    RETURN;
END



   			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            SELECT           5, TREE_CODE, SUM(ISNULL(d.Cost, 0) * ISNULL(d.QTY, 0)), NULL, 1, N'خروج مخزون لفاتورة مبيعات رقم ' + CAST(@SB_ID AS NVARCHAR(50)),N'', 1

			FROM dbo.SB_Contents_V d
WHERE Bill_T_ID = @T_ID
  AND ISNULL(isDepended, 0) = 1
  AND ISNULL(Cost, 0) * ISNULL(QTY, 0) > 0
GROUP BY TREE_CODE;
			

            END
       END

