-- مصروفات عامة BsType_ID = 2
-- من حـ/ حساب المصروف حسب EX_ID
--      إلى حـ/ الطرف AGENT
------------------------------------------------------------
ELSE IF @BsType_ID = 2
BEGIN
    IF @AgentAccountCode IS NULL
    BEGIN
        RAISERROR(N'لا يمكن ترحيل المصروفات: الطرف غير مربوط بحساب محاسبي.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    IF EXISTS
    (
        SELECT 1
        FROM EXP_Details_V WHERE IMEX_T_ID = @T_ID
          AND ISNULL(isDepended, 0) = 1
          AND Tree_Code IS NULL
    )
    BEGIN
        RAISERROR(N'لا يمكن ترحيل المصروفات: يوجد بند مصروف غير مربوط بحساب محاسبي.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    SELECT @ExpenseTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
    FROM dbo.EXP_Details
    WHERE IMEX_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1;

    IF ISNULL(@ExpenseTotal, 0) <= 0
    BEGIN
        RAISERROR(N'لا توجد تفاصيل مصروفات معتمدة لهذه الحركة.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

	   -- تحقق أن كل المصروفات الموجودة في تفاصيل الفاتورة مربوطة بحساب الصمروف
IF EXISTS
(
    SELECT 1
    FROM dbo.EXP_Details_V  
    WHERE IMEX_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1
      AND ISNULL(Price, 0) * ISNULL(QYT, 0) > 0
      AND TREE_CODE IS NULL
)
BEGIN
    RAISERROR(N'لا يمكن الترحيل: يوجد مصروف غير مربوط بحساب مصروف في الدليل.', 16, 1);
    ROLLBACK TRANSACTION;
    RETURN;
END


    ---- مدين: حسابات المصروفات حسب EX_ID

			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            SELECT          5, m.Tree_Code, SUM(ISNULL(m.Total, 0)),NULL, 1, N'مصروفات للحركة رقم ' + CAST(@EXP_ID AS NVARCHAR(50)),N'', 1
			 FROM dbo.EXP_Details_V m  WHERE isDepended = 1 and IMEX_T_ID = @T_ID
    GROUP BY m.Tree_Code;
	
    ---- دائن الطرف

				INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            VALUES           (6, @AgentAccountCode, NULL,@ExpenseTotal, 1, N'استحقاق مصروفات على الطرف للحركة رقم ' + CAST(@EXP_ID AS NVARCHAR(50)),N'', 1)

END


------------------------------------------------------------
-- فاتورة مشتريات BsType_ID = 7
--
-- القيد:
-- من حـ/ مخزون المخزن
--      إلى حـ/ المورد
--      إلى حـ/ الخصم المكتسب إن وجد
------------------------------------------------------------
ELSE IF @BsType_ID = 7
BEGIN
    IF @AgentAccountCode IS NULL
    BEGIN
        RAISERROR(N'لا يمكن ترحيل فاتورة المشتريات: المورد غير مربوط بحساب محاسبي.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    IF ISNULL(@Discount, 0) > 0 AND @DiscountReceivedAccountCode IS NULL
    BEGIN
        RAISERROR(N'يوجد خصم في فاتورة المشتريات ولم يتم تحديد حساب الخصم المكتسب.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    SELECT @PurchaseTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
    FROM dbo.Pch_Details
    WHERE Pch_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1;

    IF ISNULL(@PurchaseTotal, 0) <= 0
    BEGIN
        RAISERROR(N'لا توجد تفاصيل مشتريات معتمدة لهذه الفاتورة.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    /*
        مهم:
        هذا الجزء يفترض وجود View باسم Pch_Details_V
        يحتوي TREE_CODE الخاص بحساب مخزون المخزن.
        إذا لم يكن موجودًا، أنشئه بنفس فكرة SB_Contents_V.
    */

    IF EXISTS
    (
        SELECT 1
        FROM dbo.Pch_Details_V
        WHERE Pch_T_ID = @T_ID
          AND ISNULL(isDepended, 0) = 1
          AND ISNULL(Total, 0) > 0
          AND TREE_CODE IS NULL
    )
    BEGIN
        RAISERROR(N'لا يمكن الترحيل: يوجد مخزن في تفاصيل المشتريات غير مربوط بحساب مخزون في الدليل.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    -- مدين المخزون حسب المخزن
    INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
    SELECT
        17,
        TREE_CODE,
        NULL,
        SUM(ISNULL(Total, 0)),
        1,
        N'إدخال مخزون من فاتورة مشتريات رقم ' + CAST(@Pch_ID AS NVARCHAR(50)),
        N'',
        1
    FROM dbo.Pch_Details_V
    WHERE Pch_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1
      AND ISNULL(Total, 0) > 0
    GROUP BY TREE_CODE;

    -- دائن المورد بالصافي
    INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
    VALUES
    (
        18,
        @AgentAccountCode,
        @Pure,
        NULL,
        1,
        N'استحقاق مورد عن فاتورة مشتريات رقم ' + CAST(@Pch_ID AS NVARCHAR(50)),
        N'',
        1
    );

    -- دائن الخصم المكتسب إن وجد
    IF ISNULL(@Discount, 0) > 0
    BEGIN
        INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
        VALUES
        (
            19,
            @DiscountReceivedAccountCode,
            @Discount,
            NULL,
            1,
            N'خصم مكتسب لفاتورة مشتريات رقم ' + CAST(@Pch_ID AS NVARCHAR(50)),
            N'',
            1
        );
    END
END



------------------------------------------------------------
