--
-- القيد:
-- من حـ/ مخزون المخزن
--      إلى حـ/ رأس المال / حقوق الملكية
------------------------------------------------------------
ELSE IF @BsType_ID = 9
BEGIN
    --IF @AgentAccountCode IS NULL
    --BEGIN
    --    RAISERROR(N'لا يمكن ترحيل فاتورة المشتريات: المورد غير مربوط بحساب محاسبي.', 16, 1);
    --    ROLLBACK TRANSACTION;
    --    RETURN;
    --END

    --IF ISNULL(@Discount, 0) > 0 AND @DiscountReceivedAccountCode IS NULL
    --BEGIN
    --    RAISERROR(N'يوجد خصم في فاتورة المشتريات ولم يتم تحديد حساب الخصم المكتسب.', 16, 1);
    --    ROLLBACK TRANSACTION;
    --    RETURN;
    --END

    SELECT @PurchaseTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
    FROM dbo.Pch_Details
    WHERE Pch_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1;

    IF ISNULL(@PurchaseTotal, 0) <= 0
    BEGIN
        RAISERROR(N'لا توجد تفاصيل جرد معتمدة لهذه الفاتورة.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    /*
        مهم:
        هذا الجزء يفترض وجود View باسم Pch_Details_V
        يحتوي TREE_CODE الخاص بحساب مخزون المخزن.
        إذا لم يكن موجودًا، أنشئه بنفس فكرة SB_Contents_V.
    */

    IF EXISTS
    (
        SELECT 1
        FROM dbo.Pch_Details_V
        WHERE Pch_T_ID = @T_ID
          AND ISNULL(isDepended, 0) = 1
          AND ISNULL(Total, 0) > 0
          AND TREE_CODE IS NULL
    )
    BEGIN
        RAISERROR(N'لا يمكن الترحيل: يوجد مخزن في تفاصيل الجرد غير مربوط بحساب مخزون في الدليل.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    -- مدين المخزون حسب المخزن
    INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
    SELECT
        17,
        TREE_CODE,
        NULL,
        SUM(ISNULL(Total, 0)),
        1,
        N'إدخال مخزون من فاتورة جرد رقم ' + CAST(@Pch_ID AS NVARCHAR(50)),
        N'',
        1
    FROM dbo.Pch_Details_V
    WHERE Pch_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1
      AND ISNULL(Total, 0) > 0
    GROUP BY TREE_CODE;

    -- دائن المورد بالصافي
    INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
    VALUES
    (
        18,
        @CapitalAccountCode,
        @Pure,
        NULL,
        1,
        N'زيادة رأس مال عن فاتورة جرد رقم ' + CAST(@Pch_ID AS NVARCHAR(50)),
        N'',
        1
    );


END


        ------------------------------------------------------------
        -- 8. فاتورة تالف BsType_ID = 8
        --
        -- القيد:
        -- من حـ/ مصروف التالف
        --      إلى حـ/ المخزون
        ------------------------------------------------------------
        ELSE IF @BsType_ID = 8
        BEGIN
            IF @DamageExpenseAccountCode IS NULL --OR @InventoryAccountCode IS NULL
            BEGIN
                RAISERROR(N'لا يمكن ترحيل التالف: حساب التالف غير محدد.', 16, 1);
