            FROM dbo.IMEX_Details
            WHERE IMEX_T_ID = @T_ID
              AND ISNULL(isDepended, 0) = 1;

            IF ISNULL(@DamageTotal, 0) <= 0
            BEGIN
                RAISERROR(N'لا توجد تفاصيل تالف معتمدة لهذه الحركة.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

		    INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            VALUES           (7, @DamageExpenseAccountCode, NULL,@DamageTotal, 1, N'إثبات تالف للحركة رقم ' + CAST(@IMEX_ID AS NVARCHAR(50)),N'', 1)


			   -- تحقق أن كل المخازن الموجودة في تفاصيل الفاتورة مربوطة بحساب مخزون
IF EXISTS
(
    SELECT 1
    FROM dbo.IMEX_Details_V  
    WHERE IMEX_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1
      AND ISNULL(Cost, 0) * ISNULL(QYT, 0) > 0
      AND TREE_CODE IS NULL
)
BEGIN
    RAISERROR(N'لا يمكن الترحيل: يوجد مخزن غير مربوط بحساب مخزون في الدليل.', 16, 1);
    ROLLBACK TRANSACTION;
    RETURN;
END


		INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
   --         VALUES           (8, @InventoryAccountCode, NULL,@DamageTotal, 1, N'تخفيض المخزون بسبب التالف للحركة رقم ' + CAST(@IMEX_ID AS NVARCHAR(50)),N'', 1)

               SELECT           8, TREE_CODE, SUM(ISNULL(d.Cost, 0) * ISNULL(d.QYT, 0)), NULL, 1, N'تخفيض المخزون بسبب التالف للحركة رقم ' + CAST(@IMEX_ID AS NVARCHAR(50)),N'', 1

			FROM dbo.IMEX_Details_V d
WHERE IMEX_T_ID = @T_ID
  AND ISNULL(isDepended, 0) = 1
  AND ISNULL(Cost, 0) * ISNULL(QYT, 0) > 0
GROUP BY TREE_CODE;
			

        END



---------------------------------------------------------- <تحت  الصيانة>
-- فاتورة تسوية BsType_ID = 39
--
-- إذا الفرق موجب:
-- من حـ/ المخزون
--      إلى حـ/ أرباح تسوية مخزون
--
-- إذا الفرق سالب:
-- من حـ/ خسائر تسوية مخزون
--      إلى حـ/ المخزون
------------------------------------------------------------
ELSE IF @BsType_ID = 39
BEGIN
    IF @InventoryAdjustmentGainAccountCode IS NULL
    BEGIN
        RAISERROR(N'لا يمكن ترحيل الجرد: حساب أرباح تسوية المخزون غير محدد.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    IF @InventoryAdjustmentLossAccountCode IS NULL
    BEGIN
        RAISERROR(N'لا يمكن ترحيل الجرد: حساب خسائر تسوية المخزون غير محدد.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    /*
        هذا الجزء يفترض وجود View باسم Jrd_Details_V
        يحتوي:
        Jrd_T_ID,
        TREE_CODE,
        TotalDiff,
        isDepended
    */

    IF EXISTS
    (
        SELECT 1
        FROM dbo.ST_QTY_Deferences_Details_V
        WHERE Bill_T_ID = @T_ID
          --AND ISNULL(isDepended, 0) = 1
          --AND ISNULL(TOTAL, 0) <> 0
          AND TREE_CODE IS NULL
    )
    BEGIN
        RAISERROR(N'لا يمكن ترحيل الجرد: يوجد مخزن غير مربوط بحساب مخزون في الدليل.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    SELECT
        @InventoryGainTotal = ISNULL(SUM(CASE WHEN Total > 0 THEN Total ELSE 0 END), 0),
        @InventoryLossTotal = ISNULL(SUM(CASE WHEN Total < 0 THEN ABS(Total) ELSE 0 END), 0)
    FROM dbo.ST_QTY_Deferences_Details_V
    WHERE Bill_T_ID = @T_ID
      --AND ISNULL(isDepended, 0) = 1;

    IF ISNULL(@InventoryGainTotal, 0) = 0 AND ISNULL(@InventoryLossTotal, 0) = 0
    BEGIN
        RAISERROR(N'لا توجد فروقات جردية معتمدة لهذه الحركة.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    -- زيادة جردية: مدين المخزون حسب المخزن
    IF ISNULL(@InventoryGainTotal, 0) > 0
    BEGIN
        INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
        SELECT
            20,
            TREE_CODE,
            SUM(Total),
            NULL,
            1,
            N'زيادة جردية للحركة رقم ' + CAST(@Jrd_ID AS NVARCHAR(50)),
            N'',
            1
        FROM dbo.ST_QTY_Deferences_Details_V
        WHERE Bill_T_ID = @T_ID
          --AND ISNULL(isDepended, 0) = 1
          AND Total > 0
        GROUP BY TREE_CODE;

        -- دائن أرباح التسوية
        INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
        VALUES
        (
            21,
            @InventoryAdjustmentGainAccountCode,
            NULL,
            @InventoryGainTotal,
            1,
            N'أرباح تسوية جرد للحركة رقم ' + CAST(@Jrd_ID AS NVARCHAR(50)),
            N'',
            1
        );
    END

    -- عجز جردي: مدين خسائر التسوية
    IF ISNULL(@InventoryLossTotal, 0) > 0
    BEGIN
        INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
        VALUES
        (
            22,
            @InventoryAdjustmentLossAccountCode,
            @InventoryLossTotal,
            NULL,
            1,
            N'خسائر تسوية جرد للحركة رقم ' + CAST(@Jrd_ID AS NVARCHAR(50)),
            N'',
            1
        );

        -- دائن المخزون حسب المخزن
        INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
        SELECT
            23,
            TREE_CODE,
            NULL,
            SUM(ABS(Bill_T_ID)),
            1,
            N'عجز جردي للحركة رقم ' + CAST(@Jrd_ID AS NVARCHAR(50)),
            N'',
            1
        FROM dbo.ST_QTY_Deferences_Details_V
        WHERE Bill_T_ID = @T_ID
          --AND ISNULL(isDepended, 0) = 1
          AND Total < 0
        GROUP BY TREE_CODE;
    END
END



        ------------------------------------------------------------
        -- 9. إرجاع مبيعات BsType_ID = 10
        --
        -- القيد:
        -- من حـ/ مردودات المبيعات
        --      إلى حـ/ العميل
        --
        -- عكس التكلفة:
        -- من حـ/ المخزون
        --      إلى حـ/ تكلفة المبيعات
        ------------------------------------------------------------
        ELSE IF @BsType_ID = 10
        BEGIN
            IF @AgentAccountCode IS NULL
            BEGIN
                RAISERROR(N'لا يمكن ترحيل إرجاع المبيعات: العميل غير مربوط بحساب محاسبي.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

            IF @SalesReturnAccountCode IS NULL
            BEGIN
                RAISERROR(N'لا يمكن ترحيل إرجاع المبيعات: حساب مردودات المبيعات غير محدد.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

            SELECT
                @ReturnTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0),
                @CostTotal = ISNULL(SUM(ISNULL(Cost, 0) * ISNULL(QTY, 0)), 0)
            FROM dbo.Rtn_Contents
            WHERE Bill_T_ID = @T_ID
              AND Rtn_Type_ID = 1
              AND ISNULL(isDepended, 0) = 1;

            IF ISNULL(@ReturnTotal, 0) <= 0
            BEGIN
                RAISERROR(N'لا توجد تفاصيل إرجاع مبيعات معتمدة لهذه الحركة.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            VALUES           (9, @SalesReturnAccountCode, NULL,@ReturnTotal, 1, N'مردودات مبيعات للحركة رقم ' + CAST(@SRtn_ID AS NVARCHAR(50)),N'', 1)

            -- دائن العميل

			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            VALUES           (10, @AgentAccountCode, @ReturnTotal,NULL, 1, N'تخفيض مديونية العميل بسبب إرجاع مبيعات رقم ' + CAST(@SRtn_ID AS NVARCHAR(50)),N'', 1)

            -- عكس تكلفة المبيعات
            IF ISNULL(@CostTotal, 0) > 0
            BEGIN
                IF @CostOfGoodsSoldAccountCode IS NULL --OR @InventoryAccountCode IS NULL  
                BEGIN
                    RAISERROR(N'لا يمكن ترحيل عكس تكلفة إرجاع المبيعات: حساب التكلفة غير محدد.', 16, 1);
                    ROLLBACK TRANSACTION;
                    RETURN;
                END


IF EXISTS
(
    SELECT 1
    FROM dbo.Rtn_Contents_V  
    WHERE Bill_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1
      AND ISNULL(Cost, 0) * ISNULL(QTY, 0) > 0
      AND TREE_CODE IS NULL
)
BEGIN
    RAISERROR(N'لا يمكن الترحيل: يوجد مخزن غير مربوط بحساب مخزون في الدليل.', 16, 1);
    ROLLBACK TRANSACTION;
    RETURN;
END


			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            --VALUES           (11, @InventoryAccountCode, @CostTotal,NULL, 1, N'رجوع مخزون من إرجاع مبيعات رقم ' + CAST(@SRtn_ID AS NVARCHAR(50)),N'', 1)

			 SELECT           11, TREE_CODE, NULL, SUM(ISNULL(d.Cost, 0) * ISNULL(d.QTY, 0)), 1, N'رجوع مخزون من إرجاع مبيعات رقم ' + CAST(@SRtn_ID AS NVARCHAR(50)),N'', 1
			FROM dbo.Rtn_Contents_V d
			
WHERE Bill_T_ID = @T_ID AND Rtn_Type_ID = 1
  AND ISNULL(isDepended, 0) = 1
  AND ISNULL(Cost, 0) * ISNULL(QTY, 0) > 0
GROUP BY TREE_CODE;



			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            VALUES           (12, @CostOfGoodsSoldAccountCode, @CostTotal,NULL, 1, N'عكس تكلفة بضاعة مباعة لإرجاع مبيعات رقم ' + CAST(@SRtn_ID AS NVARCHAR(50)),N'', 1)

            END
        END


        ------------------------------------------------------------
        -- 10. إرجاع مشتريات BsType_ID = 11
        --
        -- القيد:
        -- من حـ/ المورد
        --      إلى حـ/ المخزون
        ------------------------------------------------------------
        ELSE IF @BsType_ID = 11
        BEGIN
            IF @AgentAccountCode IS NULL
            BEGIN
                RAISERROR(N'لا يمكن ترحيل إرجاع المشتريات: المورد غير مربوط بحساب محاسبي.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

            --IF @InventoryAccountCode IS NULL
            --BEGIN
            --    RAISERROR(N'لا يمكن ترحيل إرجاع المشتريات: حساب المخزون غير محدد.', 16, 1);
            --    ROLLBACK TRANSACTION;
            --    RETURN;
            --END

            SELECT @ReturnTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0)
            FROM dbo.Rtn_Contents
            WHERE Bill_T_ID = @T_ID
              AND Rtn_Type_ID = 7
              AND ISNULL(isDepended, 0) = 1;

            IF ISNULL(@ReturnTotal, 0) <= 0
            BEGIN
                RAISERROR(N'لا توجد تفاصيل إرجاع مشتريات معتمدة لهذه الحركة.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END


IF EXISTS
(
    SELECT 1
    FROM dbo.Rtn_Contents_V  
    WHERE Bill_T_ID = @T_ID
	  AND Rtn_Type_ID = 7
      AND ISNULL(isDepended, 0) = 1
      AND ISNULL(Price, 0) * ISNULL(QTY, 0) > 0
      AND TREE_CODE IS NULL
)
BEGIN
    RAISERROR(N'لا يمكن الترحيل: يوجد مخزن غير مربوط بحساب مخزون في الدليل.', 16, 1);
    ROLLBACK TRANSACTION;
    RETURN;
END

            ---- مدين المورد

		    INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            VALUES           (13, @AgentAccountCode, NULL,@ReturnTotal, 1, N'تخفيض مستحقات المورد بسبب إرجاع مشتريات رقم ' + CAST(@PRtn_ID AS NVARCHAR(50)),N'', 1)

            -- دائن المخزون

			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            --VALUES           (14, @AgentAccountCode, NULL,@ReturnTotal, 1, N'خروج مخزون بسبب إرجاع مشتريات رقم ' + CAST(@PRtn_ID AS NVARCHAR(50)),N'', 1)

			SELECT           14, TREE_CODE, SUM(ISNULL(d.Price, 0) * ISNULL(d.QTY, 0)), NULL, 1, N'خروج مخزون بسبب إرجاع مشتريات رقم ' + CAST(@PRtn_ID AS NVARCHAR(50)),N'', 1

			FROM dbo.Rtn_Contents_V d			
            WHERE Bill_T_ID = @T_ID AND Rtn_Type_ID = 7
            AND ISNULL(isDepended, 0) = 1
            AND ISNULL(Price, 0) * ISNULL(QTY, 0) > 0
            GROUP BY TREE_CODE;

        END




		------------------------------------------------------------
-- إذن تحويل أصناف بين المخازن BsType_ID = 12
--
-- القيد:
-- من حـ/ مخزون المخزن الداخل
--      إلى حـ/ مخزون المخزن الخارج
------------------------------------------------------------
ELSE IF @BsType_ID = 12
BEGIN
    /*
        هذا الجزء يفترض وجود View باسم St_Trans_V
        يحتوي:
        B_T_ID,
        TREE_CODE_ST_FROM,
        TREE_CODE_ST_TO,
        T_Price,
        isDepended
    */

    IF EXISTS
    (
        SELECT 1
        FROM dbo.St_Trans_V
        WHERE B_T_ID = @T_ID
          AND ISNULL(isDepended, 0) = 1
          AND ISNULL(T_Price, 0) > 0
          AND (TREE_CODE_ST_FROM IS NULL OR TREE_CODE_ST_TO IS NULL)
    )
    BEGIN
        RAISERROR(N'لا يمكن ترحيل التحويل: يوجد مخزن صادر أو وارد غير مربوط بحساب مخزون في الدليل.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    SELECT @TransferTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0)
    FROM dbo.St_Trans_V
    WHERE B_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1;

    IF ISNULL(@TransferTotal, 0) <= 0
    BEGIN
        RAISERROR(N'لا توجد تفاصيل تحويل أصناف معتمدة لهذه الحركة.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    -- مدين مخزون المخزن الداخل
    INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
    SELECT
        24,
        TREE_CODE_ST_TO,
        SUM(ISNULL(T_Price, 0)),
        NULL,
        1,
        N'دخول مخزون من تحويل أصناف رقم ' + CAST(@ST_Tran_ID AS NVARCHAR(50)),
        N'',
        1
    FROM dbo.St_Trans_V
    WHERE B_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1
      AND ISNULL(T_Price, 0) > 0
    GROUP BY TREE_CODE_ST_TO;

    -- دائن مخزون المخزن الخارج
    INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
    SELECT
        25,
        TREE_CODE_ST_FROM,
        NULL,
        SUM(ISNULL(T_Price, 0)),
        1,
        N'خروج مخزون من تحويل أصناف رقم ' + CAST(@ST_Tran_ID AS NVARCHAR(50)),
        N'',
        1
    FROM dbo.St_Trans_V
    WHERE B_T_ID = @T_ID
      AND ISNULL(isDepended, 0) = 1
      AND ISNULL(T_Price, 0) > 0
    GROUP BY TREE_CODE_ST_FROM;
END






        ------------------------------------------------------------
        -- 11. استهلاك تصنيع BsType_ID = 14
        --
        -- القيد:
        -- من حـ/ تكلفة تصنيع
        --      إلى حـ/ المخزون
        ------------------------------------------------------------
        ELSE IF @BsType_ID = 14
        BEGIN
            IF @ManufacturingExpenseAccountCode IS NULL
                SET @ManufacturingExpenseAccountCode = @CostOfGoodsSoldAccountCode;

            IF @ManufacturingExpenseAccountCode IS NULL --OR @InventoryAccountCode IS NULL
            BEGIN
                RAISERROR(N'لا يمكن ترحيل استهلاك التصنيع: حساب التصنيع غير محدد.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

            SELECT @ManufacturingTotal = ISNULL(SUM(ISNULL(Cost, 0) * ISNULL(QYT, 0)), 0)
            FROM dbo.FRM_Contents_Details
            WHERE Bill_T_ID = @T_ID
              AND ISNULL(isDepended, 0) = 1;

            IF ISNULL(@ManufacturingTotal, 0) <= 0
            BEGIN
                RAISERROR(N'لا توجد تفاصيل استهلاك تصنيع معتمدة لهذه الحركة.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            VALUES           (15, @ManufacturingExpenseAccountCode, @ManufacturingTotal,NULL, 1, N'استهلاك تصنيع للحركة رقم ' + CAST(@FRM_ID AS NVARCHAR(50)),N'', 1)


			INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
            --VALUES           (16, @InventoryAccountCode, NULL,@ManufacturingTotal, 1, N'خروج مخزون لاستهلاك تصنيع رقم ' + CAST(@FRM_ID AS NVARCHAR(50)),N'', 1)

	   		SELECT           16, TREE_CODE, NULL, SUM(ISNULL(d.Cost, 0) * ISNULL(d.QYT, 0)), 1, N'خروج مخزون لاستهلاك تصنيع رقم ' + CAST(@FRM_ID AS NVARCHAR(50)),N'', 1

			FROM dbo.FRM_Contents_V d			
            WHERE Bill_T_ID = @T_ID 
            AND ISNULL(isDepended, 0) = 1
            AND ISNULL(Cost, 0) * ISNULL(QYT, 0) > 0
            GROUP BY TREE_CODE;


        END

        ------------------------------------------------------------
        -- نوع غير مدعوم
        ------------------------------------------------------------
        ELSE
        BEGIN
            RAISERROR(N'نوع الحركة غير مدعوم حالياً في إجراء ترحيل الفواتير.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        ------------------------------------------------------------
        -- 12. فحص توازن القيد
        ------------------------------------------------------------
        SELECT
            @DebitTotal = ISNULL(SUM(ISNULL(DEBIT, 0)), 0),
            @CreditTotal = ISNULL(SUM(ISNULL(CREDIT, 0)), 0)
        FROM @ROWS
        --WHERE B_T_ID = @JournalId
        --  AND IS_VOID = 0;

        IF @DebitTotal <> @CreditTotal
        BEGIN
            DECLARE @Msg NVARCHAR(1000);

            SET @Msg = N'القيد غير متوازن. إجمالي المدين = ' 
                     + CAST(@DebitTotal AS NVARCHAR(50))
                     + N'، إجمالي الدائن = '
                     + CAST(@CreditTotal AS NVARCHAR(50));

            RAISERROR(@Msg, 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END


	EXEC dbo.ACC_BALANCE_proc_BULK
    @B_T_ID = @JournalId,
    @DATE = @DATE,
    @USER_ID = @UserId,
    @IS_VOID = 0,
    @Notes_MASTER = N'قيد يومية ألي',
    @Cr_ID = 1,
    @Currency_Equal = 1,
    @Rows = @Rows,
    @OP_Status = @OP_Status OUTPUT,
    @ERROR_MSG = @ERROR_MSG OUTPUT,
    @NextNumber = @NextNumber OUTPUT,
    @New_B_T_ID = @New_B_T_ID OUTPUT;


        ------------------------------------------------------------
        -- 13. تحديث الحركة وربطها بالقيد
        ------------------------------------------------------------
        UPDATE dbo.Agents_Balance_MV
        SET
            JournalId = @New_B_T_ID,
            PostedAt = GETDATE(),
            PostedBy = @UserId
        WHERE T_ID = @T_ID;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @ErrorMessage NVARCHAR(4000);
        SET @ErrorMessage = ERROR_MESSAGE();

        RAISERROR(@ErrorMessage, 16, 1);
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[PostAgentBalanceReceiptToAccounting]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PostAgentBalanceReceiptToAccounting]
    @T_ID INT,
    @UserId INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

		
			DECLARE @Rows dbo.ACC_BALANCE_BULK_TYPE,@DATE DATETIME,@OP_Status NVARCHAR(2500),@ERROR_MSG NVARCHAR(2500),@NextNumber NVARCHAR(50),@New_B_T_ID INT;
        ------------------------------------------------------------
        -- المتغيرات
        ------------------------------------------------------------
        DECLARE
            @BsType_ID INT,
            @DocDate DATETIME,
            @ReceiptTitle NVARCHAR(550),
            @ReceiptNum INT,
            @AG_ID INT,
            @Tr_ID INT,
            @Total NUMERIC(18,3),
            @Discount NUMERIC(18,3),
            @Pure NUMERIC(18,3),
            @IsDepended INT,
            @IsVoid INT,
            @ExistingJournalId INT,

            @JournalId INT,
            @DetailId INT,

            @AgentAccountCode VARCHAR(50),
            @TreasuryAccountCode VARCHAR(50),

			@DiscountAllowedAccountCode VARCHAR(50),
            @DiscountReceivedAccountCode VARCHAR(50),
            @ReceiptAmount NUMERIC(18,3),

            @CurrencyId INT,
            @CurrencyEqual NUMERIC(18,3),

            @DebitTotal NUMERIC(18,3),
            @CreditTotal NUMERIC(18,3);

        ------------------------------------------------------------
        -- 1. قراءة رأس الإيصال
        ------------------------------------------------------------
        SELECT
            @BsType_ID = BsType_ID,
            @DocDate = [Date],
            @ReceiptTitle = Receipt_Title,
            @ReceiptNum = Receipt_Num,
            @AG_ID = AG_ID,
            @Tr_ID = Tr_ID,
            @Total = ISNULL(Total, 0),
            @Discount = ISNULL(Discount, 0),
            @Pure = ISNULL(Pure, 0),
            @IsDepended = isDepended,
            @IsVoid = isVoid,
            @ExistingJournalId = JournalId,
			@DATE = DATE
        FROM dbo.Agents_Balance_MV_RCT
        WHERE T_ID = @T_ID;

        IF @BsType_ID IS NULL
        BEGIN
            RAISERROR(N'الإيصال غير موجود في جدول Agents_Balance_MV_RCT.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        IF ISNULL(@IsVoid, 0) = 1
        BEGIN
            RAISERROR(N'لا يمكن ترحيل إيصال ملغى.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        IF ISNULL(@IsDepended, 0) <> 1
        BEGIN
            RAISERROR(N'لا يمكن ترحيل إيصال غير معتمد.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        IF @ExistingJournalId IS NOT NULL
        BEGIN
            RAISERROR(N'هذا الإيصال مرحل محاسبياً من قبل.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        IF @BsType_ID NOT IN (3, 4)
        BEGIN
            RAISERROR(N'نوع الإيصال غير مدعوم. الإجراء يدعم إيصال قبض 3 وإيصال صرف 4 فقط.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        IF ISNULL(@Pure, 0) <= 0
        BEGIN
            RAISERROR(N'لا يمكن ترحيل إيصال بقيمة صفر أو قيمة غير صحيحة.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        ------------------------------------------------------------
        -- 2. قراءة العملة الافتراضية من إعدادات الربط
        ------------------------------------------------------------
        SELECT TOP 1
            @CurrencyId = DefaultCurrencyId,
            @CurrencyEqual = DefaultCurrencyEqual,
			@DiscountAllowedAccountCode = DiscountAllowedAccountCode,
            @DiscountReceivedAccountCode = DiscountReceivedAccountCode
        FROM dbo.AccountingPostingSettings
        WHERE IsActive = 1
        ORDER BY Id DESC;

        IF @CurrencyId IS NULL
            SET @CurrencyId = 1;

        IF @CurrencyEqual IS NULL OR @CurrencyEqual = 0
            SET @CurrencyEqual = 1;

        ------------------------------------------------------------
        -- 3. جلب حساب الطرف AG_ID
        ------------------------------------------------------------
        IF @AG_ID IS NOT NULL
        BEGIN
            SELECT @AgentAccountCode = Tree_Code FROM dbo.Agents WHERE  AG_ID = @AG_ID
        END

        IF @AgentAccountCode IS NULL
        BEGIN
            RAISERROR(N'لا يمكن ترحيل الإيصال: الطرف AG_ID غير مربوط بحساب محاسبي.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

		IF ISNULL(@Discount, 0) > 0 AND @BsType_ID = 3 AND @DiscountAllowedAccountCode IS NULL
BEGIN
    RAISERROR(N'لا يمكن ترحيل إيصال القبض: يوجد خصم ولم يتم تحديد حساب الخصم المسموح.', 16, 1);
    ROLLBACK TRANSACTION;
    RETURN;
END

IF ISNULL(@Discount, 0) > 0 AND @BsType_ID = 4 AND @DiscountReceivedAccountCode IS NULL
BEGIN
    RAISERROR(N'لا يمكن ترحيل إيصال الصرف: يوجد خصم ولم يتم تحديد حساب الخصم المكتسب.', 16, 1);
    ROLLBACK TRANSACTION;
    RETURN;
END

        ------------------------------------------------------------
        -- 4. جلب حساب الخزينة Tr_ID
        ------------------------------------------------------------
        --SELECT @TreasuryAccountCode = ACC_CODE
        --FROM dbo.AccountingEntityMap
        --WHERE EntityType = 'TREASURY'
        --  AND EntityId = @Tr_ID
        --  AND IsActive = 1;

		IF @Tr_ID IS NOT NULL
        BEGIN
        SELECT @TreasuryAccountCode = Tree_Code FROM dbo.TreasuryCard WHERE  Tr_ID = @Tr_ID
        END

        IF @TreasuryAccountCode IS NULL
        BEGIN
            RAISERROR(N'لا يمكن ترحيل الإيصال: الخزينة Tr_ID غير مربوطة بحساب محاسبي.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END


		SET @ReceiptAmount = 
    CASE 
        WHEN ISNULL(@Total, 0) > 0 THEN ISNULL(@Total, 0)
        ELSE ISNULL(@Pure, 0) + ISNULL(@Discount, 0)
    END;

        ------------------------------------------------------------
        -- 7. إيصال قبض BsType_ID = 3
        --
        -- من حـ/ الخزينة
        --      إلى حـ/ الطرف
        ------------------------------------------------------------

		IF @BsType_ID = 3
BEGIN
    ------------------------------------------------------------
    -- إيصال قبض مع خصم
    --
    -- من حـ/ الخزينة              Pure
    -- من حـ/ الخصم المسموح        Discount
    --      إلى حـ/ الطرف          Total أو Pure + Discount
    ------------------------------------------------------------

    INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
    VALUES
    (
        1,
        @TreasuryAccountCode,
        NULL,
        @Pure,
        1,
        N'إيصال قبض رقم ' + CAST(@T_ID AS NVARCHAR(50)),
        N'',
        1
    );

    IF ISNULL(@Discount, 0) > 0
    BEGIN
        INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
        VALUES
        (
            2,
            @DiscountAllowedAccountCode,
            NULL,
            @Discount,
            1,
            N'خصم مسموح بإيصال قبض رقم ' + CAST(@T_ID AS NVARCHAR(50)),
            N'',
            1
        );
    END

    INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
    VALUES
    (
        3,
        @AgentAccountCode,
        @ReceiptAmount,
        NULL,
        1,
        N'تخفيض مديونية الطرف بإيصال قبض رقم ' + CAST(@T_ID AS NVARCHAR(50)),
        N'',
        1
    );
END

  --      IF @BsType_ID = 3
  --      BEGIN
  

		--INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
  --      VALUES           (1, @TreasuryAccountCode, @Pure, NULL, 1, N'إيصال قبض رقم ' + CAST(@T_ID AS NVARCHAR(50)), N'', 1) 



	 --   INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
  --      VALUES           (2, @AgentAccountCode, NULL, @Pure, 1, N'تخفيض مديونية الطرف بإيصال قبض رقم ' + CAST(@T_ID AS NVARCHAR(50)), N'', 1) 

  --      END

        ------------------------------------------------------------
        -- 8. إيصال صرف BsType_ID = 4
        --
        -- من حـ/ الطرف
        --      إلى حـ/ الخزينة
        ------------------------------------------------------------

		IF @BsType_ID = 4
BEGIN
    ------------------------------------------------------------
    -- إيصال صرف مع خصم
    --
    -- من حـ/ الطرف              Total أو Pure + Discount
    --      إلى حـ/ الخزينة       Pure
    --      إلى حـ/ الخصم المكتسب Discount
    ------------------------------------------------------------

    INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
    VALUES
    (
        4,
        @AgentAccountCode,
        NULL,
        @ReceiptAmount,
        1,
        N'إيصال صرف رقم ' + CAST(@T_ID AS NVARCHAR(50)),
        N'',
        1
    );

    INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
    VALUES
    (
        5,
        @TreasuryAccountCode,
        @Pure,
        NULL,
        1,
        N'خروج نقدية من الخزينة بإيصال صرف رقم ' + CAST(@T_ID AS NVARCHAR(50)),
        N'',
        1
    );

    IF ISNULL(@Discount, 0) > 0
    BEGIN
        INSERT INTO @Rows(RowNo, ACC_CODE, DEBIT, CREDIT, Currency, Notes, Bill_Num, COST_ID)
        VALUES
        (
            6,
            @DiscountReceivedAccountCode,
            @Discount,
            NULL,
            1,
            N'خصم مكتسب بإيصال صرف رقم ' + CAST(@T_ID AS NVARCHAR(50)),
            N'',
            1
        );
    END
END


   --     IF @BsType_ID = 4
   --     BEGIN

	  --  INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
   --     VALUES           (3, @AgentAccountCode, @Pure, NULL, 1, N'إيصال صرف رقم ' + CAST(@T_ID AS NVARCHAR(50)), N'', 1)  


		 --INSERT INTO @Rows(RowNo,ACC_CODE,DEBIT,CREDIT,Currency,Notes,Bill_Num,COST_ID)
   --      VALUES           (4, @TreasuryAccountCode, NULL, @Pure, 1, N'خروج نقدية من الخزينة بإيصال صرف رقم ' + CAST(@T_ID AS NVARCHAR(50)), N'', 1)  

   --     END

        ------------------------------------------------------------
        -- 9. فحص توازن القيد
        ------------------------------------------------------------
        SELECT
            @DebitTotal = ISNULL(SUM(ISNULL(DEBIT, 0)), 0),
            @CreditTotal = ISNULL(SUM(ISNULL(CREDIT, 0)), 0)
        FROM @ROWS
        --WHERE B_T_ID = @JournalId
        --  AND IS_VOID = 0;

        IF @DebitTotal <> @CreditTotal
        BEGIN
            DECLARE @Msg NVARCHAR(1000);

            SET @Msg = N'القيد الناتج عن الإيصال غير متوازن. إجمالي المدين = '
                     + CAST(@DebitTotal AS NVARCHAR(50))
                     + N'، إجمالي الدائن = '
                     + CAST(@CreditTotal AS NVARCHAR(50));

            RAISERROR(@Msg, 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END


			EXEC dbo.ACC_BALANCE_proc_BULK
    @B_T_ID = @JournalId,
    @DATE = @DATE,
    @USER_ID = @UserId,
    @IS_VOID = 0,
    @Notes_MASTER = N'قيد يومية ألي',
    @Cr_ID = 1,
    @Currency_Equal = 1,
    @Rows = @Rows,
    @OP_Status = @OP_Status OUTPUT,
    @ERROR_MSG = @ERROR_MSG OUTPUT,
    @NextNumber = @NextNumber OUTPUT,
    @New_B_T_ID = @New_B_T_ID OUTPUT;

        ------------------------------------------------------------
        -- 10. ربط الإيصال بالقيد
        ------------------------------------------------------------
        UPDATE dbo.Agents_Balance_MV_RCT
        SET
            JournalId = @New_B_T_ID,
            PostedAt = GETDATE(),
            PostedBy = @UserId
        WHERE T_ID = @T_ID;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @ErrorMessage NVARCHAR(4000);
        SET @ErrorMessage = ERROR_MESSAGE();

        RAISERROR(@ErrorMessage, 16, 1);
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[PostToAccounting]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PostToAccounting]
    @SourceTable NVARCHAR(20), -- MV أو RCT
    @T_ID INT,
    @UserId INT
AS
BEGIN
    SET NOCOUNT ON;

    IF @SourceTable = 'MV'
    BEGIN
        EXEC dbo.PostAgentBalanceInvoiceToAccounting
             @T_ID = @T_ID,
             @UserId = @UserId;
        RETURN;
    END

    IF @SourceTable = 'RCT'
    BEGIN
        EXEC dbo.PostAgentBalanceReceiptToAccounting
             @T_ID = @T_ID,
             @UserId = @UserId;
        RETURN;
    END

    RAISERROR(N'مصدر الترحيل غير معروف. استخدم MV أو RCT.', 16, 1);
END
GO
/****** Object:  StoredProcedure [dbo].[Pr_SelectClosePr]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Pr_SelectClosePr] 
@D_F DATE,
@D_T DATE
AS 

BEGIN


select Pr_ID, ( Periods_V.UserName +' \  من ' + convert(varchar(100),Pr_Start) + ' - ' + ' إلى '+convert(varchar(100),Pr_End) ) 
AS 'Notes' from Periods_V WHERE convert(DATE,Pr_Start) BETWEEN @D_F AND @D_T 


END



































































