CREATE PROCEDURE [dbo].[Pr_SelectUserList] 
@USER_ID INT
AS 
DECLARE @isAdmin Bit
BEGIN

SELECT @isAdmin = isAdmin FROM Users WHERE User_ID = @USER_ID

IF @isAdmin = 1
BEGIN
--select Pr_ID, ( Open_Periods_V.UserName +' \ ' + convert(varchar(100),Pr_Start) + ' - ' ) 
--AS 'Notes' from Open_Periods_V
select Pr_ID,UserName , Convert(DATE,Pr_Start) AS Date ,  Convert(varchar(30),Pr_Start,108) AS TIME 
,CONCAT((DATEDIFF(Minute,[Pr_Start],GETDATE())/60),':',(DATEDIFF(Minute,[Pr_Start],GETDATE())%60)) AS WORK_TIME 
 from Open_Periods_V
END
ELSE
BEGIN
--select Pr_ID, ( Open_Periods_V.UserName +' \ ' + convert(varchar(100),Pr_Start) + ' - ' ) 
--AS 'Notes' from Open_Periods_V WHERE User_ID = @USER_ID
select Pr_ID,UserName , Convert(DATE,Pr_Start) AS Date ,  Convert(varchar(30),Pr_Start,108) AS TIME 
,CONCAT((DATEDIFF(Minute,[Pr_Start],GETDATE())/60),':',(DATEDIFF(Minute,[Pr_Start],GETDATE())%60)) AS WORK_TIME 
 from Open_Periods_V WHERE User_ID = @USER_ID
END


END




































































