/****** Object:  StoredProcedure [dbo].[PREPARE_ACC_BALANCE]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[PREPARE_ACC_BALANCE] 
@ACC_CODE BIGINT,
@DATE_F DATE = NULL,
@DATE_T DATE = NULL,
@is_Balance_View INT = 1,
@COST_ID INT = NULL
--@Period_Type VARCHAR(60) =''
--AS
--BEGIN 

AS
BEGIN TRY
BEGIN TRANSACTION 




--IF @DATE_F IS NULL BEGIN SET @DATE_F = '1900-01-01' END
IF @DATE_F IS NULL BEGIN SELECT TOP 1 @DATE_F = M_FROM FROM MONTHS_CALENDR WHERE YEAR = (SELECT YEAR_ID FROM YEARS WHERE is_Close = 0) END
IF @DATE_T IS NULL BEGIN SET @DATE_T =  GETDATE()
SET @DATE_T = DATEADD(DAY, 1, @DATE_T)
END 

IF @ACC_CODE = 0
BEGIN

IF @is_Balance_View = 1
BEGIN

UPDATE m
     SET m.DEBIT = s.DEBIT ,m.CREDIT = s.CREDIT
FROM ACCOUNTS_TREE m CROSS APPLY
     (SELECT ISNULL(SUM(DEBIT),0) as DEBIT , ISNULL(SUM(CREDIT),0) as CREDIT
      FROM ACC_Billing_TMP_1_V t
      WHERE t.ACC_CODE = m.ACC_CODE AND CONVERT(DATE,DATE) BETWEEN @DATE_F AND @DATE_T AND is_Balance_View =1  AND  (@COST_ID IS NULL OR COST_ID = @COST_ID) 
     ) s;
END
ELSE
BEGIN

UPDATE m
     SET m.DEBIT = s.DEBIT ,m.CREDIT = s.CREDIT
FROM ACCOUNTS_TREE m CROSS APPLY
     (SELECT ISNULL(SUM(DEBIT),0) as DEBIT , ISNULL(SUM(CREDIT),0) as CREDIT
      FROM ACC_Billing_TMP_1_V t
      WHERE t.ACC_CODE = m.ACC_CODE AND CONVERT(DATE,DATE) BETWEEN @DATE_F AND @DATE_T   AND  (@COST_ID IS NULL OR COST_ID = @COST_ID)  --AND is_Balance_View =1
     ) s;

END


END
ELSE IF @ACC_CODE = -1
BEGIN
UPDATE m
     SET m.DEBIT = s.DEBIT ,m.CREDIT = s.CREDIT
FROM ACCOUNTS_TREE m CROSS APPLY
     (SELECT ISNULL(SUM(DEBIT),0) as DEBIT , ISNULL(SUM(CREDIT),0) as CREDIT
      FROM ACC_Billing_TMP_1_V t
      WHERE t.ACC_CODE = m.ACC_CODE AND CONVERT(DATE,DATE) BETWEEN @DATE_F AND @DATE_T AND is_Balance_View =1   AND  (@COST_ID IS NULL OR COST_ID = @COST_ID) 
     ) s;
END
ELSE
BEGIN

UPDATE ACCOUNTS_TREE SET
DEBIT = (SELECT ISNULL(SUM(DEBIT),0) FROM ACC_Billing_TMP_1_V WHERE ACC_CODE = @ACC_CODE AND CONVERT(DATE,DATE) BETWEEN @DATE_F AND @DATE_T AND  (@COST_ID IS NULL OR COST_ID = @COST_ID))    
,
CREDIT= (SELECT ISNULL(SUM(CREDIT),0) FROM ACC_Billing_TMP_1_V WHERE ACC_CODE = @ACC_CODE  AND CONVERT(DATE,DATE) BETWEEN @DATE_F AND @DATE_T AND  (@COST_ID IS NULL OR COST_ID = @COST_ID) )   

WHERE ACC_CODE = @ACC_CODE  

END




COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = '[PREPARE_ACC_BALANCE] ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH
GO
/****** Object:  StoredProcedure [dbo].[Prepare_Income_Sheet]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Prepare_Income_Sheet] 
--AS
--BEGIN 

AS
BEGIN TRY
BEGIN TRANSACTION 


DELETE FROM Tmp_IncomeReport
DELETE FROM Tmp_IncomeReport_2
DBCC CHECKIDENT ('[Tmp_IncomeReport_2]', RESEED, 0);

EXEC [CALC_INCOME]

UPDATE Tmp_IncomeReport  SET Sign = (SELECT Group_Calc FROM Income_Group_Master WHERE RESULT_CODE = Tmp_IncomeReport.ACC_CODE )
WHERE T_ID IS NULL


DECLARE @I INT
SELECT @I = MIN(Group_ID) FROM Tmp_IncomeReport
WHILE @I IS NOT NULL
BEGIN

INSERT INTO Tmp_IncomeReport_2 SELECT * FROM  Tmp_IncomeReport WHERE Tmp_IncomeReport.[Group_ID] = @I ORDER BY Group_ID, Row_Num;

INSERT INTO Tmp_IncomeReport_2 SELECT NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL , NULL
INSERT INTO Tmp_IncomeReport_2 SELECT NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL , NULL

SELECT @I = MIN(Group_ID) FROM Tmp_IncomeReport WHERE GROUP_ID > @I
END




DECLARE @RESULT_ONE_CODE VARCHAR(50),@RESULT_TWO_CODE VARCHAR(50),@Calc_BETWEEN_ONE_TWO	char(1)	='',@RESULT_CODE VARCHAR(50),@ID INT ,@RESULT_TITLE NVARCHAR(2500),@Column_Num int , @value numeric(18,3)

SELECT @I = MIN(T_ID) FROM Income_Group_Results
WHILE @I IS NOT NULL
BEGIN

SELECT @RESULT_TITLE = RESULT_TITLE ,@RESULT_ONE_CODE = RESULT_ONE_CODE ,@RESULT_TWO_CODE = RESULT_TWO_CODE,
@Calc_BETWEEN_ONE_TWO = Calc_BETWEEN_ONE_TWO, @RESULT_CODE = RESULT_CODE, @Column_Num = Column_Num  FROM Income_Group_Results WHERE T_ID = @I

SELECT @ID = ID FROM Tmp_IncomeReport_2 WHERE ACC_CODE = @RESULT_TWO_CODE

if @Calc_BETWEEN_ONE_TWO = '-'
begin
set @value = (SELECT TOP 1 Total_Income FROM Tmp_IncomeReport_2 WHERE ACC_CODE = @RESULT_ONE_CODE  ) - (SELECT TOP 1 Total_Income FROM Tmp_IncomeReport_2 WHERE ACC_CODE = @RESULT_TWO_CODE )
end
else
begin
set @value = (SELECT TOP 1 Total_Income FROM Tmp_IncomeReport_2 WHERE ACC_CODE = @RESULT_ONE_CODE ) + (SELECT TOP 1 Total_Income FROM Tmp_IncomeReport_2 WHERE ACC_CODE = @RESULT_TWO_CODE)
end


UPDATE Tmp_IncomeReport_2 SET 

      [Result_Title]= @RESULT_TITLE
      ,[ACC_CODE] = @RESULT_CODE
      ,[Total_Income] = @value

WHERE ID = @Column_Num

SELECT @I = MIN(T_ID) FROM Income_Group_Results WHERE T_ID > @I
END


SELECT TOP 1 @value =  Total_Income FROM Tmp_IncomeReport_2 ORDER BY ID DESC

IF @value < 0
BEGIN
UPDATE Tmp_IncomeReport_2 SET Result_Title = CONCAT(Result_Title , ' (خسائر)') WHERE ID IN ( SELECT TOP 1 ID FROM Tmp_IncomeReport_2 ORDER BY ID DESC)

END


DECLARE @STR NVARCHAR(550)
SELECT @I = MIN(ID) FROM Tmp_IncomeReport_2
WHILE @I IS NOT NULL
BEGIN

SELECT @STR = Group_Name FROM  Tmp_IncomeReport_2 WHERE ID = @I

IF @STR IS NOT NULL
UPDATE Tmp_IncomeReport_2 SET Group_Name = NULL WHERE ID <> @I AND Group_Name = @STR

SELECT @I = MIN(ID) FROM Tmp_IncomeReport_2 WHERE ID > @I
END

UPDATE Tmp_IncomeReport_2 SET Sign = NULL WHERE Group_Name IS NOT NULL AND ACC_NAME IS NOT NULL

UPDATE Tmp_IncomeReport_2 SET ACC_NAME = '=' WHERE Result_Title IS NOT NULL --AND ACC_NAME IS NOT NULL

--SELECT [ID]
--      --,[T_ID]
--      --,[Group_ID]
--      ,[Group_Name]
--      ,[Result_Title]
--      --,[ACC_CODE]
--      ,[ACC_NAME]
--      ,[Sign]
--      ,[Original_Balance]
--      ,[Final_Balance]
--      ,[Total_Income]
--      --,[Cumulative_Total]
--      --,[Row_Num]
--	  FROM Tmp_IncomeReport_2


--END

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = '[Prepare_Income_Sheet] ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH




























GO
