CREATE PROCEDURE [dbo].[prepare_MONTHS_CALENDR_BY_YEAR]

@Year_INPUT INT 
AS
BEGIN


DECLARE @i int


IF OBJECT_ID('Tree_Test..TMP_CALENDR') IS NOT NULL
 drop TABLE [Tree_Test].[dbo].[TMP_CALENDR]

 CREATE TABLE [Tree_Test].[dbo].[TMP_CALENDR](
	[MonthNumber] [int] NULL,
	[StartDate] [DATE] NULL,
	[EndDate] [DATE] NULL

)

DECLARE @Year INT = @Year_INPUT; 


WITH Months AS (
    SELECT 
        MONTH(DATEADD(MONTH, number, DATEFROMPARTS(@Year, 1, 1))) AS MonthNumber,
        DATEADD(MONTH, number, DATEFROMPARTS(@Year, 1, 1)) AS StartDate
    FROM 
        master.dbo.spt_values 
    WHERE 
        type = 'P' AND number BETWEEN 0 AND 11
)
INSERT INTO TMP_CALENDR (MonthNumber, StartDate, EndDate)
SELECT 
    MonthNumber,
    StartDate,
    EOMONTH(StartDate) AS EndDate
FROM 
    Months;

	

	DELETE FROM MONTHS_CALENDR WHERE YEAR = @Year_INPUT


INSERT [dbo].[MONTHS_CALENDR] ([M_ID],[YEAR], [M_NAME], [M_FROM], [M_TO]) VALUES (1,@Year_INPUT, N'يناير(1)', CAST(N'2024-01-01' AS Date), CAST(N'2024-01-31' AS Date))
