INSERT [dbo].[MONTHS_CALENDR] ([M_ID],[YEAR], [M_NAME], [M_FROM], [M_TO]) VALUES (4,@Year_INPUT, N'أبريل(4)', CAST(N'2024-04-01' AS Date), CAST(N'2024-04-30' AS Date))
INSERT [dbo].[MONTHS_CALENDR] ([M_ID],[YEAR], [M_NAME], [M_FROM], [M_TO]) VALUES (5,@Year_INPUT, N'مايو(5)', CAST(N'2024-05-01' AS Date), CAST(N'2024-05-31' AS Date))
INSERT [dbo].[MONTHS_CALENDR] ([M_ID],[YEAR], [M_NAME], [M_FROM], [M_TO]) VALUES (6,@Year_INPUT, N'يونيو(6)', CAST(N'2024-06-01' AS Date), CAST(N'2024-06-30' AS Date))
INSERT [dbo].[MONTHS_CALENDR] ([M_ID],[YEAR], [M_NAME], [M_FROM], [M_TO]) VALUES (7,@Year_INPUT, N'يوليو(7)', CAST(N'2024-07-01' AS Date), CAST(N'2024-07-31' AS Date))
