INSERT [dbo].[MONTHS_CALENDR] ([M_ID],[YEAR], [M_NAME], [M_FROM], [M_TO]) VALUES (10,@Year_INPUT, N'أكتوبر(10)', CAST(N'2024-10-01' AS Date), CAST(N'2024-10-31' AS Date))
INSERT [dbo].[MONTHS_CALENDR] ([M_ID],[YEAR], [M_NAME], [M_FROM], [M_TO]) VALUES (11,@Year_INPUT, N'نوفمبر(11)', CAST(N'2024-11-01' AS Date), CAST(N'2024-11-30' AS Date))
INSERT [dbo].[MONTHS_CALENDR] ([M_ID],[YEAR], [M_NAME], [M_FROM], [M_TO]) VALUES (12,@Year_INPUT, N'ديسمبر(12)', CAST(N'2024-12-01' AS Date), CAST(N'2024-12-31' AS Date))




			Update MONTHS_CALENDR set  YEAR = @Year_INPUT, M_FROM=(SELECT StartDate FROM TMP_CALENDR WHERE MonthNumber = M_ID ) , M_TO=(SELECT EndDate FROM TMP_CALENDR WHERE MonthNumber = M_ID ) 
