/****** Object:  StoredProcedure [dbo].[ProcessEntries]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ProcessEntries]
    @Entries dbo.EntryTableType READONLY,
	@User_ID INT 
AS
--BEGIN
BEGIN TRY
BEGIN TRANSACTION 



    SET NOCOUNT ON;

    DECLARE
	    @BankTransactionNumber nvarchar(50),
        @EntryDate DATETIME, --DATE
        @CostID NVARCHAR(50),
        @CostCenter NVARCHAR(100),
        @DebitAccount NVARCHAR(100),
        @DebitNumber NVARCHAR(50),
        @CreditAccount NVARCHAR(100),
        @CreditNumber NVARCHAR(50),
        @Amount DECIMAL(18,2),
        @Description NVARCHAR(255),
        @Source NVARCHAR(100),
        @ActionName NVARCHAR(100);

    DECLARE cur CURSOR FOR
        SELECT BankTransactionNumber, EntryDate, CostID, CostCenter, DebitAccount, DebitNumber,
               CreditAccount, CreditNumber, Amount, Description, Source, ActionName
        FROM @Entries;

    OPEN cur;

    FETCH NEXT FROM cur INTO 
        @BankTransactionNumber,@EntryDate, @CostID, @CostCenter, @DebitAccount, @DebitNumber,
        @CreditAccount, @CreditNumber, @Amount, @Description, @Source, @ActionName;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        -- 👇 هنا منطق المعالجة لكل صف
        --PRINT CONCAT('🔹 التاريخ: ', @EntryDate, ' | البيان: ', @Description, ' | المبلغ: ', @Amount);


		IF @ActionName = '(قيد جديد)'
		BEGIN
		---------------------------------------------------------------------------------------------------------------
		DECLARE	@return_value int,
		@ERROR_MSG nvarchar(500),
		@OP_Status int

SELECT	@ERROR_MSG = N''' '''
SELECT	@OP_Status = 1


EXEC	@return_value = [dbo].[ACC_BALANCE_proc_Receipt]
		@DATE = @EntryDate,
		@ACC_CODE_FROM = @DebitNumber,
		@ACC_CODE_TO = @CreditNumber,
		@DEBIT = @Amount,
		@CREDIT = @Amount,
		@USER_ID = @User_ID,
		@Notes_MASTER = @Description,
		@COST_ID = @CostID,
		@ERROR_MSG = @ERROR_MSG OUTPUT,
		@OP_Status = @OP_Status OUTPUT,
		@Receipt_Type = NULL,
		@Receipt_Num = NULL,
		@Bank_Name = NULL,
		@Check_Number = NULL,
		@Cr_ID = 1,
		@Currency_Equal = 1,
		@BankTransactionNumber = @BankTransactionNumber

SELECT	@ERROR_MSG as N'@ERROR_MSG',
		@OP_Status as N'@OP_Status'

--SELECT	'Return Value' = @return_value


		--------------------------------------------------------------------------------------------------------------
END

        IF @ActionName = '(إلغاء القيد)'
		BEGIN
		DECLARE @T_ID INT

		SELECT @T_ID = T_ID FROM ACC_BALANCE_MASTER WHERE BankTransactionNumber = @BankTransactionNumber
		EXEC ACC_BALANCE_Insert_reverse  @T_ID,@OP_Status,@ERROR_MSG,@USER_ID
		--UPDATE ACC_BALANCE_MASTER SET is_Depended = 0 WHERE BankTransactionNumber = @BankTransactionNumber
		--UPDATE ACC_BALANCE SET is_Depended = 0 WHERE B_T_ID = (SELECT T_ID FROM ACC_BALANCE_MASTER WHERE BankTransactionNumber = @BankTransactionNumber )
		END

		 IF @ActionName = '(تعديل القيد)'
		BEGIN

		DECLARE @YY INT,@NextNumber NVARCHAR(40)
		SET @YY = DATEPART(YEAR, @EntryDate)
        EXEC GetNextJournalNumber '1',@YY,'قيد يومية',@EntryDate,@NextNumber = @NextNumber OUTPUT

		UPDATE ACC_BALANCE_MASTER SET DATE = @EntryDate , JournalNumber = @NextNumber WHERE BankTransactionNumber = @BankTransactionNumber
		UPDATE ACC_BALANCE SET DEBIT = @Amount WHERE B_T_ID = (SELECT T_ID FROM ACC_BALANCE_MASTER WHERE BankTransactionNumber = @BankTransactionNumber ) AND DEBIT > 0
		UPDATE ACC_BALANCE SET CREDIT = @Amount WHERE B_T_ID = (SELECT T_ID FROM ACC_BALANCE_MASTER WHERE BankTransactionNumber = @BankTransactionNumber ) AND CREDIT > 0
		END


        -- مثال على شرط منطقي:
        --IF @Amount > 10000
            --PRINT CONCAT('⚠️ عملية كبيرة من المصدر: ', @Source);

        -- يمكنك استدعاء إجراء آخر:
        -- EXEC dbo.HandleEntry @EntryDate, @DebitAccount, @CreditAccount, @Amount;

        FETCH NEXT FROM cur INTO 
            @BankTransactionNumber, @EntryDate, @CostID, @CostCenter, @DebitAccount, @DebitNumber,
            @CreditAccount, @CreditNumber, @Amount, @Description, @Source, @ActionName;
    END

    CLOSE cur;
    DEALLOCATE cur;
--END;

 COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = ' [dbo.ProcessEntries] - ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH

GO
/****** Object:  StoredProcedure [dbo].[Project_Full_Report]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  PROCEDURE [dbo].[Project_Full_Report]
    @ProjectId INT
AS
BEGIN
    SET NOCOUNT ON;

    ------------------------------------------------------------
    -- 1) بيانات المشروع + الملخص المالي + ملخص نسب الشركاء
    ------------------------------------------------------------
    SELECT
        P.ProjectId,
        P.ProjectCode,
        P.ProjectName,
        P.ProjectDesc,
        P.CreatedDate,
        P.UpdatedDate,
        P.PartnerMode,
        CASE 
            WHEN P.PartnerMode = 1 THEN N'كل الشركاء'
            WHEN P.PartnerMode = 2 THEN N'شركاء محددون'
            ELSE N'غير محدد'
        END AS PartnerModeName,

        ISNULL(VS.PurchaseCost, 0) AS PurchaseCost,
        ISNULL(VS.ExpenseCost, 0) AS ExpenseCost,
        ISNULL(VS.SalesValue, 0) AS SalesValue,

        ISNULL(VS.PurchasePaid, 0) AS PurchasePaid,
        ISNULL(VS.ExpensePaid, 0) AS ExpensePaid,
        ISNULL(VS.SalesReceived, 0) AS SalesReceived,

        ISNULL(VS.PurchaseRest, 0) AS PurchaseRest,
        ISNULL(VS.ExpenseRest, 0) AS ExpenseRest,
        ISNULL(VS.SalesRest, 0) AS SalesRest,

        ISNULL(VS.PurchaseCost, 0) + ISNULL(VS.ExpenseCost, 0) AS TotalCost,
        ISNULL(VS.Profit, 0) AS Profit,

        ISNULL(PP.TotalPartners, 0) AS TotalPartners,
        ISNULL(PP.TotalPercent, 0) AS TotalPartnersPercent,
        CASE
            WHEN ISNULL(PP.TotalPercent, 0) = 100 THEN N'مكتمل'
            ELSE N'غير مكتمل'
        END AS PartnersPercentStatus

    FROM dbo.Projects P
    LEFT JOIN dbo.V_ProjectSummary VS
        ON VS.ProjectId = P.ProjectId
    LEFT JOIN
    (
        SELECT
            ProjectId,
            COUNT(*) AS TotalPartners,
            ISNULL(SUM(SharePercent), 0) AS TotalPercent
        FROM dbo.ProjectPartners
        GROUP BY ProjectId
    ) PP
        ON PP.ProjectId = P.ProjectId
    WHERE P.ProjectId = @ProjectId
      AND ISNULL(P.IsDeleted, 0) = 0;

    ------------------------------------------------------------
    -- 2) الفواتير المرتبطة بالمشروع
    ------------------------------------------------------------
    SELECT
        PD.Id AS ProjectDocumentId,
        PD.ProjectId,
        PD.BsType_ID,
        CASE
            WHEN PD.BsType_ID = 1 THEN N'مبيعات'
            WHEN PD.BsType_ID = 2 THEN N'مصروفات'
            WHEN PD.BsType_ID = 7 THEN N'مشتريات'
            ELSE N'أخرى'
        END AS BillTypeName,
        PD.T_ID,
        A.Bill_Num,
        A.[Date],
        A.Total,
        A.Discount,
        A.Pure,
        A.Pied,
        (A.Pure - A.Pied) AS Rest,
        A.isPied,
        PD.Notes,
        PD.CreatedDate
    FROM dbo.ProjectDocuments PD
    INNER JOIN dbo.Agents_Balance_MV_Project_V A
        ON A.T_ID = PD.T_ID
    WHERE PD.ProjectId = @ProjectId
    ORDER BY
        CASE 
            WHEN PD.BsType_ID = 7 THEN 1
            WHEN PD.BsType_ID = 2 THEN 2
            WHEN PD.BsType_ID = 1 THEN 3
            ELSE 4
        END,
        A.[Date] DESC,
        A.Bill_Num DESC;

    ------------------------------------------------------------
    -- 3) الشركاء ونصيبهم من الربح
    ------------------------------------------------------------
    SELECT
        VPS.ProjectPartnerId,
        VPS.ProjectId,
        VPS.PartnerId,
        VPS.PartnerName,
        VPS.DefaultSharePercent,
        VPS.SharePercent,
        VPS.ProjectProfit,
        VPS.PartnerProfit,
        VPS.Notes
    FROM dbo.V_ProjectPartnersSummary VPS
    WHERE VPS.ProjectId = @ProjectId
    ORDER BY VPS.ProjectPartnerId;
END
GO
/****** Object:  StoredProcedure [dbo].[ProjectPartners_AddDefaultPartner]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
