SET QUOTED_IDENTIFIER ON
GO
 CREATE PROCEDURE [dbo].[ProjectPartners_AddDefaultPartner]
    @ProjectId INT,
    @PartnerId INT
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.ProjectPartners
        WHERE ProjectId = @ProjectId
          AND PartnerId = @PartnerId
    )
    BEGIN
        INSERT INTO dbo.ProjectPartners
        (
            ProjectId,
            PartnerId,
            SharePercent,
            Notes,
            CreatedDate
        )
        SELECT
            @ProjectId,
            P.PartnerId,
            P.DefaultSharePercent,
            NULL,
            GETDATE()
        FROM dbo.Partners P
        WHERE P.PartnerId = @PartnerId
          AND P.IsActive = 1;
    END
END
