/****** Object:  StoredProcedure [dbo].[PushSalesDraft]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  PROCEDURE [dbo].[PushSalesDraft]
(
    @AG_ID          INT,
    @S_Bill_Pr_ID   INT = NULL,
    @Table_ID       INT = NULL,
    @Date           DATETIME,
    @Discount       NUMERIC(18,3) = 0,
    @About          NVARCHAR(MAX) = NULL,
    @BsType_ID      INT,
    @isVoid         INT = 0,
    @isPied         INT = NULL,
    @User_ID        INT,
    @Markter_ID     INT = NULL,
    @Details        dbo.SB_Contents_DraftType READONLY,
	@Tr_ID int ,
	@Pay_ID int = 1,
	@Pr_ID int 
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;


IF NOT EXISTS (SELECT 1 FROM @Details)
BEGIN
    RAISERROR(N'لا يمكن حفظ فاتورة بدون تفاصيل.', 16, 1);
    RETURN;
END


IF @BsType_ID IS NULL OR @User_ID IS NULL OR @AG_ID IS NULL
BEGIN
    RAISERROR(N'بيانات رأس الفاتورة غير مكتملة.', 16, 1);
    RETURN;
END


        DECLARE @Header_T_ID INT,@Bill_Num INT;
        DECLARE @SB_ID INT;
        DECLARE @Total NUMERIC(18,3);
        DECLARE @Pure NUMERIC(18,3);
        DECLARE @NextDetailTID BIGINT;

        -- حساب الإجمالي من جدول التفاصيل
        SELECT @Total = ISNULL(SUM(T_Price), 0)
        FROM @Details;

        SET @Pure = ISNULL(@Total, 0) - ISNULL(@Discount, 0);

        -- توليد T_ID للرأس
        --SELECT @Header_T_ID = ISNULL(MAX(T_ID), 0) + 1
        --FROM dbo.Agents_Balance_MV WITH (UPDLOCK, HOLDLOCK);

		EXEC @Header_T_ID = AA_GET_MAX_ID 'Agents_Balance_MV'
        EXEC @Bill_Num = AG_BalanceMV_GetMax_BillNum
        EXEC @SB_ID = AG_BalanceMV_GetMax_SB_ID

        -- توليد SB_ID
        --SELECT @SB_ID = ISNULL(MAX(SB_ID), 0) + 1
        --FROM dbo.Agents_Balance_MV WITH (UPDLOCK, HOLDLOCK)
        --WHERE BsType_ID = @BsType_ID;


        -- إدخال رأس الفاتورة
        INSERT INTO dbo.Agents_Balance_MV
        (
            T_ID,
            AG_ID,
            SB_ID,
            S_Bill_Pr_ID,
            Table_ID,
            [Date],
            Total,
            Discount,
            Pure,
            About,
            BsType_ID,
            isDepended,
            isVoid,
            isPied,
            User_ID,
            Markter_ID,
			Barcode
        )
        VALUES
        (
            @Header_T_ID,
            @AG_ID,
            @SB_ID,
            @S_Bill_Pr_ID,
            @Table_ID,
            @Date,
            @Total,
            @Discount,
            @Pure,
            @About,
            @BsType_ID,
            1,              -- معتمد نهائي
            @isVoid,
            @isPied,
            @User_ID,
            @Markter_ID,
			(@Header_T_ID + 100)
        );

        -- بداية ترقيم تفاصيل الفاتورة
        --SELECT @NextDetailTID = ISNULL(MAX(T_ID), 0)
        --FROM dbo.SB_Contents WITH (UPDLOCK, HOLDLOCK);
		EXEC @NextDetailTID = AA_GET_MAX_ID 'SB_Contents'

        ;WITH D AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY (SELECT 1)) AS RN,
                IM_ID,
                U_ID,
                ST_ID,
                [Date],
                Compons,
                Cost,
                Price,
                D_Vaild,
                QTY,
                T_Price,
                U_Cargo,
                ST_QTY,
                isDepended,
				Barcode
            FROM @Details
        )


        INSERT INTO dbo.SB_Contents
        (
            T_ID,
            Bill_T_ID,
            IM_ID,
            U_ID,
            ST_ID,
            [Date],
            Compons,
            Cost,
            Price,
            D_Vaild,
            QTY,
            T_Price,
            U_Cargo,
            ST_QTY,
            isDepended,
			Barcode
        )
        SELECT
            @NextDetailTID + RN,
            @Header_T_ID,
            IM_ID,
            U_ID,
            ST_ID,
            [Date],
            Compons,
            Cost,
            Price,
            D_Vaild,
            QTY,
            T_Price,
            U_Cargo,
            ST_QTY,
            1,
			Barcode
        FROM D;




IF ( (SELECT is_Auto_Pied FROM Agents WHERE AG_ID = @AG_ID) = 1 ) 
BEGIN
DECLARE @Receipt_Title NVARCHAR(2500)
SELECT @Receipt_Title = N'فاتورة مبيعات : ' + CAST(@SB_ID AS NVARCHAR(50))
----------------------------------------------------------------------<INSERT RCT>

EXEC [Agents_BalanceMV_insert_RCT]
0,
@DATE,
0,--@Receipt_Num
@AG_ID,
@Pr_ID,
@Header_T_ID,--@Receipt_Tran_ID
NULL,--@ReferNum
@Receipt_Title,
@Pure,--@Pure
NULL,--@About
3,--@BsType_ID
@User_ID ,
@Tr_ID,
'',--BANK_NAME
'',--CHECK_NUMBER
@Pay_ID

END

        COMMIT TRAN;

        SELECT
            CAST(1 AS BIT) AS IsSuccess,
            @Header_T_ID AS Header_T_ID,
            @SB_ID AS SB_ID,
            @Total AS Total,
            @Pure AS Pure;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRAN;

        SELECT
            CAST(0 AS BIT) AS IsSuccess,
            ERROR_NUMBER() AS ErrorNumber,
            ERROR_MESSAGE() AS ErrorMessage,
            ERROR_LINE() AS ErrorLine;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[Recalculate_Agent_Bill_Total]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE  PROCEDURE [dbo].[Recalculate_Agent_Bill_Total]
    @T_ID INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE 
        @BsType_ID INT,
        @DetailsTotal DECIMAL(18,3) = 0,
        @Discount DECIMAL(18,3) = 0,
        @Pure DECIMAL(18,3) = 0;

    -------------------------------------------------------------------
    -- جلب نوع الفاتورة والخصم الحالي من الهيدر
    -------------------------------------------------------------------
    SELECT 
        @BsType_ID = BsType_ID,
        @Discount = ISNULL(Discount, 0)
    FROM Agents_Balance_MV
    WHERE T_ID = @T_ID;

    IF @BsType_ID IS NULL
    BEGIN
        RAISERROR(N'لم يتم العثور على الفاتورة في الجدول الرئيسي Agents_Balance_MV', 16, 1);
        RETURN;
    END

    -------------------------------------------------------------------
    -- تحديد جدول التفاصيل حسب نوع المعاملة
    -------------------------------------------------------------------
    IF @BsType_ID = 1
    BEGIN
        -- فاتورة مبيعات
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0)
        FROM SB_Contents
        WHERE Bill_T_ID = @T_ID;
    END
	ELSE IF @BsType_ID = 2
    BEGIN
        -- فاتورة صروفات
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
        FROM EXP_Details
        WHERE IMEX_T_ID  = @T_ID;
    END
    ELSE IF @BsType_ID = 7
    BEGIN
        -- فاتورة مشتريات
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
        FROM Pch_Details
        WHERE Pch_T_ID = @T_ID;
    END
    ELSE IF @BsType_ID = 8
    BEGIN
        -- فاتورة تالف
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
        FROM IMEX_Details
        WHERE IMEX_T_ID = @T_ID;
    END
    ELSE IF @BsType_ID = 9
    BEGIN
        -- فاتورة جرد
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
        FROM Pch_Details
        WHERE Pch_T_ID = @T_ID;
    END
    ELSE IF @BsType_ID = 10
    BEGIN
        -- إرجاع مبيعات
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0)
        FROM Rtn_Contents
        WHERE Bill_T_ID = @T_ID
          AND Rtn_Type_ID = 1;
    END
    ELSE IF @BsType_ID = 11
    BEGIN
        -- إرجاع مشتريات
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0)
        FROM Rtn_Contents
        WHERE Bill_T_ID = @T_ID
          AND Rtn_Type_ID = 7;
    END
    ELSE IF @BsType_ID = 12
    BEGIN
        -- إذن تحويل أصناف
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
        FROM Store_Trans_Details
        WHERE B_T_ID = @T_ID;
    END
    ELSE IF @BsType_ID = 16
    BEGIN
        -- فاتورة عرض
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(T_Price, 0)), 0)
        FROM ViewBill_Contents
        WHERE Bill_T_ID = @T_ID;
    END
    ELSE IF @BsType_ID = 17
    BEGIN
        -- إذن صرف
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
        FROM InSale_Details
        WHERE InSale_T_ID = @T_ID;
    END
    ELSE IF @BsType_ID = 35
    BEGIN
        -- إذن استلام
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
        FROM Outsale_Details
        WHERE Outsale_T_ID = @T_ID;
    END
	ELSE IF @BsType_ID = 13 or @BsType_ID = 18
    BEGIN
        -- تصنيع
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
        FROM FRM_Details 
        WHERE FRM_T_ID = @T_ID;
    END
	ELSE IF @BsType_ID = 39
    BEGIN
        -- تسوية محزنية
        SELECT @DetailsTotal = ISNULL(SUM(ISNULL(Total, 0)), 0)
        FROM ST_QTY_Deferences 
        WHERE Bill_T_ID = @T_ID;
    END
    ELSE
    BEGIN
        RAISERROR(N'نوع الفاتورة غير مدعوم حاليًا في الإجراء', 16, 1);
        RETURN;
    END

    -------------------------------------------------------------------
    -- حساب الصافي
    -------------------------------------------------------------------
    SET @Pure = @DetailsTotal - ISNULL(@Discount, 0);

    -------------------------------------------------------------------
    -- تحديث الجدول الرئيسي
    -- هنا أفترض أن Balance = Pure
    -- إذا لديك منطق آخر مرتبط بالمدفوعات أخبرني لنعدله
    -------------------------------------------------------------------
    UPDATE Agents_Balance_MV
    SET 
        Total   = @DetailsTotal,
        Pure    = @Pure--,
        --Balance = @Pure
    WHERE T_ID = @T_ID;
END
GO
/****** Object:  StoredProcedure [dbo].[Recalculate_All_Agent_Bills]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [dbo].[Recalculate_All_Agent_Bills]
    @BsType_ID INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @T_ID INT;

    DECLARE BillCursor CURSOR LOCAL FAST_FORWARD FOR
    SELECT T_ID
    FROM Agents_Balance_MV
    WHERE (@BsType_ID IS NULL OR BsType_ID = @BsType_ID);

    OPEN BillCursor;
    FETCH NEXT FROM BillCursor INTO @T_ID;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC dbo.Recalculate_Agent_Bill_Total @T_ID = @T_ID;
        FETCH NEXT FROM BillCursor INTO @T_ID;
    END

    CLOSE BillCursor;
    DEALLOCATE BillCursor;
END
GO
