/****** Object:  StoredProcedure [dbo].[RECOUNT_IM_ALL_QTY]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[RECOUNT_IM_ALL_QTY]
@ST_ID int 
	
AS
BEGIN TRY

BEGIN TRANSACTION 


DECLARE @I INT = 0 ,@J INT = 0, @QTY FLOAT = 0 , @Valid_ST NVARCHAR(50)


SELECT @I = MIN(IM_ID) FROM IM_Menu WHERE isStore IN (1,2) AND isValid = 0
WHILE @I IS NOT NULL
BEGIN

set @QTY = 
  (select ISNULL(SUM(ST_QTY),0) FROM Pch_Details WHERE ST_ID = @ST_ID AND IM_ID=@I AND isDepended = 1)
+ ( select ISNULL(SUM(ST_QTY),0) FROM Rtn_Contents WHERE ST_ID = @ST_ID AND IM_ID=@I AND isDepended = 1 and Rtn_Type_ID = 1)
+ (select ISNULL(SUM(ST_QTY),0) FROM Store_Trans_Details WHERE ST_To_ID = @ST_ID AND IM_ID=@I AND isDepended = 1)
+ (select ISNULL(SUM(ST_QTY),0) FROM FRM_Details WHERE ST_ID = @ST_ID AND IM_ID=@I AND isDepended = 1)
+ (select ISNULL(SUM(ST_QTY),0) FROM Outsale_Details WHERE ST_ID = @ST_ID AND IM_ID=@I AND isDepended = 1)

- (select ISNULL(SUM(ST_QTY),0) FROM SB_Contents WHERE ST_ID = @ST_ID AND IM_ID=@I AND isDepended = 1)
- ( select ISNULL(SUM(ST_QTY),0) FROM Rtn_Contents WHERE ST_ID = @ST_ID AND IM_ID=@I AND isDepended = 1 and Rtn_Type_ID = 7)
- (select ISNULL(SUM(ST_QTY),0) FROM IMEX_Details WHERE ST_ID = @ST_ID AND IM_ID=@I AND isDepended = 1)
- (select ISNULL(SUM(ST_QTY),0) FROM Store_Trans_Details WHERE ST_F_ID = @ST_ID AND IM_ID=@I AND isDepended = 1)
- (select ISNULL(SUM(ST_QTY),0) FROM InSale_Details WHERE ST_ID = @ST_ID AND IM_ID=@I AND isDepended = 1)
- (select ISNULL(SUM(ST_QTY),0) FROM FRM_Contents_Details WHERE ST_ID = @ST_ID AND IM_ID=@I AND isDepended = 1)

+ (select ISNULL(SUM(ST_QTY),0) FROM [ST_QTY_Deferences] WHERE ST_ID = @ST_ID AND IM_ID=@I)

delete from ST_Balance where ST_ID = @ST_ID AND IM_ID = @I 

IF @QTY <> 0 
BEGIN
INSERT INTO ST_Balance(ST_ID,IM_ID,D_Valid,ST_QTY) VALUES (@ST_ID,@I,'',@QTY)
END

EXEC [CHeck_IM_Default_Unit] @I

SELECT @I = MIN(IM_ID) FROM IM_Menu WHERE IM_ID > @I AND isStore IN (1,2) AND isValid = 0
 
END


-------------------------------------------------------------------------------------------------------------------

SELECT @I = MIN(IM_ID) FROM IM_Menu WHERE isStore IN (1,2) AND isValid = 1
WHILE @I IS NOT NULL
BEGIN

SELECT @J = MIN(T_ID) FROM Pch_Details WHERE IM_ID = @I AND isDepended = 1
WHILE @J IS NOT NULL
BEGIN

SELECT @Valid_ST = D_Vaild FROM Pch_Details WHERE IM_ID = @I AND T_ID = @J

set @QTY = 
  (select ISNULL(SUM(ST_QTY),0) FROM Pch_Details WHERE ST_ID = @ST_ID AND IM_ID=@I AND D_Vaild = @Valid_ST AND isDepended = 1)
+ ( select ISNULL(SUM(ST_QTY),0) FROM Rtn_Contents WHERE ST_ID = @ST_ID AND IM_ID=@I AND D_Vaild = @Valid_ST AND isDepended = 1 and Rtn_Type_ID = 1)
+ (select ISNULL(SUM(ST_QTY),0) FROM Store_Trans_Details WHERE ST_To_ID = @ST_ID AND IM_ID=@I AND D_Vaild = @Valid_ST AND isDepended = 1)
+ (select ISNULL(SUM(ST_QTY),0) FROM FRM_Details WHERE ST_ID = @ST_ID AND IM_ID=@I AND D_Vaild = @Valid_ST AND isDepended = 1)

- (select ISNULL(SUM(ST_QTY),0) FROM SB_Contents WHERE ST_ID = @ST_ID AND IM_ID=@I AND D_Vaild = @Valid_ST AND isDepended = 1)
- ( select ISNULL(SUM(ST_QTY),0) FROM Rtn_Contents WHERE ST_ID = @ST_ID AND IM_ID=@I AND D_Vaild = @Valid_ST AND isDepended = 1 and Rtn_Type_ID = 7)
- (select ISNULL(SUM(ST_QTY),0) FROM IMEX_Details WHERE ST_ID = @ST_ID AND IM_ID=@I AND D_Vaild = @Valid_ST AND isDepended = 1)
- (select ISNULL(SUM(ST_QTY),0) FROM Store_Trans_Details WHERE ST_F_ID = @ST_ID AND IM_ID=@I AND D_Vaild = @Valid_ST AND isDepended = 1)
- (select ISNULL(SUM(ST_QTY),0) FROM InSale_Details WHERE ST_ID = @ST_ID AND IM_ID=@I AND D_Vaild = @Valid_ST AND isDepended = 1)
- (select ISNULL(SUM(ST_QTY),0) FROM FRM_Contents_Details WHERE ST_ID = @ST_ID AND IM_ID=@I AND D_Vaild = @Valid_ST AND isDepended = 1)

+ (select ISNULL(SUM(ST_QTY),0) FROM [ST_QTY_Deferences] WHERE ST_ID = @ST_ID AND IM_ID=@I AND Valid_D = @Valid_ST)

DELETE FROM ST_Balance WHERE IM_ID = @I AND D_Valid = @Valid_ST

--IF @QTY > 0 BEGIN UPDATE ST_Balance SET ST_QTY = @QTY WHERE T_ID = @J AND IM_ID = @I END

IF @QTY <> 0 
BEGIN
INSERT INTO ST_Balance(ST_ID,IM_ID,D_Valid,ST_QTY) VALUES (@ST_ID,@I,@Valid_ST,@QTY)
END

EXEC [CHeck_IM_Default_Unit] @I


SELECT @J = MIN(T_ID) FROM Pch_Details WHERE IM_ID = @I AND isDepended = 1 AND T_ID > @J
END


SELECT @I = MIN(IM_ID) FROM IM_Menu WHERE IM_ID > @I AND isStore IN (1,2) AND isValid = 1
 
END

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[RECOUNT_IM_ALL_QTY]',16,1,'خطأ')
ROLLBACK
END CATCH











