/****** Object:  StoredProcedure [dbo].[Recount_IM_Cost]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Recount_IM_Cost]
@IM_ID int,
@NewCOST FLOAT,
@NewMarkVal FLOAT,
@D_F DATE,
@D_T DATE,
@Edit_On_Card bit,
@Edit_MarkVal_On_Card bit,

@Calc_COST bit,
@Calc_MarkVal bit

AS
BEGIN TRY
BEGIN TRANSACTION 

if @Calc_COST = 1 
BEGIN
UPDATE SB_Contents SET Cost = @NewCOST * U_Cargo WHERE IM_ID = @IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T
UPDATE Rtn_Contents SET Cost = @NewCOST * U_Cargo WHERE IM_ID = @IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T


UPDATE InSale_Details SET Cost = @NewCOST * U_Cargo WHERE IM_ID = @IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T
UPDATE Outsale_Details SET Cost = @NewCOST * U_Cargo WHERE IM_ID = @IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T


UPDATE Store_Trans_Details SET Price = @NewCOST * U_Cargo WHERE IM_ID = @IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T

IF @Edit_On_Card = 1 BEGIN UPDATE IM_Menu SET Cost = @NewCOST WHERE IM_ID = @IM_ID END
END

if @Calc_MarkVal = 1 
BEGIN
UPDATE SB_Contents SET Markter_Val = @NewMarkVal WHERE IM_ID = @IM_ID AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T
IF @Edit_MarkVal_On_Card = 1 BEGIN UPDATE IM_Menu SET Markter_Val = @NewMarkVal WHERE IM_ID = @IM_ID END
END


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[Recount_IM_Cost]',16,1,'خطأ')
ROLLBACK
END CATCH


























































