--    CASE WHEN SUM(DiffAmount) > 0 THEN SUM(DiffAmount) ELSE 0 END,
--    CASE WHEN SUM(DiffAmount) < 0 THEN ABS(SUM(DiffAmount)) ELSE 0 END,
--    N'فرق تكلفة مبيعات بسبب إعادة تدوير تكلفة الصنف',
--    @CreatedBy
--FROM dbo.InventoryCostRecountImpact
--WHERE BatchId = @BatchId
--  AND MovementType = N'SALE'
--GROUP BY BatchId, IM_ID
--HAVING SUM(DiffAmount) <> 0;


--INSERT INTO dbo.InventoryCostRecountJournalDraft
--(
--    BatchId,
--    IM_ID,
--    AccountEffect,
--    Debit,
