CREATE proc [dbo].[ReCount_Tresuary_balance]
@Tr_ID int
as
begin

declare @ela_id nvarchar(10)=@Tr_ID
declare @bal numeric(18,3) = 0
;WITH q AS (
    SELECT top 10000000  *
    FROM    Treasury_Balance_MV 
    where Tr_ID = @ela_id and isVoid = 0
    ORDER BY
            [date],[T_ID]
)            
UPDATE  q  set @bal=balance = @bal + (isnull(Credit,0) - isnull(Debit,0))

END









