CREATE PROCEDURE [dbo].[Reports_Fetch_AG_Reciepts] 
@is_By_Pr BIT,
@D_F DATE,
@D_T DATE,
@Pr_ID INT = 0
AS 

BEGIN

If @is_By_Pr = 0
BEGIN
SELECT Ag_name,ISNULL(SUM(PURE),0) AS PURE FROM Agents_Balance_MV_RCT_V WHERE isVoid = 0 AND CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T AND BsType_ID = 3 AND AG_ID > 1
GROUP BY Ag_name
END
ELSE
BEGIN
SELECT Ag_name,ISNULL(SUM(PURE),0) FROM Agents_Balance_MV_RCT_V WHERE isVoid = 0 AND Pr_ID = @Pr_ID AND BsType_ID = 3 AND AG_ID > 1
GROUP BY Ag_name
END

END































