/****** Object:  StoredProcedure [dbo].[Rollback_IM_Units_ByBatch]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Rollback_IM_Units_ByBatch]
    @BatchId UNIQUEIDENTIFIER,
    @User_ID INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRAN;

        -- تحديث الأسعار للقيَم القديمة
        UPDATE U
        SET 
            U.Price       = H.Old_Price,
            U.Min_SP      = H.Old_Min_SP,
            U.Min_SP_2    = H.Old_Min_SP_2,
            U.OFFER_PRICE= H.Old_OFFER_PRICE,
            U.User_ID     = @User_ID
        FROM IM_Units U
        INNER JOIN IM_Units_Prices_History H
            ON U.U_IM_ID = H.U_IM_ID
        WHERE H.BatchId = @BatchId;

        COMMIT;
    END TRY
    BEGIN CATCH
        ROLLBACK;
        THROW;
    END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[RPT_ProjectPartnersProfit]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  PROCEDURE [dbo].[RPT_ProjectPartnersProfit]
(
      @DateFrom      DATE
    , @DateTo        DATE
    , @PartnerId     INT = 0
    , @ProjectId     INT = 0
    , @ProfitMode    INT = 0   -- 0=الكل / 1=الرابحة فقط / 2=غير الرابحة أو صفر
)
AS
BEGIN
    SET NOCOUNT ON;

    ------------------------------------------------------------
    -- جدول مؤقت للتفاصيل بعد تطبيق الفلاتر
    ------------------------------------------------------------
    IF OBJECT_ID('tempdb..#Details') IS NOT NULL
        DROP TABLE #Details;

    SELECT
          pp.ProjectPartnerId
        , pp.ProjectId
        , pp.ProjectCode
        , pp.ProjectName
        , ps.CreatedDate
        , ps.PurchaseCost
        , ps.ExpenseCost
        , ps.SalesValue
        , ISNULL(ps.Profit, 0) AS ProjectProfit
        , pp.PartnerId
        , pp.PartnerName
        , ISNULL(pp.DefaultSharePercent, 0) AS DefaultSharePercent
        , ISNULL(pp.SharePercent, 0) AS SharePercent
        , ISNULL(pp.PartnerProfit, 0) AS PartnerProfit
        , ISNULL(pp.Notes, N'') AS Notes
    INTO #Details
    FROM V_ProjectPartnersSummary pp
    INNER JOIN V_ProjectSummary ps
        ON ps.ProjectId = pp.ProjectId
    WHERE
            CAST(ps.CreatedDate AS DATE) BETWEEN @DateFrom AND @DateTo
        AND (@PartnerId = 0 OR pp.PartnerId = @PartnerId)
        AND (@ProjectId = 0 OR pp.ProjectId = @ProjectId)
        AND
        (
               @ProfitMode = 0
            OR (@ProfitMode = 1 AND ISNULL(ps.Profit,0) > 0)
            OR (@ProfitMode = 2 AND ISNULL(ps.Profit,0) <= 0)
        );

    ------------------------------------------------------------
    -- 1) الملخص العام للمشاريع
    -- مهم: لا نحسب الربح من #Details مباشرة حتى لا يتكرر المشروع بعدد الشركاء
    ------------------------------------------------------------
    SELECT
          COUNT(*) AS TotalProjects
        , SUM(ISNULL(x.ProjectProfit, 0)) AS TotalProjectsProfit
        , SUM(ISNULL(x.SalesValue, 0)) AS TotalSalesValue
        , SUM(ISNULL(x.PurchaseCost, 0)) AS TotalPurchaseCost
        , SUM(ISNULL(x.ExpenseCost, 0)) AS TotalExpenseCost
    FROM
    (
        SELECT DISTINCT
              d.ProjectId
            , d.SalesValue
            , d.PurchaseCost
            , d.ExpenseCost
            , d.ProjectProfit
        FROM #Details d
    ) x;

    ------------------------------------------------------------
    -- 2) ملخص عام للشركاء
    ------------------------------------------------------------
    SELECT
          COUNT(DISTINCT d.PartnerId) AS TotalPartners
        , SUM(ISNULL(d.PartnerProfit, 0)) AS TotalDistributedProfit
        , AVG(CAST(ISNULL(d.SharePercent, 0) AS DECIMAL(18,3))) AS AvgPartnersSharePercent
    FROM #Details d;

    ------------------------------------------------------------
    -- 3) التفاصيل
    ------------------------------------------------------------
    SELECT
          ROW_NUMBER() OVER (ORDER BY d.CreatedDate, d.ProjectCode, d.PartnerName) AS RowNo
        , d.ProjectPartnerId
        , d.ProjectId
        , d.ProjectCode
        , d.ProjectName
        , d.CreatedDate
        , d.SalesValue
        , d.PurchaseCost
        , d.ExpenseCost
        , d.ProjectProfit
        , d.PartnerId
        , d.PartnerName
        , d.DefaultSharePercent
        , d.SharePercent
        , d.PartnerProfit
        , d.Notes
    FROM #Details d
    ORDER BY
          d.CreatedDate
        , d.ProjectCode
        , d.PartnerName;

    ------------------------------------------------------------
    -- 4) الإجمالي حسب الشريك
    ------------------------------------------------------------
    SELECT
          ROW_NUMBER() OVER (ORDER BY d.PartnerName) AS RowNo
        , d.PartnerId
        , d.PartnerName
        , COUNT(DISTINCT d.ProjectId) AS ProjectCount
        , AVG(CAST(ISNULL(d.SharePercent, 0) AS DECIMAL(18,3))) AS AvgSharePercent
        , SUM(ISNULL(d.PartnerProfit, 0)) AS TotalPartnerProfit
        , SUM(ISNULL(d.ProjectProfit, 0)) AS TotalProjectsProfitForPartner
    FROM #Details d
    GROUP BY
          d.PartnerId
        , d.PartnerName
    ORDER BY
          d.PartnerName;

END
GO
