/****** Object:  StoredProcedure [dbo].[Rtn_Contents_Delete_IM]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Rtn_Contents_Delete_IM]
	@T_ID int
AS
DECLARE
@Rtn_Type_ID INT,
@IM_ID int,
@ST_ID INT,
@Valid_ST NVARCHAR(50),
@ST_QTY NUMERIC(18,3)

BEGIN TRY
BEGIN TRANSACTION 

DECLARE @Bill_T_ID INT

SELECT @Rtn_Type_ID = Rtn_Type_ID , @IM_ID = IM_ID , @ST_ID = ST_ID , @Valid_ST = D_Vaild , @ST_QTY = ST_QTY , @Bill_T_ID = Bill_T_ID FROM Rtn_Contents  where T_ID = @T_ID

DELETE FROM Rtn_Contents  where T_ID = @T_ID


 --IF @Rtn_Type_ID = 7 BEGIN EXEC Inc_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY END
 --else IF @Rtn_Type_ID = 1 BEGIN EXEC Dec_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY END

 EXEC [Recalculate_Agent_Bill_Total] @Bill_T_ID

 
COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[Rtn_Contents_Delete_IM]',16,1,'خطأ')
ROLLBACK
END CATCH












GO
/****** Object:  StoredProcedure [dbo].[Rtn_Contents_INSERT]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Rtn_Contents_INSERT]
    @Rtn_Type_ID INT,
	@SB_T_ID int,
	@IM_ID int,
	@D_Vaild DATE = NULL,
	@QYT float = 1,
	@U_ID INT,
	@ST_ID	int,
	@Cost FLOAT = 0,
	@Price FLOAT,
	@Saler_Percent Numeric(18,2)=NULL,
	@Orginal_Bill_T_ID	int = NULL,
	@Markter_Val	numeric(18, 3) = NULL,
	@Serial_Code	nvarchar(100) = NULL,
	@is_By_Min_SP	int = NULL,
    @is_By_Min_SP_2	int	= NULL,
	@Barcode nvarchar(50)

AS
BEGIN TRY

BEGIN TRANSACTION 

DECLARE @T_ID INT , @ST_QTY NUMERIC(18,2),@U_Cargo NUMERIC(18,2),@Valid_ST NVARCHAR(50)


SET @Valid_ST = @D_Vaild
IF @Valid_ST IS NULL BEGIN SET @Valid_ST ='' END

SELECT @U_Cargo = U_Cargo , @ST_QTY = (U_Cargo * @QYT) FROM Units WHERE U_ID = @U_ID

EXEC @T_ID = [AA_GET_MAX_ID] 'Rtn_Contents'
INSERT INTO Rtn_Contents 
(T_ID,Date,Bill_T_ID,Rtn_Type_ID,IM_ID,U_ID,ST_ID,Compons,Cost,Price,D_Vaild,QTY,T_Price,U_Cargo,ST_QTY,
isDepended,Saler_Percent,Orginal_Bill_T_ID,Markter_Val,Serial_Code,is_By_Min_SP,is_By_Min_SP_2,Barcode)
 VALUES
 (@T_ID,GETDATE(),@SB_T_ID,@Rtn_Type_ID,@IM_ID,@U_ID,@ST_ID,NULL,@Cost,@Price,@Valid_ST,@QYT,(@Price * @QYT)
 ,@U_Cargo,@ST_QTY,1,@Saler_Percent,@Orginal_Bill_T_ID,@Markter_Val,@Serial_Code,@is_By_Min_SP,@is_By_Min_SP_2,@Barcode)


 --IF @Rtn_Type_ID = 7 BEGIN EXEC Dec_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY END
 -- else IF @Rtn_Type_ID = 1 BEGIN EXEC inc_IM_QTY @IM_ID,@ST_ID,@Valid_ST,@ST_QTY END

 EXEC [Recalculate_Agent_Bill_Total] @SB_T_ID

EXEC Rtn_Contents_SELECT_Bill @SB_T_ID
 
COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('Rtn_Contents_INSERT',16,1,'خطأ')
ROLLBACK
END CATCH





























































GO
