/****** Object:  StoredProcedure [dbo].[Rtn_Contents_UPDATE_DEPENDED]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Rtn_Contents_UPDATE_DEPENDED]
@T_ID int 
	
AS
BEGIN TRY
BEGIN TRANSACTION 

Declare @Rtn_Berfet Numeric(18,3), @i int , @Org_B_ID INT

SELECT @i = MIN(T_ID) FROM Rtn_Contents WHERE Bill_T_ID = T_ID
WHILE @i IS NOT NULL
BEGIN

SELECT @Org_B_ID = Orginal_Bill_T_ID FROM Rtn_Contents WHERE T_ID = @i
SELECT @Rtn_Berfet = SUM(T_Price) - ISNULL(SUM(T_COST),0) FROM Rtn_Contents_V WHERE Orginal_Bill_T_ID = @Org_B_ID AND isDepended = 1
UPDATE Agents_Balance_MV SET Bill_Rtn_Berfet = @Rtn_Berfet WHERE T_ID = @Org_B_ID 

SELECT @i = MIN(T_ID) FROM Rtn_Contents WHERE Bill_T_ID = T_ID AND T_ID > @i
END

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[Rtn_Contents_UPDATE_DEPENDED]',16,1,'خطأ')
ROLLBACK
END CATCH













GO
