	@TOTAL FLOAT,
	@Discount FLOAT,
	@Pure FLOAT,
	@Pied FLOAT = NULL,
	@AGType_ID INT,
	@Point_Inc FLOAT = NULL,
	@Points_Sale FLOAT = NULL,
	@Deliver_date NVARCHAR(150) = NULL,
	@Order_isDeleverd Bit = NULL,
	@isCostmerScreen Bit = NULL,
	@Tr_ID INT,
	@Pr_ID INT,
	@TB_ID int = NULL,
	@User_ID int = NULL,
	@Pay_ID int = 1
AS
declare @B_Type INT , @TB_ORDER_CODE NVARCHAR(100) = NULL, @TB_NAME NVARCHAR(100) = NULL ,
@Bill_Num INT,@AG_ID INT , @SB_ID nvarchar(25) , @Receipt_Title NVARCHAR(500)
,@DATE DATETIME ,@isPied INT = 0

SET DEADLOCK_PRIORITY NORMAL

BEGIN TRY
BEGIN TRANSACTION
--BEGIN



SELECT @AG_ID = AG_ID,@B_Type = S_Bills_Type , @Bill_Num = S_Bill_Pr_ID ,@isPied = isPied , @SB_ID=SB_ID ,@DATE = GETDATE() FROM SB_Info_V WHERE T_ID = @T_ID 
--IF @B_Type <> 3 BEGIN EXEC AG_Balance_Update_isDepended @T_ID END

EXEC [SB_Contents_Structers_insert] @T_ID

IF @TB_ID IS NOT NULL
BEGIN
SELECT @TB_ORDER_CODE = TB_ORDER_CODE , @TB_NAME = T_NAME FROM Tables WHERE TB_ID = @TB_ID
SET @TB_NAME = ' جزء من طاولة ' + @TB_NAME
Update Agents_Balance_MV SET About = @TB_NAME  WHERE T_ID = @T_ID 
END 

Update Agents_Balance_MV SET isDepended = 1 , Receipt_Title = @SB_ID , Total = @TOTAL,Discount = @Discount,
 SB_isOpen = 0 ,isPause = NULL ,Deliver_date= @Deliver_date,
 Order_isDeleverd=@Order_isDeleverd , TB_ORDER_CODE = @TB_ORDER_CODE , Table_ID = @TB_ID 
 WHERE T_ID = @T_ID 

UPDATE Periods SET AG_Counter += 1 WHERE Pr_ID = @Pr_ID 

IF ( (SELECT is_Auto_Pied FROM Agents WHERE AG_ID = @AG_ID) = 1 ) OR ( @AGType_ID IN (3,5)) BEGIN SET @Pied= @Pure end

IF @Pied > 0 AND @isPied = 0 
BEGIN
--UPDATE Agents_Balance_MV SET Pied = @Pied ,@Pure = @Pied, isPied = 1 WHERE T_ID = @T_ID

SELECT @Receipt_Title = 'فاتورة مبيعات  : ' + @SB_ID
SET @Pure = @Pied
-----------------------------------------------------------------------<INSERT RCT>

EXEC [Agents_BalanceMV_insert_RCT]
0,
@DATE,
0,--@Receipt_Num
@AG_ID,
@Pr_ID,
@T_ID,--@Receipt_Tran_ID
NULL,--@ReferNum
@Receipt_Title,
@Pure,--@Pure
NULL,--@About
3,--@BsType_ID
@User_ID ,
@Tr_ID,
'',--BANK_NAME
'',--CHECK_NUMBER
@Pay_ID
-----------------------------------------------------------------------</INSERT RCT>

--EXEC @Receipt_Num = AG_BalanceMV_GetMaxRecepitNum

--INSERT INTO Agents_Balance_MV
--(Receipt_Tran_ID,AG_ID,Receipt_Num,S_Bill_Pr_ID,Pr_ID,Date,BsType_ID,Receipt_Title,Credit,SB_isOpen,isDepended,User_ID) 
--VALUES (@T_ID,@AG_ID,@Receipt_Num,@Bill_Num,@Pr_ID,GETDATE(),3,'فاتورة مبيعات  : ' + @SB_ID,@Pied,0,1,@User_ID)
--SELECT @NEW_T_ID = SCOPE_IDENTITY();
----------------------------------------------------------------------------

--Insert Into Treasury_Balance_MV 
--(AGBalance_T_ID,Tran_ID,date,Tr_ID,notice_move,Bank_Name,CheckNum,Debit,Credit,Balance,
--Tr_Type_ID,isTran_From,isTran_To,User_ID,isVoid)
--Values (@NEW_T_ID,NULL,GETDATE(),@Tr_ID,'فاتورة مبيعات : ' + @SB_ID,NULL,NULL,@Pied,NULL,NULL,2,NULL,NULL,@User_ID,0)
--SELECT @TRMV_T_ID = SCOPE_IDENTITY();
--END
-----------------------------------------------------------------------------
END

--IF @AGType_ID = 4
--BEGIN
--IF @Pure >= @Points_Sale
--BEGIN

--EXEC @Receipt_Num = AG_BalanceMV_GetMaxRecepitNum
--INSERT INTO Agents_Balance_MV 
--(Receipt_Tran_ID,AG_ID,Receipt_Num,S_Bill_Pr_ID,Pr_ID,Date,Receipt_Title,BsType_ID,Credit,SB_isOpen,isDepended,User_ID) 
--VALUES (@T_ID,@AG_ID,@Receipt_Num,@Bill_Num,@Pr_ID,GETDATE(),'نقاط',3,@Point_Inc ,0,1,@User_ID)
--SELECT @NEW_T_ID = SCOPE_IDENTITY();
	
--Insert Into Treasury_Balance_MV 
--(AGBalance_T_ID,Tran_ID,date,Tr_ID,notice_move,Bank_Name,CheckNum,Debit,Credit,Balance,
--Tr_Type_ID,isTran_From,isTran_To,User_ID,isVoid)
--Values (@NEW_T_ID,NULL,GETDATE(),@Tr_ID,'نقاط مظافة',NULL,NULL,@Point_Inc,NULL,NULL,2,NULL,NULL,@User_ID,1)
--SELECT @TRMV_T_ID = SCOPE_IDENTITY();

--END
--END
---------------------------------------------------------------------------

--**************************************
IF @isCostmerScreen = 1 BEGIN Insert Into Costmer_Screen(T_ID,Bill_Num,isawait,isShowed,TimeStart) 
Values (@T_ID,@Bill_Num,1,1,GetDate()) END
