Update Agents_Balance_MV SET 
TB_ORDER_CODE = (SELECT TB_ORDER_CODE FROM Tables WHERE TB_ID = @TB_ID) 
 WHERE T_ID = @T_ID 

--IF (SELECT COUNT(*) AS S from Tables_NotPied_V where Table_ID = @TB_ID)  = 0
--BEGIN
--UPDATE Tables SET isbusy = 0 WHERE TB_ID = @TB_ID
--END

