CREATE PROCEDURE [dbo].[SB_Contents_CALC_Components] 
@IM_T_ID	int
AS
BEGIN TRY
BEGIN TRANSACTION

DECLARE @i INT,@Comp_Name NVARCHAR(MAX),@Sum_Cops NVARCHAR(MAX) = ''
BEGIN

UPDATE SB_Contents SET Compons = NULL WHERE T_ID = @IM_T_ID
SELECT @i = MIN(T_ID) FROM SB_IM_Compon_V WHERE IM_T_ID = @IM_T_ID
WHILE (@i IS NOT NULL)
BEGIN
SELECT @Comp_Name = Comp_Name FROM SB_IM_Compon_V WHERE T_ID = @i
SET @Sum_Cops = @Sum_Cops + ' | ' + @Comp_Name
SELECT @i = MIN(T_ID) FROM SB_IM_Compon_V WHERE IM_T_ID = @IM_T_ID AND T_ID > @i
END
UPDATE SB_Contents SET Compons = @Sum_Cops WHERE T_ID = @IM_T_ID
END
COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
		print 'DB ERROR ! [SB_Contents_CALC_Components]'
ROLLBACK
END CATCH













GO
