CREATE PROCEDURE [dbo].[SB_Contents_Change_IM_Qty]
	@T_ID int,
	@Def int,
	@On_Update Bit
AS

BEGIN TRY
BEGIN TRANSACTION


DECLARE @U_Cargo NUMERIC(18,2),@IM_ID INT,@ST_ID INT,@D_Vaild NVARCHAR(50),@ST_QTY NUMERIC(18,3),@SB_T_ID INT,@AG_ID INT , @Cur_QTY FLOAT

SELECT @U_Cargo = U_Cargo ,@IM_ID=IM_ID, @ST_ID=ST_ID,@D_Vaild=D_Vaild ,@SB_T_ID = Bill_T_ID  ,@Cur_QTY = QTY   FROM SB_Contents where T_ID = @T_ID

IF (@Cur_QTY + @Def) >= 1 
BEGIN
UPDATE  SB_Contents SET QTY = QTY + @Def , T_Price = (Price * (QTY + @Def)) , ST_QTY = (QTY + @Def) * U_Cargo
where T_ID = @T_ID
END


IF @On_Update = 1 BEGIN EXEC AG_Balance_Update_Pied_On_Update @SB_T_ID,1 END


IF (SELECT ISNULL(S_Bills_Type,1) FROM Agents_Balance_MV WHERE T_ID = @SB_T_ID) <> 3  -- SURE That the bill is not order
 BEGIN

 IF @On_Update = 1 BEGIN EXEC [SB_Contents_Structers_Recount_One] @T_ID END

 IF @Def = 1 
BEGIN 
EXEC Dec_IM_QTY @IM_ID,@ST_ID,@D_Vaild,@U_Cargo 
END 
ELSE 
BEGIN 
EXEC Inc_IM_QTY @IM_ID,@ST_ID,@D_Vaild,@U_Cargo 
END

END




COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[SB_Contents_Change_IM_Qty]',16,1,'خطأ')
ROLLBACK
END CATCH

















GO
