GO
CREATE PROCEDURE [dbo].[SB_Contents_Change_TB_IM_Qty]

    @Bill_T_ID INT,
	@T_ID int,
	@Def int--,
	--@Desc  nvarchar(MAX) = NULL

AS
DECLARE @isError int,@U_Cargo NUMERIC(18,2),@IM_ID INT,@ST_ID INT,@D_Vaild NVARCHAR(50)
BEGIN TRAN

---------------------
SELECT @U_Cargo = U_Cargo ,@IM_ID=IM_ID, @ST_ID=ST_ID,@D_Vaild=D_Vaild   FROM SB_Contents where T_ID = @T_ID
UPDATE  SB_Contents SET QTY = QTY + @Def , T_Price = (Price * (QTY + @Def)) , ST_QTY = (QTY + @Def) * U_Cargo
where T_ID = @T_ID
---------------------


--select @isError = @@ERROR 
--	IF @isError <> 0 
--	goto PROBLEM

--UPDATE  Agents_Balance_MV SET Pure = ((SELECT ISNULL(SUM(T_Price),0) FROM SB_Contents WHERE Bill_T_ID = @Bill_T_ID) - ISNULL(Discount,0) )
--WHERE T_ID = @Bill_T_ID

--select @isError = @@ERROR 
--	IF @isError <> 0 
--	goto PROBLEM




IF (SELECT TB_Auto_Print FROM Sys_Features WHERE T_ID = (SELECT T_ID FROM Sys_Model)) = 1
BEGIN

DECLARE @Desc NVARCHAR(MAX),@IM_NAME NVARCHAR(2500) , @QTY FLOAT , @TB_ID INT
SELECT @IM_ID = IM_ID , @QTY = QTY FROM SB_Contents where T_ID = @T_ID
SELECT @IM_NAME = item_name FROM IM_Menu WHERE IM_ID = @IM_ID
SELECT @TB_ID = TABLE_ID FROM Agents_Balance_MV WHERE T_ID = (SELECT TOP 1 Bill_T_ID FROM SB_Contents WHERE T_ID = @T_ID)

IF @Def > 0
BEGIN
SET @Desc = CONCAT(' زيادة :',CHAR(13), CHAR(10),@IM_NAME,CHAR(13), CHAR(10),' العدد : ',"1",CHAR(13), CHAR(10), ' طاولة : ',(SELECT TOP 1 T_Name  FROM Tables WHERE TB_ID = @TB_ID))
END
ELSE
BEGIN
SET @Desc = CONCAT(' نقص :',CHAR(13), CHAR(10),@IM_NAME,CHAR(13), CHAR(10),' العدد : ',"1",CHAR(13), CHAR(10), ' طاولة : ',(SELECT TOP 1 T_Name  FROM Tables WHERE TB_ID = @TB_ID))

END


INSERT INTO TB_AutoPrint_tmp (T_ID, Notes, Printer_IP)
SELECT 0, @Desc, GP.Printer_IP
FROM GM_Printer_V GP
JOIN IM_Menu IM ON GP.GM_ID = IM.GM_ID
WHERE IM.IM_ID = @IM_ID  AND GP.Printer_IP IS NOT NULL;

END



exec Recalculate_Agent_Bill_Total @Bill_T_ID


		COMMIT TRAN

	PROBLEM:
	if @isError <> 0 begin
	raiserror ('DB ERROR (SB_Contents_Change_TB_IM_Qty)',16,1,'خطأ')
	ROLLBACK TRAN

END




























































