CREATE PROCEDURE [dbo].[SB_Contents_Delete_TB_IM]
@Bill_T_ID INT,
@T_ID int--,
--@Desc  nvarchar(MAX) = NULL

AS
DECLARE @isError int,@TB_ID INT,@IM_ID INT, @QTY FLOAT 
BEGIN TRAN

SELECT @IM_ID = IM_ID , @QTY = QTY FROM SB_Contents where T_ID = @T_ID
SELECT @TB_ID = Table_ID  FROM Agents_Balance_MV where T_ID = ( SELECT TOP 1 Bill_T_ID FROM SB_Contents WHERE  T_ID = @T_ID )


DELETE FROM SB_Contents  where T_ID = @T_ID
 
select @isError = @@ERROR 
IF @isError <> 0 
goto PROBLEM

--exec [AG_Balance_Update_Pied_On_Update] @Bill_T_ID


IF (SELECT TB_Auto_Print FROM Sys_Features WHERE T_ID = (SELECT T_ID FROM Sys_Model)) = 1
BEGIN

DECLARE @Desc NVARCHAR(MAX),@IM_NAME NVARCHAR(2500) --, @QTY FLOAT , @TB_ID INT,@IM_ID INT
--SELECT @IM_ID = IM_ID , @QTY = QTY FROM SB_Contents where T_ID = @T_ID
SELECT @IM_NAME = item_name FROM IM_Menu WHERE IM_ID = @IM_ID
SET @Desc = CONCAT(' مسح :',CHAR(13), CHAR(10),@IM_NAME,CHAR(13), CHAR(10),' العدد : ',@QTY,CHAR(13), CHAR(10), ' طاولة : ',(SELECT TOP 1 T_Name  FROM Tables WHERE TB_ID = @TB_ID))

INSERT INTO TB_AutoPrint_tmp (T_ID, Notes, Printer_IP)
SELECT 0, @Desc, GP.Printer_IP
FROM GM_Printer_V GP
JOIN IM_Menu IM ON GP.GM_ID = IM.GM_ID
WHERE IM.IM_ID = @IM_ID  AND GP.Printer_IP IS NOT NULL;

END

exec Recalculate_Agent_Bill_Total @Bill_T_ID



select @isError = @@ERROR 
	IF @isError <> 0 
	goto PROBLEM

		COMMIT TRAN

	PROBLEM:
	if @isError <> 0 begin
	raiserror ('DB ERROR ([SB_Contents_Delete_TB_IM])',16,1,'خطأ')
	ROLLBACK TRAN

END














































