CREATE PROCEDURE [dbo].[SB_Contents_UPDATE_ST_PERCENT] 
@IM_T_ID int,
@ST_ID INT

AS
BEGIN TRY
BEGIN TRANSACTION 

DECLARE @Total Numeric(18,3),@T_ID INT

SELECT @T_ID = Bill_T_ID FROM SB_Contents WHERE T_ID = @T_ID

UPDATE SB_Contents SET Saler_Percent= (SELECT Saler_Percent FROM Stores WHERE ST_ID = @ST_ID) WHERE T_ID = @T_ID

SELECT @Total = ISNULL(SUM(T_Price),0) FROM SB_Contents WHERE Bill_T_ID = @T_ID
UPDATE Agents_Balance_MV SET Pure = @Total - ISNULL(Discount,0),
Bill_Berfet = ((SELECT SUM(T_Price) FROM SB_Contents_V WHERE Bill_T_ID = @T_ID)  -
(SELECT SUM(SUM_Cost) FROM SB_Contents_V WHERE Bill_T_ID = @T_ID ))
WHERE T_ID = @T_ID

COMMIT
END TRY

