/****** Object:  StoredProcedure [dbo].[SB_Discount_Distribute]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SB_Discount_Distribute] 
@T_ID	int,
@Discount_Val Numeric(18,2)= NULL
AS

declare @isError int , @SUM_QTY Numeric(18,2) , @j INT , @U_ID INT , @IM_ID INT , @SLAEPRICE Numeric(18,2)
BEGIN TRAN

IF @Discount_Val IS NOT NULL 
BEGIN
SELECT @j = min(T_ID) From SB_Contents WHERE Bill_T_ID = @T_ID
WHILE @j is Not NULL
BEGIN
SELECT @U_ID = U_ID ,@IM_ID = IM_ID FROM SB_Contents WHERE T_ID = @j
SELECT @SLAEPRICE = Price FROM IM_Units WHERE IM_ID = @IM_ID and U_ID = @U_ID 
Update SB_Contents SET Price =@SLAEPRICE, T_Price = (QTY * @SLAEPRICE) 
WHERE T_ID = @j 
SELECT @j = min(T_ID) From SB_Contents WHERE Bill_T_ID = @T_ID AND T_ID > @j
END
-------------------------------------------------------------------------------------------
SELECT @SUM_QTY = ISNULL(SUM(QTY),0) FROM SB_Contents WHERE Bill_T_ID = @T_ID
Update SB_Contents SET Price = Price -  (@Discount_Val / @SUM_QTY) , T_Price = (QTY * (Price - (@Discount_Val / @SUM_QTY)))
WHERE Bill_T_ID = @T_ID 

UPDATE Agents_Balance_MV SET Discount = @Discount_Val WHERE T_ID = @T_ID

END
ELSE
BEGIN

SELECT @j = min(T_ID) From SB_Contents WHERE Bill_T_ID = @T_ID
WHILE @j is Not NULL
BEGIN
SELECT @U_ID = U_ID ,@IM_ID = IM_ID FROM SB_Contents WHERE T_ID = @j
SELECT @SLAEPRICE = Price FROM IM_Units WHERE IM_ID = @IM_ID and U_ID = @U_ID 
Update SB_Contents SET Price =@SLAEPRICE, T_Price = (QTY * @SLAEPRICE) 
WHERE T_ID = @j
SELECT @j = min(T_ID) From SB_Contents WHERE Bill_T_ID = @T_ID AND T_ID > @j

UPDATE Agents_Balance_MV SET Discount = NULL WHERE T_ID = @T_ID
END


END

	select @isError = @@ERROR 
	IF @isError <> 0 
	goto PROBLEM

		COMMIT TRAN

	PROBLEM:
	if @isError <> 0 begin
	print 'DB ERROR ! _ SB_Discount_Distribute '
	ROLLBACK TRAN

END
























































GO
