CREATE PROCEDURE [dbo].[SB_IM_Compon_Clear] 
@IM_T_ID int
AS
BEGIN TRY

BEGIN TRANSACTION 


DECLARE @IM_ID INT ,@U_ID INT , @DEFULT_Price Numeric(18,2) , @SUM_COM Numeric(18,2)

SELECT @IM_ID = IM_ID , @U_ID = U_ID FROM SB_Contents WHERE T_ID = @IM_T_ID
SELECT @DEFULT_Price = PRICE FROM IM_Units WHERE IM_ID = @IM_ID AND U_ID = @U_ID

DELETE FROM SB_IM_Components WHERE IM_T_ID=@IM_T_ID

SELECT @SUM_COM = ISNULL(SUM(PRICE),0) FROM SB_IM_Components WHERE IM_T_ID = @IM_T_ID
 UPDATE SB_Contents SET Price = @DEFULT_Price , T_Price = @DEFULT_Price  * QTY , Compons = '' WHERE T_ID = @IM_T_ID


COMMIT
END TRY

BEGIN CATCH
