/****** Object:  StoredProcedure [dbo].[SB_IM_Compon_DELETE]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SB_IM_Compon_DELETE] 

@T_ID int


AS
BEGIN TRY

BEGIN TRANSACTION

DECLARE @IM_ID INT ,@U_ID INT , @DEFULT_Price Numeric(18,2) , @SUM_COM Numeric(18,2) , @IM_T_ID INT , @Bercent NUMERIC(18,2)

CREATE INDEX IDX ON SB_IM_Components(IM_T_ID)

SELECT @IM_T_ID = IM_T_ID FROM SB_IM_Components WHERE T_ID = @T_ID

SELECT @IM_ID = IM_ID , @U_ID = U_ID FROM SB_Contents WHERE T_ID = (SELECT IM_T_ID FROM SB_IM_Components WHERE T_ID = @T_ID)

SELECT @DEFULT_Price = PRICE FROM IM_Units WHERE IM_ID = @IM_ID AND U_ID = @U_ID

select @Bercent = Percent_Price from Change_Price WHERE GM_ID = (SELECT GM_ID FROM IM_Menu WHERE IM_ID = @IM_ID ) 
IF @Bercent IS NOT NULL
BEGIN
SET @DEFULT_Price += @DEFULT_Price * (@Bercent / 100)
END


DELETE FROM SB_IM_Components WHERE T_ID = @T_ID

SELECT @SUM_COM = ISNULL(SUM(PRICE),0) FROM SB_IM_Components WHERE IM_T_ID = @IM_T_ID


 UPDATE SB_Contents SET Price = (@DEFULT_Price + @SUM_COM) ,T_Price = ((@DEFULT_Price + @SUM_COM) * QTY) WHERE T_ID = @IM_T_ID

DROP INDEX SB_IM_Components.IDX

EXEC SB_Contents_CALC_Components @IM_T_ID


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DROP INDEX SB_IM_Components.IDX
raiserror('[SB_IM_Compon_DELETE]',16,1,'خطأ')
ROLLBACK
END CATCH



















GO
/****** Object:  StoredProcedure [dbo].[SB_IM_Compon_INSERT]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SB_IM_Compon_INSERT] 
@IM_T_ID int,
@Com_ID int

AS
BEGIN TRY

BEGIN TRANSACTION 

DECLARE @IM_ID INT ,@U_ID INT , @DEFULT_Price FLOAT , @SUM_COM Numeric(18,2) , @Price Numeric(18,2), @Bercent NUMERIC(18,2) , @OFFER_PRICE FLOAT ,@T_ID INT
CREATE INDEX IDX ON SB_IM_Components(IM_T_ID,Com_ID)

SELECT @IM_ID = IM_ID , @U_ID = U_ID FROM SB_Contents WHERE T_ID = @IM_T_ID

SELECT @DEFULT_Price = PRICE , @OFFER_PRICE = OFFER_PRICE FROM IM_Units WHERE IM_ID = @IM_ID AND U_ID = @U_ID

 EXEC [Check_IM_OFFER] @IM_ID,@DEFULT_Price OUTPUT,@OFFER_PRICE



SELECT @Price  = PRICE FROM GM_Components WHERE Comp_ID = @Com_ID

select @Bercent = Percent_Price from Change_Price WHERE GM_ID = (SELECT GM_ID FROM IM_Menu WHERE IM_ID = @IM_ID ) 
IF @Bercent IS NOT NULL
BEGIN
SET @DEFULT_Price += @DEFULT_Price * (@Bercent / 100)
END



IF ( SELECT T_ID FROM SB_IM_Components WHERE IM_T_ID= @IM_T_ID AND Com_ID = @Com_ID ) IS NULL
BEGIN
EXEC @T_ID = AA_GET_MAX_SB_IM_Components
insert into SB_IM_Components (T_ID,IM_T_ID,Com_ID,Price,Qty) values(@T_ID,@IM_T_ID,@Com_ID,@Price,1)

SELECT @SUM_COM = SUM(PRICE) FROM SB_IM_Components WHERE IM_T_ID = @IM_T_ID

 UPDATE SB_Contents SET Price = (@DEFULT_Price + @SUM_COM) ,T_Price = ((@DEFULT_Price + @SUM_COM) * QTY) WHERE T_ID = @IM_T_ID
END

DROP INDEX SB_IM_Components.IDX

EXEC SB_Contents_CALC_Components @IM_T_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DROP INDEX SB_IM_Components.IDX
raiserror('[SB_IM_Compon_INSERT]',16,1,'خطأ')
ROLLBACK
END CATCH















GO
/****** Object:  StoredProcedure [dbo].[SB_IM_Compon_Update_QTY]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SB_IM_Compon_Update_QTY] 
@T_ID int,
@Def INT


AS
BEGIN TRY

BEGIN TRANSACTION 

DECLARE @IM_ID INT ,@U_ID INT , @DEFULT_Price Numeric(18,2) , @SUM_COM Numeric(18,2) , @Price Numeric(18,2) , @Com_ID INT , @IM_T_ID INT
, @Bercent NUMERIC(18,2)
CREATE INDEX IDX ON SB_IM_Components(IM_T_ID,Com_ID)

SELECT @Com_ID = COM_ID, @IM_T_ID = IM_T_ID FROM SB_IM_Components WHERE T_ID = @T_ID


SELECT @IM_ID = IM_ID , @U_ID = U_ID FROM SB_Contents WHERE T_ID = @IM_T_ID
SELECT @DEFULT_Price = PRICE FROM IM_Units WHERE IM_ID = @IM_ID AND U_ID = @U_ID

SELECT @Price  = PRICE FROM GM_Components WHERE Comp_ID = @Com_ID

select @Bercent = Percent_Price from Change_Price WHERE GM_ID = (SELECT GM_ID FROM IM_Menu WHERE IM_ID = @IM_ID ) 
IF @Bercent IS NOT NULL
BEGIN
SET @DEFULT_Price += @DEFULT_Price * (@Bercent / 100)
END

UPDATE SB_IM_Components SET Qty = (Qty + @Def) ,  Price = ((Qty + @Def) * @Price)   WHERE T_ID = @T_ID


SELECT @SUM_COM = ISNULL(SUM(PRICE),0) FROM SB_IM_Components WHERE IM_T_ID = @IM_T_ID

 UPDATE SB_Contents SET Price = (@DEFULT_Price + @SUM_COM) ,T_Price = ((@DEFULT_Price + @SUM_COM) * QTY) WHERE T_ID = @IM_T_ID

DROP INDEX SB_IM_Components.IDX

EXEC SB_Contents_CALC_Components @IM_T_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
CREATE INDEX IDX ON SB_IM_Components(IM_T_ID,Com_ID)
raiserror('[SB_IM_Compon_UPDATE_QTY]',16,1,'خطأ')
ROLLBACK
END CATCH






















GO
