CREATE PROCEDURE [dbo].[SB_SELECT_Orders]
@Type INT,
@Date Date = NULL,
@Bar_CB Bit,
@SH NVARCHAR(500),
@ALL BIT
AS
BEGIN

IF @ALL = 0
BEGIN
IF @Type = 0
BEGIN
IF @Bar_CB = 1 BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode from OrdersMenu_V WHERE Order_isDeleverd = 0 And Barcode = @SH ORDER By Deliver_date ASC  END
ELSE BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode  from OrdersMenu_V WHERE Order_isDeleverd = 0 And (Ag_name LIKE '%'+ @SH + '%' OR AG_Barcode Like '%'+ @SH + '%' )  ORDER By Deliver_date ASC  END
END

ELSE IF @Type = 1
BEGIN
IF @Bar_CB = 1 BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode  from OrdersMenu_V WHERE Order_isDeleverd = 1 And Barcode = @SH  ORDER By Deliver_date ASC END
ELSE BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode  from OrdersMenu_V WHERE Order_isDeleverd = 1  And (Ag_name LIKE '%'+ @SH + '%' OR AG_Barcode Like '%'+ @SH + '%' ) ORDER By Deliver_date ASC END
END

ELSE IF @Type = 2
BEGIN
IF @Bar_CB = 1 BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode  from OrdersMenu_V WHERE Barcode = @SH AND CONVERT(Date,Date) = CONVERT(Date,@Date) ORDER By Deliver_date ASC  END
ELSE BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode  from OrdersMenu_V WHERE (Ag_name LIKE '%'+ @SH + '%' OR AG_Barcode Like '%'+ @SH + '%' ) ORDER By Deliver_date ASC   END
END
END

ELSE
BEGIN
IF @Type = 0
BEGIN
IF @Bar_CB = 1 BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode  from OrdersMenu_V WHERE Order_isDeleverd = 0 And Barcode = @SH ORDER By Deliver_date ASC  END
ELSE BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode  from OrdersMenu_V WHERE Order_isDeleverd = 0  ORDER By Deliver_date ASC  END
END

ELSE IF @Type = 1
BEGIN
IF @Bar_CB = 1 BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode  from OrdersMenu_V WHERE Order_isDeleverd = 1 And Barcode = @SH  ORDER By Deliver_date ASC END
ELSE BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode  from OrdersMenu_V WHERE Order_isDeleverd = 1  ORDER By Deliver_date ASC END
END

ELSE IF @Type = 2
BEGIN
IF @Bar_CB = 1 BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode  from OrdersMenu_V WHERE Barcode = @SH AND CONVERT(Date,Date) = CONVERT(Date,@Date) ORDER By Deliver_date ASC  END
ELSE BEGIN SELECT T_ID,SB_ID,Barcode,Date,Deliver_date,Ag_name,AG_Barcode  from OrdersMenu_V  ORDER By Deliver_date ASC   END
END
END



END




































