CREATE PROCEDURE [dbo].[SB_VALUE_Bercent_Details_pros]
(@SB_T_ID           int,
@AG_ID             int,
@VALUE_Bercent     numeric,
@Process	 VARCHAR(20)
) AS


BEGIN
IF @Process = 'DELETE'
BEGIN
	DELETE FROM dbo.SB_VALUE_Bercent_Details
	 WHERE SB_T_ID = @SB_T_ID 
	RETURN 1
END
IF EXISTS (SELECT 1 FROM SB_VALUE_Bercent_Details WHERE SB_T_ID = @SB_T_ID )
BEGIN
	UPDATE dbo.SB_VALUE_Bercent_Details
	SET [AG_ID]             = @AG_ID,
       [VALUE_Bercent]     = @VALUE_Bercent
	WHERE SB_T_ID = @SB_T_ID 
	RETURN 1
END
ELSE
BEGIN
	INSERT INTO dbo.SB_VALUE_Bercent_Details
	([SB_T_ID],[AG_ID],
       [VALUE_Bercent])
	SELECT @SB_T_ID,@AG_ID,
       @VALUE_Bercent
	RETURN 1
END
 
END
