CREATE PROCEDURE [dbo].[Search_AG_Bill_AAAAAAAAAAA]

--@AllAgentsCheckBox BIT,
--@AllUsersCheckBox BIT,
@AllTimeCheckBox BIT,
--@AllRecieptsCheckBox BIT,

@DateTimePicker_From DATE,
@DateTimePicker_To DATE,

@AG_ID INT = 0,
@Markter_ID INT = 0,
@Bill_cmb INT=0, 
@isDeletedCheckBox INT
--@UsersComboBox INT=0

AS
BEGIN

--IF @AllAgentsCheckBox = 0 BEGIN EXEC ReCount_Tresuary_balance @TR_ID END

IF EXISTS (SELECT *  FROM sys.indexes  WHERE name='IDX_AG_BILL') begin DROP INDEX Agents_Balance_MV.IDX_AG_BILL end
CREATE INDEX IDX_AG_BILL ON Agents_Balance_MV(AG_ID)


DECLARE @STR AS NVARCHAR(MAX) , @WHERE_ST AS NVARCHAR(MAX) = ' WHERE 1=1 '


--SET @STR = '
--SELECT ROW_NUMBER() OVER(ORDER BY Date DESC) AS '+ '''ت'''+ ',T_ID,Date AS '+ ' تاريخ '+ ',UserName AS ' + 'المستخدم '+ ' ,Bill_ID AS '+ ' رقم_الفاتورة '+ ',B_Name AS '+ ' النوع '+ ',Ag_name AS '+ ' الحساب '+ '
--,Proj_NAME AS '+ ' الزبون_2 '+ ',TOTAL AS '+ ' الإجمالي '+ ',Discount AS '+ ' التخفيض '+ ',Cost AS '+ ' الصافي '+ ',
--                "Total_Pied AS '+ ' المدفوع '+ ',Rest AS '+ ' الباقي '+ ',Name_ AS '+ ' / '+ ',isVoid,isPied,PIED_Name AS '+ ' الخلاص'+ ' FROM  SB_Balance_MV_V'

SET @STR = '
SELECT ROW_NUMBER() OVER(ORDER BY Date DESC) AS IDX,T_ID,Date,UserName ,Bill_ID ,B_Name ,Ag_name
,Proj_NAME ,TOTAL,Discount,Cost,Total_Pied ,Rest,Name_,isVoid,isPied,PIED_Name FROM  SB_Balance_MV_V'

				IF @AG_ID > 0 
				BEGIN
				SET @WHERE_ST = @WHERE_ST + '  AND AG_ID = ' + @AG_ID
				END



				--IF @Bill_cmb = 0 
				--BEGIN
				--SET @WHERE_ST = @WHERE_ST + ' AND isVoid = ' + @isDeletedCheckBox
				--END
				--ELSE IF @Bill_cmb = 1
				--BEGIN
				--SET @WHERE_ST = @WHERE_ST + ' AND isVoid = ' + @isDeletedCheckBox + ' AND  isPied = 1 '
				--END
				--ELSE IF @Bill_cmb = 2
				--BEGIN
				--SET @WHERE_ST = @WHERE_ST + ' AND isVoid = ' + @isDeletedCheckBox + ' AND  isPied = 0 '
				--END


				IF @Markter_ID > 0 
				BEGIN
				SET @WHERE_ST = @WHERE_ST + '  AND Markter_ID = ' + @Markter_ID
				END


				IF @AllTimeCheckBox = 0 
				BEGIN
				SET @WHERE_ST = @WHERE_ST + '  AND CONVERT(DATE,DATE) BETWEEN   CONVERT(DATE,' +  CONVERT(NVARCHAR(MAX), @DateTimePicker_From) + ') AND CONVERT(DATE,' + CONVERT(NVARCHAR(MAX),@DateTimePicker_To ) + ')'   
				END
				

				SET @STR = @STR + @WHERE_ST + ' order by Date DESC '
				

--SET @STR = 'SELECT T_ID,Tr_Name,Date,Type_Name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid FROM TR_MV_Report_V '


--IF @AllAgentsCheckBox = 0 BEGIN SET @WHERE_ST = @WHERE_ST + ' AND And Tr_ID = ' +  @Tr_ID  END
--IF @AllUsersCheckBox = 0 BEGIN SET @WHERE_ST = @WHERE_ST + ' AND And User_ID = ' +  @UsersComboBox  END
--IF @AllRecieptsCheckBox = 0 BEGIN SET @WHERE_ST = @WHERE_ST + ' AND And Type_ID = ' +  @ReceiptTypeComboBox  END
--IF @AllTimeCheckBox = 0 BEGIN SET @WHERE_ST = @WHERE_ST + ' AND And Convert(Date,Date)  Between ' + CONVERT(NVARCHAR(MAX), @DateTimePicker_From) + ' AND ' + CONVERT(NVARCHAR(MAX),@DateTimePicker_To ) END


EXEC(@STR)

			DROP INDEX Agents_Balance_MV.IDX_AG_BILL


END









































































