CREATE PROCEDURE [dbo].[Search_Tr_MV]

@AllAgentsCheckBox BIT,
@AllUsersCheckBox BIT,
@AllTimeCheckBox BIT,
@AllRecieptsCheckBox BIT,

@DateTimePicker_From DATE,
@DateTimePicker_To DATE,

@Tr_ID INT = 1,
@ReceiptTypeComboBox INT=0, 
@UsersComboBox INT=0
AS
BEGIN

IF @AllAgentsCheckBox = 0 BEGIN EXEC ReCount_Tresuary_balance @TR_ID END

IF EXISTS (SELECT *  FROM sys.indexes  WHERE name='IDX_1') begin DROP INDEX Treasury_Balance_MV.IDX_1 end
CREATE INDEX IDX_1 ON Treasury_Balance_MV(Tr_ID,Tr_Type_ID,User_ID)

--====================================================================
--1-------------------------
            If @AllAgentsCheckBox = 0 And @AllUsersCheckBox = 0 And @AllRecieptsCheckBox = 0 And @AllTimeCheckBox = 0  Begin
                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V
                     Where Convert(Date,Date) Between  @DateTimePicker_From  and  @DateTimePicker_To  And Tr_ID =  @Tr_ID
                    And User_ID =   @UsersComboBox   And Type_ID = @ReceiptTypeComboBox
					ORDER BY Date ASC
					END
                --2-------------------------
            Else
			If @AllAgentsCheckBox = 1 And @AllUsersCheckBox = 0 And @AllRecieptsCheckBox = 0 And @AllTimeCheckBox = 0 Begin

                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V
                     Where Convert(Date,Date) Between  @DateTimePicker_From  and  @DateTimePicker_To  And User_ID =   @UsersComboBox 
                        And Type_ID =   @ReceiptTypeComboBox 
						ORDER BY Date ASC 
						END
                --3-------------------------
            Else 
			If @AllAgentsCheckBox = 0 And @AllUsersCheckBox = 1 And @AllRecieptsCheckBox = 0 And @AllTimeCheckBox = 0 Begin
              select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where Convert(Date,Date) Between   @DateTimePicker_From   and   @DateTimePicker_To   And Type_ID =   @ReceiptTypeComboBox 
                And Tr_ID =   @Tr_ID  
				ORDER BY Date ASC
				END
                --4-------------------------
            Else 
			If @AllAgentsCheckBox = 1 And @AllUsersCheckBox = 1 And @AllRecieptsCheckBox = 0 And @AllTimeCheckBox = 0 Begin

                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where Convert(Date,Date) Between   @DateTimePicker_From   and   @DateTimePicker_To   And Type_ID =   @ReceiptTypeComboBox
					 ORDER BY Date ASC 
					 END
                --5-------------------------
            Else 
			If @AllAgentsCheckBox = 0 And @AllUsersCheckBox = 0 And @AllRecieptsCheckBox = 1 And @AllTimeCheckBox = 0 Begin
                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where Convert(Date,Date) Between   @DateTimePicker_From   and   @DateTimePicker_To   And User_ID =   @UsersComboBox   
                     And Tr_ID =   @Tr_ID  
					 ORDER BY Date ASC
                  END
                --6-------------------------
            Else  
			If @AllAgentsCheckBox = 1 And @AllUsersCheckBox = 0 And @AllRecieptsCheckBox = 1 And @AllTimeCheckBox = 0 Begin

                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where Convert(Date,Date) Between   @DateTimePicker_From   and   @DateTimePicker_To   And User_ID =   @UsersComboBox  
					 ORDER BY Date ASC
					 END
                --7-------------------------
            Else 
			If @AllAgentsCheckBox = 0 And @AllUsersCheckBox = 1 And @AllRecieptsCheckBox = 1 And @AllTimeCheckBox = 0 Begin
			-----------------------------------//////////////////////

			SELECT * FROM (
			select TOP 1 T_ID,Tr_Name,Date,' الرصيد الإفتتاحي ' AS Type_Name,Ag_name,Bank_Name,'رصيد قبل المدة' AS notice_move,CheckNum,
			CASE WHEN ([Balance]) > 0 THEN (Balance ) ELSE 0 END AS Debit,
			CASE WHEN ([Balance]) < 0 THEN (Balance * -1 ) ELSE 0 END   AS Credit,
			Balance,'---' AS UserName,isVoid From TR_MV_Report_V  
			Where Convert(Date,Date) < @DateTimePicker_From  And Tr_ID =   @Tr_ID  
			ORDER BY Date DESC
			 ) AS A1



			UNION 
            -----------------------------------//////////////////////

						SELECT * FROM (
                 select TOP 999999 T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where Convert(Date,Date) Between   @DateTimePicker_From   and   @DateTimePicker_To   And Tr_ID =   @Tr_ID  
					 ORDER BY Date ASC
					 ) AS A2 ORDER BY Date ASC


                   END
                --8-------------------------
            Else 
			If @AllAgentsCheckBox = 1 And @AllUsersCheckBox = 1 And @AllRecieptsCheckBox = 1 And @AllTimeCheckBox = 0 Begin
              
                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where Convert(Date,Date) Between   @DateTimePicker_From   and   @DateTimePicker_To  
					 ORDER BY Date ASC
                 END
                --9-------------------------
            Else 
			If @AllAgentsCheckBox = 0 And @AllUsersCheckBox = 0 And @AllRecieptsCheckBox = 0 And @AllTimeCheckBox = 1 Begin
                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where User_ID =   @UsersComboBox   And Tr_ID =   @Tr_ID   And  
                     Type_ID =   @ReceiptTypeComboBox  
					 ORDER BY Date ASC
					 END
                --10-------------------------
            Else 
			If @AllAgentsCheckBox = 1 And @AllUsersCheckBox = 0 And @AllRecieptsCheckBox = 0 And @AllTimeCheckBox = 1 Begin

                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where User_ID =   @UsersComboBox   And 
                     Type_ID =   @ReceiptTypeComboBox  
					 ORDER BY Date ASC
                  END
                --11-------------------------
            Else 
			If @AllAgentsCheckBox = 0 And @AllUsersCheckBox = 1 And @AllRecieptsCheckBox = 0 And @AllTimeCheckBox = 1 Begin
                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where Tr_ID =   @Tr_ID   And  
                     Type_ID =   @ReceiptTypeComboBox  
					 ORDER BY Date ASC
                 END
                --12-------------------------
            Else 
			If @AllAgentsCheckBox = 1 And @AllUsersCheckBox = 1 And @AllRecieptsCheckBox = 0 And @AllTimeCheckBox = 1 Begin

                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where Type_ID =   @ReceiptTypeComboBox  
					 ORDER BY Date ASC
					 END
                --13-------------------------
            Else 
			If @AllAgentsCheckBox = 0 And @AllUsersCheckBox = 0 And @AllRecieptsCheckBox = 1 And @AllTimeCheckBox = 1 Begin
                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where User_ID =   @UsersComboBox   And Tr_ID =   @Tr_ID 
					 ORDER BY Date ASC 
					 END
                --14-------------------------
            Else 
			If @AllAgentsCheckBox = 1 And @AllUsersCheckBox = 0 And @AllRecieptsCheckBox = 1 And @AllTimeCheckBox = 1 Begin

                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where User_ID =   @UsersComboBox  
					 ORDER BY Date ASC
					 END
                --15-------------------------
            Else 
			If @AllAgentsCheckBox = 0 And @AllUsersCheckBox = 1 And @AllRecieptsCheckBox = 1 And @AllTimeCheckBox = 1 Begin
                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V  
                     Where Tr_ID =   @Tr_ID  
					 ORDER BY Date ASC
					 END
                --16-------------------------
            Else 
			If @AllAgentsCheckBox = 1 And @AllUsersCheckBox = 1 And @AllRecieptsCheckBox = 1 And @AllTimeCheckBox = 1 Begin
                 select T_ID,Tr_Name,Date,Type_Name,Ag_name,Bank_Name,notice_move,CheckNum,Debit,Credit,Balance,UserName,isVoid From TR_MV_Report_V
				 ORDER BY Date ASC
            End

			DROP INDEX Treasury_Balance_MV.IDX_1
END









































































