/****** Object:  StoredProcedure [dbo].[SearchAgentBill]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- ALTER date: <ALTER Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SearchAgentBill]

@isVoid INT,
--@isPied INT,
@Date_From DATE,
@Date_To DATE,

@AG_ID INT = 0,
@Bill_cmb INT= 0,
@ALL_time_CheckBox BIT = 0
AS
BEGIN
DECLARE @STR NVarchar(MAX)


EXEC [UpdateAgentsBalanceIsPied]


--,UserName AS [  المستخدم ]

SET @STR = '
SELECT ROW_NUMBER() OVER(ORDER BY Date DESC) AS [ ت ],T_ID,Date AS [ التاريخ ],Bill_ID AS [ رقم الفاتورة ],B_Name AS [ النوع ],Ag_name AS [ الحساب ],Proj_NAME AS [ الزبون 2 ],TOTAL AS [ الإجمالي ],Discount AS [ التخفيض ],Cost AS [ الصافي ], 
Pied AS [ المدفوع ],(Cost - isnull(Pied,0)) AS [ الباقي ],Name_ AS [ / ],isVoid,isPied,PIED_Name AS [ الخلاص] 
from ##Temp_SB_Balance_MV_V WHERE 1 = 1  '


IF @ALL_time_CheckBox = 0
BEGIN
SET @STR = @STR + ' AND CONVERT(DATE, DATE) BETWEEN ''' + CONVERT(VARCHAR, @Date_From, 23) + ''' AND ''' + CONVERT(VARCHAR, @Date_To, 23) + ''''
END


IF @AG_ID > 0 
BEGIN SET @STR = @STR + ' AND AG_ID =  ' + CAST(@AG_ID AS VARCHAR) END


IF @Bill_cmb = 0 
BEGIN SET @STR = @STR + ' AND isVoid =  ' + CAST(@isVoid AS VARCHAR) END

IF @Bill_cmb = 1 
BEGIN SET @STR = @STR + '  AND isVoid =  ' + CAST(@isVoid AS VARCHAR) + ' AND isPied = 1 ' END

IF @Bill_cmb = 2 
BEGIN SET @STR = @STR + '  AND isVoid =  ' + CAST(@isVoid AS VARCHAR) + ' AND isPied = 0 ' END




exec (@STR)




--IF EXISTS (SELECT *  FROM sys.indexes  WHERE name='IDX_1') begin DROP INDEX Agents_Balance_MV.IDX_1 end
--CREATE INDEX IDX_1 ON Agents_Balance_MV(AG_ID,BsType_ID,User_ID)


--DROP INDEX Agents_Balance_MV.IDX_1 
END
































