SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE  [dbo].[SELECT_ACC_CODE_MV]

AS
BEGIN


SELECT 
a.[رقم الحساب],a.[التاريــخ],a.[رقم القيــد],a.[البيــان],a.[دائن],a.[مدين],

SUM(a.[الرصيد])
OVER (ORDER BY a.[رقم القيــد] ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS 'الرصيد'

from
(
SELECT ACC_CODE AS 'رقم الحساب','1900-01-01' AS 'التاريــخ','0' AS 'رقم القيــد','الرصيد قبل المدة' AS 'البيــان',0 AS 'مدين',0 AS 'دائن', (SUM(CREDIT) - SUM(DEBIT) )  AS 'الرصيد',SUM(CREDIT) AS CREDIT,SUM(DEBIT) AS DEBIT  

FROM ACC_BALANCE_V   WHERE ACC_CODE = '4111'
and convert(date,date) <'2024-01-20'

GROUP BY ACC_CODE





union all

SELECT ACC_CODE AS 'رقم الحساب',DATE AS 'التاريــخ',B_T_ID AS 'رقم القيــد',NOTES AS 'البيــان',CREDIT AS 'مدين',DEBIT AS 'دائن',  SUM(BALANCE)
OVER (ORDER BY ACC_CODE ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS 'الرصيد',CREDIT,DEBIT  FROM ACC_BALANCE_V   WHERE ACC_CODE = '4111'

and convert(date,date) between '2024-01-20' and '2024-01-27'


) as a



end


GO
/****** Object:  StoredProcedure [dbo].[Select_Debt_Till_Date]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Select_Debt_Till_Date]
@Date Date
AS

BEGIN

DELETE FROM [AG_MV_Report]

INSERT INTO [dbo].[AG_MV_Report]
([AG_ID],[Type_ID],[T_ID],[Ag_name],[Date],[Type_Name],[ReferNum],[Receipt_Title],[Debit],[Credit],[Balance],[UserName],[User_ID],[isVoid],[Debit_2],[Credit_2],[Balance_2])
SELECT 
[AG_ID],[Type_ID],[T_ID],[Ag_name],[Date],[Type_Name],[ReferNum],[Receipt_Title],[Debit],[Credit],[Balance],[UserName],[User_ID],[isVoid],[Debit_2],[Credit_2],[Balance_2] FROM AG_MV_Report_TMP_1_V
UNION
SELECT
[AG_ID],[Type_ID],[T_ID],[Ag_name],[Date],[Type_Name],[ReferNum],[Receipt_Title],[Debit],[Credit],[Balance],[UserName],[User_ID],[isVoid],[Debit_2],[Credit_2],[Balance_2] FROM AG_MV_Report_TMP_2_V


DECLARE @I INT , @Balance FLOAT
SELECT @I = MIN(AG_ID) FROM Agents
WHILE (@I) IS NOT NULL
BEGIN
EXEC ReCount_Agent_balance @I
SELECT TOP 1 @Balance = ISNULL(Balance,0) FROM Agents_Balance_MV_TMP WHERE CONVERT(DATE,DATE) <= @Date AND AG_ID = @I ORDER BY DATE DESC
UPDATE Agents SET T_Balance_TMP = @Balance WHERE AG_ID = @I
SET @Balance = 0
SELECT @I = MIN(AG_ID) FROM Agents WHERE AG_ID > @I

END


END






GO
/****** Object:  StoredProcedure [dbo].[SelectDetails_IM_By_Date]    Script Date: 09/05/2026 16:40:13 ******/
