GO

CREATE PROCEDURE [dbo].[SelectDetails_IM_By_Date] 
@D_F DATE,
@D_T DATE,
@GM_ID INT,
@ALL_PR INT = 0
AS 

BEGIN

IF @ALL_PR = 0
BEGIN

IF @GM_ID = 0
BEGIN
SELECT U_Name,item_name,SUM(QTY) AS S_QTY,SUM(T_Price) AS S_T_Price FROM Pr_IM_SalesDetails_V
WHERE ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T )   AND ( isVoid = 0 ) Group By item_name,U_Name
END
ELSE
BEGIN
SELECT U_Name,item_name,SUM(QTY) AS S_QTY,SUM(T_Price) AS S_T_Price FROM Pr_IM_SalesDetails_V
WHERE ( CONVERT(DATE,DATE) BETWEEN @D_F AND @D_T ) AND (GM_ID = @GM_ID)  AND ( isVoid = 0 ) Group By item_name,U_Name
END

END
ELSE
BEGIN

SELECT U_Name,item_name,SUM(QTY) AS S_QTY,SUM(T_Price) AS S_T_Price FROM Pr_IM_SalesDetails_V
WHERE 
Pr_ID IN (SELECT Pr_ID FROM Periods WHERE CONVERT(date,Pr_Start) BETWEEN @D_F AND @D_T )
AND 
 isVoid = 0 
Group By item_name,U_Name

END

END
GO
