BEGIN
SELECT U_Name,item_name,SUM(QTY) AS S_QTY,SUM(T_Price) AS S_T_Price FROM Pr_IM_SalesDetails_V
WHERE Pr_ID = @Pr_ID AND isVoid = 0 Group By item_name,U_Name 
END
ELSE
BEGIN
SELECT U_Name,item_name,SUM(QTY) AS S_QTY,SUM(T_Price) AS S_T_Price FROM Pr_IM_SalesDetails_V
WHERE Pr_ID = @Pr_ID AND isVoid = 0 AND GM_ID = @GM_ID Group By item_name,U_Name 
END


END



































































