-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE  [dbo].[Set_SwitchActivation]
@T_ID INT,
@CP_NAME NVARCHAR(500)
AS
BEGIN
DECLARE @Prev_PC_Name nvarchar(500)
SELECT @Prev_PC_Name = CP_NAME FROM Activation_Details WHERE T_ID = @T_ID

UPDATE Activation_Details SET CP_NAME = @CP_NAME WHERE T_ID = @T_ID


DELETE FROM SysSetting WHERE CP_NAME = @CP_NAME

UPDATE SysSetting SET CP_NAME = @CP_NAME WHERE CP_NAME = @Prev_PC_Name 
end











