CREATE PROCEDURE [dbo].[ST_Trans_Details_insert]
@B_T_ID	int,
@IM_ID	int,
@U_ID	int,
@D_Vaild	nvarchar(50),
@QTY	numeric(18, 2),
@Price	numeric(18, 2),
@ST_F_ID	int,
@ST_To_ID	int,
@ON_Update bit,
@Barcode NVARCHAR(50) = NULL
	
AS
BEGIN TRY

BEGIN TRANSACTION 

DECLARE @T_ID int,@ST_QTY NUMERIC(18,2),@U_Cargo NUMERIC(18,2),@SPrice NUMERIC(18,3)

SELECT @U_Cargo = U_Cargo FROM Units WHERE U_ID = @U_ID
SELECT @ST_QTY = (U_Cargo * @QTY) FROM Units WHERE U_ID = @U_ID

SELECT @SPrice = PRICE FROM IM_Units WHERE U_ID = @U_ID AND IM_ID = @IM_ID

EXEC @T_ID = [AA_GET_MAX_Store_Trans_Details] 
insert into Store_Trans_Details (T_ID,B_T_ID,Date,IM_ID,U_ID,D_Vaild,QTY,Price,Total,U_Cargo,ST_QTY,ST_F_ID,ST_To_ID,isDepended,Barcode,SPrice)
 values(@T_ID,@B_T_ID,GETDATE(),@IM_ID,@U_ID,@D_Vaild,@QTY,@Price,(@Price * @QTY),@U_Cargo,@ST_QTY,@ST_F_ID,@ST_To_ID,0,@Barcode,@SPrice)

 --SELECT @T_ID = SCOPE_IDENTITY()
IF @ON_Update = 1 BEGIN UPDATE Store_Trans_Details  SET isDepended = 1 WHERE T_ID = @T_ID  END
 
--EXEC Dec_IM_QTY @IM_ID,@ST_F_ID,@D_Vaild,@ST_QTY
--EXEC Inc_IM_QTY @IM_ID,@ST_To_ID,@D_Vaild,@ST_QTY

EXEC [Recalculate_Agent_Bill_Total] @B_T_ID

COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[Store_Trans_Details_insert]',16,1,'خطأ')
ROLLBACK
END CATCH








GO
