create PROCEDURE [dbo].[StatIncome]
@SubId as nvarchar(50)= '0',
@StartFrom as nvarchar(50)= ''
AS
BEGIN
if @StartFrom =''
set @startFrom =format(GETDATE(),'yyyy/MM/dd')
IF OBJECT_ID('tempdb..#StataSale') IS NOT NULL
  drop TABLE #StataSale

CREATE TABLE #StataSale(
	[m] [int] NOT NULL,
	[y] [int] NOT NULL,
	[Tot] [numeric](18, 3) NOT NULL
) 
declare @ela nvarchar(250)=
(FORMAT ((SELECT EOmonth(@StartFrom) AS StartOfMonth), 'yyyy/MM/dd'))
--select @ela  
declare @PreM nvarchar(250)=(FORMAT ((DATEADD(month, -5, @StartFrom)), 'yyyy/MM/dd'))
--select @prem
declare @mn nvarchar(250)=
(FORMAT ((SELECT DATEADD(month, DATEDIFF(month, 0, @prem), 0) AS StartOfMonth), 'yyyy/MM/dd'))
--select @mn  
Declare @CurrD nvarchar(50)=@mn
Declare @CurrFrom nvarchar(50)=(FORMAT ((SELECT DATEADD(month, DATEDIFF(month, 0, @CurrD), 0) AS StartOfMonth), 'yyyy/MM/dd'))
Declare @CurrTo nvarchar(50)=(FORMAT ((SELECT EOmonth(@CurrD) AS StartOfMonth), 'yyyy/MM/dd'))
declare @i int = 1
if @subid is not null
begin
while @i <=6
begin
insert into #StataSale
select 
month(@CurrFrom) as 'M'
,year(@CurrFrom) as Y
,isnull(sum(pure),0) as tot
from Agents_Balance_MV_RCT_V ms
where convert(Date,Date) between @CurrFrom and @CurrTo and isDepended = 1 and isVoid = 0 --and fatura between @SubId and @SubId +10000000

--set @CurrD =(FORMAT ((DATEADD(month, 1, @CurrD)), 'yyyy/MM/dd'))
--set @CurrFrom =(FORMAT ((SELECT DATEADD(month, DATEDIFF(month, 0, @CurrD), 0) AS StartOfMonth), 'yyyy/MM/dd'))
--set @CurrTo =(FORMAT ((SELECT EOmonth(@CurrD) AS StartOfMonth), 'yyyy/MM/dd'))
--set @i=@i+1
--end
--end
--else
--begin
--while @i <=6
--begin
--insert into #StataSale
--select 
--month(@CurrFrom) as 'M'
--,year(@CurrFrom) as Y
--,isnull(sum(total),0) as tot
--from mainsale ms
--where pch_date between @CurrFrom and @CurrTo 

set @CurrD =(FORMAT ((DATEADD(month, 1, @CurrD)), 'yyyy/MM/dd'))
set @CurrFrom =(FORMAT ((SELECT DATEADD(month, DATEDIFF(month, 0, @CurrD), 0) AS StartOfMonth), 'yyyy/MM/dd'))
set @CurrTo =(FORMAT ((SELECT EOmonth(@CurrD) AS StartOfMonth), 'yyyy/MM/dd'))
set @i=@i+1
end
end

select m,y,tot from #StataSale 
END



