CREATE PROCEDURE [dbo].[Store_DELETE]
@ST_ID INT 


AS 
BEGIN

IF ( SELECT COUNT(ST_ID) FROM ST_Balance WHERE ST_ID = @ST_ID )  = 0
AND ( SELECT COUNT(ST_ID) FROM ViewBill_Contents WHERE ST_ID = @ST_ID )  = 0
AND ( SELECT COUNT(ST_ID) FROM ST_QTY_Deferences WHERE ST_ID = @ST_ID )  = 0
AND ( SELECT COUNT(ST_ID) FROM SB_Contents WHERE ST_ID = @ST_ID )  = 0
AND ( SELECT COUNT(ST_ID) FROM IM_QTY_ALERT WHERE ST_ID = @ST_ID )  = 0
AND ( SELECT COUNT(ST_ID) FROM InSale_Details WHERE ST_ID = @ST_ID )  = 0
AND ( SELECT COUNT(ST_ID) FROM FRM_Contents_Details WHERE ST_ID = @ST_ID )  = 0
AND ( SELECT COUNT(ST_ID) FROM FRM_Details WHERE ST_ID = @ST_ID )  = 0
AND ( SELECT COUNT(ST_ID) FROM IMEX_Details WHERE ST_ID = @ST_ID )  = 0
AND ( SELECT COUNT(ST_ID) FROM Pch_Details WHERE ST_ID = @ST_ID )  = 0
AND ( SELECT COUNT(ST_ID) FROM Rtn_Contents WHERE ST_ID = @ST_ID )  = 0
AND ( SELECT COUNT(T_ID) FROM Store_Trans_Details WHERE ST_F_ID = @ST_ID OR ST_To_ID = @ST_ID )  = 0

BEGIN
DELETE FROM  Stores  where ST_ID = @ST_ID
END
ELSE
BEGIN
raiserror('لايمكن حذف مخزن عليه حركة',16,1,'خطأ')
END


END







