/****** Object:  StoredProcedure [dbo].[Store_Trans_Fetch]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Store_Trans_Fetch]
@D_F DATE,
@D_T DATE,
@ST_F_ID INT,
@ST_T_ID INT
		
AS
BEGIN

IF @ST_F_ID = 0 AND @ST_T_ID = 0
BEGIN
Select St_F,St_To,item_name,D_Vaild,Sum(QTY) AS QTY,SUM(Total) AS Total,U_Name,UserName FROM St_Trans_Report_V 
 Where CONVERT(Date,Date) Between @D_F and @D_T Group By St_F,St_To,item_name,D_Vaild,U_Name,UserName
END

IF @ST_F_ID > 0 AND @ST_T_ID = 0
BEGIN
Select St_F,St_To,item_name,D_Vaild,Sum(QTY) AS QTY,SUM(Total) AS Total,U_Name,UserName FROM St_Trans_Report_V 
 Where CONVERT(Date,Date) Between @D_F and @D_T AND ST_F_ID = @ST_F_ID Group By St_F,St_To,item_name,D_Vaild,U_Name,UserName
END

IF @ST_F_ID = 0 AND @ST_T_ID > 0
BEGIN
Select St_F,St_To,item_name,D_Vaild,Sum(QTY) AS QTY,SUM(Total) AS Total,U_Name,UserName FROM St_Trans_Report_V 
 Where CONVERT(Date,Date) Between @D_F and @D_T AND ST_To_ID = @ST_T_ID Group By St_F,St_To,item_name,D_Vaild,U_Name,UserName
END

IF @ST_F_ID > 0 AND @ST_T_ID > 0
BEGIN
Select St_F,St_To,item_name,D_Vaild,Sum(QTY) AS QTY,SUM(Total) AS Total,U_Name,UserName FROM St_Trans_Report_V 
 Where CONVERT(Date,Date) Between @D_F and @D_T AND ST_F_ID = @ST_F_ID AND ST_To_ID = @ST_T_ID Group By St_F,St_To,item_name,D_Vaild,U_Name,UserName
END



END






































