BEGIN
select '0' AS T_ID,IM_ID,ST_ID,ST_Name,GM_Name,IM_Num,Barcode,item_name,D_Valid,QTY,Cost,CONVERT(Numeric(18,2),Last_Pch_Price) AS Last_Pch_Price,T_Cost,U_Name
from IM_STORE_View WHERE is_Default = 1 AND CONVERT(DATE,D_Valid) BETWEEN @D_F AND @D_T AND D_Valid <> ''    AND QTY <> 0
ORDER BY item_name ASC

 END

 ELSE 	IF @St_ID = 0 AND @GM_ID > 0
BEGIN
select '0' AS T_ID,IM_ID,ST_ID,ST_Name,GM_Name,IM_Num,Barcode,item_name,D_Valid,QTY,Cost,CONVERT(Numeric(18,2),Last_Pch_Price) AS Last_Pch_Price,T_Cost,U_Name
from IM_STORE_View WHERE is_Default = 1 AND GM_ID = @GM_ID AND CONVERT(DATE,D_Valid) BETWEEN @D_F AND @D_T AND D_Valid <> ''    AND QTY <> 0
ORDER BY item_name ASC

 END

ELSE 	IF @St_ID > 0 AND @GM_ID = 0
BEGIN
select '0' AS T_ID,IM_ID,ST_ID,ST_Name,GM_Name,IM_Num,Barcode,item_name,D_Valid,QTY,Cost,CONVERT(Numeric(18,2),Last_Pch_Price) AS Last_Pch_Price,T_Cost,U_Name
from IM_STORE_View WHERE is_Default = 1 AND ST_ID = @ST_ID AND CONVERT(DATE,D_Valid) BETWEEN @D_F AND @D_T AND D_Valid <> ''    AND QTY <> 0
ORDER BY item_name ASC
END


ELSE 	IF @St_ID > 0 AND @GM_ID > 0
BEGIN
select '0' AS T_ID,IM_ID,ST_ID,ST_Name,GM_Name,IM_Num,Barcode,item_name,D_Valid,QTY,Cost,CONVERT(Numeric(18,2),Last_Pch_Price) AS Last_Pch_Price,T_Cost,U_Name
 from IM_STORE_View WHERE is_Default = 1 AND ST_ID = @ST_ID AND GM_ID = @GM_ID AND CONVERT(DATE,D_Valid) BETWEEN @D_F AND @D_T AND D_Valid <> ''   AND QTY <> 0
 ORDER BY item_name ASC

 END


END	


END









