CREATE PROCEDURE  [dbo].[SYNC_FROM_SALES]
@TREE_DB NVARCHAR(2000),
@SALES_DB NVARCHAR(2000)
AS
BEGIN

EXEC(
N'
BEGIN TRANSACTION;

-- 📝 حذف الصفوف التي لا توجد في BALANCES_VIEW
DELETE B
FROM [' + @TREE_DB + '].[dbo].[SALES_SYSTEM_BALANCES] B
LEFT JOIN [' + @SALES_DB + '].[dbo].[BALANCES_VIEW] A
    ON B.Tran_ID = A.T_ID
WHERE A.T_ID IS NULL;

-- 📝 حذف الصفوف التي توجد في كلا الجدولين ولكن بها اختلافات
DELETE B
FROM [' + @TREE_DB + '].[dbo].[SALES_SYSTEM_BALANCES] B
JOIN [' + @SALES_DB + '].[dbo].[BALANCES_VIEW] A
    ON B.Tran_ID = A.T_ID
WHERE 
    (ISNULL(B.DATE, ''1900-01-01'') <> ISNULL(A.DATE, ''1900-01-01'')) OR
    (ISNULL(B.Bill_Num, '''') <> ISNULL(A.Bill_Num, '''')) OR
    (ISNULL(B.CREDIT, 0) <> ISNULL(A.CREDIT, 0)) OR
    (ISNULL(B.DEBIT, 0) <> ISNULL(A.DEBIT, 0)) OR
    (ISNULL(B.AMOUNT, 0) <> ISNULL(A.AMOUNT, 0));

-- 📝 إضافة الصفوف الجديدة أو المعدلة من BALANCES_VIEW إلى SALES_SYSTEM_BALANCES
INSERT INTO [' + @TREE_DB + '].[dbo].[SALES_SYSTEM_BALANCES]
    ([Tran_ID], [DATE], [Bill_Num], [CREDIT], [DEBIT], [AMOUNT])
SELECT 
    A.T_ID, 
    A.DATE, 
    A.Bill_Num, 
    A.CREDIT, 
    A.DEBIT, 
    A.AMOUNT
FROM [' + @SALES_DB + '].[dbo].[BALANCES_VIEW] A
LEFT JOIN [' + @TREE_DB + '].[dbo].[SALES_SYSTEM_BALANCES] B
    ON A.T_ID = B.Tran_ID
WHERE B.Tran_ID IS NULL

UNION

SELECT 
    A.T_ID, 
    A.DATE, 
    A.Bill_Num, 
    A.CREDIT, 
    A.DEBIT, 
    A.AMOUNT
FROM [' + @SALES_DB + '].[dbo].[BALANCES_VIEW] A
JOIN [' + @TREE_DB + '].[dbo].[SALES_SYSTEM_BALANCES] B
    ON A.T_ID = B.Tran_ID
WHERE 
    (ISNULL(B.DATE, ''1900-01-01'') <> ISNULL(A.DATE, ''1900-01-01'')) OR
    (ISNULL(B.Bill_Num, '''') <> ISNULL(A.Bill_Num, '''')) OR
    (ISNULL(B.CREDIT, 0) <> ISNULL(A.CREDIT, 0)) OR
    (ISNULL(B.DEBIT, 0) <> ISNULL(A.DEBIT, 0)) OR
    (ISNULL(B.AMOUNT, 0) <> ISNULL(A.AMOUNT, 0));

COMMIT;

