GO
CREATE PROCEDURE [dbo].[Sys_Features_Update]
@T_ID INT,
@Pr INT,
@Tables INT,
@SubPrints int,
@Notes int,
@Orders  int,
@Stores  int,
@Frm  int,
@inside_Bill  int,
@SScreenDefault int,
@AgentCards int,
@IM_Default_Stut INT,
@Marketers int,
@SerialCode	int,
@Out_Travel	int	,
@Allow_MinSP INT,
@Exp_Pch INT,
@Phone_For_Tables INT,
@is_Auto_Recive_ST_Tran INT,
@IM_Valid INT

AS
BEGIN
UPDATE dbo.Sys_Features
   SET T_ID = @T_ID,
      Pr = @Pr,
      Tables = @Tables,
      SubPrints = @SubPrints,
      Notes = @Notes,
      Orders = @Orders,
      Stores = @Stores,
      Frm = @Frm,
      inside_Bill = @inside_Bill,
	  SScreenDefault = @SScreenDefault,
	  AgentCards = @AgentCards,
	  IM_Default_Stut = @IM_Default_Stut,
	  Marketers = @Marketers,
	  SerialCode = @SerialCode,
	  Out_Travel =@Out_Travel,
	  Allow_MinSP =@Allow_MinSP,
	  Exp_Pch = @Exp_Pch,
	  Phone_For_Tables = @Phone_For_Tables,
	  is_Auto_Recive_ST_Tran = @is_Auto_Recive_ST_Tran,
	  IM_Valid = @IM_Valid

 WHERE T_ID = @T_ID

 DELETE FROM Sys_Model 
 INSERT INTO Sys_Model VALUES(@T_ID)

 UPDATE SysSetting SET SScreenDefault = @SScreenDefault
 UPDATE SysSetting SET IM_Default_Stut = @IM_Default_Stut

 UPDATE AgentBalance_Type SET Visible = 1
 UPDATE AgentBalance_Type SET Visible = 0 WHERE id BETWEEN 19 AND 33


 UPDATE AgentBalance_Type SET Visible = @Frm WHERE ID IN (13,14,18)
 UPDATE AgentBalance_Type SET Visible = @inside_Bill WHERE id = 17
 UPDATE Agents_Types SET Visible = @AgentCards WHERE ID IN (5,6,7)

END







