CREATE PROCEDURE [dbo].[SysSetting_insert]
@CP_NAME	nvarchar(500),
@CompName	nvarchar(200) = '',
@englishN	nvarchar(200) = '',
@logo	image = NULL,
@SB_DefaultStatus	INT=1,
@Use_Order	bit=0,
@SScreenDefault INT=0,
@IM_Default_Stut	int	=1
AS
declare @isError int
-----------------------
Declare
@BillNotes	nvarchar(MAX) = '',
@isBackup	bit=0,
@BackupPath	nvarchar(500)='',
@isBackup2	bit=0,
@BackupPath_2	nvarchar(500)='',
@Default_Printer_80	nvarchar(250)='',
@Default_Printer_A4	nvarchar(250)='',
@SB_AutoPrint BIT=0,
@isShowPrintBtn bit=0,
@isDiscount	bit=1,
@MinDisValue numeric(18, 2) = 0,

@PrintTBKsh bit=0,
@SB_TypeOf_Inc INT=1,
@KshPrint bit=0,
@BK_OnExit nvarchar(MAX)='',
@OrderPage_ID int=1,
@ReceiptPage_ID int=2,
@SB_Default_AG int=1,
@ScannerName	nvarchar(500)='',
@isCostmerScreen bit=0,	
@AGBillPage_ID int=1,
@IM_Day_Valid	int=0,
@SB_ST_ID	int=1,
@PCH_ST_ID	int=1,
@SB_ST_Can_change	bit=0,
@PCH_ST_Can_change	bit=0,
@CP_Bill_Screen Bit=0,
@Sales_Page_ID INT=1,
@User_AutoPrintSB bit=0,
@is_SB_OutputScreen bit=0,
@SB_Default_ST INT=0,
@POS_By_Shortcut INT=0,
@Open_NewBill_When_OpenSale bit=1,
@SB_IM_Alert_When_Repetition bit = 0,
@Discount_Distribute	bit	=0,
@Check_With_Thankes	bit=0,	
@PCH_TR_ID	int = 1,
@SB_TR_ID	int = 1,
@E_mail	nvarchar(300)= '', 
@E_mail_Pass	nvarchar(300)= '',
@Host	nvarchar(100)= '',
@Port	nvarchar(100)= '',
@IM_min_QTY	bit	=0,
@SB_AutoOpenDrawer bit = 0,
@Pr_PrinterPage_Type	int = 0,
@is_Multi_BAR	bit = 0,
@Def_Befor_Print INT = 0,
@SB_is_Check_IM INT = 0,
@SB_is_Copy	int = 0,
@Copy_Printer_Path	nvarchar(600) = ''
BEGIN Tran

DECLARE @DEF_AG_ID INT,@DEF_TR_ID INT , @DEF_ST_ID INT

SELECT TOP 1 @SB_Default_AG = AG_ID FROM Agents

SELECT TOP 1 @SB_ST_ID = ST_ID FROM Stores
SELECT TOP 1 @PCH_ST_ID = ST_ID FROM Stores

SELECT TOP 1 @PCH_TR_ID = TR_ID FROM TreasuryCard
SELECT TOP 1 @SB_TR_ID = TR_ID FROM TreasuryCard



DELETE FROM SysSetting WHERE CP_NAME = @CP_NAME

	select @isError = @@ERROR 
	IF @isError <> 0 
	goto PROBLEM


INSERT INTO [dbo].[SysSetting]
           ([CP_NAME]
           ,[CompName]
           ,[englishN]
           ,[logo]
           ,[BillNotes]
           ,[isBackup]
           ,[BackupPath]
           ,[isBackup2]
           ,[BackupPath_2]
           ,[Default_Printer_80]
		   ,[Default_Printer_A4]
		   ,[SB_AutoPrint]
           ,[isShowPrintBtn]
           ,[isDiscount]
           ,[MinDisValue]
           ,[SB_DefaultStatus]
           ,[PrintTBKsh]
		   ,[SB_TypeOf_Inc]
		   ,[KshPrint]
		   ,[BK_OnExit]
		   ,[OrderPage_ID]
		   ,[ReceiptPage_ID]
		   ,[SB_Default_AG]
		   ,[ScannerName]
		   ,[isCostmerScreen]
		   ,[SScreenDefault]
		   ,[AGBillPage_ID]
		   ,[IM_Day_Valid]
		   ,[SB_ST_ID]
           ,[PCH_ST_ID]
           ,[SB_ST_Can_change]
           ,[PCH_ST_Can_change]
		   ,[Use_Order]
		   ,[CP_Bill_Screen]
		   ,[Sales_Page_ID]
		   ,[User_AutoPrintSB]
		   ,[is_SB_OutputScreen]
		   ,[SB_Default_ST]
		   ,[POS_By_Shortcut]
		   ,[Open_NewBill_When_OpenSale]
		   ,[SB_IM_Alert_When_Repetition]
		   ,[Discount_Distribute]
		   ,[Check_With_Thankes]
		   ,[PCH_TR_ID]
           ,[SB_TR_ID]
           ,[E_mail]
           ,[E_mail_Pass]
           ,[Host]
           ,[Port]
		   ,[IM_min_QTY]
		   ,[SB_AutoOpenDrawer]
           ,[Pr_PrinterPage_Type]
		   ,[is_Multi_BAR]
		   ,[IM_Default_Stut]
		   ,[Def_Print_Befor_Print]
		   ,[SB_is_Check_IM]
		   ,[SB_is_Copy]
		   ,[Copy_Printer_Path])
     VALUES
           (@CP_NAME
           ,@CompName
           ,@englishN
           ,@logo
           ,@BillNotes
           ,@isBackup
           ,@BackupPath
           ,@isBackup2
           ,@BackupPath_2
           ,@Default_Printer_80
		   ,@Default_Printer_A4
		   ,@SB_AutoPrint
           ,@isShowPrintBtn
           ,@isDiscount
           ,@MinDisValue
           ,@SB_DefaultStatus
           ,@PrintTBKsh
		   ,@SB_TypeOf_Inc
		   ,@KshPrint
		   ,@BK_OnExit
		   ,@OrderPage_ID
		   ,@ReceiptPage_ID
		   ,@SB_Default_AG
		   ,@ScannerName
		   ,@isCostmerScreen
		   ,@SScreenDefault
		   ,@AGBillPage_ID
		   ,@IM_Day_Valid
		   ,@SB_ST_ID
           ,@PCH_ST_ID
           ,@SB_ST_Can_change
           ,@PCH_ST_Can_change
		   ,@Use_Order
		   ,@CP_Bill_Screen
		   ,@Sales_Page_ID
		   ,@User_AutoPrintSB
		   ,@is_SB_OutputScreen
		   ,@SB_Default_ST
		   ,@POS_By_Shortcut
		   ,@Open_NewBill_When_OpenSale
		   ,@SB_IM_Alert_When_Repetition
		   ,@Discount_Distribute
		   ,@Check_With_Thankes
		   ,@PCH_TR_ID
           ,@SB_TR_ID
		   ,@E_mail
           ,@E_mail_Pass
           ,@Host
           ,@Port
		   ,@IM_min_QTY
		   ,@SB_AutoOpenDrawer
           ,@Pr_PrinterPage_Type
		   ,@is_Multi_BAR
		   ,@IM_Default_Stut
		   ,@Def_Befor_Print
		   ,@SB_is_Check_IM
		   ,@SB_is_Copy
		   ,@Copy_Printer_Path)

    select @isError = @@ERROR 
	IF @isError <> 0 
	goto PROBLEM

		   	COMMIT TRAN

	PROBLEM:
	if @isError <> 0 begin
	raiserror ('DB ERROR (SysSetting_insert)',16,1,'خطأ')
	ROLLBACK TRAN

END















































