/****** Object:  StoredProcedure [dbo].[TB_Contents_INSERT_Table_Apart]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[TB_Contents_INSERT_Table_Apart]
	@SB_T_ID_From int,
	@SB_T_ID_To INT,
	@T_ID INT

AS
BEGIN TRY
BEGIN TRANSACTION

DECLARE @Price FLOAT ,@T_Price FLOAT,@U_ID INT, @ST_QTY NUMERIC(18,2),@U_Cargo NUMERIC(18,2),@Cost NUMERIC(18,2)
DECLARE @QTY NUMERIC(18,2),@IM_ID INT,@D_Vaild NVARCHAR(50) = '',@ST_ID INT , @Total Numeric(18,2)=0,@Disc Numeric(18,3),@T_ID_2 INT


SELECT @QTY = QTY FROM SB_Contents WHERE T_ID = @T_ID 
IF @QTY = 1
BEGIN
UPDATE SB_Contents SET Bill_T_ID = @SB_T_ID_To , Apart_From = @SB_T_ID_From WHERE T_ID = @T_ID

-----------------------------
--SELECT @Total = ISNULL(SUM(T_Price),0) FROM SB_Contents WHERE Bill_T_ID = @SB_T_ID_From
--SELECT @Disc = Discount from Agents_Balance_MV where T_ID = @SB_T_ID_From
--EXEC [AG_Balance_Update_Total] @SB_T_ID_From,@Total,@Disc


--SELECT @Total = ISNULL(SUM(T_Price),0) FROM SB_Contents WHERE Bill_T_ID = @SB_T_ID_To
--SELECT @Disc = Discount from Agents_Balance_MV where T_ID = @SB_T_ID_To
--EXEC [AG_Balance_Update_Total] @SB_T_ID_To,@Total,@Disc



-----------------------------
END
ELSE
BEGIN

EXEC SB_Contents_Change_IM_Qty @T_ID,-1,0


SELECT @IM_ID=IM_ID,@ST_ID = ST_ID , @D_Vaild=D_Vaild , @Price = PRICE ,@U_ID = U_ID FROM SB_Contents WHERE T_ID = @T_ID

SELECT @U_Cargo = U_Cargo , @Cost = Cost FROM IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_Cargo = 1 
SELECT @ST_QTY = (U_Cargo * 1) FROM Units WHERE U_ID = @U_ID

EXEC @T_ID_2 = AA_GET_MAX_ID 'SB_Contents'

INSERT INTO SB_Contents (T_ID,Bill_T_ID,IM_ID,U_ID,ST_ID,Date,Compons,Cost,Price,D_Vaild,QTY,T_Price,U_Cargo,ST_QTY,isDepended,Apart_From)
 VALUES(@T_ID_2,@SB_T_ID_To,@IM_ID,@U_ID,@ST_ID,GETDATE(),NULL,(@Cost * @U_Cargo),@Price,@D_Vaild,1,(@Price * 1),@U_Cargo,@ST_QTY,0,@SB_T_ID_From)

 -----------------------------
--SELECT @Total = ISNULL(SUM(T_Price),0) FROM SB_Contents WHERE Bill_T_ID = @SB_T_ID_From
--SELECT @Disc = Discount from Agents_Balance_MV where T_ID = @SB_T_ID_From
--EXEC [AG_Balance_Update_Total] @SB_T_ID_From,@Total,@Disc


--SELECT @Total = ISNULL(SUM(T_Price),0) FROM SB_Contents WHERE Bill_T_ID = @SB_T_ID_To
--SELECT @Disc = Discount from Agents_Balance_MV where T_ID = @SB_T_ID_To
--EXEC [AG_Balance_Update_Total] @SB_T_ID_To,@Total,@Disc


-----------------------------

END

exec Recalculate_Agent_Bill_Total @SB_T_ID_From
exec Recalculate_Agent_Bill_Total @SB_T_ID_To




COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = ' [TB_Contents_INSERT_Table_Apart] ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH
GO
