CREATE PROCEDURE [dbo].[Transform_Bill_Pros] 
@T_ID	int,
@TMP_BARCODE nvarchar(max) = NULL

AS
BEGIN TRY
BEGIN TRANSACTION 

DECLARE @T_ID_OLD INT

    select @T_ID_OLD = T_ID from SB_Info_V WHERE Barcode = @TMP_BARCODE
    
	IF @T_ID_OLD IS NOT NULL
	BEGIN
	EXEC TB_Contents_Transfer_From_Bills @T_ID_OLD,@T_ID
	EXEC SB_Contents_SELECT_Bill @T_ID
	END

COMMIT
END TRY

BEGIN CATCH
