/****** Object:  StoredProcedure [dbo].[Transform_Tables]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Transform_Tables]
	@Table_From int,
	@Table_To int

AS
BEGIN TRY
BEGIN TRANSACTION

DECLARE  @TB_ORDER_CODE NVARCHAR(100)
IF (SELECT TB_ORDER_CODE FROM Tables WHERE TB_ID = @Table_To) IS NULL
BEGIN
SELECT TOP 1 @TB_ORDER_CODE = TB_ORDER_CODE FROM Agents_Balance_MV WHERE Table_ID = @Table_From and isPied = 0 
UPDATE TABLES SET TB_ORDER_CODE = @TB_ORDER_CODE , Start_Open = GETDATE() WHERE TB_ID = @Table_To
END
ELSE
BEGIN
SELECT @TB_ORDER_CODE = TB_ORDER_CODE FROM Tables WHERE TB_ID = @Table_To
END 

update Agents_Balance_MV set Table_id = @Table_To , TB_ORDER_CODE = @TB_ORDER_CODE where Table_id =@Table_From and isPied = 0 



UPDATE TABLES SET isbusy = 0,TB_ORDER_CODE = NULL , Start_Open = NULL WHERE TB_ID = @Table_From


IF (SELECT COUNT(IM_ID) FROM Tables_NotPied_V  WHERE Table_ID = @Table_To ) > 0 
BEGIN
UPDATE TABLES SET isbusy = 1 WHERE TB_ID = @Table_To
END


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
	print 'DB ERROR ! __ [Transform_Tables]'
ROLLBACK
END CATCH










GO
