GO
CREATE PROCEDURE [dbo].[Trial_balance_SELECT](@Hide_Zeros  BIT,@ACC_LEVEL     int,@DATE_F DATE = NULL,@DATE_T DATE = NULL,@TYPE_SHOW INT = 1,@COST_ID INT = NULL)AS--BEGIN TRY
--BEGIN TRANSACTION 
BEGIN




DELETE FROM BALANCES_REVIEW_FINAL_TABLE



IF @TYPE_SHOW = 1
BEGIN

EXEC PREPARE_ACC_BALANCE 0,@DATE_F,@DATE_T,1,@COST_ID

IF @Hide_Zeros = 1
BEGIN

 INSERT INTO BALANCES_REVIEW_FINAL_TABLE SELECT * FROM [dbo].[BALANCES_REVIEW_V]  WHERE ACC_LEVEL = @ACC_LEVEL AND ( [مدين - المجاميع]  <>  0
              OR  [دائــن - المجاميع]  <> 0 )
ORDER BY ACC_LEVEL,[رقم الحساب]

END
ELSE
BEGIN

 INSERT INTO BALANCES_REVIEW_FINAL_TABLE SELECT * FROM [dbo].[BALANCES_REVIEW_V]  WHERE ACC_LEVEL = @ACC_LEVEL  ORDER BY ACC_LEVEL,[رقم الحساب]


END

END
ELSE IF @TYPE_SHOW = 2
BEGIN


UPDATE ACCOUNTS_TREE  SET 
DEBIT = (SELECT ISNULL(SUM(DEBIT),0) FROM AGENTS_Billing_TMP_1_V WHERE ACC_CODE = ACCOUNTS_TREE.ACC_CODE AND DATE BETWEEN @DATE_F AND @DATE_T AND  (@COST_ID IS NULL OR COST_ID = @COST_ID))   
,
CREDIT= (SELECT ISNULL(SUM(CREDIT),0) FROM AGENTS_Billing_TMP_1_V WHERE ACC_CODE = ACCOUNTS_TREE.ACC_CODE  AND DATE BETWEEN @DATE_F AND @DATE_T AND  (@COST_ID IS NULL OR COST_ID = @COST_ID) )   


--DEBIT =  ( SELECT SUM(DEBIT)  FROM ACC_BALANCE_V A WHERE ACC_CODE = ACCOUNTS_TREE.ACC_CODE AND (IS_VOID = 0) AND (is_Depended = 1) AND CONVERT(DATE,DATE) BETWEEN @DATE_F AND @DATE_T )
--,CREDIT =  ( SELECT SUM(CREDIT)  FROM ACC_BALANCE_V A WHERE ACC_CODE = ACCOUNTS_TREE.ACC_CODE AND (IS_VOID = 0) AND (is_Depended = 1) AND CONVERT(DATE,DATE) BETWEEN @DATE_F AND @DATE_T )


IF @Hide_Zeros = 1
BEGIN

 INSERT INTO BALANCES_REVIEW_FINAL_TABLE SELECT * FROM [dbo].[BALANCES_REVIEW_NO_LEVELS_V]  WHERE  ( [مدين - المجاميع]  <>  0
              OR  [دائــن - المجاميع]  <> 0 )
ORDER BY [رقم الحساب], ACC_LEVEL

END
ELSE
BEGIN

 INSERT INTO BALANCES_REVIEW_FINAL_TABLE SELECT * FROM [dbo].[BALANCES_REVIEW_NO_LEVELS_V]   ORDER BY [رقم الحساب],ACC_LEVEL


END


END


SELECT * FROM  BALANCES_REVIEW_FINAL_TABLE 

-- COMMIT
--END TRY

--BEGIN CATCH
--IF @@TRANCOUNT > 0
--DECLARE @ERR_STR NVARCHAR(MAX)
--       SET @ERR_STR  = ' [ACC_BALANCE_proc] - ' + ERROR_MESSAGE()
--	   raiserror(@ERR_STR,16,1,'خطأ')
--ROLLBACK
--END CATCH

END

