CREATE PROCEDURE [dbo].[Update_Agent_balance]
	@AG_ID int,
	@T_ID int
AS
declare @SumDebit money,@SumCredit money,@SumBalance money
begin

select @SumBalance = isnull(Sum(Balance),0) from Agents_Balance_MV Where AG_ID = @AG_ID 
select @SumDebit = ISNULL(sum(Debit),0) , @SumCredit = ISNULL(sum(Credit),0) from Active_BalanceList_V where AG_ID  = @AG_ID
SET @SumBalance = isnull( @SumDebit - @SumCredit,0 )
update Agents_Balance_MV set Balance =   @SumBalance  where AG_ID=@AG_ID and T_ID = @T_ID  AND isDepended = 1 AND isVoid = 0
update Agents set T_Debit = @SumDebit,T_Credit = @SumCredit , T_Balance = @SumBalance where AG_ID = @AG_ID

end


















