CREATE PROCEDURE [dbo].[UPDATE_Cheque_Status](@IssueDate DATE = NULL,@DueDate DATE = NULL,@ReconciliationDate DATE = NULL,@BankTransactionNumber NVARCHAR(40) = NULL,@Notes NVARCHAR(MAX) = NULL,@StatusId INT,@ChequeId INT,@USER_ID INT,@ERROR_MSG NVARCHAR(500) Output)ASBEGIN TRY
BEGIN TRANSACTION 
DECLARE @OP_Status int = 1 --,@ERROR_MSG NVARCHAR(500) 

--SELECT @B_T_ID = T_ID FROM ACC_BALANCE_MASTER WHERE Receipt_Num = @

IF (SELECT is_Generate_Reverse FROM ChequeStatuses WHERE StatusId =@StatusId) = 1
BEGIN
EXEC ACC_BALANCE_Insert_reverse  @ChequeId,@OP_Status,@ERROR_MSG,@USER_ID
END


--IF @OP_Status =0
--BEGIN
--GOTO EXIT_PROC
--END

UPDATE ACC_BALANCE_MASTER
   SET IssueDate = @IssueDate,
       DueDate = @DueDate,
       ReconciliationDate = @ReconciliationDate,
       BankTransactionNumber = @BankTransactionNumber,
       Cheque_Notes = @Notes,
       StatusId = @StatusId
 WHERE T_ID = @ChequeId;
 

 EXIT_PROC:


  COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
DECLARE @ERR_STR NVARCHAR(MAX)
       SET @ERR_STR  = ' [UPDATE_Cheque_Status] - ' + ERROR_MESSAGE()
	   raiserror(@ERR_STR,16,1,'خطأ')
ROLLBACK
END CATCH


--END

