CREATE PROCEDURE [dbo].[Update_Treasury_balance]
	@Tr_ID int
AS
declare @D money, @C money , @B money

 begin


select @D = (isnull(sum(Debit),0)) , @C =  (isnull(sum(Credit),0)) , @B = ((isnull(sum(Debit),0)) - (isnull(sum(Credit),0)) )
 from Treasury_Balance_MV where Tr_id  = @Tr_ID And isVoid = 0

begin
update TreasuryCard set T_Balance = @B  where Tr_ID = @Tr_ID

RETURN @B

end
end























































