CREATE PROCEDURE [dbo].[UpdateAgentsBalanceIsPied]
    --@FromDate DATE ,
    --@ToDate DATE,
	--@BsType_ID INT
AS
BEGIN
DECLARE @RCT_TYPE  INT = 3

IF OBJECT_ID('tempdb..##Temp_SB_Balance_MV_V') IS NOT NULL
 drop TABLE ##Temp_SB_Balance_MV_V

  SELECT  * INTO ##Temp_SB_Balance_MV_V FROM [SB_Balance_MV_V];

     
	 --IF @BsType_ID = 7 BEGIN  SET @RCT_TYPE = 4 END

    -- تحديث القيم بصفر أولاً للفواتير في الفترة المحددة
    UPDATE A
    SET A.isPied = 0,
        A.Pied = 0
    FROM ##Temp_SB_Balance_MV_V A
    WHERE isDepended = 1 AND isVoid = 0  --AND BsType_ID = @BsType_ID;
	-- A.[DATE] BETWEEN @FromDate AND @ToDate AND
    -- تحديث الفواتير التي لديها إيصالات (بغض النظر عن كفاية المبلغ)
    UPDATE A
    SET 
        A.Pied = R.TotalPaid,
        A.isPied = CASE WHEN V.Pure = R.TotalPaid THEN 1 ELSE 0 END
    FROM ##Temp_SB_Balance_MV_V A
    INNER JOIN Agents_Balance_MV_V V ON A.T_ID = V.T_ID
    INNER JOIN (
        SELECT Receipt_Tran_ID, SUM(Pure) AS TotalPaid
        FROM Agents_Balance_MV_RCT  WHERE isDepended = 1 AND isVoid = 0 AND BsType_ID = @RCT_TYPE
        GROUP BY Receipt_Tran_ID
    ) R ON A.T_ID = R.Receipt_Tran_ID
    WHERE A.isDepended = 1 AND A.isVoid = 0  --AND A.BsType_ID = @BsType_ID;

	--A.[DATE] BETWEEN @FromDate AND @ToDate AND 

END
GO
