SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[UpdateAgentsBalanceIsPied_BY_AG_ID]
    @FromDate DATE,
    @ToDate DATE,
	@BsType_ID INT,
	@AG_ID INT
AS
BEGIN
DECLARE @RCT_TYPE  INT = 3
     
	 IF @BsType_ID = 7 BEGIN  SET @RCT_TYPE = 4 END

    -- تحديث القيم بصفر أولاً للفواتير في الفترة المحددة
    UPDATE A
    SET A.isPied = 0,
        A.Pied = 0
    FROM Agents_Balance_MV A
    WHERE A.[DATE] BETWEEN @FromDate AND @ToDate AND isDepended = 1 AND isVoid = 0  AND BsType_ID = @BsType_ID  AND AG_ID = @AG_ID;

    -- تحديث الفواتير التي لديها إيصالات (بغض النظر عن كفاية المبلغ)
    UPDATE A
    SET 
        A.Pied = R.TotalPaid,
        A.isPied = CASE WHEN V.Pure = R.TotalPaid THEN 1 ELSE 0 END
    FROM Agents_Balance_MV A
    INNER JOIN Agents_Balance_MV_V V ON A.T_ID = V.T_ID
    INNER JOIN (
        SELECT Receipt_Tran_ID, SUM(Pure) AS TotalPaid
        FROM Agents_Balance_MV_RCT  WHERE isDepended = 1 AND isVoid = 0 AND BsType_ID = @RCT_TYPE  AND AG_ID = @AG_ID
        GROUP BY Receipt_Tran_ID
    ) R ON A.T_ID = R.Receipt_Tran_ID
    WHERE A.[DATE] BETWEEN @FromDate AND @ToDate  AND A.AG_ID = @AG_ID AND A.isDepended = 1 AND A.isVoid = 0;
END
GO
/****** Object:  StoredProcedure [dbo].[UpdateAgentsBalanceIsPied_SB_EXP_PCH]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[UpdateAgentsBalanceIsPied_SB_EXP_PCH]
AS
BEGIN

SET NOCOUNT ON;

--------------------------------------------------
-- تصفير القيم
--------------------------------------------------

UPDATE A
SET 
    A.isPied = 0,
    A.Pied = 0
FROM Agents_Balance_MV A
WHERE 
    A.isDepended = 1
    AND A.isVoid = 0
    AND A.BsType_ID IN (1,7,2);

--------------------------------------------------
-- تحديث المدفوعات
--------------------------------------------------

UPDATE A
SET 
    A.Pied = R.TotalPaid,
    A.isPied =
        CASE 
            WHEN V.Pure = R.TotalPaid THEN 1
            ELSE 0
        END
FROM Agents_Balance_MV A
INNER JOIN Agents_Balance_MV_V V 
    ON A.T_ID = V.T_ID
INNER JOIN
(
    SELECT 
        Receipt_Tran_ID,
        BsType_ID,
        SUM(Pure) AS TotalPaid
    FROM Agents_Balance_MV_RCT
    WHERE 
        isDepended = 1 
        AND isVoid = 0
        AND BsType_ID IN (3,4)
    GROUP BY Receipt_Tran_ID, BsType_ID
) R 
ON A.T_ID = R.Receipt_Tran_ID
AND
(
    (A.BsType_ID = 1 AND R.BsType_ID = 3) -- المبيعات مع القبض
    OR
    (A.BsType_ID IN (7,2) AND R.BsType_ID = 4) -- المشتريات والمصروفات مع الصرف
)
WHERE 
    A.isDepended = 1
    AND A.isVoid = 0;

END
