CREATE PROCEDURE [dbo].[User_Insert] 

	@UserName nvarchar(200),
	@UserPass nvarchar(4000),
	@isAdmin bit = 0,
	--@isPone_Users	bit,
	--@TB_ID	int = NULL,
	@isCostmerScreen Bit = 0,
	@AG_ID INT = NULL,
	@is_Allow	int,
	@Valid_ID INT,
	@Tr_ID	int,
	@WEB_PASS  nvarchar(4000)
AS
declare @isError int ,@user_id int

BEGIN TRAN
    EXEC @user_id = AA_GET_MAX_ID 'Users'

DECLARE @TOKEN NVARCHAR(2500)
EXEC [dbo].[usp_generateIdentifier] 1,1000,@user_id,@TOKEN OUTPUT

	insert into Users (user_id,UserName,UserPass,isAdmin,isCostmerScreen,AG_ID,is_Allow,Valid_ID,Tr_ID,TOKEN,WEB_PASS)
	values(@user_id,@UserName,@UserPass,@isAdmin,@isCostmerScreen,@AG_ID,@is_Allow,@Valid_ID,@Tr_ID,@TOKEN,@WEB_PASS)
	--SELECT @user_id = SCOPE_IDENTITY();

	select @isError = @@ERROR
	IF @isError <> 0 
	goto PROBLEM

	COMMIT TRAN

	PROBLEM:
	if @isError <> 0 begin
	raiserror ('DB ERROR (User_Insert)',16,1,'خطأ')
	ROLLBACK TRAN

END






















































