CREATE PROCEDURE [dbo].[View_Contents_IM_Unit_Change] 
@IM_T_ID int,
@U_ID int,
@QTY Numeric(18,2) = NULL,
@Price FLOAT


AS
DECLARE @Bill_T_ID INT,@U_Cargo NUMERIC(18,2),@IM_ID INT,@ST_ID int ,@D_Valid NVARCHAR(20) = '' 
,@ST_QTY_DEF FLOAT = 0
BEGIN TRY
BEGIN TRANSACTION 

SELECT @IM_ID = IM_ID , @ST_ID = ST_ID , @D_Valid = D_Vaild FROM ViewBill_Contents WHERE T_ID = @IM_T_ID

SELECT @U_Cargo = U_Cargo FROM IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_ID = @U_ID

 UPDATE ViewBill_Contents SET U_ID=@U_ID , QTY=@QTY , Price=@Price , T_Price = (@Price * @QTY) 
 , U_Cargo = @U_Cargo , ST_QTY = (@QTY * @U_Cargo)
 WHERE T_ID = @IM_T_ID



COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[View_Contents_IM_Unit_Change]',16,1,'خطأ')
ROLLBACK
END CATCH












