CREATE PROCEDURE [dbo].[ViewBill_ConfermBill]
	@T_ID int,
	@TOTAL FLOAT,
	@Discount FLOAT,
	@Pure FLOAT
	
AS
BEGIN TRY
BEGIN TRANSACTION


EXEC AG_Balance_Update_isDepended @T_ID

Update Agents_Balance_MV SET Total = @TOTAL,Discount = @Discount,
 Pure= @Pure , SB_isOpen = 0 ,isPied = 1, TB_isOrderd = 1
 WHERE T_ID = @T_ID 

COMMIT
END TRY

BEGIN CATCH
