SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE PROCEDURE [dbo].[ViewBill_Contents_Change_IM_Qty]
	@T_ID int,
	@Def int

AS
BEGIN TRY
BEGIN TRANSACTION

DECLARE @U_Cargo NUMERIC(18,2),@IM_ID INT,@ST_ID INT,@D_Vaild NVARCHAR(50)

SELECT @U_Cargo = U_Cargo ,@IM_ID=IM_ID, @ST_ID=ST_ID,@D_Vaild=D_Vaild   FROM ViewBill_Contents where T_ID = @T_ID

UPDATE  ViewBill_Contents SET QTY = QTY + @Def , T_Price = (Price * (QTY + @Def)) , ST_QTY = (QTY + @Def) * U_Cargo
where T_ID = @T_ID


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[ViewBill_Contents_Change_IM_Qty]',16,1,'خطأ')
ROLLBACK
END CATCH































GO
