/****** Object:  StoredProcedure [dbo].[ViewBill_Contents_INSERT_2]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ViewBill_Contents_INSERT_2]
	@SB_T_ID int,
	@IM_ID int,
	@D_Vaild DATE = NULL,
	@QYT float = 1,
	@U_ID INT,
	@ST_ID INT,
	@Price FLOAT,
	@Current_QTY Float = NULL,
	@Barcode nvarchar(50)

AS
DECLARE  @T_ID INT, @U_Cargo NUMERIC(18,2),@Cost NUMERIC(18,3),@ST_QTY NUMERIC(18,2),@Valid_ST NVARCHAR(50),@isDepended int = 0
BEGIN TRY
BEGIN TRANSACTION 
--BEGIN

SET @Valid_ST = @D_Vaild

IF @Valid_ST IS NULL 
BEGIN 
SET @Valid_ST ='' 
END
ELSE
BEGIN
IF @Current_QTY <= 0 BEGIN SET @Valid_ST = (SELECT  Top 1 D_Vaild FROM ViewBill_Contents WHERE ST_ID = @ST_ID  AND IM_ID = @IM_ID ORDER BY T_ID DESC) END
IF @Valid_ST IS NULL BEGIN SET @Valid_ST = '01-01-1900' END
END


--SELECT  Top 1 @isDepended = ISNULL(isDepended,0) FROM ViewBill_Contents WHERE Bill_T_ID = @SB_T_ID 

IF @isDepended IS NULL BEGIN SET @isDepended = 0 END


SELECT @U_Cargo = U_Cargo , @Cost = Cost FROM IM_Menu_Units_V WHERE IM_ID = @IM_ID AND U_ID = @U_ID
SELECT @ST_QTY = (@U_Cargo * @QYT)

EXEC @T_ID = AA_GET_MAX_ID 'ViewBill_Contents'

INSERT INTO ViewBill_Contents (T_ID,Bill_T_ID,IM_ID,U_ID,ST_ID,Date,Compons,Cost,Price,D_Vaild,QTY,T_Price,U_Cargo,ST_QTY,isDepended,Barcode)
 VALUES(@T_ID,@SB_T_ID,@IM_ID,@U_ID,@ST_ID,GETDATE(),NULL,(@Cost * @U_Cargo),@Price,@Valid_ST,@QYT,(@Price * @QYT),@U_Cargo,@ST_QTY,@isDepended,@Barcode)

 --SELECT @T_ID = SCOPE_IDENTITY();

EXEC [Recalculate_Agent_Bill_Total] @SB_T_ID

 
COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror('[ViewBill_Contents_INSERT_2]',16,1,'خطأ')
ROLLBACK
END CATCH

--END
































GO
