/****** Object:  StoredProcedure [dbo].[ViewBill_Move_IM_To_SB]    Script Date: 09/05/2026 16:40:13 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ViewBill_Move_IM_To_SB]
@SB_T_ID INT,
@View_Bill_T_ID INT,
@TOTAL FLOAT,
@Disc FLOAT
AS
BEGIN TRY
BEGIN TRANSACTION 
Declare @i INT,@IM_ID INT,@D_Valid NVARCHAR(50),@ST_ID INT,@ST_QTY NUMERIC(18,2),@AG_ID INT,@T_ID INT,@date datetime

SELECT @date = DATE FROM Agents_Balance_MV WHERE T_ID = @View_Bill_T_ID


SELECT @i = min(T_ID) From ViewBill_Contents WHERE Bill_T_ID = @View_Bill_T_ID
WHILE @i IS NOT NULL
BEGIN


EXEC @T_ID = [AA_GET_MAX_SB_Contents]

INSERT INTO [dbo].[SB_Contents]
           ([T_ID]
		   ,[Bill_T_ID]
           ,[IM_ID]
           ,[U_ID]
           ,[ST_ID]
           ,[Date]
           ,[Compons]
           ,[Cost]
           ,[Price]
           ,[D_Vaild]
           ,[QTY]
           ,[T_Price]
           ,[U_Cargo]
           ,[ST_QTY]
           ,[isDepended]
           ,[Apart_From]
           ,[Saler_Percent]
           ,[Notes]
           ,[Markter_Val]
           ,[Barcode])
    SELECT
	        @T_ID
           ,@SB_T_ID
           ,IM_ID
           ,U_ID
           ,ST_ID
           ,Date
           ,Compons
           ,Cost
           ,Price
           ,D_Vaild
           ,QTY
           ,T_Price
           ,U_Cargo
           ,ST_QTY
           ,isDepended
           ,Apart_From
           ,Saler_Percent
           ,Notes
           ,0
           ,Barcode
		    FROM ViewBill_Contents WHERE Bill_T_ID = @View_Bill_T_ID AND T_ID = @i



SELECT @i = min(T_ID) From ViewBill_Contents WHERE Bill_T_ID = @View_Bill_T_ID AND T_ID > @i
END



SELECT @TOTAL = ISNULL(SUM(T_Price),0) FROM ViewBill_Contents WHERE Bill_T_ID = @View_Bill_T_ID

UPDATE Agents_Balance_MV SET AG_ID = (SELECT AG_ID FROM Agents_Balance_MV WHERE T_ID = @View_Bill_T_ID) ,
Total = @TOTAL ,Discount = @Disc , Pure = (@TOTAL - @Disc) , Credit = (@TOTAL - @Disc) , DATE =  @date  WHERE T_ID = @SB_T_ID


COMMIT
END TRY

BEGIN CATCH
IF @@TRANCOUNT > 0
raiserror ('DB ERROR [ViewBill_Move_IM_To_SB]',16,1,'خطأ')
ROLLBACK
END CATCH











GO
